CREATE PROCEDURE "informix".sp_cat_resultados_his()
RETURNING char(6), char(150);

--declaracion de variables
DEFINE sql_err                  INTEGER;
DEFINE isam_err                 INTEGER;
DEFINE error_info               CHAR(150);
DEFINE cMensaje                 CHAR(150); 
DEFINE cCod_ret                 CHAR(6);
DEFINE vempresa                  CHAR(3);
DEFINE vnumcte              	CHAR(20);
DEFINE vid_llamada          	CHAR(100);
DEFINE vtipo_telefono       	SMALLINT;
DEFINE vtelefono            	CHAR(13);
DEFINE vextension           	CHAR(5);
DEFINE vcodigo_resultado    	INTEGER;
DEFINE vfecha_llamar_despues    CHAR(40);
DEFINE vhora_llamar_despues 	CHAR(40);
DEFINE vejecutivo           	CHAR(10);
DEFINE vfh_movimiento       	CHAR(40);
DEFINE vdia						        DATE;
DEFINE vhora					        CHAR(8);
DEFINE vvcCod_ret             CHAR(6);
DEFINE cproceso                 CHAR(4);
DEFINE vrowid                   INTEGER;
DEFINE vfecha_llamada           DATE;
DEFINE vtipo_campania           CHAR(1);
DEFINE vparentesco              CHAR(1);

    --SET DEBUG FILE TO '/ids10_uc9/jtrujillo/sp_cat_resultados_his.out';
    --TRACE ON;
	
	--inicializacion de variables
	LET cCod_ret      = '00000';
	LET sql_err       = 0;
	LET isam_err      = 0;
	LET error_info    = ''; 	
	LET cMensaje      = 'PROCESO EXITOSO';
    LET cproceso      = '0010';
    LET vempresa      = '001';
    
    BEGIN
	
    ON EXCEPTION SET sql_err, isam_err, error_info
        LET cCod_ret = sql_err;
        LET cMensaje = error_info;
        CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje, '02')
            RETURNING vvcCod_ret;
        RETURN cCod_ret, cMensaje;
    END EXCEPTION;

        CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje, '01')
            RETURNING vvcCod_ret;	
    
		--se obtiene la informacion
		
		
		SET LOCK MODE TO WAIT 3;
	  SET ISOLATION TO DIRTY READ;
    FOREACH cursor_borra WITH HOLD FOR

			SELECT rowid, fecha_llamada, tipo_campania, numcte, id_llamada, tipo_telefono
                ,telefono, extension, codigo_resultado, parentesco, fecha_llamar_despues, hora_llamar_despues
                ,ejecutivo, fh_movimiento
            INTO vrowid, vfecha_llamada, vtipo_campania, vnumcte, vid_llamada, vtipo_telefono
                ,vtelefono, vextension, vcodigo_resultado, vparentesco, vfecha_llamar_despues, vhora_llamar_despues
                ,vejecutivo, vfh_movimiento
            FROM cb_cat_resultado_llamada
            
            INSERT INTO informix.cb_cat_resultado_llamada_his(empresa, fecha_llamada, tipo_campania, numcte, id_llamada
                        ,tipo_telefono, telefono, extension, codigo_resultado, parentesco, fecha_llamar_despues
                        ,hora_llamar_despues, ejecutivo, fh_movimiento, fh_insert) 
            VALUES(vempresa, vfecha_llamada, vtipo_campania, vnumcte, vid_llamada, vtipo_telefono, vtelefono, vextension
                    ,vcodigo_resultado, vparentesco, vfecha_llamar_despues, vhora_llamar_despues, vejecutivo
                    ,vfh_movimiento, TODAY);

            BEGIN WORK;
               DELETE FROM bdicobranza:cb_cat_resultado_llamada
               WHERE CURRENT OF cursor_borra;                                                                             
            COMMIT WORK;

	END FOREACH;

        CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje, '03')
        RETURNING vvcCod_ret;
				
	RETURN cCod_ret, cMensaje;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cat_graba_respuesta_llamada(pEmpresa     CHAR(3),
                                                           pNumcte      CHAR(20),
                                                           pTipotel     SMALLINT,
                                                           pTelefono    CHAR(13),
                                                           pResultado   SMALLINT,
                                                           pFechaProg   DATE,
                                                           pHoraProg    DATETIME HOUR TO FRACTION,
                                                           pEjecutivo   CHAR(8),
                                                           pId_llamada  CHAR(100),
                                                           pTipoCob     CHAR(1),
                                                           pParentesco  CHAR(1),
                                                           pTpoMovto    SMALLINT)

RETURNING CHAR(6) AS cod_ret;

DEFINE iSqlErr          INTEGER; 
DEFINE iIsamErr         INTEGER;
DEFINE cCod_ret         CHAR(6);

DEFINE iExiste          SMALLINT;
DEFINE dtFecha          DATETIME HOUR TO FRACTION;
DEFINE dtFechaHora      DATETIME YEAR TO FRACTION;
DEFINE cMensaje         CHAR(80);

LET iSqlErr          = 0;
LET iIsamErr         = 0;
LET cCod_ret         = "000000";

LET iExiste          = 0;
LET dtFecha          = DATE(1);
LET dtFechaHora      = CURRENT YEAR TO SECOND;
LET cMensaje         = "";

--SET DEBUG FILE TO "/home/sysifx/sp_cat_graba_respuesta_llamada.out";
--TRACE ON;

SET ISOLATION TO DIRTY READ;
SET LOCK MODE TO WAIT 3;

BEGIN

    ON EXCEPTION SET iSqlErr, iIsamErr
          LET cCod_ret = iSqlErr;
          RETURN cCod_ret;
    END EXCEPTION;

     IF pTpoMovto NOT IN (1,2) THEN
        LET cCod_ret = "102001";
     END IF;

    IF pTpoMovto = 1 THEN -- Identifica que es una llamada
        IF NVL(pEmpresa,"") = "" OR NVL(pNumcte,"") = "" OR pTipotel IS NULL OR NVL(pTelefono,"") = ""
           OR  pResultado IS NULL OR NVL(pId_llamada,"") = "" THEN
            LET cCod_ret = "102002";
            RETURN cCod_ret;
        END IF;
    END IF;

     IF pTpoMovto = 2 THEN -- Identifica que es una gestión
         IF NVL(pTipotel,"") <> "" OR NVL(pTelefono,"") <> ""  OR NVL(pFechaProg,"") <> "" 
              OR NVL(pHoraProg,"") <> "" OR NVL(pId_llamada,"") <> "" OR NVL(pEmpresa,"") = "" OR NVL(pNumcte,"") = "" THEN
              LET cCod_ret = "102002";
              RETURN cCod_ret;
         END IF;        
     END IF;

   SELECT COUNT(empresa)
     INTO iExiste
     FROM bdinteg:"informix".si_empresas
    WHERE empresa = pEmpresa;

    IF iExiste = 0 THEN
        LET cCod_ret = "102003";
        RETURN cCod_ret;
    END IF;

    SELECT fecha_hoy, CURRENT
      INTO dtFecha, dtFechaHora
      FROM bdinteg:"informix".si_fechas
     WHERE empresa = pEmpresa;

   INSERT INTO bdicobranza:"informix".cb_cat_resultado_llamada (empresa,fecha_llamada,tipo_campania,numcte,id_llamada,
                                                                  tipo_telefono,telefono,codigo_resultado,fecha_llamar_despues,
                                                                  hora_llamar_despues,ejecutivo,fh_movimiento,parentesco)
           VALUES (pEmpresa,dtFecha,pTipoCob,pNumcte,pId_llamada,
                   pTipotel,pTelefono,pResultado,pFechaProg,
                   pHoraProg,pEjecutivo,dtFechaHora,pParentesco);
    IF pTpoMovto = 2 THEN 
        EXECUTE PROCEDURE "informix".sp_cat_cambia_estatus_cte(pNumcte, 
                                                            "PR", 
                                                            0, 
                                                            pTipoCob,
                                                            pEmpresa, 
                                                            pEjecutivo)
        INTO cCod_ret, cMensaje;
        IF cCod_ret <> "000000" THEN
            LET cCod_ret = "102004";
        END IF;
   END IF;
RETURN cCod_ret;

END 
END PROCEDURE
DOCUMENT
"Descripción: Registra los resultados de la llamadas realizadas por el ejecutivo",
"cobranza telefónica",
"BD: bdicobranza",
"Autor: Viridiana Osobampo Aguilar",
"Fecha: 29-Sep-2010";

CREATE PROCEDURE "informix".sp_random() RETURNING INTEGER;
	DEFINE GLOBAL seed DECIMAL(10) DEFAULT 1; 
	DEFINE d DECIMAL(20,0); 
	LET d = (seed * 1103515245) + 12345; 
	LET seed = d - 4294967296 * TRUNC(d / 4294967296); 
	RETURN MOD(TRUNC(seed / 65536), 32768); 
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cat_actualiza_resultado_gestion(pempresa CHAR(3), ptipo_campania CHAR(1))
RETURNING CHAR(5);

--Fecha de Creación: 19/Enero/2011
--Creado por: Enrique Lizárraga Lugo
--Proceso para la actualización del resultado de la gestión y la fecha de último contacto en cb_cat_directorio_cte

--Definición de variables de bitácora
DEFINE cCodRet 				CHAR(5);
DEFINE isqlerr 				INTEGER;
DEFINE isam_err	 			INTEGER;
DEFINE vProceso				CHAR(5);
DEFINE error_info			CHAR(80);
DEFINE cMensaje				CHAR(80);
DEFINE vempresa				CHAR(3);
--Definición de variables de trabajo
DEFINE vcodigo_resultado 	SMALLINT;
DEFINE vnumcte				CHAR(20);
DEFINE vtipo_llamada		CHAR(1);
DEFINE vfh_movimiento		DATETIME YEAR TO FRACTION;

--Inicialización de variables
LET cCodRet = '00000';
LET isqlerr = 0;
LET isam_err = 0;
LET vProceso = 'actrg';
LET error_info = '';
LET cMensaje = 'PROCESO EXITOSO';
LET vempresa = '001';
LET vcodigo_resultado = 0;
LET vnumcte = '';
LET vtipo_llamada = '';
LET vfh_movimiento = '';

BEGIN    
        ON EXCEPTION SET isqlerr, isam_err, error_info
            LET cCodret = isqlerr;
	        LET cMensaje = error_info;
            CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vProceso, cCodRet, cMensaje, '02');
			RETURN cCodRet;            
        END EXCEPTION;
		
		--SET DEBUG FILE TO "/ids10_uc9/elizarraga/resgestion.out";
		--TRACE ON; 
		
	SET ISOLATION TO DIRTY READ;
	
		CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vProceso, cCodRet, cMensaje, '01');
		
	FOREACH
	SELECT {+INDEX(bdicobranza:cb_cat_resultado_llamada idx_resul_llamada3)}{+INDEX(bdicobranza:cb_cat_tipo_resultado idx_tipo)} min(a.codigo_resultado), a.numcte, b.tipo_llamada 
	INTO vcodigo_resultado, vnumcte, vtipo_llamada
	FROM cb_cat_resultado_llamada a, cb_cat_tipo_resultado b 
	WHERE a.codigo_resultado = b.codigo_resultado
	AND a.empresa = pempresa
	and a.numcte <> ''
	AND a.tipo_campania = ptipo_campania
	AND b.tipo_llamada <> ''
	group by a.numcte, b.tipo_llamada
	order by a.numcte
	
	IF vtipo_llamada = 'C' THEN
		SELECT {+INDEX(bdicobranza:cb_cat_resultado_llamada idx_resul_llamada3)}{+INDEX(bdicobranza:cb_cat_tipo_resultado idx_tipo)} max(a.fh_movimiento)
		INTO vfh_movimiento
		FROM cb_cat_resultado_llamada a, cb_cat_tipo_resultado b
		WHERE a.codigo_resultado = b.codigo_resultado
		AND a.empresa = pempresa
		AND a.numcte = vnumcte
		AND a.tipo_campania = ptipo_campania
		AND a.codigo_resultado = vcodigo_resultado
		AND b.tipo_llamada = 'C';
		
		UPDATE {+INDEX(bdicobranza:cb_cat_directorio_cte idx_dir2)} bdicobranza:cb_cat_directorio_cte set codigo_resultado = vcodigo_resultado, fecha_ultimo_contacto = vfh_movimiento
		WHERE empresa = pempresa and numcte = vnumcte and tipo_cobranza = ptipo_campania;
		
	ELSE
		UPDATE {+INDEX(bdicobranza:cb_cat_directorio_cte idx_dir2)} bdicobranza:cb_cat_directorio_cte SET codigo_resultado = vcodigo_resultado
		WHERE empresa = pempresa and numcte = vnumcte and tipo_cobranza = ptipo_campania;
	END IF;
	
	END FOREACH;
	
	CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vProceso, cCodRet, cMensaje, '03');
	RETURN cCodRet;
		
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_llenaredcarrier()
RETURNING CHAR(5);

--Definición de variables
DEFINE 	sql_err			INTEGER;
DEFINE 	isam_err		INTEGER;
DEFINE 	error_info		CHAR(80);
DEFINE 	cMensaje		CHAR(80);
DEFINE 	cCod_ret		CHAR(6);
DEFINE 	vproceso		CHAR(30);
DEFINE	vempresa		CHAR(3);
DEFINE 	vtelefono 		CHAR(10);
DEFINE	vtelaux			CHAR(3);
DEFINE	vtelaux2		CHAR(13);
DEFINE	vtipored 		CHAR(10);
DEFINE	vnumero_carrier	CHAR(3);
DEFINE 	vCod_ret		CHAR(5);
DEFINE	vnumcte			CHAR(20);
DEFINE	vTipoTel        SMALLINT;
DEFINE  vorigen			SMALLINT;

--Inicialización de variables
LET cCod_ret = '000000';
LET sql_err = 0;
LET isam_err = 0;
LET error_info = '';
LET cMensaje = 'PROCESO EXITOSO';
LET vproceso = 'carr';
LET vempresa = '001';
LET vtelefono = '';
LET vtipored = '';
LET vnumero_carrier = '';
LET vCod_ret = '00000';
LET vnumcte = '';

BEGIN
    ON EXCEPTION SET sql_err, isam_err, error_info
	        LET cCod_ret = sql_err;
            LET cMensaje = error_info;
            CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vproceso, cCod_ret, cMensaje, '02');
        RETURN cCod_ret;
	END EXCEPTION;

    CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vproceso, cCod_ret, cMensaje, '01');

FOREACH

	SELECT SUBSTR(a.telefono,1,3), telefono, telefono , numcte , origen
    INTO vtelaux , vtelefono, vtelaux2 , vnumcte , vorigen
	FROM bdicobranza:cb_telefonos a
	WHERE empresa = '001'
    --AND nvl(numero_carrier,0) =0

	IF vtelaux = '045' THEN
		LET vtelefono = SUBSTR(vtelefono,4,10);
	END IF;

	EXECUTE PROCEDURE bdinteg:"informix".sp_tipored ('001', vtelefono) into vCod_ret , vtipored , vnumero_carrier;

	IF vtelaux ='045' THEN
		UPDATE {+INDEX(bdicobranza:cb_telefonos idx_pk_cb_telefonos)} bdicobranza:"informix".cb_telefonos 
                   SET tipored = vtipored , numero_carrier = vnumero_carrier 
                 WHERE empresa = '001' 
                   and numcte = vnumcte 
                   and telefono = vtelaux2 
                   and origen = vorigen;
	ELSE
		UPDATE {+INDEX(bdicobranza:cb_telefonos idx_pk_cb_telefonos)}  bdicobranza:"informix".cb_telefonos SET tipored = vtipored , numero_carrier = vnumero_carrier WHERE empresa = '001' and numcte = vnumcte and telefono = vtelefono and origen = vorigen;
	END IF;

END FOREACH;

CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vproceso, cCod_ret, cMensaje, '03');

RETURN cCod_ret;

END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cat_actualiza_resultado_gestion_his(pempresa CHAR(3), ptipo_campania CHAR(1))
RETURNING CHAR(5);

--Fecha de Creación: 1/Febrero/2011
--Creado por: Enrique Lizárraga Lugo
--Proceso para la actualización del resultado de la gestión y la fecha de último contacto en cb_cat_directorio_cte_his

--Definición de variables de bitácora
DEFINE cCodRet 				CHAR(5);
DEFINE isqlerr 				INTEGER;
DEFINE isam_err	 			INTEGER;
DEFINE vProceso				CHAR(5);
DEFINE error_info			CHAR(80);
DEFINE cMensaje				CHAR(80);
DEFINE vempresa				CHAR(3);
--Definición de variables de trabajo
DEFINE vcodigo_resultado 	SMALLINT;
DEFINE vnumcte				CHAR(20);
DEFINE vtipo_llamada		CHAR(1);
DEFINE vfh_movimiento		DATETIME YEAR TO FRACTION;

--Inicialización de variables
LET cCodRet = '00000';
LET isqlerr = 0;
LET isam_err = 0;
LET vProceso = 'argh';
LET error_info = '';
LET cMensaje = 'PROCESO EXITOSO';
LET vempresa = '001';
LET vcodigo_resultado = 0;
LET vnumcte = '';
LET vtipo_llamada = '';
LET vfh_movimiento = '';

BEGIN    
        ON EXCEPTION SET isqlerr, isam_err, error_info
            LET cCodret = isqlerr;
	        LET cMensaje = error_info;
            CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vProceso, cCodRet, cMensaje, '02');
			RETURN cCodRet;            
        END EXCEPTION;
		
		--SET DEBUG FILE TO "/ids10_uc9/elizarraga/resgestion.out";
		--TRACE ON; 
		
	SET ISOLATION TO DIRTY READ;
	
		CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vProceso, cCodRet, cMensaje, '01');
		
	FOREACH
	SELECT {+INDEX(bdicobranza:cb_cat_resultado_llamada_his idx_resul_llamada_his)}{+INDEX(bdicobranza:cb_cat_tipo_resultado idx_tipo)} min(a.codigo_resultado), a.numcte, b.tipo_llamada 
	INTO vcodigo_resultado, vnumcte, vtipo_llamada
	FROM cb_cat_resultado_llamada_his a, cb_cat_tipo_resultado b 
	WHERE a.codigo_resultado = b.codigo_resultado
	AND a.empresa = pempresa
	and a.numcte <> ''
	AND a.tipo_campania = ptipo_campania
	AND b.tipo_llamada <> ''
	group by a.numcte, b.tipo_llamada
	order by a.numcte
	
	IF vtipo_llamada = 'C' THEN
		SELECT {+INDEX(bdicobranza:cb_cat_resultado_llamada_his idx_resul_llamada_his)}{+INDEX(bdicobranza:cb_cat_tipo_resultado idx_tipo)} max(a.fh_movimiento)
		INTO vfh_movimiento
		FROM cb_cat_resultado_llamada_his a, cb_cat_tipo_resultado b
		WHERE a.codigo_resultado = b.codigo_resultado
		AND a.empresa = pempresa
		AND a.numcte = vnumcte
		AND a.tipo_campania = ptipo_campania
		AND a.codigo_resultado = vcodigo_resultado
		AND b.tipo_llamada = 'C';
		
		UPDATE {+INDEX(bdicobranza:idx_directorio_his)} bdicobranza:cb_cat_directorio_cte_his set codigo_resultado = vcodigo_resultado, fecha_ultimo_contacto = vfh_movimiento
		WHERE empresa = pempresa and numcte = vnumcte and tipo_cobranza = ptipo_campania and fecha_insert <= vfh_movimiento and fecha_insert+30 > vfh_movimiento;
		
	ELSE
		UPDATE {+INDEX(bdicobranza:idx_directorio_his)} bdicobranza:cb_cat_directorio_cte_his SET codigo_resultado = vcodigo_resultado
		WHERE empresa = pempresa and numcte = vnumcte and tipo_cobranza = ptipo_campania and fecha_insert <= vfh_movimiento and fecha_insert+30 > vfh_movimiento;
	END IF;
	
	END FOREACH;
	
	CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vProceso, cCodRet, cMensaje, '03');
	RETURN cCodRet;
		
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_auronix_msj()
       RETURNING char(6), char(150);

DEFINE sql_err 			INTEGER;
DEFINE isam_err 		INTEGER;
DEFINE error_info		CHAR(150);
DEFINE cCod_ret         CHAR(6);
DEFINE cMensaje 		CHAR(150);
DEFINE vnumcte          CHAR(20);
DEFINE vnum_credito     CHAR(20);
DEFINE vpagos_vencidos  INTEGER;
DEFINE vsituacion       CHAR(1);
DEFINE vcausa           SMALLINT;
DEFINE vinstruccion     CHAR(1);
DEFINE vempresa         CHAR(3);
DEFINE vtFechaLimite    DATE;
DEFINE vtfechacorte     DATE;
DEFINE vcelular         CHAR(13);
DEFINE cccCod_ret       CHAR(6);
DEFINE cccMensaje       CHAR(150);
DEFINE vfecha_insert    DATE;
DEFINE vnombre          CHAR(110);
DEFINE vciudad          CHAR(20);
DEFINE vestado          CHAR(20);

    LET vempresa      = '001';
    LET cCod_ret      = '000000';
    LET sql_err       = 0;
    LET cMensaje      = 'PROCESO EXITOSO';

--SET DEBUG FILE TO '/tmp/sp_datos_admin_auronix.out';
--TRACE ON;

BEGIN

        ON EXCEPTION SET sql_err, isam_err, error_info
	        LET cCod_ret = sql_err;
	        LET cMensaje = error_info;
            RETURN cCod_ret, cMensaje;
	    END EXCEPTION;

    SET ISOLATION TO dirty READ; 
    TRUNCATE bdicobranza:cb_ctes_mensajes;

    SELECT limit 1 fecha_insert 
    INTO vfecha_insert
    FROM cb_cat_directorio_cte where tipo_cobranza = 'A';

    SET ISOLATION TO dirty READ;
    FOREACH

        SELECT LIMIT 40000 a.numcte
            ,a.num_credito
            ,a.pago_venc
            ,substr(b.telefono,length(b.telefono)-9,10) celular
            ,trim(a.nombre1) || " " || trim(a.nombre2) || " " ||
             trim(a.apell_paterno) || " " || trim(a.apell_materno) Nombre
            ,a.ciudad
        INTO vnumcte, vnum_credito, vpagos_vencidos, vcelular, vnombre, vciudad
        FROM cb_cat_directorio_cte a, cb_telefonos b
        where a.numcte = b.numcte
        and b.tipo_telefono = 2
		and b.origen = 2
		and b.tipored is not null
        and a.tipo_cobranza = 'A'
        and a.fecha_insert = vfecha_insert
        and a.status_cliente IN ('AC', 'PR')
        and a.pago_venc between 1 and 3
        

        SELECT first 1 a.ciudad_coppel || '-' || trim(b.inicialciudad) Ciudad    --- ciudad
               ,b.numeroestado || '-' || trim(b.inicialestado) Estado   --- estado*/
        INTO vciudad, vestado
        FROM bdinteg:si_ciudades a, bdinteg:si_catciudades b
        WHERE a.ciudad_coppel = b.numerociudad
        AND a.ciudad = vciudad;


                        LET vsituacion = NULL;
                        LET vcausa     = NULL;

                        SELECT {+INDEX(bdisitesp:se_ctessitespcte se_ctessitespcte_idx1)} FIRST 1 nvl(situacion, ''),  nvl(causa, 0)
                        INTO   vsituacion, vcausa
                        FROM bdisitesp:se_ctessitespcte
                        WHERE numcte = vnumcte;

                         LET vinstruccion = 1;

                    IF ((vsituacion IS NOT NULL) AND (vcausa IS NOT NULL)) THEN

                                SELECT FIRST 1 instruccion
                                INTO vinstruccion
                                FROM bdisitesp:se_situacionaccion
                                WHERE situacion= vsituacion
                                AND causa= vcausa
                                AND idaccion = 9
                                AND empresa = vempresa;

                    END IF;

                    IF (vinstruccion = 1) THEN

                        INSERT INTO "informix".cb_ctes_mensajes(cliente, credito, ciudad, estado, nombre, t_celular, pago_venc, fecha_ejecucion, causa, situacion) 
                        VALUES(vnumcte, vnum_credito, vciudad, vestado, vnombre, vcelular, vpagos_vencidos, TODAY, nvl(vcausa, 0), nvl(vsituacion, ''));
                        
                    END IF;

END FOREACH;

	CALL bdicobranza:"informix".sp_target_phone()
    RETURNING cccCod_ret, cccMensaje;
 
    RETURN cCod_ret, cMensaje;

	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cat_ejecuta_mensaje(pTramaXML CHAR(3000))
RETURNING CHAR(6) AS COD_RET, CHAR(7500) AS TRAMA;
-- VARIABLES GENERALES
DEFINE iSqlErr INTEGER;
DEFINE iIsamErr INTEGER;
DEFINE error_info CHAR(80);
DEFINE cCodRet CHAR(6);
DEFINE cMensaje VARCHAR(80);
DEFINE iNumFilas INTEGER;
DEFINE cEmpresa CHAR(3);
