        INTO cVAR_S1,cVAR_S2,cVAR_S3,cVAR_S4,cVAR_S5,cVAR_S6,cVAR_S7,cVAR_S8,cVAR_S9,cVAR_S10,cVAR_S11,cVAR_S12,cVAR_S13,cVAR_S14,cVAR_S15,cVAR_S16
        IF cVAR_S1::INTEGER <> 0 THEN
