create procedure "informix".sp_mail_compraxmonto(pempresa char(3), pfechacorte date)
returning VARCHAR(6);
--DEFINE pempresa          char(3);
DEFINE pnumcredito       char(20);
DEFINE pnumcte		 char(20);
DEFINE pemail		 char (60);
DEFINE pmonto  decimal(18,2);
--DEFINE pfechaact         date;
--DEFINE pfechaant         date;
DEFINE pfechahoy         date;
DEFINE pfechamov		 date;	

DEFINE cProceso  char(4);
DEFINE cCod_ret  smallint;
DEFINE cMensaje  char (100); 
--DEFINE pdia      date; 
DEFINE pfechaarmada date; 
 

DEFINE SQL_ERR            INTEGER;
DEFINE ISAM_ERR           INTEGER;
DEFINE ERROR_INFO         VARCHAR(80);
DEFINE P_COD_RET          VARCHAR(6);
DEFINE P_MENSAJE          VARCHAR(80);

BEGIN 
  
    ON exception SET SQL_ERR, ISAM_ERR, ERROR_INFO
    CALL bdicobranza:"informix".sp_inserta_bitacora_cob(pempresa, cProceso, P_COD_RET, P_MENSAJE, '02')
        RETURNING P_COD_RET;
         LET P_COD_RET = SQL_ERR;
         LET P_MENSAJE = ERROR_INFO;
    RETURN P_COD_RET;
    END exception;
 
    let P_COD_RET = '111111';
    let cCod_ret = '';
    let cMensaje = '';
    let cProceso = '2027';
	
	--valida parametros
	IF NVL (pempresa, '') = '' THEN
        LET cCod_Ret= '104002';
        SELECT descripcion
        INTO cMensaje
        FROM cb_errores
        WHERE origen = 3
        AND codigo_error = cCod_Ret;
	
        IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
        END IF;

        CALL bdicobranza:"informix".sp_inserta_bitacora_cob(pempresa, cproceso, cCod_ret, cMensaje, '01');
        Return cCod_Ret;
	END IF;
	IF NVL (pfechacorte, '') = '' THEN
        LET cCod_Ret= '104008';        SELECT descripcion
        INTO cMensaje
        FROM cb_errores
        WHERE origen = 3
        AND codigo_error = cCod_Ret;
	
       IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
        END IF;

        CALL bdicobranza:"informix".sp_inserta_bitacora_cob(pempresa, cProceso, cCod_ret, cMensaje, '01');
        Return cCod_Ret;
	END IF;
	
    Select Fecha_Hoy
        Into pfechahoy
    From bdicred:sd_fechas
    Where empresa = '001';

    delete from bdicobranza:cb_mail_cliente where fecha_insert = pfechahoy and tipo_mensaje = 1 and pagos_vencidos= 30;     
   /* select limit 1 dia_corte into pdia from bdicred:sd_maecredanexo where empresa = pempresa;
     
   
   let pfechaarmada = mdy(month(pfechacorte),day(pdia),year(pfechacorte));
   let pfechaact = date(pfechacorte);

   if (pfechacorte <= pfechaarmada) then
        let pfechaant = date (pfechaarmada) - 1 units month + 1 units day;
   end if;
   if (pfechacorte > pfechaarmada ) then
        let pfechaant = date (pfechaarmada) + 1 units day;
   end if;   */
   let pfechaarmada = date (pfechacorte) -  1 units day;

	
    CALL bdicobranza:"informix".sp_inserta_bitacora_cob(pempresa, cProceso, cCod_ret, cMensaje, '01')
        RETURNING P_COD_RET;

set isolation to dirty read;
foreach 
	
         
	SELECT  a.num_credito, a.numcte, b.email, e.monto, e.fecha_mov
		INTO  pnumcredito, pnumcte, pemail, pmonto, pfechamov
    FROM bdicred:sd_maecred a
		inner join bdinteg:si_ctepf b on ( b.empresa=a.empresa and b.numcte = a.numcte)
		join bdicred:sd_movhis e on (  e.empresa = a.empresa  and e.num_credito = a.num_credito)
    WHERE  a.status_cred = 'AA' 
       and e.fecha_mov = pfechaarmada
	   and nvl(e.monto,0) > 5000
       and e.codigo_fun = 002
	   and e.codigo_ref IN (50,30,40,41,42,34,35,36,60,61,62,63,64, 37,57)
	and e.reversado='N'	   
       AND nvl(b.email, '') <> '' 
       group by a.num_credito, a.numcte, b.email, e.monto, e.fecha_mov
    
    call "informix".sp_mail_inserta_cliente (pempresa,1, pnumcte, pnumcredito, pemail,pmonto,0,30,0,null,null,pfechamov,0,0)
    returning P_COD_RET;
    let P_COD_RET = '000000';

end foreach
	call   bdicobranza:"informix".sp_inserta_mensaje('001',1,0,30)
	RETURNING P_COD_RET;
            let P_COD_RET = '000000';  	  

    CALL bdicobranza:"informix".sp_inserta_bitacora_cob(pempresa, cProceso, cCod_ret, cMensaje, '03')
        RETURNING P_COD_RET;
end
    RETURN P_COD_RET;
END PROCEDURE;

create procedure "informix".sp_mail_remanentepagmin(pempresa char (3),pfechacorte date)
returning VARCHAR(6);
--DEFINE pempresa          char(3);
DEFINE pnumcredito       char(20);
DEFINE pnumcte		 char(20);
DEFINE pemail		 char (60);
DEFINE pmontofinanciado  decimal(18,2);
DEFINE pfechaact         date;
DEFINE pfechaant         date;
DEFINE pfechahoy         date;

--DEFINE vempresa  char(3);
DEFINE cProceso  char(4);
DEFINE cCod_ret  smallint;
DEFINE cMensaje  char (100); 
DEFINE pdia      date; 
DEFINE pfechaarmada date; 
 


DEFINE SQL_ERR            INTEGER;
DEFINE ISAM_ERR           INTEGER;
DEFINE ERROR_INFO         VARCHAR(80);
DEFINE P_COD_RET          VARCHAR(6);
DEFINE P_MENSAJE          VARCHAR(80);

BEGIN 
  
    ON exception SET SQL_ERR, ISAM_ERR, ERROR_INFO
    CALL bdicobranza:"informix".sp_inserta_bitacora_cob(pempresa, cProceso, P_COD_RET, P_MENSAJE, '02')
        RETURNING P_COD_RET;
        LET P_COD_RET = SQL_ERR;
        LET P_MENSAJE = ERROR_INFO;
    RETURN P_COD_RET;
    END exception;
 
    let P_COD_RET = '111111';
    let cCod_ret = '';
    let cMensaje = '';
    let cProceso = '2022';
	
	--valida parametros
	IF NVL (pempresa, '') = '' THEN
        LET cCod_Ret= '104002';
        SELECT descripcion
        INTO cMensaje
        FROM cb_errores
        WHERE origen = 3
        AND codigo_error = cCod_Ret;
	
        IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
        END IF;

        CALL bdicobranza:"informix".sp_inserta_bitacora_cob(pempresa, cProceso, cCod_ret, cMensaje, '01');
        Return cCod_Ret;
	END IF;
	
	IF NVL (pfechacorte, '') = '' THEN
        LET cCod_Ret= '104008';        SELECT descripcion
        INTO cMensaje
        FROM cb_errores
        WHERE origen = 3
        AND codigo_error = cCod_Ret;
	
       IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
        END IF;

        CALL bdicobranza:"informix".sp_inserta_bitacora_cob(pempresa, cProceso, cCod_ret, cMensaje, '01');
        Return cCod_Ret;
	END IF;
		
	
    Select Fecha_Hoy
    Into pfechahoy
    From bdicred:sd_fechas
    Where empresa = pempresa ;

    delete from bdicobranza:cb_mail_cliente where fecha_insert = pfechahoy and tipo_mensaje = 1 and pagos_vencidos= 31;     
    select limit 1 dia_corte into pdia from bdicred:sd_maecredanexo where empresa = pempresa ;
     
   
   let pfechaarmada = mdy(month(pfechacorte),day(pdia),year(pfechacorte));
   let pfechaact = date(pfechacorte);

   if (pfechacorte <= pfechaarmada) then
        let pfechaant = date (pfechaarmada) - 1 units month + 1 units day;
   end if;
   if (pfechacorte > pfechaarmada ) then
        let pfechaant = date (pfechaarmada) + 1 units day;
   end if;   

	
   CALL bdicobranza:"informix".sp_inserta_bitacora_cob(pempresa, cProceso, cCod_ret, cMensaje, '01')
        RETURNING P_COD_RET;

set isolation to dirty read;
foreach 
     
    SELECT   a.num_credito, a.numcte, b.email, f.monto_financiado Pago_minimo
        INTO  pnumcredito, pnumcte, pemail, pmontofinanciado
	FROM bdicred:sd_maecred a
		inner join bdinteg:si_ctepf b on ( b.empresa=a.empresa and b.numcte = a.numcte)
		join bdicred:sd_maecredanexo d on (  d.empresa = a.empresa  and d.num_credito = a.num_credito)
		join bdicred:sd_maesdos f on (f.empresa = a.empresa and f.num_credito = a.num_credito)
    WHERE  a.status_cred = 'AA' 
       AND nvl(b.email, '') <> ''
       and d.fecha_ult_pago between pfechaant and  pfechaact
       and f.monto_financiado > 0
	   

    call "informix".sp_mail_inserta_cliente (pempresa,1, pnumcte, pnumcredito, pemail,pmontofinanciado,0,31,0,null,null,null,0,0)
    returning P_COD_RET;
    let P_COD_RET = '000000';

end foreach
	 call  "informix".sp_inserta_mensaje('001',1,0,31) RETURNING P_COD_RET;
            let P_COD_RET = '000000';  	  

    CALL bdicobranza:"informix".sp_inserta_bitacora_cob(pempresa, cProceso, cCod_ret, cMensaje, '03')
    RETURNING P_COD_RET;
end
    RETURN P_COD_RET;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_compac_consultacompromisosvigente_ofi( pEmpresa CHAR(3), pNumCuenta CHAR(20))
RETURNING CHAR(5)       AS Codigo_Retorno,
          CHAR(80)      AS Mensaje_Retorno,
          DATE          AS Fecha_Convenio,
          DATE          AS Fecha_Vencimiento,
          DECIMAL(14,2) AS Importe,
          CHAR (3)      AS Origen;
--definicion de variables
DEFINE iSqlErr      	           INTEGER;
DEFINE iIsamErr                    INTEGER;
DEFINE cErrorInfo                  CHAR(80);
DEFINE Codigo_Retorno              CHAR(5); 
DEFINE Mensaje_Retorno             CHAR(80); 
DEFINE Fecha_Convenio              DATE;
DEFINE Fecha_Vencimiento           DATE;
DEFINE Importe                     DECIMAL;
DEFINE Origen                      CHAR(3);

--inicializacion de variables	  
LET iSqlErr                  = 0;
LET iIsamErr                 = 0;
LET cErrorInfo               = '';
LET Codigo_Retorno           = '';
LET Mensaje_Retorno          = '';
LET Fecha_Convenio          = DATE(1);
LET Fecha_Vencimiento       = DATE(1);
LET Importe                 = 0;  
LET Origen                  = '';

--Set debug file to '/home/sysifx/jesusm/sp_debug_OFI.out';
--trace on;	


SET ISOLATION TO DIRTY READ;
SET LOCK MODE TO WAIT 3;

BEGIN

    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
          LET Codigo_Retorno= iSqlErr;
          LET Mensaje_Retorno= cErrorInfo;
          RETURN  Codigo_Retorno,Mensaje_Retorno,Fecha_Convenio,Fecha_Vencimiento,Importe,Origen;
       END IF;
    END EXCEPTION;

	EXECUTE PROCEDURE sp_compac_consultacompromisosvigente( pEmpresa , pNumCuenta)
					INTO Codigo_Retorno,Mensaje_Retorno,Fecha_Convenio,Fecha_Vencimiento,Importe,Origen;
					
    RETURN  Codigo_Retorno,Mensaje_Retorno,Fecha_Convenio,Fecha_Vencimiento,Importe,Origen;
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_compac_obtenerrechazosconvenio(pEmpresa char(3))
RETURNING CHAR(5)  AS Codigo_Retorno,
          CHAR(80) AS Mensaje_Retorno,
		  CHAR(100) AS Descripcion;   
		  
--definicion de variables
DEFINE cCodRet           CHAR(5); 
DEFINE cMensajeRet       CHAR(80);
DEFINE iSqlErr      	 INTEGER;
DEFINE iIsamErr          INTEGER;
DEFINE iCont	          INTEGER;
DEFINE cErrorInfo        CHAR(80);
DEFINE vDescripcion      CHAR(100);


--inicializacion de variables	  
LET iSqlErr                  = 0;
LET iCont                  = 0;
LET iIsamErr                 = 0;
LET cErrorInfo               = '';
LET cCodRet                  = '00000';
LET cMensajeRet              = 'Se realizó la consulta correctamente';	  
LET vDescripcion              = '';	  
		  
		  
BEGIN

ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
   IF iSqlErr != 0 THEN
      LET cCodRet= iSqlErr;
      LET cMensajeRet= cErrorInfo;
      RETURN cCodRet, cMensajeRet,vDescripcion;
   END IF;
END EXCEPTION;

--Set debug file to '/home/sysifx/jesusm/sp_debug.out';
--trace on;		  

SET ISOLATION TO DIRTY READ;
SET LOCK MODE TO WAIT 3;

IF pEmpresa IS NULL OR TRIM(pEmpresa) = "" THEN
    LET cCodRet                  = '00001';
	LET cMensajeRet              = 'El parametro Empresa no es valido';
    RETURN cCodRet, cMensajeRet,vDescripcion;
END IF;

FOREACH WITH HOLD
	SELECT descripcion 
	  INTO  vDescripcion
	  FROM bdicobranza:cb_param_campania
	 WHERE tipo_campania=10
	   AND grupo_parametro='MOTRCOMPAC'
	   AND empresa=pEmpresa	
	
	RETURN cCodRet, cMensajeRet,vDescripcion WITH RESUME;		
END FOREACH;

	LET iCont = dbinfo("sqlca.sqlerrd2");
	IF iCont = 0 THEN
		LET cCodRet = '00002';
		LET cMensajeRet = 'No se encontraron registros';
		RETURN cCodRet, cMensajeRet,vDescripcion;
	END IF;
	
END
END PROCEDURE
