LET vproceso	            = '2032';
LET pusuario                = USER;
LET cruta                   = "";
LET cnombre		    = "";
LET cnomarchivo             = "";
LET cnomarchivo1            = "";
LET cnumcte                 = "";
LET cSQL                    = "";
LET cSQL1                   = "";
LET cSQL2                   = "";
LET cSQL3                   = "";
LET cempresa                = "001";
LET cdelimitador            = "";
LET cCod_RetIB              = "000000";
LET num = 0;
LET contar = 0;

BEGIN

    ON EXCEPTION SET sql_err, isam_err, error_info
	        LET cCod_ret = sql_err;
            LET cMensaje = error_info;
            CALL bdicobranza:"informix".inserta_bitacora_cob(cempresa, vproceso, cCod_ret, cMensaje, '02');
        RETURN cCod_ret;
	END EXCEPTION;

	--Directiva para lectura de tablas bloqueadas.
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;

    CALL bdicobranza:"informix".inserta_bitacora_cob(cempresa, vproceso, cCod_ret, cMensaje, '01');
	
	
	--Obtener caracter delimitador
	SELECT trim(valor_alfabetico)
	INTO cdelimitador
	FROM bdicobranza:cb_param_campania
	WHERE empresa = cempresa
	AND tipo_campania = 1
	AND grupo_parametro = 'ARCHIVOS'
	AND num_parametro = 25;
	
	--Valida que exista el caracter
	IF NVL(cDelimitador,'') = '' THEN
        LET cCod_Ret= '104004';
        SELECT descripcion
        INTO cMensaje
        FROM cb_errores
        WHERE origen = 3
        AND codigo_error = cCod_Ret;
	
        IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
        END IF;

        CALL bdicobranza:"informix".inserta_bitacora_cob(cempresa, vproceso, cCod_ret, cMensaje, '01');
        Return cCod_Ret;
	END IF;
	
	--Obtener ruta del archivo
	SELECT TRIM(valor_alfabetico)
	INTO cruta
	FROM bdicobranza:cb_param_campania
	WHERE empresa = cempresa
	AND tipo_campania = 1
	AND grupo_parametro = 'ARCHIVOS'
	AND num_parametro = 38;	
	--Valida que exista la carpeta
	IF NVL (cruta,'') = '' THEN
        LET cCod_Ret= '104005';
        SELECT descripcion
        INTO cMensaje
        FROM cb_errores
        WHERE origen = 3
        AND codigo_error = cCod_Ret;
	
        IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
        END IF;

       CALL bdicobranza:"informix".inserta_bitacora_cob(cempresa, vproceso, cCod_ret, cMensaje, '01');
       Return cCod_Ret;
	END IF;
	
	let cnombre = 'correos_mora';
	FOR i in (1 to 5)
	
	LET num = 0;
	select count(*) into contar from bdicobranza:cb_mail_cliente  where tipo_mensaje = 1  and pagos_vencidos = i;
	if (contar <= 1000) then
		LET contar = 1;
	else
		LET contar = contar / 1000;
		let contar = (substr(contar, 0,1))+1;
	end if;
	
	
	for x in (1 to contar )
	
	--Validar que existe el archivo
    LET cnomarchivo1 =  trim(cnombre)||'Aux'||'.txt';
    LET cnomarchivo =  trim(cnombre)||i||x||'.txt';
	LET cSQL1 = ' echo "SET ISOLATION TO DIRTY READ; UNLOAD TO ' || TRIM(cruta) || TRIM(cnomarchivo1) || ' DELIMITER ' || ''''|| cdelimitador || ''''||'';
   
	
		LET cSQL2 = " SELECT skip "||num||" LIMIT 1000 trim('rcpt to:<')||trim(email)||trim('>')"
		||  " from bdicobranza:cb_mail_cliente"
		|| " where tipo_mensaje = 1 "
		|| " and pagos_vencidos =  '"||i||"'"
		|| " order by numcte ";
	   
		let num = num + 1000;
   
	LET cSQL3 = '">'||TRIM(cRuta)||'Ejecuta_archivo.sql';

    LET cSQL = trim(cSQL1) || cSQL2 || trim(cSQL3);
    System cSQL;

    LET cSQL='chmod 777 '|| TRIM(cRuta)||'Ejecuta_archivo.sql';
    System cSQL;

    let cSQL = 'dbaccess bdicobranza ' || TRIM(cRuta) || 'Ejecuta_archivo.sql';
    System cSQL;

    LET cSql = cSql;
    LET cSql = "sed 's/"||cDelimitador||"$//g' "|| TRIM(cRuta) || TRIM(cnomarchivo1) || " >> " || TRIM(cRuta) || TRIM(cnomarchivo);
    SYSTEM cSql;
	--Borra el archivo de control.
	LET cSQL = '' ;
	LET cSQL = 'rm ' || TRIM(cruta) || 'Ejecuta_archivo.sql';
	SYSTEM cSQL;

    LET cSQL = '' ;
	LET cSQL = 'rm ' || TRIM(cruta) || cnomarchivo1;
	SYSTEM cSQL;  
	
	end for
	END FOR

	CALL bdicobranza:"informix".inserta_bitacora_cob(cempresa, vproceso, cCod_ret, cMensaje, '03');
	RETURN cCod_ret;
	
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_calculacobranza(	pCampania SMALLINT,
													pVencido_min INTEGER,
													pVencido_max INTEGER,
													pImporte_min DECIMAL(18,2),
													pImporte_max DECIMAL(18,2),
													pFecha_ejec DATE,
													pSituacion CHAR(7),
													pCausa SMALLINT)

	RETURNING 	CHAR(6) AS CODRET, INTEGER AS REG,
				DECIMAL(18,2) AS IMP_MIN,
				DECIMAL(18,2)AS IMP_MAX,
				DECIMAL(18,2)AS VENC_MIN,
				DECIMAL(18,2) AS  VENC_MAX;

	---Elaborado por: Lorenzo Ibarra Garcia
	--Fecha: 05-10-2009
	--Objetivo: Obtener el número total de registros para las diferentes campañas del CAT filtrando por los parámetros.
	--Modifico: Armida Pazos
	--Fecha:07/12/09
	--Se modifico para agregar la campaña de os telefonica

	--Modifico:Adilene Lara
	--Fecha:03-03-2010
	--Se modifica para realizar el filtrado por el campo pago_min.
	--Se modifica para que cada campaña obtenga el importe minimo e importe maximo,
	--ademas de obtener el vencido minimo y el vencido maximo de su respectiva tabla.
	--Se modifica para que reciba como parametros los campos de situacion y causa.
	--Fecha: 15-04-2010
	--Se modifica para excluir a los clientes que contenga el apellido o nombre coppel.

	--Fecha 16-04-2010
	--Se modifica para que cuando el parametro situacion sea "Todas" muestre el resultado sin importar si tiene o no una situacion especial y causa.

	--SE DEFINEN VARIABLES.
	DEFINE vcodret             						CHAR(6);
	DEFINE vsqlerr             						INTEGER;
	DEFINE vRegistros          						INTEGER;

	DEFINE iCampaniaAdministrativa 					SMALLINT;
	DEFINE iCampaniaPreventiva 						SMALLINT;
	DEFINE iCampaniaostel 							SMALLINT;
	DEFINE iCampaniaAuronix 						SMALLINT;
	DEFINE iCampaniaTargetPhone 					SMALLINT;

	DEFINE iCampaniaPagoMinimoIncompleto			SMALLINT;
	DEFINE iCampaniaTdcPorEntregar       			SMALLINT;
	DEFINE iCampaniaFechaPagoReestructura 			SMALLINT;
	DEFINE iCampaniaPagoTotalReestructura 		 	SMALLINT;
	DEFINE iCampaniaReestructuraVencidos  			SMALLINT;
	
	DEFINE iCampaniaPrestamoPersonalDeposito 		SMALLINT;
	DEFINE iCampaniaPrestamoPersonalPagoCompleto	SMALLINT;
	DEFINE iCampaniaPrestamoPrsonalMoratorios		SMALLINT;
	


	DEFINE vSituacion  					CHAR(1);
	DEFINE iCausa       				SMALLINT;

	DEFINE vImp_min 					DECIMAL(18,2);
	DEFINE vImp_max 					DECIMAL(18,2);
	DEFINE v_fecha  					DATE;

	DEFINE iVenc_min 					SMALLINT;
	DEFINE iVenc_max 					SMALLINT;


	--SE INICIALIZAN VARIABLES.
	LET vcodret 								= '000';
	LET vsqlerr 								= 0;
	LET vRegistros 								= 0;

	LET iCampaniaAdministrativa 				= 1;
	LET iCampaniaPreventiva 					= 2;
	LET iCampaniaostel 							= 3;
	LET iCampaniaAuronix 						= 4;
	LET iCampaniaTargetPhone 					= 5;

	LET iCampaniaPagoMinimoIncompleto			= 7;
	LET iCampaniaTdcPorEntregar       			= 8;
	LET iCampaniaFechaPagoReestructura 			= 9;
	LET iCampaniaPagoTotalReestructura  		= 10;
	LET iCampaniaReestructuraVencidos  			= 11;
	
	LET iCampaniaPrestamoPersonalDeposito 		= 12;
	LET iCampaniaPrestamoPersonalPagoCompleto 	= 13;
	LET iCampaniaPrestamoPrsonalMoratorios		= 14;

	LET vSituacion 						= '';
	LET iCausa 							= 0;

	LET vImp_min 						= 0;
	LET vImp_max						= 0;

	LET iVenc_max 						= 0;
	LET iVenc_min 						= 0;


	--SET DEBUG FILE TO '/home/sysifx/SPs PAYAN/"informix"sp_calculacobranza.out';
	--TRACE ON;

	BEGIN
		ON EXCEPTION SET vsqlerr
			IF vsqlerr <> 0 THEN
				LET vcodret = vsqlerr;
				RETURN vcodret, vRegistros, vImp_min, vImp_max, iVenc_min, iVenc_max;
			END IF;
		END EXCEPTION;

		SET LOCK MODE TO WAIT 3;

		IF pCampania IS NULL OR pVencido_min IS NULL OR pVencido_max IS NULL OR pImporte_min IS NULL OR pImporte_max IS NULL THEN
			LET vcodret = '001'; -- Parametros no validos
			RETURN vcodret, vRegistros, vImp_min, vImp_max, iVenc_min, iVenc_max;
		END IF;

		IF pSituacion = 'Ninguna' THEN
			Let pSituacion = NULL;
		END IF;

		IF pCausa = 0 THEN
			Let pCausa = NULL;
		END IF;


		IF pCampania NOT IN (	iCampaniaAdministrativa, iCampaniaPreventiva, iCampaniaAuronix, iCampaniaostel,
								iCampaniaTargetPhone,iCampaniaPagoMinimoIncompleto, iCampaniaTdcPorEntregar,
								iCampaniaFechaPagoReestructura, iCampaniaPagoTotalReestructura,
								iCampaniaReestructuraVencidos,iCampaniaPrestamoPersonalDeposito, 
								iCampaniaPrestamoPersonalPagoCompleto, iCampaniaPrestamoPrsonalMoratorios ) THEN
			LET vcodret = '002'; -- campaña no valida

		Elif pCampania = iCampaniaAdministrativa THEN
			IF pSituacion = 'Todas' AND pCausa IS NULL THEN
				SELECT COUNT(pago_venc)
				INTO vRegistros
				FROM bdicobranza:"informix".cb_info_administrativa
				WHERE pago_venc >= pVencido_min AND pago_venc <= pVencido_max
					AND pago_min >= pImporte_min AND pago_min <= pImporte_max
					AND UPPER(TRIM (nombre1)|| TRIM (nombre2)|| TRIM (apell_paterno)|| TRIM (apell_materno)) NOT LIKE "%COPPEL%"
					AND fecha_ejecucion = pFecha_ejec
					AND num_campania = iCampaniaAdministrativa;  --Se agrego Filtro para campania 1.

				SELECT MIN(pago_min), MAX(pago_min)
				INTO vImp_min, vImp_max
				FROM bdicobranza:"informix".cb_info_administrativa
				WHERE pago_venc >= pVencido_min AND pago_venc <= pVencido_max
					AND pago_min >= pImporte_min AND pago_min <= pImporte_max
					AND UPPER(TRIM (nombre1)|| TRIM (nombre2)|| TRIM (apell_paterno)|| TRIM (apell_materno)) NOT LIKE "%COPPEL%"
					AND fecha_ejecucion = pFecha_ejec
					AND num_campania = iCampaniaAdministrativa;  --Se agrego Filtro para campania 1.

				SELECT MIN(pago_venc), MAX(pago_venc)
				INTO iVenc_min, iVenc_max
				FROM bdicobranza:"informix".cb_info_administrativa
				WHERE pago_venc >= pVencido_min AND pago_venc <= pVencido_max
					AND pago_min >= pImporte_min AND pago_min <= pImporte_max
					AND UPPER(TRIM (nombre1)|| TRIM (nombre2)|| TRIM (apell_paterno)|| TRIM (apell_materno)) NOT LIKE "%COPPEL%"
					AND fecha_ejecucion = pFecha_ejec
					AND num_campania = iCampaniaAdministrativa;  --Se agrego Filtro para campania 1.

			ELSE
				SELECT COUNT(pago_venc)
				INTO vRegistros
				FROM bdicobranza:"informix".cb_info_administrativa
				WHERE pago_venc >= pVencido_min AND pago_venc <= pVencido_max
					AND pago_min >= pImporte_min AND pago_min <= pImporte_max
					AND UPPER(TRIM (nombre1)|| TRIM (nombre2)|| TRIM (apell_paterno)|| TRIM (apell_materno)) NOT LIKE "%COPPEL%"
					AND NVL(causa,0) = NVL(pCausa,0) AND NVL(situacion,'') = NVL(pSituacion,'')
					AND fecha_ejecucion = pFecha_ejec
					AND num_campania = iCampaniaAdministrativa;  --Se agrego Filtro para campania 1.

				SELECT MIN(pago_min), MAX(pago_min)
				INTO vImp_min, vImp_max
				FROM bdicobranza:"informix".cb_info_administrativa
				WHERE pago_venc >= pVencido_min AND pago_venc <= pVencido_max
					AND pago_min >= pImporte_min AND pago_min <= pImporte_max
					AND UPPER(TRIM (nombre1)|| TRIM (nombre2)|| TRIM (apell_paterno)|| TRIM (apell_materno)) NOT LIKE "%COPPEL%"
					AND NVL(causa,0) = NVL(pCausa,0) AND NVL(situacion,'') = NVL(pSituacion,'')
					AND fecha_ejecucion = pFecha_ejec
					AND num_campania = iCampaniaAdministrativa;  --Se agrego Filtro para campania 1.

				SELECT MIN(pago_venc), MAX(pago_venc)
				INTO iVenc_min, iVenc_max
				FROM bdicobranza:"informix".cb_info_administrativa
				WHERE pago_venc >= pVencido_min AND pago_venc <= pVencido_max
					AND pago_min >= pImporte_min AND pago_min <= pImporte_max
					AND UPPER(TRIM (nombre1)|| TRIM (nombre2)|| TRIM (apell_paterno)|| TRIM (apell_materno)) NOT LIKE "%COPPEL%"
					AND NVL(causa,0) = NVL(pCausa,0) AND NVL(situacion,'') = NVL(pSituacion,'')
					AND fecha_ejecucion = pFecha_ejec
					AND num_campania = iCampaniaAdministrativa;  --Se agrego Filtro para campania 1.
			END IF

		Elif pCampania = iCampaniaPreventiva THEN
			IF pSituacion = 'Todas' AND pCausa IS NULL THEN

				SELECT COUNT(vencido)
				INTO vRegistros
				FROM bdicobranza:"informix".cb_info_preventiva
				WHERE vencido >= pVencido_min AND vencido <= pVencido_max
					AND pago_min >= pImporte_min AND pago_min <= pImporte_max
					AND UPPER(nombre) NOT LIKE "%COPPEL%"
					AND fecha_ejecucion = pFecha_ejec;


				SELECT MIN(pago_min), MAX(pago_min)
				INTO vImp_min, vImp_max
				FROM bdicobranza:"informix".cb_info_preventiva
				WHERE vencido >= pVencido_min AND vencido <= pVencido_max
					AND pago_min >= pImporte_min AND pago_min <= pImporte_max
					AND UPPER(nombre) NOT LIKE "%COPPEL%"
					AND fecha_ejecucion = pFecha_ejec;


				SELECT MIN(vencido), MAX(vencido)
				INTO iVenc_min, iVenc_max
				FROM bdicobranza:"informix".cb_info_preventiva
				WHERE vencido >= pVencido_min AND vencido <= pVencido_max
					AND pago_min >= pImporte_min AND pago_min <= pImporte_max
					AND UPPER(nombre) NOT LIKE "%COPPEL%"
					AND fecha_ejecucion = pFecha_ejec;


			ELSE

				SELECT COUNT(vencido)
				INTO vRegistros
				FROM bdicobranza:"informix".cb_info_preventiva
				WHERE vencido >= pVencido_min AND vencido <= pVencido_max
					AND pago_min >= pImporte_min AND pago_min <= pImporte_max
					AND UPPER(nombre) NOT LIKE "%COPPEL%"
					AND NVL(causa,0) = NVL(pCausa,0) AND NVL(situacion,'') = NVL(pSituacion,'')
					AND fecha_ejecucion = pFecha_ejec;


				SELECT MIN(pago_min), MAX(pago_min)
				INTO vImp_min, vImp_max
				FROM bdicobranza:"informix".cb_info_preventiva
				WHERE vencido >= pVencido_min AND vencido <= pVencido_max
					AND pago_min >= pImporte_min AND pago_min <= pImporte_max
					AND UPPER(nombre) NOT LIKE "%COPPEL%"
					AND NVL(causa,0) = NVL(pCausa,0) AND NVL(situacion,'') = NVL(pSituacion,'')
					AND fecha_ejecucion = pFecha_ejec;


				SELECT MIN(vencido), MAX(vencido)
				INTO iVenc_min, iVenc_max
				FROM bdicobranza:"informix".cb_info_preventiva
				WHERE vencido >= pVencido_min AND vencido <= pVencido_max
					AND pago_min >= pImporte_min AND pago_min <= pImporte_max
					AND UPPER(nombre) NOT LIKE "%COPPEL%"
					AND NVL(causa,0) = NVL(pCausa,0) AND NVL(situacion,'') = NVL(pSituacion,'')
					AND fecha_ejecucion = pFecha_ejec;

			END IF

		Elif pCampania = iCampaniaAuronix THEN
			SELECT NVL(MAX(fecha_ejecucion),'01/01/1900')
			INTO v_fecha
			FROM bdicobranza:"informix".cb_info_administrativa;

			IF pSituacion = 'Todas' AND pCausa IS NULL THEN

				SELECT COUNT(pago_venc)
				INTO vRegistros
				FROM bdicobranza:"informix".cb_info_administrativa
				WHERE pago_venc >= pVencido_min AND pago_venc <= pVencido_max
					AND pago_min >= pImporte_min AND pago_min <= pImporte_max
					AND UPPER(TRIM (nombre1)|| TRIM (nombre2)|| TRIM (apell_paterno)|| TRIM (apell_materno)) NOT LIKE "%COPPEL%"
					AND fecha_ejecucion = v_fecha
					AND num_campania = iCampaniaAuronix;  --Se agrego Filtro para campania 4.

				SELECT MIN(pago_min), MAX(pago_min)
				INTO vImp_min, vImp_max
				FROM bdicobranza:"informix".cb_info_administrativa
				WHERE pago_venc >= pVencido_min AND pago_venc <= pVencido_max
