'AUTOR: Marco A. Campos 2012-02-21';

CREATE PROCEDURE "informix".sp_cat_ivr_gen_arcctesexcluidos(pEmpresa  CHAR(3),
                                                           pFecha_ex DATE)
RETURNING CHAR(6) AS codigo_retorno;


-- 'AUTOR : Abrham Lopez Lopez.', 'FECHA : 22/JUNIO/2010', 'BD    : BDICOBRANZA';
-- 'El SP genera un archivo que extrae información de los clientes excluidos para campaña IVR',
-- Modificado por: MAHR. Abril 2012. Se asigna proceso: 2002, a fin de no repetir numero asignado con otros proceso.

          
DEFINE cCodRet             CHAR(6); 
DEFINE cMensajeRet         CHAR(80);
DEFINE iSqlErr             INTEGER;
DEFINE iIsamErr            INTEGER;
DEFINE cErrorInfo          CHAR(80);
DEFINE cSql                CHAR(2204);
DEFINE cNombreArchivo1     CHAR(50);
DEFINE cNombreArchivo      CHAR(50);
DEFINE cRuta               CHAR(100);
DEFINE iNumreg             INTEGER;
DEFINE iDatos              INTEGER;
DEFINE cEmpresa            CHAR(3);
DEFINE cNombre             CHAR(100);
DEFINE cdelimitador        CHAR(1);
DEFINE cValor_status       CHAR(20);
DEFINE cHora               CHAR(8);
DEFINE cUsuario            CHAR(8);
DEFINE cSql1               CHAR(100);
DEFINE cSql2               CHAR(2004);
DEFINE cSql3               CHAR(100);
DEFINE dDia                DATE;
DEFINE cFechaGenArchivo    CHAR(8);
DEFINE cCodRetIB           CHAR(6);
DEFINE cMensaje            CHAR(80);
DEFINE cProceso            CHAR(4);


LET iSqlErr                = 0;
LET iIsamErr               = 0;
LET cErrorInfo             = "";
LET cCodRet                = "000000";
LET cRuta                  = "";
LET cNombreArchivo1        = "";
LET cNombreArchivo         = "";
LET iNumreg                = 0;
LET iDatos                 = 0;
LET cEmpresa               = "";
LET cNombre                = '';
LET cdelimitador           = '';
LET cSql                   = "";
LET cValor_status          = "";
LET cHora                  = "";
LET dDia                   = DATE(1);
LET cMensajeRet            = 'PROCESO EXITOSO';
LET cProceso               = '2002';
LET cUsuario               = USER;
LET cSql1                  = "";
LET cSql2                  = "";
LET cSql3                  = "";
LET cFechaGenArchivo       = "";
LET cCodRetIB              = "000000";
LET cMensaje               = "";

BEGIN

    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
        IF iSqlErr != 0 THEN
            LET cCodRet     = iSqlErr;
            LET cMensajeRet = cErrorInfo;
            EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensajeRet,"02")
                     INTO cCodRetIB;
            RETURN cCodRet; 
        END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    --SET DEBUG FILE TO '/home/syscobra/cat/envios/sp_ctbcpl_gen_arcctesexcluidos.out';
    --TRACE ON;

    -- Inserta bitacora de procesos
    EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,"","","01")
             INTO cCodRetIB;
        
    -- Validacion de los datos de entrada
    IF NVL(pEmpresa,"") = "" THEN
        LET cCodRet     = "104007";
        SELECT descripcion
            INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen        = 3
            AND codigo_error    = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensaje,"02")
                 INTO cCodRetIB;
        RETURN cCodRet;
    END IF;
    
    SELECT empresa
        INTO cEmpresa 
        FROM bdinteg:si_empresas
        WHERE empresa = pEmpresa;
    
    IF NVL(cEmpresa,"")= "" then
        LET cCodRet = "104002";
        SELECT descripcion
            INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
            AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensaje,"02")
                 INTO cCodRetIB;
        RETURN cCodRet;
    END IF;

    IF NVL(pFecha_ex,"") = "" THEN
        LET cCodRet     = "104008";
        SELECT descripcion
            INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
            AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensaje,"02")
                 INTO cCodRetIB;
        RETURN cCodRet;
    END IF;

    -- obtener la ruta donde se almacenara el archivo que sera enviado a buro de credito
    SELECT valor_alfabetico 
        INTO cRuta
        FROM bdicobranza:cb_param_campania
        WHERE empresa         = pEmpresa
        AND tipo_campania   = '1'
        AND grupo_parametro = 'ARCHIVOS'
        AND num_parametro   = 3;
        
    IF NVL(cRuta,"")    = "" THEN
        LET cCodRet     = "104005";
        SELECT descripcion
            INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
            AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensaje,"02")
                  INTO cCodRetIB;
        RETURN cCodRet;
    END IF;

    -- Se obtiene del nombre del archivo
    SELECT valor_alfabetico 
        INTO cNombre
        FROM bdicobranza:cb_param_campania
        WHERE empresa         = pEmpresa
        AND tipo_campania   = '1'
        AND grupo_parametro = 'ARCHIVOS'
        AND num_parametro   = 28;

    IF NVL(cNombre,"") = "" THEN
        LET cCodRet = "104006";
        SELECT descripcion
            INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
            AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensaje,"02")
                     INTO cCodRetIB;
        RETURN cCodRet;
    END IF;


    --Obtener caracter delimitador
    SELECT trim(valor_alfabetico)
        INTO cdelimitador
        FROM bdicobranza:cb_param_campania
        WHERE empresa = pempresa
        AND tipo_campania = 1
        AND grupo_parametro = 'ARCHIVOS'
        AND num_parametro = 25;
    
	IF NVL(cdelimitador,"") = "" THEN
        LET cCodRet     = "104004";
        SELECT descripcion
            INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
            AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensaje,"02")
                     INTO cCodRetIB;
        RETURN cCodRet;
    END IF;
     
	LET cNombreArchivo1 = 'prueba.txt';
    LET cNombreArchivo  = TRIM(cNombre) || LPAD(TRIM(DAY(pFecha_ex)::CHAR(2)),2,'0') || LPAD(TRIM(MONTH(pFecha_ex)::CHAR(2)),2,'0') || YEAR(pFecha_ex) || '.txt';
   
    FOREACH
        SELECT trim(valor_alfabetico)
	    INTO cValor_status
		FROM bdicobranza:cb_param_campania
		WHERE empresa         = pEmpresa
		AND tipo_campania   = '1'
        AND grupo_parametro = 'STATARCHCE'
        AND valor_alfabetico IN ('EX','IN', 'AC')  -- mahr. solo se contemplan estos status para CAT
     
		SELECT COUNT (numcte)
            INTO iNumreg
			FROM bdicobranza:cb_cat_directorio_cte
			WHERE status_cliente       = cValor_status
			AND fecha_modificacion   = pFecha_ex
		    AND empresa              = pEmpresa
            AND tipo_cobranza        = 'P';

        IF iNumreg = 0 THEN
            CONTINUE FOREACH;
        END IF;

		LET iDatos = iDatos + 1;
			
		--se ejecuta para ponerle el encabezado
		let cSql='';
		let csql = 'echo "cliente'||','||'nombre'||','||'tipoproducto'||','||'telcasa'||','||'telcelular'||','||
				 'fechalimitepago'||','||'fechacorte'||'">'||TRIM(cruta)|| cNombreArchivo;   
		system csql; 

        -- para generar el archivo 
		LET cSql1 = 'echo "SET ISOLATION TO DIRTY READ; UNLOAD TO ' || TRIM(cRuta) || TRIM (cNombreArchivo1) || " DELIMITER '" || cdelimitador || "'";
				
		LET cSql2 = " select  a.numcte as cliente , "
				|| " trim (h.apell_paterno) ||' '|| trim (h.apell_materno)||' '|| trim(h.nombre1) ||' '|| trim(h.nombre2) as nombre , "
				|| " f.num_producto as tipoproducto, " 
				|| " nvl(b.telefono,' ') as telcasa, "
				|| " nvl((case when d.numero_carrier = 1 then 6 || d.telefono  when d.numero_carrier = 2 then 7 || d.telefono  else 7 || d.telefono end),' ') as telcelular ,1, "
				|| " (e.prox_fecha_pago) as fechalimitepago, "
				|| " (day(e.prox_fecha_pago+4 units day))||'/'||lpad(month(e.prox_fecha_pago),2,'0')||'/'||(year(e.prox_fecha_pago-1 units month))fechacorte "
				|| " from bdicobranza:cb_cat_directorio_cte  a "
				|| " join bdicred:sd_maecred f  on (a.empresa = f.empresa and a.numcte = f.numcte ) "
				|| " join bdinteg:si_cliente h on (h.empresa = a.empresa and h.numcte = a.numcte) "    
				|| " left outer join bdicobranza:cb_telefonos b on ( b.empresa = a.empresa and b.numcte = a.numcte and b.tipo_telefono = 1) "
				|| " left outer join bdicobranza:cb_telefonos d on ( d.empresa = a.empresa and d.numcte = a.numcte and d.tipo_telefono = 2) "
				|| " join bdicred:sd_maecredanexo e   on (e.empresa= a.empresa and e.num_credito = a.num_credito) "
				|| " where a.empresa = '001' "
				|| " and a.tipo_cobranza = 'P' "
                || " and a.status_cliente = '" || trim(cValor_status) || "'"   --  IN ('EX','IN') " -- MAHR
                || " and a.fecha_modificacion  = '" || pFecha_ex || "'"
				|| " and ((nvl(b.telefono,'')<> '') or (nvl(d.telefono,'') <> '')) ";
						
        LET cSql3 = ' " > '|| TRIM(cRuta) || 'Ejecuta_GenArchivoTelefonos.sql';
            
        LET cSql1 = TRIM(cSql1);
        LET cSql3 = TRIM(cSql3);
            
        LET cSql = cSql1 || cSql2 || cSql3;
			
		SYSTEM cSQL;
		--Permiso para la creacion de archivo.
		LET cSQL = '' ;
		LET cSQL = 'chmod 666 ' || TRIM(cRuta) || 'Ejecuta_GenArchivoTelefonos.sql' ;
		LET cSQL = '' ;
		LET cSQL = 'dbaccess bdicobranza ' || TRIM(cRuta) || 'Ejecuta_GenArchivoTelefonos.sql';
		SYSTEM cSQL;
			
		LET cSql = "sed 's/"||cdelimitador||"$//g' "|| TRIM(cRuta) || cNombreArchivo1 || " >> " || TRIM(cRuta) || cNombreArchivo;
        SYSTEM cSql;

		--Borra el archivo de control.
		LET cSQL = '' ;
		LET cSQL = 'rm ' || TRIM(cRuta) || 'Ejecuta_GenArchivoTelefonos.sql';
		SYSTEM cSQL;

		LET cSQL = '' ;
		LET cSQL = 'rm ' || TRIM(cRuta) || cNombreArchivo1;
		SYSTEM cSQL;
		
    END FOREACH;

    -- Por si el archivo no  se genera 
    IF iDatos = 0 THEN
        LET cCodRet = '104009';
        SELECT descripcion
            INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
            AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensaje,"02")
                 INTO cCodRetIB;
        RETURN cCodRet;
    END IF;

    EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensajeRet,"03")
             INTO cCodRetIB;

    RETURN cCodRet;

END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_carga_info_atento()
RETURNING CHAR(6), CHAR(80);

/* 	MARIA ELIZABETH ANZURES IBARGUEN
	06-MARZO-2012
	ARCHIVO QUE CARGA MOVIMEINTOS DEL CAT A TABLA MOVIMIENTOS Y PASA A 
		TABLAS CB-COMPAC CONVENIO Y TELEFONOS A CB_TELEFONOS LOS TELEFONOS NUEVOS DE CLIENTES*/

--DECLARACION DE VARIABLES
	DEFINE sql_err		INTEGER;
	DEFINE isam_err		INTEGER;
	DEFINE error_info	CHAR(80);
	DEFINE cCod_ret		CHAR(6);
	DEFINE vempresa     CHAR(3);
	DEFINE cproceso     CHAR(4);
	DEFINE vvcCod_ret   CHAR(6);
	DEFINE cMensaje		CHAR(80);
	DEFINE cCadena		CHAR(500);
	DEFINE vRuta		CHAR(100);
	DEFINE cSql         CHAR(2204);	
	DEFINE pNomArch 	CHAR(100);
	DEFINE vNomArch		CHAR(100);
	DEFINE X 			CHAR(100);
	DEFINE vfecha 		DATE;
	DEFINE vfecha_cat 	DATE;
	
	----variables
	DEFINE vnumcte					CHAR(20);
	DEFINE vtelefonoreconstruido	CHAR(13);
	DEFINE vtipotelefono			SMALLINT;
	DEFINE vsecuencia				SMALLINT;
	DEFINE vnumext					CHAR(5);
	DEFINE vfinllamada				SMALLINT;
	DEFINE vnumempleado				CHAR(8);
	DEFINE vnumcuenta				CHAR(20);
	DEFINE vplazo					CHAR(2);
	DEFINE vimporte					DECIMAL(18,2);
	DEFINE vtipoconvenio			CHAR(1);
	DEFINE vhorainicio				DATE;

	--SET DEBUG FILE TO "/informix/Elizabeth/sp_carga_info_atento.out ";
	--TRACE ON;

--DEFINICIAON DE VARIABLES
	LET cCod_ret  	= "000000";
	LET sql_err   	= 0;
	LET cMensaje  	= "PROCESO EXITOSO";
	LET cCadena   	= "";
	LET vRuta     	= "";
	LET cSql      	= "";
	LET vempresa    = '001';
	LET cproceso    = '2063';
	LET pNomArch 	= '';
	let vfecha 		= DATE(1);
	let vfecha_cat	= date(1);
	let vNomArch	= '';
	let X ='';
	
	---VARIABLES
	LET vnumcte					='';
	LET vtelefonoreconstruido	='';
	LET vtipotelefono			=0;
	LET vsecuencia				=0;
	LET vnumext					='';
	LET vfinllamada				=0;
	LET vnumempleado			='';
	LET vnumcuenta				='';
	LET vplazo					='';
	LET vimporte				=0;
	LET vtipoconvenio			='';
	LET vhorainicio				=DATE(1);

      BEGIN
  
        ON EXCEPTION SET sql_err, isam_err, error_info
	        LET cCod_ret = sql_err;
			LET cMensaje = error_info;
		  CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje, '02')
            RETURNING vvcCod_ret;
			    RETURN cCod_ret, cMensaje;	    
	    END EXCEPTION;
		
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
		
	--SE MANDA LLAMAR SP PARA INSERTAR EN BITACORA EL INICIO DE LA EJECUCION DE SP
		CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje, '01')
        RETURNING vvcCod_ret;
 
	--SELECCIONAMOS LA FECHA DEL DIA
	select fecha_hoy 
		into vfecha 
	from bdicred:sd_fechas 
	where empresa = '001';

		--SELECCIONAMOS LA RUTA 
    select valor_alfabetico 
		into vRuta 
    from bdicobranza:cb_param_campania
    where empresa = '001'
		and tipo_campania = 1
		and grupo_parametro = 'ARCHIVOS'
		and num_parametro = 36;	
	
	---------------------------------------------CARGAR ARCHIVO A LA TABLA	---------------------------------------------------------------------
	
		--ASIGNAMOS NOMBRE AL ARCHIVO
		LET pNomArch = 'movimientos_atento'|| to_char(vfecha,'%d%m%Y')||'.txt';
		let vNomArch = pNomArch;
--let vRuta = '/informix/Elizabeth/';----PRUEBA	
		--DESCOMPRIMIMOS EL ARCHIVO
		--LET cSql = "gunzip "  || trim(vRuta) || trim(pNomArch); 
       -- system cSql;
	
		--TOMAMOS EL NOMBRE DE ARCHIVO YA DESCOMPRIMIDO SIN LOS 3 ULTIMOS CARACTERES 
		--LET X = length(pNomArch);
		--LET vNomArch = substr(pNomArch,0,X-3);
		
		LET cCadena = 'echo " load from ' || SUBSTR(vRuta,1,LENGTH(vRuta)) || SUBSTR(vNomArch,1,
			LENGTH(vNomArch))  || ' insert into bdicobranza:cb_atento_movimientos " >' || SUBSTR(vRuta,1,LENGTH(vRuta)) || 'catmovimientosctbcpl.sql';
			System SUBSTR(cCadena,1,LENGTH(cCadena));
			let cCadena = 'dbaccess bdicobranza ' || SUBSTR(vRuta,1,LENGTH(vRuta)) || 'catmovimientosctbcpl.sql';
		System SUBSTR(cCadena,1,LENGTH(cCadena));
		  
		--BORRA EL ARCHIVO 
        let cCadena = 'rm ' || SUBSTR(vRuta,1,LENGTH(vRuta)) || 'catmovimientosctbcpl.sql';
        System SUBSTR(cCadena,1,LENGTH(cCadena));
		
		--SE COMPRIME DE NUEVO EL ARCHIVO	
/*		LET cSql = "gzip " || trim(vRuta) || trim(vNomArch); 
*/		system cSql;
	

	---------------------------------CARGAR REGISTROS A TABLAS CORRESPONDINETES------------------------------------------------------------------
	select  max(date(horainicio)) into vfecha_cat
	from bdicobranza:cb_atento_movimientos; 
	
	FOREACH
	--------cb_telefonos-------
	SELECT cliente,tipotelefono,telefonoreconstruido,numext,finllamada,numempleado
		INTO  vnumcte,vtipotelefono,vtelefonoreconstruido,vnumext,vfinllamada,vnumempleado
	FROM  bdicobranza:cb_atento_movimientos
	WHERE DATE(horainicio) =  vfecha_cat and
		 telefonoreconstruido > 0
		AND sucursal = '0000'
		and cvemovimiento = 'T'
	
	select max(secuencia) into vsecuencia
	from bdicobranza:"informix".cb_telefonos 
	where numcte = vnumcte and empresa = '001';
	
	if vsecuencia is null then 
		let vsecuencia = 1;
	else 
		let vsecuencia = vsecuencia + 1;
	end if;
	if not exists (SELECT numcte FROM bdicobranza:"informix".cb_telefonos WHERE numcte= vnumcte AND telefono=vtelefonoreconstruido AND tipo_telefono=vtipotelefono)THEN
	INSERT INTO bdicobranza:"informix".cb_telefonos(empresa, origen, numcte, telefono, tipo_telefono, secuencia, extension, estatus,
		numvecesmarcado, tipored, fultimocontacto, codigo_resultado, quiencontestouc, orden_telefono, fecha_insert, user_insert, fecha_modifica, numero_carrier)
	VALUES('001', 6, vnumcte, vtelefonoreconstruido, vtipotelefono, vsecuencia, vnumext, 'A',
		null, null, NULL, vfinllamada, null, null, vfecha, vnumempleado, NULL, 0);
	END IF;
	END FOREACH;
	
	---------cb_compac----------
	FOREACH
		
	SELECT cliente,tipotelefono,telefonoreconstruido,numext,finllamada,numempleado,tienda,plazo,importe , tipoconvenio,date(horainicio)
		INTO vnumcte,vtipotelefono,vtelefonoreconstruido,vnumext,vfinllamada,vnumempleado,vnumcuenta,vplazo,vimporte , vtipoconvenio,vhorainicio
	FROM  bdicobranza:cb_atento_movimientos
	WHERE DATE(horainicio) = vfecha_cat and
		 plazo > 0 
		and sucursal = '0000'
		and cvemovimiento = 'C' 
		and importe > 0
	
	
	INSERT INTO bdicobranza:"informix".cb_compac(empresa, sucursal, origen, empleado_captura, numcliente, numcuenta, plazo, 
				importe, tipo_compac, activo, flag_pago, efectuo_compac, nombre_efectuo, fecha_compac, fecha_insert,  quien_convenio, nom_convenio, email, referenciacoppel, imp_pagado)
    VALUES('001', '9999', 4, vnumempleado, vnumcte, vnumcuenta, vplazo, 
				vimporte, vtipoconvenio, '1', '0', 0, '', vhorainicio, vhorainicio  + (vplazo * 7) , null,  null, '', '',  NULL);
	END FOREACH;
	
	--SE MANDA LLAMAR SP PARA INSERTAR EN BITACORA EL FINAL DE LA EJECUCION DE SP
		CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje, '03')
		RETURNING vvcCod_ret;
		
RETURN cCod_ret, cMensaje;

END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_compac_genera_reporte(pEmpresa CHAR(3), pTipoReporte INTEGER, pFechaIni DATE, pFechaFin DATE)
RETURNING CHAR(6)  AS codigo_retorno,
          CHAR(80) AS mensaje_retorno,
		  CHAR(80) AS Nombre_archivo; 
---DECLARACIONES
DEFINE cCodRet        	  CHAR(6); 
DEFINE cMensajeRet        CHAR(80);
DEFINE cComentario        CHAR(80);
DEFINE iSqlErr      	  INTEGER;
DEFINE iIsamErr           INTEGER;
DEFINE cErrorInfo         CHAR(80);
DEFINE cNombreArchivo	  CHAR(80);
DEFINE iNumArchivo		  INTEGER;
DEFINE cTipoArchivo	      CHAR(80);
DEFINE cConsulta		  CHAR(2200);
DEFINE cConsulta2		  CHAR(200);
DEFINE cConsulta3		  CHAR(200);
DEFINE cSql		 		  CHAR(3000);
DEFINE cParam1		      CHAR(20);
DEFINE cParam2		      CHAR(20);
DEFINE cParam3		      CHAR(20);
DEFINE cRuta		      CHAR(80);
DEFINE cTabla		      CHAR(1);
DEFINE dtFecha		      DATE;

---INICIALIZACIONES
LET iSqlErr             = 0;
LET iIsamErr            = 0;
LET cErrorInfo          = "";
LET cCodRet             = "000000";
LET cMensajeRet         = "PROCESO EXITOSO";
LET iNumArchivo			= 0;
LET cNombreArchivo		= "reporte";
LET cTipoArchivo     	= "";
LET cConsulta			= "";
LET cConsulta2			= "";
LET cConsulta3			= "";
LET cParam1				= "";
LET cParam2				= "";
LET cParam3				= "";
LET cRuta				= "";
LET cTabla				= "N";
LET dtFecha				= DATE(1);
       
BEGIN

ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
    LET cCodRet= iSqlErr;
	LET cMensajeRet = cErrorInfo;
	IF cTabla="S" THEN
		DROP TABLE TME_ENCABEZADOS;
	END IF;
    RETURN cCodRet, cMensajeRet,"";
END EXCEPTION;

--SET DEBUG FILE TO '/home/sysifx/jesusm/sp_compac_genera_reporte.out';
--TRACE ON;

IF NVL(pEmpresa,"") = "" OR  NVL(pTipoReporte,"") = "" OR  NVL(pFechaIni,"") = "" OR  NVL(pFechaFin,"") = "" THEN
	LET cCodRet= "000001";
	LET cMensajeRet = "Parametro no valido para realizar la consulta";
	RETURN cCodRet, cMensajeRet,"";
END IF;

--se obtiene la ruta donde se almacenara el archivo generado.
	SELECT  TRIM(valor_alfabetico) 
	INTO cRuta
	FROM bdicobranza:cb_param_campania
	WHERE tipo_campania = 11  
	AND  grupo_parametro = 'RUTAS'
	AND num_parametro =1;
	
IF NVL(cRuta,"") = "" THEN
	LET cCodRet= "000002";
	LET cMensajeRet = "No se pudo obtener la ruta donde se almacenara el archivo";
	RETURN cCodRet, cMensajeRet,"";
END IF;	
		SELECT fecha_hoy   
		INTO dtFecha 
		FROM bdicred:sd_fechas
		WHERE empresa=pEmpresa;

	LET cNombreArchivo= TRIM(cNombreArchivo)|| DAY(dtFecha) || LPAD(TRIM(MONTH(dtFecha)::CHAR(2)),2,'0') || YEAR(dtFecha);

 IF EXISTS(SELECT tabname FROM sysmaster:systabnames WHERE tabname = 'TME_ENCABEZADOS'  AND dbsname = 'bdicobranza') THEN
            DROP TABLE TME_ENCABEZADOS;
 END IF;

SET ISOLATION TO DIRTY READ;
SET LOCK MODE TO WAIT 3;
	  FOREACH WITH HOLD 
	   SELECT num_archivo,tipo_archivo,query,param1,param2,param3
		INTO iNumArchivo,cTipoArchivo,cConsulta,cParam1,cParam2,cParam3		
		FROM  bdicobranza:"informix".cb_param_archivos 
		WHERE num_archivo = pTipoReporte
			
		IF NVL(iNumArchivo,0) <> 3 AND NVL(iNumArchivo,0) > 0 THEN
			
			IF cParam1 IN ('001','1','2') THEN
				LET cConsulta= replace( cConsulta , 'Param1' , "'"||TRIM(cParam1)||"'");
			END IF;
			
			IF cParam2 = 'Fecha Inicio' THEN
				LET cParam2 = pFechaIni;
				LET cConsulta= replace( cConsulta , 'Param2' , "'"||TRIM(cParam2)||"'");
			END IF;
			
			IF cParam3 = 'Fecha Fin' THEN
				LET cParam3 = pFechaFin;
				LET cConsulta= replace( cConsulta , 'Param3' , "'"||TRIM(cParam3)||"'");
			END IF;
		END IF;
		IF iNumArchivo =3 THEN
			IF cParam1 = 'Fecha Inicio' THEN
				LET cParam1 = pFechaIni;
				LET cConsulta= replace( cConsulta , 'Param1' , "'"||TRIM(cParam1)||"'");
			END IF;
			
			IF cParam2 = 'Fecha Fin' THEN
				LET cParam2 = pFechaFin;
				LET cConsulta= replace( cConsulta , 'Param2' , "'"||TRIM(cParam2)||"'");
			END IF;
		END IF;
		--crear encabezado dependiendo el tipo de archivo
		IF iNumArchivo =1 THEN
			CREATE TABLE TME_ENCABEZADOS(
			plaza   CHAR(20),
			ciudad	CHAR(20),
			sucursal CHAR(20),
			origen	CHAR(20),
			tipo_compac CHAR(20),
			plazo CHAR(20),
			total CHAR(20),
			importe CHAR(20),
			importe_pagado CHAR(20),
			cumplido CHAR(20),
			fecha_compac CHAR(20),
			fecha_vencimiento CHAR(20)
			);
			LET cTabla="S";
			LET cConsulta2 = 'INSERT INTO TME_ENCABEZADOS (plaza,ciudad,sucursal,origen,tipo_compac,plazo,total,importe,importe_pagado,cumplido,fecha_compac,fecha_vencimiento)';
			LET cConsulta3 = 'SELECT plaza,ciudad,sucursal,origen,tipo_compac,plazo,total,importe,importe_pagado,cumplido,fecha_compac,fecha_vencimiento FROM  TME_ENCABEZADOS';
			INSERT INTO TME_ENCABEZADOS (plaza,ciudad,sucursal,origen,tipo_compac,plazo,total,importe,importe_pagado,cumplido,fecha_compac,fecha_vencimiento) 
			VALUES("plaza","ciudad","sucursal","origen","tipo_compac","plazo","total","importe","importe pagado","cumplido","fecha_compac","fecha_vencimiento");
		ELIF iNumArchivo =2 THEN
			IF  cTabla="N" THEN 
				CREATE TABLE TME_ENCABEZADOS(
				SUCURSAL   CHAR(20),
				NUMERO_CONVENIO	CHAR(20),
				IMPORTE_CONVENIADO CHAR(20),
				IMPORTE_PAGADO	CHAR(20),
				CUMPLIMIENTO CHAR(20));
				LET cTabla="S";
			END IF;
			
			LET cConsulta2 = 'INSERT INTO TME_ENCABEZADOS (SUCURSAL,NUMERO_CONVENIO,IMPORTE_CONVENIADO,IMPORTE_PAGADO,CUMPLIMIENTO)';
			IF cParam1 = '1' THEN
				INSERT INTO TME_ENCABEZADOS (SUCURSAL,NUMERO_CONVENIO,IMPORTE_CONVENIADO,IMPORTE_PAGADO,CUMPLIMIENTO)
				VALUES("COMPROMISOS","","","","");
			ELIF cParam1 = '2' THEN
				INSERT INTO TME_ENCABEZADOS (SUCURSAL,NUMERO_CONVENIO,IMPORTE_CONVENIADO,IMPORTE_PAGADO,CUMPLIMIENTO)
				VALUES("ACUERDOS","","","","");
			END IF;
			LET cConsulta3 = 'SELECT SUCURSAL,NUMERO_CONVENIO,IMPORTE_CONVENIADO,IMPORTE_PAGADO,CUMPLIMIENTO FROM  TME_ENCABEZADOS';
			INSERT INTO TME_ENCABEZADOS (SUCURSAL,NUMERO_CONVENIO,IMPORTE_CONVENIADO,IMPORTE_PAGADO,CUMPLIMIENTO)
			VALUES("SUCURSAL","NUMERO DE CONVENIO","IMPORTE CONVENIADO","IMPORTE PAGADO","CUMPLIMIENTO");

		ELIF iNumArchivo =3 THEN
			CREATE TABLE TME_ENCABEZADOS(
				SUCURSAL   CHAR(20),
				Total_recuperarPagoMin   CHAR(50),
				RecupPesosPagoMin	CHAR(50),
				PorcRecupPagoMin CHAR(50),
				Total_recuperarVencido   CHAR(50),
				RecupPesosVencido	CHAR(50),
				PorcRecupVencido CHAR(50)
			);
			LET cTabla="S";
			LET cConsulta2 = 'INSERT INTO TME_ENCABEZADOS (SUCURSAL,Total_recuperarPagoMin,RecupPesosPagoMin,PorcRecupPagoMin,Total_recuperarVencido,RecupPesosVencido,PorcRecupVencido)';
			LET cConsulta3 = 'SELECT SUCURSAL,Total_recuperarPagoMin,RecupPesosPagoMin,PorcRecupPagoMin,Total_recuperarVencido,RecupPesosVencido,PorcRecupVencido FROM  TME_ENCABEZADOS';
			INSERT INTO TME_ENCABEZADOS (SUCURSAL,Total_recuperarPagoMin,RecupPesosPagoMin,PorcRecupPagoMin,Total_recuperarVencido,RecupPesosVencido,PorcRecupVencido)
				VALUES("SUCURSAL","Total a recuperar/Pago Mínimo del mes ($)","Recup. en pesos vs. Total Pago","(%) Recup. vs. Mínimo a Pagar","Total a recuperar/vdo. del mes ($)","Recup. en pesos vs. Total vdo.","(%) Recup. vs. vdo.");
		END IF;
		IF iNumArchivo = 1 THEN
			LET cSql = '';
			LET cSql = 'echo "UNLOAD TO ' ||TRIM(cRuta)||TRIM(cNombreArchivo)||'.'||'unl'|| ' '||TRIM(cConsulta)||'" > '|| TRIM(cRuta) ||'query1.sql';
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = "dbaccess bdicobranza " ||TRIM(cRuta)||'query1.sql';
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = 'echo "LOAD FROM ' ||TRIM(cRuta)||TRIM(cNombreArchivo)||'.'||'unl'|| ' '||TRIM(cConsulta2)||'" > '|| TRIM(cRuta) ||'query4.sql';
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = "dbaccess bdicobranza " ||TRIM(cRuta)||'query4.sql';
			SYSTEM TRIM(cSql);
			-- borrado de temporales que fueron usados para la creacion del archivo a enviar a buro de credito
			LET cSql = '';
			LET cSQL = "rm " ||TRIM(cRuta)||'query1.sql';		
			SYSTEM cSql; 
			LET cSql = '';
			LET cSQL = "rm " ||TRIM(cRuta)||'query4.sql';		
			SYSTEM cSql; 
			LET cSql = '';
			LET cSQL = "rm " ||TRIM(cRuta)||TRIM(cNombreArchivo)||'.'||'unl';		
			SYSTEM cSql; 		
		ELSE
			LET cSql = '';
			LET cSql = 'echo "'||TRIM(cConsulta2)|| ' '||TRIM(cConsulta)||'" > '|| TRIM(cRuta) ||'query.sql';

			SYSTEM TRIM(cSql);
					
			LET cSql = '';
	        LET cSql = "dbaccess bdicobranza " ||TRIM(cRuta)||'query.sql';
	        SYSTEM TRIM(cSql);
			-- borrado de temporales que fueron usados para la creacion del archivo a enviar a buro de credito
			LET cSql = '';
			LET cSQL = "rm " ||TRIM(cRuta)||'query.sql';		
			SYSTEM cSql; 
			LET cSql = '';
		END IF;
	  END FOREACH;
		LET cConsulta3 =' '||TRIM(cConsulta3);
		LET cSql = '';
		LET cSql = 'echo "UNLOAD TO ' ||TRIM(cRuta)||TRIM(cNombreArchivo)||'.'||TRIM(cTipoArchivo)|| ' DELIMITER '|| '''	'''||cConsulta3||'" > '|| TRIM(cRuta) ||'query2.sql';
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = "dbaccess bdicobranza " ||TRIM(cRuta)||'query2.sql';
		SYSTEM TRIM(cSql);
		
	
        LET cSQL = "rm " ||TRIM(cRuta)||'query2.sql';		
        SYSTEM cSql; 
	
		IF cTabla="S" THEN
			DROP TABLE TME_ENCABEZADOS;
		END IF;
		LET cNombreArchivo= TRIM(cNombreArchivo)||'.'||TRIM(cTipoArchivo);
		RETURN cCodRet, cMensajeRet,cNombreArchivo;
END
END PROCEDURE
DOCUMENT 
'Se realiza procedimiento para la generacion de archivos de los tipos de reportes para estadistica de convenios',
'AUTOR : Jesús Manuel Aguilar Heredia',
'FECHA : 05/04/2011',
'BD    : BDICOBRANZA',
'Version: 20110404.0850',
'Se modifica para que use el tabulador como separador en la generación del archivo',
'AUTOR : Jesús Manuel Aguilar Heredia',
'FECHA : 20/04/2011',
'BD    : BDICOBRANZA',
'Version: 20110420.1250',
'2012-05-16 Si existe borrar la tabla TME_ENCABEZADOS al inicio del proceso. Autor: Marco A. Campos';

CREATE PROCEDURE "informix".sp_cargatelefonosburo_pba()
       RETURNING CHAR(5), CHAR(80);
       
DEFINE vCodRet                  CHAR(5);
DEFINE vMensaje                 CHAR(80);
DEFINE SQL_ERR, ISAM_ERR        INTEGER;
DEFINE ERROR_INFO               VARCHAR(80);
DEFINE cNombreProceso           CHAR(30);
DEFINE v_fecha                  DATE;
DEFINE v_dia, v_mes             CHAR(2);
DEFINE v_anio                   CHAR(4);
DEFINE cRuta                    CHAR(100);
DEFINE cRuta2                   CHAR(100);  
DEFINE cNombre                  CHAR(100);
DEFINE cNombre2                 CHAR(100);      
DEFINE iParamRuta               INTEGER;
DEFINE iParamNombre             INTEGER;  
DEFINE iRegistros               INTEGER;
DEFINE v_count                  INTEGER;
DEFINE cCadena                  CHAR(2000);
DEFINE cEmpresa                 CHAR(3);
DEFINE v_numcte                 CHAR(20); 
DEFINE v_cuenta                 CHAR(20);
DEFINE v_telefono1              CHAR(13);
DEFINE v_telefono2              CHAR(13); 
DEFINE v_telefono3              CHAR(13); 
DEFINE v_telefono4              CHAR(13);
DEFINE v_telefono5              CHAR(13);
DEFINE v_longitud               SMALLINT; 
DEFINE vCodRet_2                CHAR(6);
DEFINE vCodRet_tel              CHAR(5);

LET vCodRet  = '11100';
LET vMensaje = 'PROCESO INICIALIZADO';
LET SQL_ERR  = 0; 
LET ISAM_ERR = 0; 
LET ERROR_INFO = '';
LET cNombreProceso  = 'CARGA DE TELEFONOS DE BURO';
LET v_fecha  = DATE(1);
LET v_dia    = '';  
LET v_mes    = ''; 
LET v_anio   = '';
LET cRuta    = '';  
LET cNombre  = '';
LET cRuta2   = '';  
LET cNombre2 = '';
LET iParamRuta  = 20;
LET iParamNombre = 40;
LET iRegistros  = 0;
LET cCadena     = '';
LET cEmpresa    = '001';
LET v_count     = 0;
LET v_numcte = ''; 
LET v_cuenta = '';
LET v_telefono1 = ''; 
LET v_telefono2 = ''; 
LET v_telefono3 = '';
LET v_telefono4 = ''; 
LET v_telefono5 = '';
LET v_longitud  = 0;
LET vCodRet_2   = ''; 
LET vCodRet_tel = '';   

 SET DEBUG FILE TO "sp_cargatelefonosburo_pba.out";
 TRACE ON; 

BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, ERROR_INFO
        LET vCodRet  = SQL_ERR;
        LET vMensaje  = ERROR_INFO;

        --insertar control de procesos
        INSERT INTO bdicobranza:cb_bitacora_cob(proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc) 
         VALUES(cNombreProceso, '11222', vMensaje, user, v_fecha, (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals), iRegistros);
       
        RETURN vCodRet, vMensaje;
    END EXCEPTION;

    SELECT fecha_hoy 
    into v_fecha
    from bdinteg:si_fechas
    WHERE empresa = cEmpresa;

    INSERT INTO bdicobranza:cb_bitacora_cob(proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc) 
     VALUES(cNombreProceso, vCodRet, vMensaje, user, v_fecha, (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals), iRegistros);
    
    IF EXISTS(SELECT tabname FROM sysmaster:systabnames WHERE tabname = 'tmp_telefonos_buro_2'  AND dbsname = 'bdicobranza') THEN
            DROP TABLE tmp_telefonos_buro_2;
    END IF;

    INSERT INTO bdicobranza:cb_bitacora_cob(proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc) 
     VALUES(cNombreProceso, '11110', 'Obtuvo fecha y borro tabla tmp_telefonos_buro_2 si existia...', user, v_fecha, (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals), iRegistros);
    
   
    CREATE TABLE "informix".tmp_telefonos_buro_2
    (
    	cuenta           CHAR(20),
    	empleo           CHAR(60),
    	calleynum        CHAR(60),
    	colonia          CHAR(60),    	
    	delegacion       CHAR(60),
    	ciudad           CHAR(60),
    	estado           CHAR(10),
    	cp               CHAR(10),
    	telefono1        CHAR(13),
    	telefono2        CHAR(13),
    	telefono3        CHAR(13),
    	telefono4        CHAR(13),
    	telefono5        CHAR(13),
    	fecha_reg        CHAR(10) 
    );

    --CUENTA|EMPLEO|CALLE Y NUMERO|COLONIA|DELEGACION|CIUDAD|ESTADO|CP|TELEFONOS|FECHA
    CREATE INDEX "informix".idx_tmp_telefonos_buro_2 ON tmp_telefonos_buro_2 (cuenta) USING btree ;

    INSERT INTO bdicobranza:cb_bitacora_cob(proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc) 
     VALUES(cNombreProceso, '11111', 'Creo tabla tmp_telefonos_buro_2 e indice idx_tmp_telefonos_buro_2...', user, v_fecha, (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals), iRegistros);

    IF day(v_fecha) < 10 then
    	LET v_dia = '0' || day(v_fecha);
    ELSE
    	LET v_dia = day(v_fecha);
    END IF;
    
    IF month(v_fecha) < 10 then
    	LET v_mes = '0' || month(v_fecha);
    ELSE
    	LET v_mes = month(v_fecha);
    END IF;
    
    LET v_anio = year(v_fecha);

    SELECT valor  INTO cRuta
    FROM bdicobranza:cb_param
    WHERE empresa = cEmpresa
      AND cod_param = iParamRuta;

    SELECT valor  INTO cNombre2
    FROM bdicobranza:cb_param
    WHERE empresa = cEmpresa
      AND cod_param = iParamNombre;
   
    LET vMensaje = 'Obtuvo parametros..' || iParamRuta || '-' || iParamNombre || '  ' || v_dia || '-' || v_mes || '-' || v_anio;
    
    INSERT INTO bdicobranza:cb_bitacora_cob(proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc) 
     VALUES(cNombreProceso, '11112', vMensaje, user, v_fecha, (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals), iRegistros);


  IF NVL(cRuta,'') <> '' and NVL(cNombre2, '') <> '' THEN

    LET cNombre = trim(SUBSTR(cNombre2,1,LENGTH(cNombre2)) || v_dia || v_mes || v_anio || '.txt');
    
    LET cCadena = 'echo "load from ''' || SUBSTR(cRuta,1,LENGTH(cRuta)) || SUBSTR(cNombre,1,LENGTH(cNombre)) || '''' ||
                  ' insert into bdicobranza:tmp_telefonos_buro_2 " > ' || SUBSTR(cRuta,1,LENGTH(cRuta)) || 'importa_telefonosburo.sql;';
      
    system SUBSTR(cCadena,1,LENGTH(cCadena));              
    --INSERT INTO bdicobranza:cb_mensajes_trace(nom_variable, descripcion) VALUES('cCadena', trim(cCadena));

    LET cCadena = 'dbaccess bdicobranza ' || SUBSTR(cRuta,1,LENGTH(cRuta)) || 'importa_telefonosburo.sql';
    
    LET vMensaje = 'Armo cCadena: ' || cCadena;
    
    INSERT INTO bdicobranza:cb_bitacora_cob(proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc) 
    VALUES(cNombreProceso, '11113', vMensaje, user, v_fecha, (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals), iRegistros);
  
    system SUBSTR(cCadena,1,LENGTH(cCadena));
    --DESPUES QUE LOS IMPORTE SE DEBERAN PROCESAR para insertarlos a CB_TELEFONOS  con el SP "sp_cat_graba_telefono_adicional" usado por Cajera Capturista

     INSERT INTO bdicobranza:cb_bitacora_cob(proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc) 
     VALUES(cNombreProceso, '11114', 'Ejecuto el load from...', user, v_fecha, (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals), iRegistros);
 
    SELECT count(*) into v_count 
      FROM tmp_telefonos_buro_2;
      
     IF v_count <= 0 THEN
         LET vCodRet = '00001';
         LET vMensaje = 'NO SE CARGARON REGISTROS A LA TABLA TEMPORAL';
         
         INSERT INTO bdicobranza:cb_bitacora_cob(proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc) 
         VALUES(cNombreProceso, '11115', 'No se cargaron registros en tabla tempo...', user, v_fecha, (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals), iRegistros);
         RETURN vCodRet, vMensaje;  
     END IF;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    --SET pdqpriority 20;
   
     INSERT INTO bdicobranza:cb_bitacora_cob(proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc) 
     VALUES(cNombreProceso, '11116', 'Justo antes de entrar a Foreach...', user, v_fecha, (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals), iRegistros);
    
     FOREACH 
           SELECT cuenta, telefono1, telefono2, telefono3, telefono4, telefono5               --LENGTH(telefono1)  
             INTO v_cuenta, v_telefono1, v_telefono2, v_telefono3, v_telefono4, v_telefono5   --v_longitud
             FROM bdicobranza:tmp_telefonos_buro_2

           SELECT FIRST 1 numcte INTO v_numcte
             FROM bdicred:sd_maecred
            WHERE num_credito = v_cuenta;

           
           IF LENGTH(v_telefono1)>= 10 THEN  --MÍNIMO QUE SEA DE 10 POSICIONES.
              -- VALIDAR QUE NO TRAIGA CARACTERES RAROS (bdinteg:sp_tipored solo recibe tels de 10 caracteres)
              EXECUTE procedure bdinteg:"informix".sp_validar_telefono(v_telefono1) into vCodRet_tel;

           -- pEmpresa CHAR(3), pOrigen SMALLINT, pNumcte CHAR(20), pTipo_telefono SMALLINT, pTelefono CHAR(13), pExtension CHAR(5), pParentesco CHAR(1), 
           --                   pResultado_gestion   INTEGER, pEjecutivo CHAR(8))

              IF vCodRet_tel = '00000' THEN
                  EXECUTE PROCEDURE "informix".sp_cat_graba_telefono_adicional(cEmpresa, 5, v_numcte, 1, v_telefono1, '', '', 0, user) INTO vCodRet_2;
              END IF;
           END IF;
           LET vCodRet_tel = '';
           
           IF LENGTH(v_telefono2)>= 10 THEN  
              EXECUTE procedure bdinteg:"informix".sp_validar_telefono(v_telefono2) into vCodRet_tel;

              IF vCodRet_tel = '00000' THEN
                  EXECUTE PROCEDURE "informix".sp_cat_graba_telefono_adicional(cEmpresa, 5, v_numcte, 2, v_telefono2, '', '', 0, user) INTO vCodRet_2;
              END IF;
           END IF;
           LET vCodRet_tel = '';
            
           IF LENGTH(v_telefono3)>= 10 THEN  
              EXECUTE procedure bdinteg:"informix".sp_validar_telefono(v_telefono3) into vCodRet_tel;

              IF vCodRet_tel = '00000' THEN
                  EXECUTE PROCEDURE "informix".sp_cat_graba_telefono_adicional(cEmpresa, 5, v_numcte, 3, v_telefono3, '', '', 0, user) INTO vCodRet_2;
              END IF;
           END IF;
           LET vCodRet_tel = '';
            
           IF LENGTH(v_telefono4)>= 10 THEN  
              EXECUTE procedure bdinteg:"informix".sp_validar_telefono(v_telefono4) into vCodRet_tel;

              IF vCodRet_tel = '00000' THEN
                  EXECUTE PROCEDURE "informix".sp_cat_graba_telefono_adicional(cEmpresa, 5, v_numcte, 4, v_telefono4, '', '', 0, user) INTO vCodRet_2;
              END IF;
           END IF;
           LET vCodRet_tel = '';

           IF LENGTH(v_telefono5)>= 10 THEN  
              EXECUTE procedure bdinteg:"informix".sp_validar_telefono(v_telefono5) into vCodRet_tel;

              IF vCodRet_tel = '00000' THEN
                  EXECUTE PROCEDURE "informix".sp_cat_graba_telefono_adicional(cEmpresa, 5, v_numcte, 5, v_telefono5, '', '', 0, user) INTO vCodRet_2;
              END IF;
           END IF;
                           
           LET iRegistros = iRegistros + 1;
      END FOREACH 
      
      LET vMensaje = 'PROCESO FINALIZADO';

     INSERT INTO bdicobranza:cb_bitacora_cob(proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc) 
     VALUES(cNombreProceso, '11117', 'Concluyo Foreach...', user, v_fecha, (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals), iRegistros);
 	    
      INSERT INTO bdicobranza:cb_bitacora_cob(proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc) 
      VALUES(cNombreProceso, '11200', vMensaje, user, v_fecha, (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals), iRegistros);

     INSERT INTO bdicobranza:cb_bitacora_cob(proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc) 
     VALUES(cNombreProceso, '11118', 'Inserto en cb_bitacora_cob...', user, v_fecha, (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals), iRegistros);

      DROP INDEX "informix".idx_tmp_telefonos_buro_2;
      --DROP TABLE "informix".tmp_telefonos_buro_2;
      INSERT INTO bdicobranza:cb_bitacora_cob(proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc) 
      VALUES(cNombreProceso, '11119', 'Borro indice...', user, v_fecha, (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals), iRegistros);
      
  END IF;
	  
   	
RETURN vCodRet, vMensaje;
END 
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cilocconsultaalertas()
		RETURNING   CHAR(5) as Codigo,	--codret
					CHAR(40) as Descripcion,	--desc_estatus
					CHAR(4) as Tipo;
					
	DEFINE cCodRet 			CHAR(5);
	DEFINE iCont            INTEGER;
	DEFINE iSqlErr 			INTEGER;
	DEFINE cDesc_estatus    CHAR(40);
	DEFINE cTipo            CHAR(4);
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET icont=0;
	LET cDesc_estatus = '';
	LET cTipo='';
	--------------------------------------------------------------------------
	--SET DEBUG FILE TO '/home/sysifx/Malena/sp_CiLocConsultaAlertas.out';
	--TRACE ON;
	--------------------------------------------------------------------------
	
	BEGIN
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			LET cDesc_estatus='Error de Informix';
			RETURN cCodRet,cDesc_estatus,cTipo;
		END EXCEPTION;		
		
	--Se realiza consulta a la tabla cb_estatus_loc para obtener las situaciones de alarma.	
	set isolation to dirty read; -- Lectura de tablas bloqueadas.
	
		FOREACH   
			SELECT NVL(desc_estatus,''),NVL(tipo,'')
			INTO  cDesc_estatus,cTipo
			FROM bdicobranza:cb_estatus_loc
			LET icont=icont+1;
            RETURN cCodRet,cDesc_estatus,cTipo WITH RESUME;

		END FOREACH;		
		
        IF icont == 0 THEN 
			LET cCodret='00001';
            LET cDesc_estatus='No hay Informacion en la tabla';			
            RETURN cCodret,cDesc_estatus,cTipo WITH RESUME;
        END IF;

	END;
END PROCEDURE

DOCUMENT
'AUTOR       : Maria Elena Angulo Aispuro',
'DESCRIPCION : Devuelve un listado de las situaciones de alarma de la tabla cb_estatus_loc',
'FECHA       : 13 de Agosto de 2010',
'VERSION     : 20100813.1007',
'BD          : BDICOBRANZA';

