CREATE PROCEDURE "informix".sp_cilocgenerarptalertascte(pNumCte CHAR(20), pSucursal CHAR(4), pRegion SMALLINT, pFechaIni CHAR(10), pFechaFin CHAR(10), pTipo INTEGER, pSitAlarma CHAR(4))
RETURNING CHAR(5) AS CODRET, CHAR(4) AS SUCURSAL , CHAR(20) AS NUMCTE, INTEGER AS ALERTA, CHAR(4) AS SITUACION, DATE AS FECHAALERTA, CHAR(40) AS ESTATUSALERTA, CHAR(2) AS REGION, CHAR(20) AS NOMBRECD, CHAR(3) AS NUMCD, CHAR(4) AS SIGLAS;

--Declaracion de variables
------------------------------------------------------------
DEFINE sql_err 			                INTEGER;
DEFINE isam_err 		                INTEGER;
DEFINE error_info		                CHAR(80);
DEFINE cCod_ret                         CHAR(6);
DEFINE cSucursal						CHAR(4);
DEFINE cSucursal2						CHAR(4);
DEFINE cNumcte							CHAR(20);
DEFINE cNumAlerta						INTEGER;
DEFINE dFechaAlerta						DATE;
DEFINE cEstatusAlerta                   CHAR(40);
DEFINE cCiudad							CHAR(3);
DEFINE cNombreCd						CHAR(20);
DEFINE cSiglasCd						CHAR(4);
DEFINE cRegion							CHAR(2);
DEFINE cSituacion						CHAR(4);
DEFINE cCod_ret2						CHAR(5);
DEFINE dtfechainicial					DATE;
DEFINE dtfechafinal						DATE;
DEFINE dtfechainicial2					DATE;
DEFINE dtfechafinal2					DATE;
DEFINE cMesIni							CHAR(2);
DEFINE cAnoIni							CHAR(4);
DEFINE cMesFin							CHAR(2);
DEFINE cAnoFin							CHAR(4);
-----------------------------------------------------
LET cCod_ret  = '00000';
LET sql_err   = 0;
LET cSucursal = '';
LET cSucursal2 = '';
LET cNumcte	= '';
LET cNumAlerta	= 0;
LET dFechaAlerta	= '';
LET cEstatusAlerta  = '';
LET cCiudad	= '';
LET cNombreCd	= '';
LET cSiglasCd	= '';
LET cRegion		= '';
LET cSituacion = '';
LET cCod_ret2	= '';
LET dtfechainicial='';		
LET dtfechafinal='';
LET dtfechainicial2='';
LET dtfechafinal2='';
LET cMesIni		= '';
LET cAnoIni		= '';
LET cMesFin		= '';
LET cAnoFin		= '';

  BEGIN

	ON EXCEPTION SET sql_err, isam_err, error_info
		LET cCod_ret = sql_err;
		RETURN cCod_ret, cSucursal, cNumcte,  cNumAlerta, cSituacion, dFechaAlerta, cEstatusAlerta, cRegion, cNombreCd, cCiudad, cSiglasCd;
	END EXCEPTION;
	
	--SET DEBUG FILE TO "/tmp/sp_CiLocGeneraRptAlertasCte.out";
	--TRACE ON;
	
	
	--ORDENADO
	IF pTipo = 2 THEN --POR SUCURSAL
	
		IF LENGTH (pFechaIni) = 7 AND LENGTH (pFechaFin) = 7 THEN
			LET cMesIni = SUBSTR(TRIM(pFechaIni), 1, 2);
			LET cAnoIni = SUBSTR(TRIM(pFechaIni), 4, 7);
			LET cMesFin = SUBSTR(TRIM(pFechaFin), 1, 2);
			LET cAnoFin = SUBSTR(TRIM(pFechaFin), 4, 7);
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesIni,cAnoIni) into cCod_ret2,dtfechainicial, dtfechainicial2 ;
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesFin,cAnoFin) into cCod_ret2,dtfechafinal, dtfechafinal2 ;
		
			FOREACH WITH HOLD
			
				SELECT m.numcte,COUNT(m.numcte), m.sucursal ,MAX(m.fecha)
				INTO cNumcte,cNumAlerta, cSucursal,dFechaAlerta
				FROM bdicobranza:cb_alerta_succliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)
				WHERE m.numcte = CASE when pNumCte = '' THEN  m.numcte ELSE pNumCte END	
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region ELSE pRegion END
				AND m.sucursal = CASE when pSucursal = '' THEN  m.sucursal ELSE pSucursal END				
				AND m.estatus = CASE when pSitAlarma = '' THEN  m.estatus   ELSE pSitAlarma END 
				AND m.fecha::DATE between dtfechainicial::DATE AND dtfechafinal2::DATE 
				GROUP BY m.numcte,m.sucursal
				ORDER BY m.sucursal
			
				SELECT LIMIT 1 m.sucursal, e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad, 
				m.situacion
				INTO cSucursal, cEstatusAlerta, cRegion, cNombreCd, cCiudad, cSiglasCd, cSituacion
				FROM bdicobranza:cb_alerta_succliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)  
				INNER JOIN bdicobranza:cb_estatus_loc e ON (e.tipo= m.estatus)
				WHERE m.numcte = CASE when pNumCte = '' THEN  numcte ELSE pNumCte END	
				AND m.sucursal = CASE when pSucursal = '' THEN  m.sucursal ELSE pSucursal END
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region ELSE pRegion END
				AND m.estatus = CASE when pSitAlarma = '' THEN  m.estatus   ELSE pSitAlarma END 
				AND fecha::DATE = dFechaAlerta
				AND m.numalerta = (SELECT MAX(numalerta) FROM cb_alerta_succliente 
								 WHERE numcte = cNumcte 
								 AND estatus = CASE when pSitAlarma = '' THEN  estatus   ELSE pSitAlarma END
								 AND fecha::DATE = dFechaAlerta);
				
				RETURN cCod_ret, cSucursal, cNumcte,  cNumAlerta, cSituacion, dFechaAlerta, cEstatusAlerta, cRegion, cNombreCd, cCiudad, cSiglasCd WITH RESUME;
				
			END FOREACH;
			
		ELSE 
		
			FOREACH WITH HOLD						
				
				SELECT numcte,COUNT(m.numcte), m.sucursal ,MAX(m.fecha)
				INTO cNumcte,cNumAlerta, cSucursal,dFechaAlerta
				FROM bdicobranza:cb_alerta_succliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)
				WHERE m.numcte = CASE when pNumCte = '' THEN  m.numcte ELSE pNumCte END	
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region ELSE pRegion END
				AND m.sucursal = CASE when pSucursal = '' THEN  m.sucursal ELSE pSucursal END				
				AND m.estatus = CASE when pSitAlarma = '' THEN  m.estatus   ELSE pSitAlarma END 
				AND m.fecha::DATE between pFechaIni::DATE AND pFechaFin::DATE 
				GROUP BY m.numcte,m.sucursal
				ORDER BY m.sucursal
			
				SELECT LIMIT 1 m.sucursal, e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad, 
				m.situacion
				INTO cSucursal, cEstatusAlerta, cRegion, cNombreCd, cCiudad, cSiglasCd, cSituacion
				FROM bdicobranza:cb_alerta_succliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)  
				INNER JOIN bdicobranza:cb_estatus_loc e ON (m.estatus = e.tipo)
				WHERE m.sucursal = CASE when pSucursal = '' THEN  m.sucursal ELSE pSucursal END
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region   ELSE pRegion END
				AND m.estatus = CASE when pSitAlarma = '' THEN  m.estatus   ELSE pSitAlarma END 
				AND m.numcte = cNumcte
				AND m.fecha = dFechaAlerta
				AND m.numalerta = (SELECT MAX(m.numalerta) FROM cb_alerta_succliente m
								 WHERE numcte = cNumcte 
								 AND estatus = CASE when pSitAlarma = '' THEN  estatus   ELSE pSitAlarma END
								 AND fecha::DATE = dFechaAlerta );
				
				RETURN cCod_ret, cSucursal, cNumcte,  cNumAlerta, cSituacion, dFechaAlerta, cEstatusAlerta, cRegion, cNombreCd, cCiudad, cSiglasCd WITH RESUME;
				
			END FOREACH;		
		END IF;		
			
	ELIF pTipo = 3 THEN--TIPO  POR REGION
	
		IF LENGTH (pFechaIni) = 7 AND LENGTH (pFechaFin) = 7 THEN	
			LET cMesIni = SUBSTR(TRIM(pFechaIni), 1, 2);
			LET cAnoIni = SUBSTR(TRIM(pFechaIni), 4, 7);
			LET cMesFin = SUBSTR(TRIM(pFechaFin), 1, 2);
			LET cAnoFin = SUBSTR(TRIM(pFechaFin), 4, 7);
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesIni,cAnoIni) into cCod_ret2,dtfechainicial, dtfechainicial2 ;
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesFin,cAnoFin) into cCod_ret2,dtfechafinal, dtfechafinal2 ;
			
			FOREACH	WITH HOLD
				
				SELECT m.numcte,COUNT(m.numcte),c.numero_region, MAX(m.fecha)
				INTO cNumcte, cNumAlerta,cRegion, dFechaAlerta
				FROM bdicobranza:cb_alerta_succliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)
				WHERE m.numcte = CASE when pNumCte = '' THEN  m.numcte ELSE pNumCte END	
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region ELSE pRegion END
				AND m.sucursal = CASE when pSucursal = '' THEN  m.sucursal ELSE pSucursal END				
				AND m.estatus = CASE when pSitAlarma = '' THEN  m.estatus   ELSE pSitAlarma END 
				AND fecha::DATE between dtfechainicial::DATE AND dtfechafinal2::DATE 
				GROUP BY m.numcte,c.numero_region
				ORDER BY c.numero_region
			
				SELECT LIMIT 1 m.sucursal, e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad, 
				m.situacion
				INTO cSucursal, cEstatusAlerta, cRegion, cNombreCd, cCiudad, cSiglasCd, cSituacion
				FROM bdicobranza:cb_alerta_succliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)  
				INNER JOIN bdicobranza:cb_estatus_loc e ON (e.tipo= m.estatus)
				WHERE m.sucursal = CASE when pSucursal = '' THEN  m.sucursal   ELSE pSucursal END
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region   ELSE pRegion END
				AND m.estatus = CASE when pSitAlarma = '' THEN  m.estatus   ELSE pSitAlarma END 
				AND m.numcte = cNumcte
				AND m.fecha::DATE = dFechaAlerta 
				AND m.numalerta = (SELECT MAX(numalerta) FROM cb_alerta_succliente
								 WHERE numcte = cNumcte 
								 AND estatus = CASE when pSitAlarma = '' THEN  estatus   ELSE pSitAlarma END
								 AND fecha::DATE = dFechaAlerta );						
				
				RETURN cCod_ret, cSucursal, cNumcte,  cNumAlerta, cSituacion, dFechaAlerta, cEstatusAlerta, cRegion, cNombreCd, cCiudad, cSiglasCd WITH RESUME;
				
			END FOREACH;			
		ELSE
		
			FOREACH WITH HOLD
		
				SELECT m.numcte,COUNT(m.numcte),c.numero_region, MAX(m.fecha)
				INTO cNumcte, cNumAlerta, cRegion, dFechaAlerta
				FROM bdicobranza:cb_alerta_succliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)
				WHERE numcte = CASE when pNumCte = '' THEN  numcte ELSE pNumCte END
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region ELSE pRegion END				
				AND m.sucursal = CASE when pSucursal = '' THEN  m.sucursal ELSE pSucursal END				
				AND m.estatus = CASE when pSitAlarma = '' THEN  m.estatus   ELSE pSitAlarma END 
				AND m.fecha BETWEEN pFechaIni AND pFechaFin
				GROUP BY m.numcte,c.numero_region
				ORDER BY c.numero_region
				
			
				SELECT LIMIT 1 m.sucursal, e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad,
				m.situacion
				INTO cSucursal, cEstatusAlerta, cRegion, cNombreCd, cCiudad, cSiglasCd, cSituacion
				FROM bdicobranza:cb_alerta_succliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)  
				INNER JOIN bdicobranza:cb_estatus_loc e ON (e.tipo= m.estatus)
				WHERE m.sucursal = CASE when pSucursal = '' THEN  m.sucursal   ELSE pSucursal END
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region   ELSE pRegion END
				AND m.estatus = CASE when pSitAlarma = '' THEN  m.estatus   ELSE pSitAlarma END 
				AND m.numcte = cNumcte
				AND m.fecha = dFechaAlerta
				AND m.numalerta = (SELECT MAX(numalerta) FROM cb_alerta_succliente 
								 WHERE numcte = cNumcte 
								 AND estatus = CASE when pSitAlarma = '' THEN  estatus   ELSE pSitAlarma END
								 AND fecha::DATE  = dFechaAlerta );
				
				--ORDER BY c.numero_region;		
				
				RETURN cCod_ret, cSucursal, cNumcte,  cNumAlerta, cSituacion, dFechaAlerta, cEstatusAlerta, cRegion, cNombreCd, 
				cCiudad, cSiglasCd WITH RESUME;
			
			END FOREACH;
		END IF;	
	ELIF pTipo = 1 THEN -- SIN ORDER
	
		IF LENGTH (pFechaIni) = 7 AND LENGTH (pFechaFin) = 7 THEN
			LET cMesIni = SUBSTR(TRIM(pFechaIni), 1, 2);
			LET cAnoIni = SUBSTR(TRIM(pFechaIni), 4, 7);
			LET cMesFin = SUBSTR(TRIM(pFechaFin), 1, 2);
			LET cAnoFin = SUBSTR(TRIM(pFechaFin), 4, 7);
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesIni,cAnoIni) into cCod_ret2,dtfechainicial, dtfechainicial2 ;
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesFin,cAnoFin) into cCod_ret2,dtfechafinal, dtfechafinal2 ;
		
			FOREACH WITH HOLD
			
				SELECT m.numcte,COUNT(m.numcte), MAX(m.fecha)
				INTO cNumcte,cNumAlerta,dFechaAlerta
				FROM bdicobranza:cb_alerta_succliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)
				WHERE m.numcte = CASE when pNumCte = '' THEN  numcte ELSE pNumCte END	
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region ELSE pRegion END
				AND m.sucursal = CASE when pSucursal = '' THEN  m.sucursal ELSE pSucursal END				
				AND m.estatus = CASE when pSitAlarma = '' THEN  m.estatus   ELSE pSitAlarma END 
				AND m.fecha::DATE between dtfechainicial::DATE AND dtfechafinal2::DATE 			
				GROUP BY m.numcte
				
				SELECT LIMIT 1 m.sucursal, e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad,
				m.situacion
				INTO cSucursal, cEstatusAlerta, cRegion, cNombreCd, cCiudad, cSiglasCd, cSituacion
				FROM bdicobranza:cb_alerta_succliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)  
				INNER JOIN bdicobranza:cb_estatus_loc e ON (e.tipo= m.estatus)
				WHERE m.numcte = cNumcte
				AND m.sucursal = CASE when pSucursal = '' THEN  m.sucursal ELSE pSucursal END
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region ELSE pRegion END
				AND m.estatus = CASE when pSitAlarma = '' THEN  m.estatus   ELSE pSitAlarma END 
				AND m.fecha::DATE = dFechaAlerta
				AND m.numalerta = (SELECT MAX(numalerta) FROM cb_alerta_succliente  
								 WHERE numcte = cNumcte 
								 AND estatus = CASE when pSitAlarma = '' THEN  estatus   ELSE pSitAlarma END
								 AND fecha::DATE = dFechaAlerta);
				
				RETURN cCod_ret, cSucursal, cNumcte,  cNumAlerta, cSituacion, dFechaAlerta, cEstatusAlerta, cRegion, cNombreCd, 
				cCiudad, cSiglasCd WITH RESUME;				
			END FOREACH;
			
		ELSE 
		
			FOREACH  WITH HOLD						
				
				SELECT m.numcte,COUNT(m.numcte), MAX(m.fecha)
				INTO cNumcte,cNumAlerta,dFechaAlerta
				FROM bdicobranza:cb_alerta_succliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)  
				WHERE m.numcte = CASE when pNumCte = '' THEN  m.numcte ELSE pNumCte END
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region ELSE pRegion END				
				AND m.sucursal = CASE when pSucursal = '' THEN  m.sucursal ELSE pSucursal END				
				AND m.estatus = CASE when pSitAlarma = '' THEN  m.estatus   ELSE pSitAlarma END 
				AND m.fecha BETWEEN pFechaIni AND pFechaFin
				GROUP BY m.numcte
				
						
				SELECT LIMIT 1 m.sucursal, e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad,
				m.situacion
				INTO cSucursal, cEstatusAlerta, cRegion, cNombreCd, cCiudad, cSiglasCd, cSituacion
				FROM bdicobranza:cb_alerta_succliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)  
				INNER JOIN bdicobranza:cb_estatus_loc e ON (e.tipo= m.estatus)
				WHERE m.sucursal = CASE when pSucursal = '' THEN  m.sucursal   ELSE pSucursal END
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region   ELSE pRegion END
				AND m.estatus = CASE when pSitAlarma = '' THEN  m.estatus   ELSE pSitAlarma END 
				AND m.numcte = cNumcte
				AND m.fecha = dFechaAlerta
				AND m.numalerta = (SELECT MAX(numalerta) FROM cb_alerta_succliente  
								 WHERE numcte = cNumcte 
								 AND estatus = CASE when pSitAlarma = '' THEN  estatus   ELSE pSitAlarma END
								 AND fecha::DATE = dFechaAlerta );			
				
				RETURN cCod_ret, cSucursal, cNumcte,  cNumAlerta, cSituacion, dFechaAlerta, cEstatusAlerta, cRegion, cNombreCd,
				cCiudad, cSiglasCd WITH RESUME;
				
			END FOREACH;		
		END IF;			
	END IF;

END;
END PROCEDURE

DOCUMENT
'AUTOR: ABIGAIL VASAVILBAZO CAÑEDO',
'DESCRIPCION: GENERA INFORMACION PARA REPORTE DE MARCAS (ORDENADO POR REGION O SUCURSAL)',
'BD: BDICOBRANZA',
'VERSION: 20100910.1209';

CREATE PROCEDURE "informix".sp_cilocgenerarptmarcascte(pNumCte CHAR(20), pSucursal CHAR(4), pRegion SMALLINT, pFechaIni CHAR(10), pFechaFin CHAR(10), pTipo INTEGER, pMarca CHAR(4), pSitMarca CHAR(4))
RETURNING CHAR(5), CHAR(4), CHAR(20), INTEGER, CHAR(4), DATE, CHAR(40), SMALLINT, CHAR(20), CHAR(3), CHAR(4);

--Declaracion de variables
------------------------------------------------------------
DEFINE sql_err 			                INTEGER;
DEFINE isam_err 		                INTEGER;
DEFINE error_info		                CHAR(80);
DEFINE cCod_ret                         CHAR(6);
DEFINE cSucursal						CHAR(4);
DEFINE cNumcte							CHAR(20);
DEFINE iNumMarcas						INTEGER;
DEFINE cTpoMarca						CHAR(4);
DEFINE dFechaMarca						DATE;
DEFINE cEstatusMarca                    CHAR(40);
DEFINE cCiudad							CHAR(3);
DEFINE cNombreCd						CHAR(20);
DEFINE cSiglasCd						CHAR(4);
DEFINE sRegion							SMALLINT;
DEFINE cMesIni							CHAR(2);
DEFINE cAnoIni							CHAR(4);
DEFINE cMesFin							CHAR(2);
DEFINE cAnoFin							CHAR(4);
DEFINE cCod_ret2						CHAR(5);
DEFINE dtfechainicial					DATE;
DEFINE dtfechafinal						DATE;
DEFINE dtfechainicial2					DATE;
DEFINE dtfechafinal2					DATE;
DEFINE cEstatus							CHAR(4);
-----------------------------------------------------
LET cCod_ret  = '00000';
LET sql_err   = 0;
LET cSucursal = '';
LET cNumcte	= '';
LET iNumMarcas	=0;
LET cTpoMarca	= '';
LET dFechaMarca	= '';
LET cEstatusMarca  = '';
LET cCiudad	= '';
LET cNombreCd	= '';
LET cSiglasCd	= '';
LET sRegion		= '';
LET cCod_ret2   = '';
LET cMesIni		= '';
LET cAnoIni		= '';
LET cMesFin		= '';
LET cAnoFin		= '';
LET dtfechainicial='';		
LET dtfechafinal='';
LET dtfechainicial2='';
LET dtfechafinal2='';
LET cEstatus = '';

  BEGIN

	ON EXCEPTION SET sql_err, isam_err, error_info
		LET cCod_ret = sql_err;
		RETURN cCod_ret, cSucursal, cNumcte, iNumMarcas, cTpoMarca, dFechaMarca, cEstatusMarca, sRegion, cNombreCd, cCiudad, cSiglasCd ;
	END EXCEPTION;
	
	--SET DEBUG FILE TO "/tmp/sp_CiLocGeneraRptMarcasCte.out";
	--TRACE ON;
	
	--ORDENADO
	IF pTipo = 2 THEN --POR SUCURSAL
	
		IF LENGTH (pFechaIni) = 7 AND LENGTH (pFechaFin) = 7 THEN
		
			LET cMesIni = SUBSTR(TRIM(pFechaIni), 1, 2);
			LET cAnoIni = SUBSTR(TRIM(pFechaIni), 4, 7);
			LET cMesFin = SUBSTR(TRIM(pFechaFin), 1, 2);
			LET cAnoFin = SUBSTR(TRIM(pFechaFin), 4, 7);
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesIni,cAnoIni) into cCod_ret2,dtfechainicial, dtfechainicial2 ;
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesFin,cAnoFin) into cCod_ret2,dtfechafinal, dtfechafinal2 ;
		
			FOREACH WITH HOLD
			
				SELECT m.sucursal,COUNT(m.numcte), m.numcte, m.tipo_marca, MAX(m.fecha_insert), e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad, m.estatus
				INTO cSucursal, iNumMarcas,cNumcte, cTpoMarca, dFechaMarca, cEstatusMarca, sRegion, cNombreCd, cCiudad, cSiglasCd, cEstatus
				FROM bdicobranza:cb_marcacliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND ( s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)  
				INNER JOIN bdicobranza:cb_estatus_loc e ON (e.tipo= m.estatus)
				INNER JOIN  bdisitesp:se_ctessitespcte p ON (m.numcte = p.numcte)
				WHERE m.sucursal = CASE when pSucursal = '' THEN  s.sucursal   ELSE pSucursal END
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region   ELSE pRegion END
				AND m.numcte = CASE when pNumCte = '' THEN  m.numcte   ELSE pNumCte END
				AND m.tipo_marca = CASE when pMarca = '' THEN  m.tipo_marca   ELSE pMarca END
				AND m.estatus = CASE when pSitMarca = '' THEN  m.estatus   ELSE pSitMarca END 
				AND m.fecha_insert::DATE between dtfechainicial::DATE AND dtfechafinal2::DATE 
				AND p.situacion IN ('L', 'M')
				GROUP BY m.numcte, m.tipo_marca, m.sucursal, m.estatus, e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad
				ORDER BY m.sucursal, m.numcte, m.tipo_marca
				
				RETURN cCod_ret, cSucursal, cNumcte, iNumMarcas, cTpoMarca, dFechaMarca, cEstatusMarca, sRegion, cNombreCd, cCiudad, cSiglasCd WITH RESUME;
				
			END FOREACH;
			
		ELSE
		
			FOREACH WITH HOLD
		
				SELECT m.sucursal,COUNT(m.numcte), m.numcte, m.tipo_marca, MAX(m.fecha_insert), e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad, m.estatus
				INTO cSucursal, iNumMarcas,cNumcte, cTpoMarca, dFechaMarca, cEstatusMarca, sRegion, cNombreCd, cCiudad, cSiglasCd, cEstatus
				FROM bdicobranza:cb_marcacliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND ( s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)   
				INNER JOIN bdicobranza:cb_estatus_loc e ON (e.tipo= m.estatus)
				INNER JOIN  bdisitesp:se_ctessitespcte p ON (m.numcte = p.numcte)
				WHERE m.sucursal = CASE when pSucursal = '' THEN  s.sucursal   ELSE pSucursal END
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region   ELSE pRegion END
				AND m.numcte = CASE when pNumCte = '' THEN  m.numcte   ELSE pNumCte END
				AND tipo_marca = CASE when pMarca = '' THEN  m.tipo_marca   ELSE pMarca END
				AND m.estatus = CASE when pSitMarca = '' THEN  m.estatus   ELSE pSitMarca END 
				AND  m.fecha_insert::DATE between pFechaIni::DATE AND pFechaFin::DATE 
				AND p.situacion IN ('L', 'M')
				GROUP BY m.numcte, m.tipo_marca, m.sucursal, m.estatus, e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad, m.estatus
				ORDER BY m.sucursal, m.numcte, m.tipo_marca				
				
				RETURN cCod_ret, cSucursal, cNumcte, iNumMarcas, cTpoMarca, dFechaMarca, cEstatusMarca, sRegion, cNombreCd, cCiudad, cSiglasCd WITH RESUME;
				
			END FOREACH;
		
		END IF;		
			
	ELIF pTipo = 3 THEN
	
		IF LENGTH (pFechaIni) = 7 AND LENGTH (pFechaFin) = 7 THEN
			LET cMesIni = SUBSTR(TRIM(pFechaIni), 1, 2);
			LET cAnoIni = SUBSTR(TRIM(pFechaIni), 4, 7);
			LET cMesFin = SUBSTR(TRIM(pFechaFin), 1, 2);
			LET cAnoFin = SUBSTR(TRIM(pFechaFin), 4, 7);
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesIni,cAnoIni) into cCod_ret2,dtfechainicial, dtfechainicial2 ;
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesFin,cAnoFin) into cCod_ret2,dtfechafinal, dtfechafinal2 ;
	
			FOREACH WITH HOLD			
	
				SELECT m.sucursal,COUNT(m.numcte), m.numcte, m.tipo_marca, MAX(m.fecha_insert), e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad, m.estatus
				INTO cSucursal, iNumMarcas,cNumcte, cTpoMarca, dFechaMarca, cEstatusMarca, sRegion, cNombreCd, cCiudad, cSiglasCd, cEstatus
				FROM bdicobranza:cb_marcacliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND ( s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)   
				INNER JOIN bdicobranza:cb_estatus_loc e ON (e.tipo= m.estatus)
				INNER JOIN  bdisitesp:se_ctessitespcte p ON (m.numcte = p.numcte)
				WHERE m.sucursal = CASE when pSucursal = '' THEN  s.sucursal   ELSE pSucursal END
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region   ELSE pRegion END
				AND tipo_marca = CASE when pMarca = '' THEN  m.tipo_marca   ELSE pMarca END
				AND m.estatus = CASE when pSitMarca = '' THEN  m.estatus   ELSE pSitMarca END 
				AND m.numcte = CASE when pNumCte = '' THEN  m.numcte   ELSE pNumCte END
				AND  m.fecha_insert::DATE between dtfechainicial::DATE AND dtfechafinal2::DATE 
				AND p.situacion IN ('L', 'M')
				GROUP BY m.numcte, m.tipo_marca, m.sucursal, m.estatus, e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad, m.estatus
				ORDER BY c.numero_region, m.numcte, m.tipo_marca				
				
				RETURN cCod_ret, cSucursal, cNumcte, iNumMarcas, cTpoMarca, dFechaMarca, cEstatusMarca, sRegion, cNombreCd, cCiudad, cSiglasCd WITH RESUME;
				
			END FOREACH;
			
		ELSE
		
			FOREACH WITH HOLD
		
				SELECT m.sucursal,COUNT(m.numcte), m.numcte, m.tipo_marca, MAX(m.fecha_insert), e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad, m.estatus
				INTO cSucursal, iNumMarcas,cNumcte, cTpoMarca, dFechaMarca, cEstatusMarca, sRegion, cNombreCd, cCiudad, cSiglasCd, cEstatus
				FROM bdicobranza:cb_marcacliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND ( s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)  
				INNER JOIN bdicobranza:cb_estatus_loc e ON (e.tipo= m.estatus)	
				INNER JOIN  bdisitesp:se_ctessitespcte p ON (m.numcte = p.numcte)				
				WHERE m.sucursal = CASE when pSucursal = '' THEN  s.sucursal   ELSE pSucursal END
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region   ELSE pRegion END
				AND m.numcte = CASE when pNumCte = '' THEN  m.numcte   ELSE pNumCte END
				AND tipo_marca = CASE when pMarca = '' THEN  m.tipo_marca   ELSE pMarca END
				AND m.estatus = CASE when pSitMarca = '' THEN  m.estatus   ELSE pSitMarca END 
				AND  m.fecha_insert::DATE between pFechaIni::DATE AND pFechaFin::DATE 
				AND p.situacion IN ('L', 'M')
				GROUP BY m.numcte, m.tipo_marca, m.sucursal, m.estatus, e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad, m.estatus
				ORDER BY c.numero_region, m.numcte, m.tipo_marca
				
				RETURN cCod_ret, cSucursal, cNumcte, iNumMarcas, cTpoMarca, dFechaMarca, cEstatusMarca, sRegion, cNombreCd, cCiudad, cSiglasCd WITH RESUME;
			
			END FOREACH;
		
		END IF;
		
	ELIF pTipo = 1 THEN
	
		IF LENGTH (pFechaIni) = 7 AND LENGTH (pFechaFin) = 7 THEN
		
			LET cMesIni = SUBSTR(TRIM(pFechaIni), 1, 2);
			LET cAnoIni = SUBSTR(TRIM(pFechaIni), 4, 7);
			LET cMesFin = SUBSTR(TRIM(pFechaFin), 1, 2);
			LET cAnoFin = SUBSTR(TRIM(pFechaFin), 4, 7);
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesIni,cAnoIni) into cCod_ret2,dtfechainicial, dtfechainicial2 ;
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesFin,cAnoFin) into cCod_ret2,dtfechafinal, dtfechafinal2 ;
		
			FOREACH WITH HOLD
			
				SELECT m.sucursal,COUNT(m.numcte), m.numcte, m.tipo_marca, MAX(m.fecha_insert), e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad, m.estatus
				INTO cSucursal, iNumMarcas,cNumcte, cTpoMarca, dFechaMarca, cEstatusMarca, sRegion, cNombreCd, cCiudad, cSiglasCd, cEstatus
				FROM bdicobranza:cb_marcacliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND ( s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)  
				INNER JOIN bdicobranza:cb_estatus_loc e ON (e.tipo= m.estatus)
				INNER JOIN  bdisitesp:se_ctessitespcte p ON (m.numcte = p.numcte)
				WHERE m.sucursal = CASE when pSucursal = '' THEN  s.sucursal   ELSE pSucursal END
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region   ELSE pRegion END
				AND m.numcte = CASE when pNumCte = '' THEN  m.numcte   ELSE pNumCte END
				AND m.tipo_marca = CASE when pMarca = '' THEN  m.tipo_marca   ELSE pMarca END
				AND m.estatus = CASE when pSitMarca = '' THEN  m.estatus   ELSE pSitMarca END 
				AND  m.fecha_insert::DATE between dtfechainicial::DATE AND dtfechafinal2::DATE 
				AND p.situacion IN ('L', 'M')
				GROUP BY m.numcte, m.tipo_marca, m.sucursal, m.estatus, e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad, m.estatus
				ORDER BY m.numcte, m.tipo_marca

				RETURN cCod_ret, cSucursal, cNumcte, iNumMarcas, cTpoMarca, dFechaMarca, cEstatusMarca, sRegion, cNombreCd, cCiudad, cSiglasCd WITH RESUME;
				
			END FOREACH;
			
		ELSE
		
			FOREACH WITH HOLD
		
				SELECT m.sucursal,COUNT(m.numcte), m.numcte, m.tipo_marca, MAX(m.fecha_insert), e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad, m.estatus
				INTO cSucursal, iNumMarcas,cNumcte, cTpoMarca, dFechaMarca, cEstatusMarca, sRegion, cNombreCd, cCiudad, cSiglasCd, cEstatus
				FROM bdicobranza:cb_marcacliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND ( s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad)   
				INNER JOIN bdicobranza:cb_estatus_loc e ON (e.tipo= m.estatus)
				INNER JOIN  bdisitesp:se_ctessitespcte p ON (m.numcte = p.numcte)
				WHERE m.sucursal = CASE when pSucursal = '' THEN  s.sucursal   ELSE pSucursal END
				AND c.numero_region = CASE when pRegion = 0 THEN  c.numero_region   ELSE pRegion END
				AND m.numcte = CASE when pNumCte = '' THEN  m.numcte   ELSE pNumCte END
				AND tipo_marca = CASE when pMarca = '' THEN  m.tipo_marca   ELSE pMarca END
				AND m.estatus = CASE when pSitMarca = '' THEN  m.estatus   ELSE pSitMarca END 
				AND  m.fecha_insert::DATE between pFechaIni::DATE AND pFechaFin::DATE 
				AND p.situacion IN ('L','M')
				GROUP BY m.numcte, m.tipo_marca, m.sucursal, m.estatus, e.desc_estatus, c.numero_region,d.nombre, s.ciudad, c.inicialciudad, m.estatus
				ORDER BY m.numcte, m.tipo_marca
				
				RETURN cCod_ret, cSucursal, cNumcte, iNumMarcas, cTpoMarca, dFechaMarca, cEstatusMarca, sRegion, cNombreCd, cCiudad, cSiglasCd WITH RESUME;
				
			END FOREACH;
		
		END IF;		
		
	END IF;
	
	IF iNumMarcas = 0 THEN
		LET cCod_ret = '00001';
		RETURN cCod_ret, cSucursal, cNumcte, iNumMarcas, cTpoMarca, dFechaMarca, cEstatusMarca, sRegion, cNombreCd, cCiudad, cSiglasCd;
	END IF;

END;
END PROCEDURE

DOCUMENT
'AUTOR: ABIGAIL VASAVILBAZO CAÑEDO',
'DESCRIPCION: GENERA INFORMACION PARA REPORTE DE MARCAS ORDENADO POR REGION O SUCURSAL ',
'BD: BDICOBRANZA',
'VERSION: 20100910.1206';

CREATE PROCEDURE "informix".sp_cilocgenerarptsituacioncausacte(pSituacion CHAR(1),pCausa SMALLINT,pNumcte CHAR(20),pNumsucursal CHAR(4),pNumRegion smallint,pFechaInicio CHAR (10),pFechaFin CHAR(10),piTipoOrder INTEGER)
		RETURNING   CHAR(5) AS Codigo,	--codret
					CHAR(1) AS Situacion, --Situacion elegida
					SMALLINT AS Causa, --Causa segun la situacion seleccionada
					CHAR(20) AS Num_Cliente,--Numero de cliente
					CHAR(4) AS Num_Sucursal, --Numero de sucursal
					CHAR(30) AS Num_region, --Nombre de region
					DATE AS FechaInicio, -- Fecha de inicio
					DATE AS FechaFin, -- Fecha de fin
					CHAR(8) AS Num_Empleado,--Numero de empleado
					CHAR(12) AS Origen, --Valor de origen
					INTEGER AS Num_ciudad, --Numero de ciudad
					CHAR(30) AS Nom_ciudad, --Nombre de region
					CHAR(4) AS Siglas_ciudad; --Iniciales de ciudad
					
	DEFINE cCodRet 			CHAR(5);
	DEFINE cCod_ret2 		CHAR(5);
	DEFINE iCont            INTEGER;
	DEFINE iSqlErr 			INTEGER;
	DEFINE biTipoOrder      INTEGER;
	DEFINE cSituacion    	CHAR(1);
	DEFINE sCausa 			SMALLINT; 
	DEFINE cNumCte 			CHAR(20);
	DEFINE cNumsucursal		CHAR(4);
	DEFINE sRegion 			SMALLINT;
	DEFINE cFechaInicio 	DATE;
	DEFINE cFechaFin 		DATE;
	DEFINE cNum_empleado    CHAR(8);
	DEFINE cOrigen			CHAR(12);
	DEFINE sNumCiudad		SMALLINT;
	DEFINE cNombreCiudad	CHAR(30);
	DEFINE cSiglas_ciudad   CHAR(4);
	DEFINE cMesIni          CHAR(2);
	DEFINE cAnoIni			CHAR(4);
	DEFINE cMesFin			CHAR(2);
	DEFINE cAnoFin			CHAR(4);
	DEFINE dtfechainicial	DATE;
	DEFINE dtfechafinal		DATE;
	DEFINE dtfechainicial2	DATE;
	DEFINE dtfechafinal2	DATE;
	
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET icont=0;
	LET cSituacion= '';
	LET sCausa='';
	LET cNumCte='';
	LET cNumsucursal='';
	LET sRegion=0;
	LET cFechaInicio='';
	LET cFechaFin='';
	LET cNum_empleado='';
	LET cOrigen='';
	LET sNumCiudad=0;
	LET cNombreCiudad='';
	LET cSiglas_ciudad='';
	LET biTipoOrder=piTipoOrder;
	LET dtfechainicial='';		
	LET dtfechafinal='';
	LET dtfechainicial2='';
	LET dtfechafinal2='';
	--------------------------------------------------------------------------
	--SET DEBUG FILE TO '/home/sysifx/Malena/sp_CiLocGeneraRptSituacionCausaCte.out';
	--TRACE ON;
	--------------------------------------------------------------------------
	
	BEGIN
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;			RETURN cCodRet,cSituacion,sCausa,cNumcte,cNumSucursal,sRegion,cFechaInicio,cFechaFin,cNum_empleado,cOrigen,sNumCiudad,cNombreCiudad,cSiglas_ciudad;
		END EXCEPTION;		
		
	--Se realizan las consultas a la tabla se_ctessitespcte para obtener la informacion para generar el reporte de situaciones causas
	
	set isolation to dirty read; -- Lectura de tablas bloqueadas.
	
	-->>>VALORES DEL TIPO DE ORDENAMIENTO
	--1--Sin ordenar
	--2--Ordenar por sucursal
	--3--Ordenar por region

	IF piTipoOrder = 1 THEN 
	
					IF LENGTH(pFechaInicio)<> 7  OR LENGTH(pFechaFin) <> 7 THEN
						FOREACH
							SELECT CTE.sucursal,CTE.numcte,CTE.situacion,CTE.causa,CTE.fchalta::DATE,CTE.fchmodifica::DATE,CTE.empleadoefectuo,CTE.cvesitesporigen,CAT.numero_region,CAT.numerociudad,CAT.nombreciudad,CAT.inicialciudad
							INTO  cNumSucursal,cNumCte,cSituacion,sCausa,cFechaInicio,cFechaFin,cNum_empleado,cOrigen,sRegion,sNumCiudad,cNombreCiudad,cSiglas_ciudad
							FROM bdisitesp:se_ctessitespcte CTE 
							INNER JOIN bdinteg:si_sucursales AS SUC ON CTE.sucursal=SUC.sucursal 
							INNER JOIN bdinteg:si_ciudades AS CIU ON (SUC.ciudad = CIU.ciudad)AND (SUC.estado = CIU.estado)
							INNER JOIN bdinteg:si_catciudades AS CAT ON (CIU.ciudad_coppel = CAT.numerociudad)
							INNER JOIN bdinteg:si_regiones AS REG ON (CAT.numero_region = REG.numero_region)
							WHERE CTE.situacion = CASE WHEN pSituacion = '' THEN CTE.situacion ELSE pSituacion END
							AND CTE.causa = CASE WHEN pCausa = 0 THEN CTE.causa ELSE pCausa END
							AND CTE.numcte = CASE WHEN pNumcte = '' THEN CTE.numcte ELSE pNumcte END
							AND CTE.sucursal = CASE WHEN pNumsucursal = '' THEN CTE.sucursal ELSE pNumsucursal END
							AND CAT.numero_region = CASE WHEN pNumRegion= 0 THEN CAT.numero_region ELSE pNumregion END
							AND CTE.fchalta::DATE between pFechaInicio::DATE AND pFechaFin::DATE 
							ORDER BY CTE.numcte
							LET icont=icont+1;
							RETURN cCodRet,cSituacion,sCausa,cNumcte,cNumSucursal,sRegion,cFechaInicio,cFechaFin,cNum_empleado,cOrigen,sNumCiudad,cNombreCiudad,cSiglas_ciudad WITH RESUME;
						END FOREACH;
					ELSE
					LET cMesIni = SUBSTR(TRIM(pFechaInicio), 1, 2);
					LET cAnoIni = SUBSTR(TRIM(pFechaInicio), 4, 7);
					LET cMesFin = SUBSTR(TRIM(pFechaFin), 1, 2);
					LET cAnoFin = SUBSTR(TRIM(pFechaFin), 4, 7);
					execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesIni,cAnoIni) into cCod_ret2,dtfechainicial, dtfechainicial2 ;
					execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesFin,cAnoFin) into cCod_ret2,dtfechafinal, dtfechafinal2 ;			
						FOREACH
							SELECT CTE.sucursal,CTE.numcte,CTE.situacion,CTE.causa,CTE.fchalta::DATE,CTE.fchmodifica::DATE,CTE.empleadoefectuo,CTE.cvesitesporigen,CAT.numero_region,CAT.numerociudad,CAT.nombreciudad,CAT.inicialciudad
							INTO  cNumSucursal,cNumCte,cSituacion,sCausa,cFechaInicio,cFechaFin,cNum_empleado,cOrigen,sRegion,sNumCiudad,cNombreCiudad,cSiglas_ciudad
							FROM bdisitesp:se_ctessitespcte CTE 
							INNER JOIN bdinteg:si_sucursales AS SUC ON CTE.sucursal=SUC.sucursal 
							INNER JOIN bdinteg:si_ciudades AS CIU ON (SUC.ciudad = CIU.ciudad)AND (SUC.estado = CIU.estado)
							INNER JOIN bdinteg:si_catciudades AS CAT ON (CIU.ciudad_coppel = CAT.numerociudad)
							INNER JOIN bdinteg:si_regiones AS REG ON (CAT.numero_region = REG.numero_region)
							WHERE CTE.situacion = CASE WHEN pSituacion = '' THEN CTE.situacion ELSE pSituacion END
							AND CTE.causa = CASE WHEN pCausa = 0 THEN CTE.causa ELSE pCausa END
							AND	CTE.numcte = CASE WHEN pNumcte = '' THEN CTE.numcte ELSE pNumcte END
							AND CTE.sucursal = CASE WHEN pNumsucursal = '' THEN CTE.sucursal ELSE pNumsucursal END
							AND CAT.numero_region = CASE WHEN pNumRegion= 0 THEN CAT.numero_region ELSE pNumregion END
							AND CTE.fchalta::DATE between dtfechainicial::DATE AND dtfechafinal2::DATE 
							ORDER BY CTE.numcte
							LET icont=icont+1;
							RETURN cCodRet,cSituacion,sCausa,cNumcte,cNumSucursal,sRegion,cFechaInicio,cFechaFin,cNum_empleado,cOrigen,sNumCiudad,cNombreCiudad,cSiglas_ciudad WITH RESUME;
						END FOREACH;
					END IF;
	END IF;		
	
	IF piTipoOrder= 2 THEN 		
			IF LENGTH(pFechaInicio)<> 7  OR LENGTH(pFechaFin) <> 7 THEN
					FOREACH			
						SELECT CTE.sucursal,CTE.numcte,CTE.situacion,CTE.causa,CTE.fchalta::DATE,CTE.fchmodifica::DATE,CTE.empleadoefectuo,CTE.cvesitesporigen,CAT.numero_region,CAT.numerociudad,CAT.nombreciudad,CAT.inicialciudad
						INTO  cNumSucursal,cNumCte,cSituacion,sCausa,cFechaInicio,cFechaFin,cNum_empleado,cOrigen,sRegion,sNumCiudad,cNombreCiudad,cSiglas_ciudad
						FROM bdisitesp:se_ctessitespcte AS CTE
						INNER JOIN bdinteg:si_sucursales AS SUC ON CTE.sucursal=SUC.sucursal 
						INNER JOIN bdinteg:si_ciudades AS CIU ON (SUC.ciudad = CIU.ciudad)AND (SUC.estado = CIU.estado)
						INNER JOIN bdinteg:si_catciudades AS CAT ON (CIU.ciudad_coppel = CAT.numerociudad)
						INNER JOIN bdinteg:si_regiones AS REG ON (CAT.numero_region = REG.numero_region)
						WHERE CTE.situacion = CASE WHEN pSituacion = '' THEN CTE.situacion ELSE pSituacion END
						AND CTE.causa = CASE WHEN pCausa = 0 THEN CTE.causa ELSE pCausa END
						AND CTE.numcte = CASE WHEN pNumcte = '' THEN CTE.numcte ELSE pNumcte END
						AND CTE.sucursal = CASE WHEN pNumsucursal = '' THEN CTE.sucursal ELSE pNumsucursal END
						AND CAT.numero_region = CASE WHEN pNumRegion= 0 THEN CAT.numero_region ELSE pNumregion END
						AND CTE.fchalta::DATE between pFechaInicio::DATE AND pFechaFin::DATE
						Order by CTE.sucursal
							LET icont=icont+1;
							RETURN cCodRet,cSituacion,sCausa,cNumcte,cNumSucursal,sRegion,cFechaInicio,cFechaFin,cNum_empleado,cOrigen,sNumCiudad,cNombreCiudad,cSiglas_ciudad WITH RESUME;
					END FOREACH;	
			ELSE 
				LET cMesIni = SUBSTR(TRIM(pFechaInicio), 1, 2);
				LET cAnoIni = SUBSTR(TRIM(pFechaInicio), 4, 7);
				LET cMesFin = SUBSTR(TRIM(pFechaFin), 1, 2);
				LET cAnoFin = SUBSTR(TRIM(pFechaFin), 4, 7);
				execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesIni,cAnoIni) into cCod_ret2,dtfechainicial, dtfechainicial2 ;
				execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesFin,cAnoFin) into cCod_ret2,dtfechafinal, dtfechafinal2 ;
					FOREACH			
						SELECT CTE.sucursal,CTE.numcte,CTE.situacion,CTE.causa,CTE.fchalta::DATE,CTE.fchmodifica::DATE,CTE.empleadoefectuo,CTE.cvesitesporigen,CAT.numero_region,CAT.numerociudad,CAT.nombreciudad,CAT.inicialciudad
						INTO  cNumSucursal,cNumCte,cSituacion,sCausa,cFechaInicio,cFechaFin,cNum_empleado,cOrigen,sRegion,sNumCiudad,cNombreCiudad,cSiglas_ciudad
						FROM bdisitesp:se_ctessitespcte AS CTE
						INNER JOIN bdinteg:si_sucursales AS SUC ON CTE.sucursal=SUC.sucursal 
						INNER JOIN bdinteg:si_ciudades AS CIU ON (SUC.ciudad = CIU.ciudad)AND (SUC.estado = CIU.estado)
						INNER JOIN bdinteg:si_catciudades AS CAT ON (CIU.ciudad_coppel = CAT.numerociudad)
						INNER JOIN bdinteg:si_regiones AS REG ON (CAT.numero_region = REG.numero_region)
						WHERE CTE.situacion = CASE WHEN pSituacion = '' THEN CTE.situacion ELSE pSituacion END
						AND CTE.causa = CASE WHEN pCausa = 0 THEN CTE.causa ELSE pCausa END
						AND CTE.numcte = CASE WHEN pNumcte = '' THEN CTE.numcte ELSE pNumcte END
						AND CTE.sucursal = CASE WHEN pNumsucursal = '' THEN CTE.sucursal ELSE pNumsucursal END
						AND CAT.numero_region = CASE WHEN pNumRegion= 0 THEN CAT.numero_region ELSE pNumregion END
						AND CTE.fchalta::DATE BETWEEN  dtfechainicial::DATE AND dtfechafinal2::DATE
						Order by CTE.sucursal
						LET icont=icont+1;
						RETURN cCodRet,cSituacion,sCausa,cNumcte,cNumSucursal,sRegion,cFechaInicio,cFechaFin,cNum_empleado,cOrigen,sNumCiudad,cNombreCiudad,cSiglas_ciudad WITH RESUME;
					END FOREACH;						
			END IF;
	END IF;
	IF piTipoOrder= 3  THEN 
			IF LENGTH(pFechaInicio)<> 7  OR LENGTH(pFechaFin) <> 7 THEN

					FOREACH			
						SELECT CTE.sucursal,CTE.numcte,CTE.situacion,CTE.causa,CTE.fchalta::DATE,CTE.fchmodifica::DATE,CTE.empleadoefectuo,CTE.cvesitesporigen,CAT.numero_region,CAT.numerociudad,CAT.nombreciudad,CAT.inicialciudad
						INTO  cNumSucursal,cNumCte,cSituacion,sCausa,cFechaInicio,cFechaFin,cNum_empleado,cOrigen,sRegion,sNumCiudad,cNombreCiudad,cSiglas_ciudad
						FROM bdisitesp:se_ctessitespcte AS CTE
						INNER JOIN bdinteg:si_sucursales AS SUC ON CTE.sucursal=SUC.sucursal 
						INNER JOIN bdinteg:si_ciudades AS CIU ON (SUC.ciudad = CIU.ciudad)AND (SUC.estado = CIU.estado)
						INNER JOIN bdinteg:si_catciudades AS CAT ON (CIU.ciudad_coppel = CAT.numerociudad)
						INNER JOIN bdinteg:si_regiones AS REG ON (CAT.numero_region = REG.numero_region)
						WHERE CTE.situacion = CASE WHEN pSituacion = '' THEN CTE.situacion ELSE pSituacion END
						AND CTE.causa = CASE WHEN pCausa = 0 THEN CTE.causa ELSE pCausa END
						AND CTE.numcte = CASE WHEN pNumcte = '' THEN CTE.numcte ELSE pNumcte END
						AND CTE.sucursal = CASE WHEN pNumsucursal = '' THEN CTE.sucursal ELSE pNumsucursal END
						AND CAT.numero_region = CASE WHEN pNumRegion= 0 THEN CAT.numero_region ELSE pNumregion END
						AND CTE.fchalta::DATE between pFechaInicio::DATE AND pFechaFin::DATE
						Order by CAT.numero_region
						LET icont=icont+1;
						RETURN cCodRet,cSituacion,sCausa,cNumcte,cNumSucursal,sRegion,cFechaInicio,cFechaFin,cNum_empleado,cOrigen,sNumCiudad,cNombreCiudad,cSiglas_ciudad WITH RESUME;
					END FOREACH;
			ELSE
				LET cMesIni = SUBSTR(TRIM(pFechaInicio), 1, 2);
				LET cAnoIni = SUBSTR(TRIM(pFechaInicio), 4, 7);
				LET cMesFin = SUBSTR(TRIM(pFechaFin), 1, 2);
				LET cAnoFin = SUBSTR(TRIM(pFechaFin), 4, 7);
				execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesIni,cAnoIni) into cCod_ret2,dtfechainicial, dtfechainicial2 ;
				execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesFin,cAnoFin) into cCod_ret2,dtfechafinal, dtfechafinal2 ;
					FOREACH			
						SELECT CTE.sucursal,CTE.numcte,CTE.situacion,CTE.causa,CTE.fchalta::DATE,CTE.fchmodifica::DATE,CTE.empleadoefectuo,CTE.cvesitesporigen,CAT.numero_region,CAT.numerociudad,CAT.nombreciudad,CAT.inicialciudad
						INTO  cNumSucursal,cNumCte,cSituacion,sCausa,cFechaInicio,cFechaFin,cNum_empleado,cOrigen,sRegion,sNumCiudad,cNombreCiudad,cSiglas_ciudad
						FROM bdisitesp:se_ctessitespcte AS CTE
						INNER JOIN bdinteg:si_sucursales AS SUC ON CTE.sucursal=SUC.sucursal 
						INNER JOIN bdinteg:si_ciudades AS CIU ON (SUC.ciudad = CIU.ciudad)AND (SUC.estado = CIU.estado)
						INNER JOIN bdinteg:si_catciudades AS CAT ON (CIU.ciudad_coppel = CAT.numerociudad)
						INNER JOIN bdinteg:si_regiones AS REG ON (CAT.numero_region = REG.numero_region)
						WHERE CTE.situacion = CASE WHEN pSituacion = '' THEN CTE.situacion ELSE pSituacion END
						AND CTE.causa = CASE WHEN pCausa = 0 THEN CTE.causa ELSE pCausa END
						AND CTE.numcte = CASE WHEN pNumcte = '' THEN CTE.numcte ELSE pNumcte END
						AND CTE.sucursal = CASE WHEN pNumsucursal = '' THEN CTE.sucursal ELSE pNumsucursal END
						AND CAT.numero_region = CASE WHEN pNumRegion= 0 THEN CAT.numero_region ELSE pNumregion END
						AND CTE.fchalta::DATE BETWEEN dtfechainicial::DATE AND dtfechafinal2::DATE
						Order by CAT.numero_region		
						LET icont=icont+1;
						RETURN cCodRet,cSituacion,sCausa,cNumcte,cNumSucursal,sRegion,cFechaInicio,cFechaFin,cNum_empleado,cOrigen,sNumCiudad,cNombreCiudad,cSiglas_ciudad WITH RESUME;
					END FOREACH;						
			END IF;
	END IF;			
    IF icont == 0 THEN 
		LET cCodret='00001';  --'No hay Informacion para los criterios de busqueda seleccionados';
        RETURN cCodRet,cSituacion,sCausa,cNumcte,cNumSucursal,sRegion,cFechaInicio,cFechaFin,cNum_empleado,cOrigen,sNumCiudad,cNombreCiudad,cSiglas_ciudad WITH RESUME;
    END IF;

	END;
END PROCEDURE
DOCUMENT
'AUTOR       : Maria Elena Angulo Aispuro',
'DESCRIPCION : Devuelve un listado del resultado de la busqueda segun los criterios seleccionados por el cliente para la generacion del reporte de situacion especial',
'FECHA       : 17 de Agosto de 2010',
'VERSION     : 20100817.1700',
'BD          : BDICOBRANZA';

CREATE PROCEDURE "informix".sp_cilocgenerarpttotalalarmas(pNumCte CHAR(20), pSucursal CHAR(4), pRegion SMALLINT, pFechaIni CHAR(10), pFechaFin CHAR(10), pTipo INTEGER, pSitAlarma CHAR(2))
RETURNING CHAR(5) AS CODIGO, CHAR(4) AS SUCURSAL, SMALLINT as REGION ,CHAR(4) AS SITUACIONESP,CHAR (4) AS SITUACIONALARMA ,CHAR(40) AS SITUACIONALARMADESC,  INTEGER AS TOTAL;

--Declaracion de variables
------------------------------------------------------------
DEFINE sql_err 			                INTEGER;
DEFINE isam_err 		                INTEGER;
DEFINE error_info		                CHAR(80);
DEFINE cCod_ret                         CHAR(6);
DEFINE cCod_ret2                         CHAR(6);
DEFINE cSucursal						CHAR(4);
DEFINE cNumMarcas						INTEGER;
DEFINE cTpoMarca						CHAR(4);
DEFINE sRegion							SMALLINT;
DEFINE cTotal							INTEGER;
DEFINE cSituacionAlarma					CHAR(4);
DEFINE cSituacionAlarmaDesc				CHAR(40);
DEFINE cSituacionEsp					CHAR(4);
DEFINE cMesIni							CHAR(2);
DEFINE cAnoIni							CHAR(4);
DEFINE cMesFin							CHAR(2);
DEFINE cAnoFin							CHAR(4);
DEFINE dtfechainicial 					DATE;
DEFINE dtfechainicial2 					DATE;
DEFINE dtfechafinal     				DATE;
DEFINE dtfechafinal2 					DATE;
-----------------------------------------------------
LET cCod_ret  = '00000';
LET sql_err   = 0;
LET cSucursal = '';
LET cNumMarcas	=0;
LET cTpoMarca	= '';
LET sRegion		= '';
LET cTotal = 0;
LET cSituacionAlarma = '';
LET cSituacionEsp='';
LET cSituacionAlarmaDesc='';

  BEGIN

	ON EXCEPTION SET sql_err, isam_err, error_info
		LET cCod_ret = sql_err;
		RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cSituacionAlarma, ''), NVL(cSituacionAlarmaDesc, ''),NVL(cTotal, 0 );
	END EXCEPTION;
	
	--SET DEBUG FILE TO "/home/sysifx/jesusm/sp_CiLocGeneraRptTotalAlarmas.out";
	--TRACE ON;
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	IF pFechaIni = '' OR pFechaIni IS NULL THEN
		LET cCod_ret= '00001';
		RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cSituacionAlarma, ''), NVL(cSituacionAlarmaDesc, ''),NVL(cTotal, 0 );
	END IF
	IF pTipo = '' OR pTipo IS NULL THEN
		LET cCod_ret= '00002';
		RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cSituacionAlarma, ''), NVL(cSituacionAlarmaDesc, ''),NVL(cTotal, 0 );
	END IF
	--ORDENADO

	IF pTipo = 2 THEN --POR SUCURSAL		
		
		IF LENGTH (pFechaIni) = 7 AND LENGTH (pFechaFin) = 7 THEN
			LET cMesIni = SUBSTR(TRIM(pFechaIni), 1, 2);
			LET cAnoIni = SUBSTR(TRIM(pFechaIni), 4, 7);
			LET cMesFin = SUBSTR(TRIM(pFechaFin), 1, 2);
			LET cAnoFin = SUBSTR(TRIM(pFechaFin), 4, 7);
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesIni,cAnoIni) into cCod_ret2,dtfechainicial, dtfechainicial2 ;
			IF cCod_ret2 <> '000000' THEN 
				LET cCod_ret= '00005';
				RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cSituacionAlarma, ''), NVL(cSituacionAlarmaDesc, ''),NVL(cTotal, 0 );
			END IF;	
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesFin,cAnoFin) into cCod_ret2,dtfechafinal, dtfechafinal2 ;
			IF cCod_ret2 <> '000000' THEN 
				 LET cCod_ret= '00006';
				RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cSituacionAlarma, ''), NVL(cSituacionAlarmaDesc, ''),NVL(cTotal, 0 );
			END IF;	
			FOREACH
		
				SELECT m.sucursal, m.situacion,m.estatus,e.desc_estatus,count(m.estatus)
				INTO cSucursal, cSituacionEsp,cSituacionAlarma,cSituacionAlarmaDesc, cTotal
				FROM cb_alerta_succliente m
				INNER JOIN bdicobranza:cb_estatus_loc e ON (m.estatus= e.tipo)
			--	INNER JOIN  bdisitesp:se_ctessitespcte p ON (m.numcte = p.numcte)
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad) 
				WHERE c.numero_region = c.numero_region 
				AND m.numcte = CASE when pNumCte = '' THEN  m.numcte ELSE pNumCte END
				AND s.sucursal = CASE when pSucursal = '' THEN  s.sucursal   ELSE pSucursal END
				AND m.situacion in ('L','M')
				AND m.estatus = CASE when pSitAlarma = '' THEN  m.estatus   ELSE pSitAlarma END
				AND m.fecha BETWEEN dtfechainicial AND dtfechafinal2
				Group by m.sucursal, m.situacion,m.estatus,e.desc_estatus
				ORDER BY m.sucursal,m.situacion,m.estatus,e.desc_estatus
				
				RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cSituacionAlarma, ''), NVL(cSituacionAlarmaDesc, ''),NVL(cTotal, 0 ) WITH RESUME;	
				
			END FOREACH;		
			
		ELSE 
		
			FOREACH WITH HOLD
				SELECT m.sucursal, m.situacion,m.estatus,e.desc_estatus,count(m.estatus)
				INTO cSucursal, cSituacionEsp,cSituacionAlarma,cSituacionAlarmaDesc, cTotal
				FROM cb_alerta_succliente m
				INNER JOIN bdicobranza:cb_estatus_loc e ON (m.estatus= e.tipo)
				--INNER JOIN  bdisitesp:se_ctessitespcte p ON (m.numcte = p.numcte)
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad) 
				WHERE c.numero_region = c.numero_region 
				AND m.numcte = CASE when pNumCte = '' THEN  m.numcte ELSE pNumCte END
				AND s.sucursal = CASE when pSucursal = '' THEN  s.sucursal   ELSE pSucursal END
				AND m.situacion in ('L','M')
				AND m.estatus = CASE when pSitAlarma = '' THEN  m.estatus   ELSE pSitAlarma END
				AND m.fecha BETWEEN pFechaIni AND pFechaFin
				Group by m.sucursal, m.situacion,m.estatus,e.desc_estatus
				ORDER BY m.sucursal,m.situacion,m.estatus,e.desc_estatus
							
				RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cSituacionAlarma, ''), NVL(cSituacionAlarmaDesc, ''),NVL(cTotal, 0 ) WITH RESUME;	
				
			END FOREACH;
		
		END IF;		
			
	ELIF  pTipo= '3' THEN --TIPO  POR REGION	
	
		IF LENGTH (pFechaIni) = 7 AND LENGTH (pFechaFin) = 7 THEN
			LET cMesIni = SUBSTR(TRIM(pFechaIni), 1, 2);
			LET cAnoIni = SUBSTR(TRIM(pFechaIni), 4, 7);
			LET cMesFin = SUBSTR(TRIM(pFechaFin), 1, 2);
			LET cAnoFin = SUBSTR(TRIM(pFechaFin), 4, 7);
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesIni,cAnoIni) into cCod_ret2,dtfechainicial, dtfechainicial2 ;
			IF cCod_ret2 <> '000000' THEN 
				LET cCod_ret= '00005';
				RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cSituacionAlarma, ''), NVL(cSituacionAlarmaDesc, ''),NVL(cTotal, 0 );	
			END IF;	
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesFin,cAnoFin) into cCod_ret2,dtfechafinal, dtfechafinal2 ;
			IF cCod_ret2 <> '000000' THEN 
				 LET cCod_ret= '00006';
				RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cSituacionAlarma, ''), NVL(cSituacionAlarmaDesc, ''),NVL(cTotal, 0 );
			END IF;	
			FOREACH WITH HOLD
				SELECT c.numero_region, m.situacion,m.estatus,e.desc_estatus,count(m.estatus)
				INTO sRegion, cSituacionEsp,cSituacionAlarma,cSituacionAlarmaDesc, cTotal
				FROM cb_alerta_succliente m
				INNER JOIN bdicobranza:cb_estatus_loc e ON (m.estatus= e.tipo)
			--	INNER JOIN  bdisitesp:se_ctessitespcte p ON (m.numcte = p.numcte)
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad) 
				WHERE c.numero_region = CASE when pRegion = 0 THEN  c.numero_region   ELSE pRegion END
				AND m.numcte = CASE when pNumCte = '' THEN  m.numcte ELSE pNumCte END
				AND s.sucursal = s.sucursal
				AND m.situacion in ('L','M')
				AND m.estatus = CASE when pSitAlarma = '' THEN  m.estatus   ELSE pSitAlarma END
				AND m.fecha BETWEEN dtfechainicial AND dtfechafinal2
				Group by c.numero_region, m.situacion,m.estatus,e.desc_estatus
				ORDER BY c.numero_region,m.situacion,m.estatus,e.desc_estatus
				
				RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cSituacionAlarma, ''), NVL(cSituacionAlarmaDesc, ''),NVL(cTotal, 0 ) WITH RESUME;	
			
			END FOREACH;
			
		ELSE 
		
			FOREACH WITH HOLD
				SELECT c.numero_region, m.situacion,m.estatus,e.desc_estatus,count(m.estatus)
				INTO sRegion, cSituacionEsp,cSituacionAlarma,cSituacionAlarmaDesc, cTotal
				FROM cb_alerta_succliente m
				INNER JOIN bdicobranza:cb_estatus_loc e ON (m.estatus= e.tipo)
			--	INNER JOIN  bdisitesp:se_ctessitespcte p ON (m.numcte = p.numcte)
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad) 
				WHERE c.numero_region = CASE when pRegion = 0 THEN  c.numero_region   ELSE pRegion END
				AND m.numcte = CASE when pNumCte = '' THEN  m.numcte ELSE pNumCte END
				AND s.sucursal = s.sucursal
				AND m.situacion in ('L','M')
				AND m.estatus = CASE when pSitAlarma = '' THEN  m.estatus   ELSE pSitAlarma END
				AND m.fecha BETWEEN pFechaIni AND pFechaFin
				Group by c.numero_region, m.situacion,m.estatus,e.desc_estatus
				ORDER BY c.numero_region,m.situacion,m.estatus,e.desc_estatus
				
				RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cSituacionAlarma, ''), NVL(cSituacionAlarmaDesc, ''),NVL(cTotal, 0 ) WITH RESUME;	
				
			END FOREACH;
		
		END IF;
	ELSE 
		LET cCod_ret= '00004';
		RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cSituacionAlarma, ''), NVL(cSituacionAlarmaDesc, ''),NVL(cTotal, 0 );
	END IF;

END;
END PROCEDURE

DOCUMENT
'AUTOR: ABIGAIL VASAVILBAZO CAÑEDO, HECTOR MANUEL BOJORQUEZ',
'DESCRIPCION: GENERA INFORMACION PARA REPORTE DE ALARMAS (TOTALIZADO POR REGION O SUCURSAL)',
'BD: BDICOBRANZA',
'VERSION: 20100831.1123';

CREATE PROCEDURE "informix".sp_cilocgenerarpttotalmarcas(pNumCte CHAR(20), pSucursal CHAR(4), pRegion SMALLINT, pFechaIni CHAR(10), pFechaFin CHAR(10), pTipo INTEGER, pMarca CHAR(4), pSitMarca CHAR(4))
RETURNING CHAR(5) AS CODIGO, CHAR(4) AS SUCURSAL ,CHAR(4) AS TIPOMARCA, CHAR(40) AS SITUACIONESP, INTEGER AS TOTAL , SMALLINT as REGION;

--Declaracion de variables
------------------------------------------------------------
DEFINE sql_err 			                INTEGER;
DEFINE isam_err 		                INTEGER;
DEFINE error_info		                CHAR(80);
DEFINE cCod_ret                         CHAR(6);
DEFINE cSucursal						CHAR(4);
DEFINE cNumMarcas						INTEGER;
DEFINE cTpoMarca						CHAR(4);
DEFINE sRegion							SMALLINT;
DEFINE cTotal							INTEGER;
DEFINE cSituacionMarca					CHAR(40);
DEFINE cMesIni							CHAR(2);
DEFINE cAnoIni							CHAR(4);
DEFINE cMesFin							CHAR(2);
DEFINE cAnoFin							CHAR(4);
DEFINE cCod_ret2						CHAR(5);
DEFINE dtfechainicial					DATE;
DEFINE dtfechafinal						DATE;
DEFINE dtfechainicial2					DATE;
DEFINE dtfechafinal2					DATE;
-----------------------------------------------------
LET cCod_ret  = '00000';
LET sql_err   = 0;
LET cSucursal = '';
LET cNumMarcas	=0;
LET cTpoMarca	= '';
LET sRegion		= '';
LET cTotal = 0;
LET cSituacionMarca = '';
LET cCod_ret2   = '';
LET cMesIni		= '';
LET cAnoIni		= '';
LET cMesFin		= '';
LET cAnoFin		= '';
LET dtfechainicial='';		
LET dtfechafinal='';
LET dtfechainicial2='';
LET dtfechafinal2='';


  BEGIN

	ON EXCEPTION SET sql_err, isam_err, error_info
		LET cCod_ret = sql_err;
		RETURN cCod_ret, cSucursal, cTpoMarca, cSituacionMarca, cTotal, sRegion ;
	END EXCEPTION;
	
	--SET DEBUG FILE TO "/tmp/sp_CiLocGeneraRptTotalMarcas.out";
	--TRACE ON;
	
	IF pFechaIni = '' OR pFechaIni IS NULL THEN
		LET cCod_ret= '00001';
		RETURN cCod_ret, cSucursal, cTpoMarca, cSituacionMarca, cTotal, sRegion ;		
	END IF
	
	--ORDENADO
	IF pTipo = 2 THEN --POR SUCURSAL		
		
		IF LENGTH (pFechaIni) = 7 AND LENGTH (pFechaFin) = 7 THEN
		
			LET cMesIni = SUBSTR(TRIM(pFechaIni), 1, 2);
			LET cAnoIni = SUBSTR(TRIM(pFechaIni), 4, 7);
			LET cMesFin = SUBSTR(TRIM(pFechaFin), 1, 2);
			LET cAnoFin = SUBSTR(TRIM(pFechaFin), 4, 7);
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesIni,cAnoIni) into cCod_ret2,dtfechainicial, dtfechainicial2 ;
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesFin,cAnoFin) into cCod_ret2,dtfechafinal, dtfechafinal2 ;
			
			FOREACH				
		
				SELECT m.sucursal, COUNT(m.numcte), m.tipo_marca,e.desc_estatus
				INTO cSucursal,cTotal,cTpoMarca, cSituacionMarca
				FROM cb_marcacliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad) 
				INNER JOIN bdicobranza:cb_tipo_marca t ON (t.tipo = m.tipo_marca )
				INNER JOIN bdicobranza:cb_estatus_loc e ON (m.estatus= e.tipo)
				INNER JOIN  bdisitesp:se_ctessitespcte p ON (m.numcte = p.numcte)
				WHERE c.numero_region = CASE when pRegion = 0 THEN  c.numero_region   ELSE pRegion END
				AND m.numcte = CASE when pNumCte = '' THEN  m.numcte ELSE pNumCte END
				AND s.sucursal = CASE when pSucursal = '' THEN  s.sucursal   ELSE pSucursal END
				AND tipo_marca = CASE when pMarca = '' THEN  m.tipo_marca   ELSE pMarca END
				AND m.estatus = CASE when pSitMarca = '' THEN  m.estatus   ELSE pSitMarca END 
				AND m.fecha_insert::DATE between dtfechainicial::DATE AND dtfechafinal2::DATE 
				AND p.situacion IN ('L', 'M')
				Group by m.sucursal,tipo_marca,e.desc_estatus
				ORDER BY m.sucursal, m.tipo_marca
				
				RETURN cCod_ret, cSucursal, cTpoMarca, cSituacionMarca, cTotal, sRegion WITH RESUME;
				
			END FOREACH;		
			
		ELSE 
		
			FOREACH WITH HOLD
		
				SELECT m.sucursal, COUNT(m.numcte), m.tipo_marca,e.desc_estatus
				INTO cSucursal,cTotal,cTpoMarca, cSituacionMarca
				FROM cb_marcacliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad) 
				INNER JOIN bdicobranza:cb_tipo_marca t ON (t.tipo = m.tipo_marca )
				INNER JOIN bdicobranza:cb_estatus_loc e ON (m.estatus= e.tipo)
				INNER JOIN  bdisitesp:se_ctessitespcte p ON (m.numcte = p.numcte)
				WHERE c.numero_region = CASE when pRegion = 0 THEN  c.numero_region   ELSE pRegion END
				AND m.numcte = CASE when pNumCte = '' THEN  m.numcte ELSE pNumCte END
				AND s.sucursal = CASE when pSucursal = '' THEN  s.sucursal   ELSE pSucursal END
				AND tipo_marca = CASE when pMarca = '' THEN  m.tipo_marca   ELSE pMarca END
				AND m.estatus = CASE when pSitMarca = '' THEN  m.estatus   ELSE pSitMarca END 
				AND m.fecha_insert BETWEEN pFechaIni AND pFechaFin
				AND p.situacion IN ('L', 'M')
				Group by m.sucursal,tipo_marca,e.desc_estatus	
				ORDER BY m.sucursal,m.tipo_marca
				
				RETURN cCod_ret, cSucursal, cTpoMarca, cSituacionMarca, cTotal, sRegion WITH RESUME;
				
			END FOREACH;
		
		END IF;		
			
	ELIF  pTipo= '3' THEN --TIPO  POR REGION
	
	
		IF LENGTH (pFechaIni) = 7 AND LENGTH (pFechaFin) = 7 THEN
			LET cMesIni = SUBSTR(TRIM(pFechaIni), 1, 2);
			LET cAnoIni = SUBSTR(TRIM(pFechaIni), 4, 7);
			LET cMesFin = SUBSTR(TRIM(pFechaFin), 1, 2);
			LET cAnoFin = SUBSTR(TRIM(pFechaFin), 4, 7);
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesIni,cAnoIni) into cCod_ret2,dtfechainicial, dtfechainicial2 ;
			execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesFin,cAnoFin) into cCod_ret2,dtfechafinal, dtfechafinal2 ;
		
			FOREACH WITH HOLD
	
				SELECT c.numero_region, COUNT(m.numcte),m.tipo_marca,e.desc_estatus
				INTO sRegion,cTotal,cTpoMarca, cSituacionMarca
				FROM cb_marcacliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad) 
				INNER JOIN bdicobranza:cb_tipo_marca t ON (t.tipo = m.tipo_marca )
				INNER JOIN bdicobranza:cb_estatus_loc e ON (m.estatus= e.tipo)
				INNER JOIN  bdisitesp:se_ctessitespcte p ON (m.numcte = p.numcte)
				WHERE c.numero_region = CASE when pRegion = 0 THEN  c.numero_region   ELSE pRegion END
				AND m.numcte = CASE when pNumCte = '' THEN  m.numcte ELSE pNumCte END
				AND s.sucursal = CASE when pSucursal = '' THEN  s.sucursal   ELSE pSucursal END
				AND tipo_marca = CASE when pMarca = '' THEN  m.tipo_marca   ELSE pMarca END
				AND m.estatus = CASE when pSitMarca = '' THEN  m.estatus   ELSE pSitMarca END
				AND m.fecha_insert::DATE between dtfechainicial::DATE AND dtfechafinal2::DATE 
				AND p.situacion IN ('L', 'M')
				Group by c.numero_region,tipo_marca,e.desc_estatus
				ORDER BY c.numero_region,m.tipo_marca

				RETURN cCod_ret, cSucursal, cTpoMarca, cSituacionMarca, cTotal, sRegion WITH RESUME;
			
			END FOREACH;
			
		ELSE 
		
			FOREACH WITH HOLD
				
				SELECT c.numero_region, COUNT(m.numcte),tipo_marca,e.desc_estatus
				INTO sRegion,cTotal,cTpoMarca, cSituacionMarca
				FROM cb_marcacliente m
				INNER JOIN bdinteg:si_sucursales s ON (m.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad) 
				INNER JOIN bdicobranza:cb_tipo_marca t ON (t.tipo = m.tipo_marca )
				INNER JOIN bdicobranza:cb_estatus_loc e ON (m.estatus= e.tipo)
				INNER JOIN  bdisitesp:se_ctessitespcte p ON (m.numcte = p.numcte)
				WHERE c.numero_region = CASE when pRegion = 0 THEN  c.numero_region   ELSE pRegion END
				AND m.numcte = CASE when pNumCte = '' THEN  m.numcte ELSE pNumCte END
				AND s.sucursal = CASE when pSucursal = '' THEN  s.sucursal   ELSE pSucursal END
				AND tipo_marca = CASE when pMarca = '' THEN  m.tipo_marca   ELSE pMarca END
				AND m.estatus = CASE when pSitMarca = '' THEN  m.estatus   ELSE pSitMarca END 
			    AND m.fecha_insert BETWEEN pFechaIni AND pFechaFin
				AND p.situacion IN ('L', 'M')
				Group by c.numero_region,tipo_marca,e.desc_estatus
				ORDER BY c.numero_region,m.tipo_marca

				RETURN cCod_ret, cSucursal, cTpoMarca, cSituacionMarca, cTotal, sRegion WITH RESUME;
				
			END FOREACH;
		
		END IF;
		
	END IF;

END;
END PROCEDURE

DOCUMENT
'AUTOR: ABIGAIL VASAVILBAZO CAÑEDO, HECTOR MANUEL BOJORQUEZ',
'DESCRIPCION: GENERA INFORMACION PARA REPORTE DE MARCAS (TOTALIZADO POR REGION O SUCURSAL)',
'BD: BDICOBRANZA',
'VERSION: 20100901.1129';

CREATE PROCEDURE "informix".sp_cilocgenerarpttotalsituacioncausa(pSituacion CHAR(4), pCausa SMALLINT,pNumcte CHAR(20), pNumsucursal CHAR(4), pNumRegion SMALLINT, pFechaInicio CHAR(10), pFechaFin CHAR(10), piTipoOrder INTEGER)
RETURNING CHAR(5) AS CODIGO, CHAR(4) AS SUCURSAL , SMALLINT AS REGION ,CHAR(4) AS SITUACIONESP,CHAR(4) AS CAUSA,  INTEGER AS TOTAL;
				
--Declaracion de variables
------------------------------------------------------------
DEFINE sql_err 			                INTEGER;
DEFINE isam_err 		                INTEGER;
DEFINE error_info		                CHAR(80);
DEFINE cCod_ret                         CHAR(6);
DEFINE cCod_ret2                         CHAR(6);
DEFINE cSucursal						CHAR(4);
DEFINE cNumMarcas						INTEGER;
DEFINE sRegion							SMALLINT;
DEFINE cTotal							INTEGER;
DEFINE cSituacionEsp					CHAR(4);
DEFINE cCausa							CHAR(4);
DEFINE cMesIni							CHAR(2);
DEFINE cAnoIni							CHAR(4);
DEFINE cMesFin							CHAR(2);
DEFINE cAnoFin							CHAR(4);
DEFINE dtfechainicial 					DATE;
DEFINE dtfechainicial2 					DATE;
DEFINE dtfechafinal     				DATE;
DEFINE dtfechafinal2 					DATE;
-----------------------------------------------------
LET cCod_ret  = '00000';
LET sql_err   = 0;
LET cSucursal = '';
LET cNumMarcas	=0;
LET sRegion		= '';
LET cTotal = 0;
LET cSituacionEsp='';
LET cCausa = '';

  BEGIN

	ON EXCEPTION SET sql_err, isam_err, error_info
		LET cCod_ret = sql_err;
		RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cCausa, ''), NVL(cTotal, 0 );					
	END EXCEPTION;

	--SET DEBUG FILE TO "/home/sysifx/jesusm/sp_CiLocGeneraRptTotalAlarmas.out";
	--TRACE ON;
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	IF pFechaInicio = '' OR pFechaInicio IS NULL THEN
		LET cCod_ret= '00001';
		RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cCausa, ''), NVL(cTotal, 0 );					
	END IF
	IF piTipoOrder = '' OR piTipoOrder IS NULL THEN
		LET cCod_ret= '00002';
		RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cCausa, ''), NVL(cTotal, 0 );					
	END IF
	--ORDENADO
	IF piTipoOrder = 2 THEN --POR SUCURSAL		
		
		IF LENGTH (pFechaInicio) = 7 AND LENGTH (pFechaFin) = 7 THEN
		LET cMesIni = SUBSTR(TRIM(pFechaInicio), 1, 2);
		LET cAnoIni = SUBSTR(TRIM(pFechaInicio), 4, 7);
		LET cMesFin = SUBSTR(TRIM(pFechaFin), 1, 2);
		LET cAnoFin = SUBSTR(TRIM(pFechaFin), 4, 7);
		execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesIni,cAnoIni) into cCod_ret2,dtfechainicial, dtfechainicial2 ;
		IF cCod_ret2 <> '000000' THEN 
			LET cCod_ret= '00005';
			RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cCausa, ''), NVL(cTotal, 0 );					
		END IF;	
		execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesFin,cAnoFin) into cCod_ret2,dtfechafinal, dtfechafinal2 ;
		IF cCod_ret2 <> '000000' THEN 
			 LET cCod_ret= '00006';
			 RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cCausa, ''), NVL(cTotal, 0 );					
		END IF;	
	
			FOREACH
	
				SELECT p.sucursal, p.situacion, p.causa, COUNT(p.numcte)
				INTO cSucursal, cSituacionEsp, cCausa, cTotal
				FROM bdisitesp:se_ctessitespcte p
				INNER JOIN bdinteg:si_sucursales s ON (p.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad) 
				WHERE c.numero_region =c.numero_region
				AND p.numcte = CASE when pNumCte = '' THEN  p.numcte ELSE pNumCte END
				AND s.sucursal = CASE when pNumsucursal = '' THEN  s.sucursal   ELSE pNumsucursal END
				AND p.situacion = CASE when pSituacion = '' THEN  p.situacion   ELSE pSituacion END
				AND p.causa = CASE when pCausa = 0  THEN  p.causa ELSE pCausa END
				AND p.fchalta::DATE BETWEEN dtfechainicial AND dtfechafinal2
				Group by p.sucursal, p.situacion,p.causa
				ORDER BY p.sucursal,p.situacion,p.causa
				
				RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cCausa, ''), NVL(cTotal, 0 )	 WITH RESUME;				
				
			END FOREACH;					
		ELSE 
		
			FOREACH WITH HOLD
		
				SELECT p.sucursal, p.situacion, p.causa, COUNT(p.numcte)
				INTO cSucursal, cSituacionEsp, cCausa, cTotal
				FROM bdisitesp:se_ctessitespcte p
				INNER JOIN bdinteg:si_sucursales s ON (p.sucursal= s.sucursal)
				INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
				INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad) 
				WHERE c.numero_region =c.numero_region 
				AND p.numcte = CASE when pNumCte = '' THEN  p.numcte ELSE pNumCte END
				AND s.sucursal = CASE when pNumsucursal = '' THEN  s.sucursal   ELSE pNumsucursal END
				AND p.situacion = CASE when pSituacion = '' THEN  p.situacion   ELSE pSituacion END
				AND p.causa = CASE when pCausa = 0 THEN  p.causa ELSE pCausa END
				AND p.fchalta::DATE  BETWEEN pFechaInicio::DATE AND pFechaFin::DATE
				Group by p.sucursal, p.situacion,p.causa
				ORDER BY p.sucursal,p.situacion,p.causa			
							
				RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cCausa, ''), NVL(cTotal, 0 )  WITH RESUME;			
				
			END FOREACH;
		
		END IF;		
			
	ELIF  piTipoOrder= 3 THEN --TIPO  POR REGION	
	
		IF LENGTH (pFechaInicio) = 7 AND LENGTH (pFechaFin) = 7 THEN
		LET cMesIni = SUBSTR(TRIM(pFechaInicio), 1, 2);
		LET cAnoIni = SUBSTR(TRIM(pFechaInicio), 4, 7);
		LET cMesFin = SUBSTR(TRIM(pFechaFin), 1, 2);
		LET cAnoFin = SUBSTR(TRIM(pFechaFin), 4, 7);
		execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesIni,cAnoIni) into cCod_ret2,dtfechainicial, dtfechainicial2 ;
		IF cCod_ret2 <> '000000' THEN 
			LET cCod_ret= '00005';
			RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cCausa, ''), NVL(cTotal, 0 );					
		END IF;	
		execute  procedure bdinteg:sp_diaprimeroultimomesanio(cMesFin,cAnoFin) into cCod_ret2,dtfechafinal, dtfechafinal2 ;
		IF cCod_ret2 <> '000000' THEN 
			 LET cCod_ret= '00006';
			 RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cCausa, ''), NVL(cTotal, 0 );					
		END IF;	
			FOREACH WITH HOLD				

					SELECT c.numero_region, p.situacion, p.causa, COUNT(p.numcte)
					INTO sRegion, cSituacionEsp, cCausa, cTotal
					FROM bdisitesp:se_ctessitespcte p
					INNER JOIN bdinteg:si_sucursales s ON (p.sucursal= s.sucursal)
					INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
					INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad) 
					WHERE c.numero_region = CASE when pNumRegion = 0 THEN  c.numero_region   ELSE pNumRegion END
					AND p.numcte = CASE when pNumCte = '' THEN  p.numcte ELSE pNumCte END
					AND s.sucursal =  s.sucursal
					AND p.situacion = CASE when pSituacion = '' THEN  p.situacion   ELSE pSituacion END
					AND p.causa = CASE when pCausa = 0 THEN  p.causa ELSE pCausa END
					AND p.fchalta::DATE BETWEEN dtfechainicial AND dtfechafinal2
					Group by c.numero_region, p.situacion,p.causa
					ORDER BY c.numero_region,p.situacion,p.causa

				RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cCausa, ''), NVL(cTotal, 0 )  WITH RESUME;
				

			END FOREACH;		
				
		ELSE 
		
			FOREACH WITH HOLD
				
					SELECT c.numero_region, p.situacion, p.causa, COUNT(p.numcte)
					INTO sRegion, cSituacionEsp, cCausa, cTotal
					FROM bdisitesp:se_ctessitespcte p
					INNER JOIN bdinteg:si_sucursales s ON (p.sucursal= s.sucursal)
					INNER JOIN bdinteg: si_ciudades d ON (d.ciudad = s.ciudad) AND (s.estado= d.estado)
					INNER JOIN bdinteg:si_catciudades c ON (d.ciudad_coppel = c.numerociudad) 
					WHERE c.numero_region = CASE when pNumRegion = 0 THEN  c.numero_region   ELSE pNumRegion END
					AND p.numcte = CASE when pNumCte = '' THEN  p.numcte ELSE pNumCte END
					AND s.sucursal = s.sucursal 
					AND p.situacion = CASE when pSituacion = '' THEN  p.situacion   ELSE pSituacion END
					AND p.causa = CASE when pCausa = 0 THEN  p.causa ELSE pCausa END
					AND p.fchalta::DATE BETWEEN pFechaInicio::DATE AND pFechaFin::DATE
					Group by c.numero_region, p.situacion,p.causa
					ORDER BY c.numero_region,p.situacion,p.causa

				RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cCausa, ''), NVL(cTotal, 0 ) 	 WITH RESUME;
				
			END FOREACH;
		
		END IF;
	ELSE 
		LET cCod_ret= '00004';
		RETURN cCod_ret, NVL(cSucursal, ''), NVL(sRegion, 0), NVL(cSituacionEsp, ''), NVL(cCausa, ''), NVL(cTotal, 0 );	
	END IF;

END;
END PROCEDURE
DOCUMENT
'AUTOR: ABIGAIL VASAVILBAZO CAÑEDO',
'DESCRIPCION: GENERA INFORMACION PARA REPORTE DE SITUACION Y CAUSA (TOTALIZADO POR REGION O SUCURSAL)',
'BD: BDICOBRANZA',
'VERSION: 20100831.1122',
'BD: BDICOBRANZA';

CREATE PROCEDURE "informix".sp_cilocinsertamarcaautomatica()
RETURNING CHAR(5);

--Declaracion de variables
------------------------------------------------------------
DEFINE sql_err 			                INTEGER;
DEFINE isam_err 		                INTEGER;
DEFINE error_info		                CHAR(80);
DEFINE cCod_ret                         CHAR(6);
DEFINE dFechaHoy						DATE;
DEFINE iNumDias							INTEGER;
DEFINE dFechaLim						DATE;
DEFINE cNumcte							CHAR(20);
DEFINE cNombre							CHAR(40);
DEFINE cUsuario							CHAR(80);
DEFINE cCausa							CHAR(80);
DEFINE cSituacionEsp					CHAR(80);
-----------------------------------------------------
LET cCod_ret  		= '00000';
LET sql_err   		= 0;
LET dFechaHoy		= '';
LET iNumDias		= 0;
LET dFechaLim		= '';
LET cNumcte			= '';
LET cNombre			= '';
LET cUsuario		= '';
LET cCausa			= '';
LET cSituacionEsp 	= '';

  BEGIN

	ON EXCEPTION SET sql_err, isam_err, error_info
		LET cCod_ret = sql_err;
		RETURN cCod_ret;
	END EXCEPTION;
	
	--SET DEBUG FILE TO "/tmp/sp_CiLocInsertaMarcaAutomatica.out";
	--TRACE ON;
	
	SELECT fecha_hoy
	INTO dFechaHoy
	FROM bdinteg: si_fechas;
	
	SELECT NVL(valor,'')
	INTO cCausa					--Causa Necesaria para la ejecucion del sp_sustituirse, Causa por la cual será reemplazada la anterior.
	FROM bdicobranza:cb_param
	WHERE cod_param = '31';

	SELECT NVL(valor,'')
	INTO cSituacionEsp			--Situación Necesaria para la ejecucion del sp_sustituirse, Situacion por la cual será reemplazada la anterior.
	FROM bdicobranza:cb_param
	WHERE cod_param = '30';
	
	SELECT NVL(valor,'') 
	INTO cUsuario				--Usuario Necesario para la ejecución del sp:  sp_sustituirse.
	FROM bdicobranza:cb_param
	WHERE cod_param = '19';
	
	SELECT NVL(valor,'') 
	INTO iNumDias
	FROM bdicobranza:cb_param
	WHERE empresa = '001'
	AND cod_param = '15';
	
	LET iNumDias = iNumDias * 30;
	LET dFechaLim = dFechaHoy - iNumDias;
	
	FOREACH WITH HOLD
		
		SELECT numcte 
		INTO cNumcte
		FROM bdisitesp:se_ctessitespcTE 
		WHERE situacion = 'L' 
		AND fchalta::date <= dFechaLim

		EXECUTE PROCEDURE bdisitesp:sp_sustituirse( cNumcte,
							'001',
							'',
							TRIM(cSituacionEsp),
							TRIM(cCausa),
							TRIM(cUsuario),
							TRIM(cUsuario),
							'1'		--1= Cliente, 2.- Credito
							) INTO cCod_ret;
		
		IF cCod_ret <> 0 THEN
			CONTINUE FOREACH;
		END IF;
		
		IF EXISTS ( SELECT numcte FROM bdicobranza:cb_marcacliente WHERE numcte= cNumcte AND estatus = 'SA') THEN
			UPDATE bdicobranza:cb_marcacliente SET estatus = 'NA', usuario_desmarca = cUsuario, fecha_modificacion= dFechaHoy WHERE numcte= cNumcte AND estatus = 'SA' ;
		END IF;
		
		UPDATE bdicobranza:cb_alerta_succliente SET estatus= 'NA' WHERE numcte = cNumcte AND estatus = 'SA';
		
	END FOREACH;
RETURN cCod_ret;
END;
END PROCEDURE

DOCUMENT
'AUTOR: ABIGAIL VASAVILBAZO CAÑEDO',
'MODIFICO : HECTOR MANUEL BOJORQUEZ RUELAS',
'DESCRIPCION: CAMBIA DE MANERA AUTOMATICA DE SITUACION L A SITUACION M ',
'BD: BDICOBRANZA',
'VERSION: 20100914.1217';

CREATE PROCEDURE "informix".sp_cilocregistradesmarcaje( pOrigen CHAR(1),
											 pTpoDir 			CHAR(1),
											 pNumCte 			CHAR(20),
											 pEmpresa 			CHAR(3),
											 pFecha				DATE,
											 pUsuario			CHAR(8),
											 pSucursal			CHAR(4)
											)
RETURNING CHAR(5);

--Declaracion de variables
------------------------------------------------------------
DEFINE sql_err 			                INTEGER;
DEFINE isam_err 		                INTEGER;
DEFINE error_info		                CHAR(80);
DEFINE cCod_ret                         CHAR(6);
DEFINE dFechaHoy						DATE;
DEFINE iNumDias							INTEGER;
DEFINE dFechaLim						DATE;
DEFINE cNumcte							CHAR(20);
DEFINE cNombre							CHAR(40);
DEFINE cUsuario							CHAR(8);
DEFINE cSituacion						CHAR(1);
DEFINE cCausa							SMALLINT;
DEFINE iSecuencia						INTEGER;
DEFINE cSitEspecial						CHAR(1);		
DEFINE sCausaSE							SMALLINT;
DEFINE vTransaccion						INTEGER;
-----------------------------------------------------
LET cCod_ret  	= '00000';
LET sql_err   	= 0;
LET dFechaHoy	= '';				
LET iNumDias	=0;						
LET dFechaLim	='';	
LET cNumcte		= '';
LET cNombre		= '';	
LET cUsuario	= '';
LET cSituacion  = '';
LET cCausa		= 0;
LET iSecuencia = 0;
LET cSitEspecial = '';		
LET sCausaSE	= 0;
LET vTransaccion = 0;

 --SET DEBUG FILE TO "/tmp/sp_CiLocRegistraDesmarcaje.out";
 --TRACE ON;

  BEGIN
  
	ON EXCEPTION SET sql_err, isam_err, error_info
		IF sql_err = -535 THEN
			LET vTransaccion = 1;
			COMMIT WORK;
			BEGIN WORK;
		ELSE
			IF vTransaccion = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF
			LET cCod_ret = sql_err;
			RETURN cCod_ret;
		END IF
	END EXCEPTION WITH RESUME;

    IF vTransaccion = 0 THEN
         BEGIN WORK;
    END IF
	
	 IF EXISTS ( SELECT 1 FROM bdinteg:si_direcciones WHERE numcte= pNumCte AND tipo_dir = pTpoDir AND fecha_insert = pFecha) AND 
	 EXISTS (SELECT 1 FROM bdisitesp:se_ctessitespcte WHERE numcte =pNumCte AND situacion IN ('L','M') ) THEN		
	
		UPDATE bdisitesp:se_ctessitespcte SET motivo_desmarcaje= 'digitalizacion de campo de comprobante de domiclio' WHERE numcte= pNumCte AND situacion = 'L' ;
		
		SELECT situacion, causa
		INTO cSitEspecial, sCausaSE
		FROM bdisitesp:se_ctessitespcte
		WHERE numcte= pNumCte;
		
		EXECUTE PROCEDURE bdisitesp:sp_eliminarse(pNumCte,
										 pEmpresa,
										 '',
										 cSitEspecial,
										 sCausaSE	,
										 pUsuario,
										 pUsuario,
										 1 ,	--1.- Cliente, 2.- Credito
										 1		--1.- Individual, 2.- General
										) INTO cCod_ret;
		
		IF cCod_ret <> '000' THEN
			ROLLBACK WORK;
			LET cCod_ret= '00002';
			IF vTransaccion = 1 THEN         
				BEGIN WORK;
			END IF;
			RETURN cCod_ret;	
		END IF;		
			
		UPDATE bdicobranza:cb_alerta_succliente SET estatus= 'AT' WHERE numcte = pNumCte AND tipo_domicilio = pTpoDir AND estatus = 'SA';
		
		INSERT INTO bdicobranza:cb_alerta_succlientehis (numalerta, fecha, numcte, hora, tipo_alerta, estatus, sucursal, accion_origen, 
					situacion, causa, origen, tipo_domicilio)
		SELECT numalerta, fecha, numcte, hora, tipo_alerta, estatus, sucursal, accion_origen, situacion, causa, origen,
			   tipo_domicilio FROM bdicobranza:cb_alerta_succliente WHERE numcte = pNumCte AND tipo_domicilio = pTpoDir;
			   
		DELETE FROM bdicobranza:cb_alerta_succliente WHERE numcte = pNumCte AND tipo_domicilio = pTpoDir;
		
		IF EXISTS ( SELECT * FROM bdicobranza:cb_marcacliente WHERE numcte= pNumCte AND estatus = 'SA' AND tipo_domicilio = pTpoDir) THEN
			UPDATE cb_marcacliente SET estatus = 'AT', fecha_modificacion= pFecha WHERE numcte= pNumCte AND estatus = 'SA' AND tipo_domicilio = pTpoDir;
			INSERT INTO cb_marcacliente ( numcte, tipo_domicilio, tipo_marca, fecha_insert, estatus, fecha_modificacion, usuario_marca, 
										  usuario_desmarca, origen, sucursal)
			VALUES( pNumCte, pTpoDir, 'BL', pFecha, 'AT', pFecha, pUsuario, pUsuario, pOrigen ,pSucursal);		--Origen: 1 SUC/PLATAFORMA, 2 CENTRAL, 3 BPI	
			
			SELECT MAX(secuencia) 
			INTO iSecuencia
			FROM bdinteg:si_direcciones_loc 
			WHERE numcte= pNumCte 
			AND tipo_dir = pTpoDir;
			
			UPDATE bdinteg:si_direcciones_loc SET dom_verificado = 'S' WHERE numcte = pNumCte AND tipo_dir = pTpoDir AND secuencia = iSecuencia;
			
		END IF;		
	ELSE
		ROLLBACK WORK;
		LET cCod_ret= '00001';
		IF vTransaccion = 1 THEN         
			BEGIN WORK;
		END IF;
		RETURN cCod_ret;			
	END IF;	
	
	
	COMMIT WORK;
	
	IF vTransaccion = 1 THEN         
         BEGIN WORK;
    END IF;
	
	RETURN cCod_ret;	
END;
END PROCEDURE

DOCUMENT
'AUTOR: ABIGAIL VASAVILBAZO CAÑEDO',
'DESCRIPCION: ACTUALIZA A ATENDIDAS LAS MARCAS, ALERTAS Y ELIMINA LA SITUACION ESPECIAL ',
'BD: BDICOBRANZA',
'VERSION: 20100910.1551';

CREATE PROCEDURE "informix".sp_cargatelefonosburo()
       RETURNING CHAR(5), CHAR(80);
       
DEFINE vCodRet                  CHAR(5);
DEFINE vMensaje                 CHAR(80);
DEFINE SQL_ERR, ISAM_ERR        INTEGER;
DEFINE ERROR_INFO               VARCHAR(80);
DEFINE v_fecha                  DATE;
DEFINE v_dia, v_mes             CHAR(2);
DEFINE v_anio                   CHAR(4);
DEFINE cRuta                    CHAR(100);
DEFINE cRuta2                   CHAR(100);  
DEFINE cNombre                  CHAR(100);
DEFINE cNombre2                 CHAR(100);      
DEFINE iParamRuta               INTEGER;
DEFINE iParamNombre             INTEGER;  
DEFINE iRegistros               INTEGER;
DEFINE v_count                  INTEGER;
DEFINE cCadena                  CHAR(2000);
DEFINE cEmpresa                 CHAR(3);
DEFINE v_numcte                 CHAR(20); 
DEFINE v_cuenta                 CHAR(20);
DEFINE v_telefono1              CHAR(13);
DEFINE v_telefono2              CHAR(13); 
DEFINE v_telefono3              CHAR(13); 
DEFINE v_telefono4              CHAR(13);
DEFINE v_telefono5              CHAR(13);
DEFINE v_longitud               SMALLINT; 
DEFINE vCodRet_2                CHAR(6);
DEFINE vCodRet_tel              CHAR(5);
DEFINE cProceso                 CHAR(4);
DEFINE vvcCod_ret               CHAR(6);

LET SQL_ERR  = 0; 
LET ISAM_ERR = 0; 
LET ERROR_INFO = '';
LET vCodRet  = '00000'; LET vCodRet_2   = ''; LET vCodRet_tel = '';  
LET vvcCod_ret  = '';
LET vMensaje = '';
LET v_fecha  = DATE(1);
LET v_dia    = '';  LET v_mes    = '';  LET v_anio   = '';
LET cRuta    = '';  LET cNombre  = '';
LET cRuta2   = '';  LET cNombre2 = '';
LET iParamRuta  = 20;
LET iParamNombre = 40;
LET iRegistros  = 0;
LET cCadena     = '';
LET cEmpresa    = '001';
LET v_count     = 0;
LET v_numcte = ''; 
LET v_cuenta = '';
LET v_telefono1 = '';  LET v_telefono2 = '';  LET v_telefono3 = '';  
LET v_telefono4 = '';  LET v_telefono5 = '';
LET v_longitud  = 0;
LET cProceso    = '0020';   


 --SET DEBUG FILE TO "/informix/macf/sp_cargatelefonosburo.out";
 --TRACE ON; 

BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, ERROR_INFO
        LET vCodRet  = SQL_ERR;
        LET vMensaje  = ERROR_INFO;
         
        IF vCodRet = '-668' THEN
            LET vMensaje  = ISAM_ERR || ' El archivo a procesar no se encuentra en la carpeta';
            CALL bdicobranza:"informix".sp_inserta_bitacora_cob(cEmpresa, cProceso, vCodRet, trim(vMensaje), '02')
            RETURNING vvcCod_ret;
            LET vCodRet  = '00000';
            LET vMensaje  = '';
            RETURN vCodRet, vMensaje;
        ELSE 
            CALL bdicobranza:"informix".sp_inserta_bitacora_cob(cEmpresa, cProceso, vCodRet, vMensaje, '02')
            RETURNING vvcCod_ret;
        END IF;
          
        RETURN vCodRet, vMensaje;
        
    END EXCEPTION;

    SET LOCK MODE TO WAIT 3;
    CALL bdicobranza:"informix".sp_inserta_bitacora_cob(cEmpresa, cProceso, vCodRet, vMensaje, '01') RETURNING vvcCod_ret;
    SET ISOLATION TO dirty READ;

    SELECT fecha_hoy 
    into v_fecha
    from bdinteg:si_fechas
    WHERE empresa = cEmpresa;
    
    IF EXISTS(SELECT tabname FROM sysmaster:systabnames WHERE tabname = 'tmp_telefonos_buro_2'  AND dbsname = 'bdicobranza') THEN
            DROP TABLE tmp_telefonos_buro_2;
    END IF;

    CREATE TABLE "informix".tmp_telefonos_buro_2
    (
    	cuenta           CHAR(20),
    	empleo           CHAR(60),
    	calleynum        CHAR(60),
    	colonia          CHAR(60),    	
    	delegacion       CHAR(60),
    	ciudad           CHAR(60),
    	estado           CHAR(10),
    	cp               CHAR(10),
    	telefono1        CHAR(13),
    	telefono2        CHAR(13),
    	telefono3        CHAR(13),
    	telefono4        CHAR(13),
    	telefono5        CHAR(13),
    	fecha_reg        CHAR(10) 
    );

    --CUENTA|EMPLEO|CALLE Y NUMERO|COLONIA|DELEGACION|CIUDAD|ESTADO|CP|TELEFONOS|FECHA
    CREATE INDEX "informix".idx_tmp_telefonos_buro_2 ON tmp_telefonos_buro_2 (cuenta) USING btree ;

    IF day(v_fecha) < 10 then
    	LET v_dia = '0' || day(v_fecha);
    ELSE
    	LET v_dia = day(v_fecha);
    END IF;
    
    IF month(v_fecha) < 10 then
    	LET v_mes = '0' || month(v_fecha);
    ELSE
    	LET v_mes = month(v_fecha);
    END IF;
    
    LET v_anio = year(v_fecha);

    SELECT valor  INTO cRuta
      FROM bdicobranza:cb_param
     WHERE empresa = cEmpresa
       AND cod_param = iParamRuta;

    SELECT valor  INTO cNombre2
      FROM bdicobranza:cb_param
     WHERE empresa = cEmpresa
       AND cod_param = iParamNombre;
   
    --LET vMensaje = 'Obtuvo parametros..' || iParamRuta || '-' || iParamNombre || '  ' || v_dia || v_mes || v_anio || ' -- ' || cRuta || '  ' || cNombre2;
    
  IF NVL(cRuta,'') <> '' and NVL(cNombre2, '') <> '' THEN

    LET cNombre = trim(SUBSTR(cNombre2,1,LENGTH(cNombre2)) || v_dia || v_mes || v_anio || '.txt');
    
    LET cCadena = 'echo "load from ''' || SUBSTR(cRuta,1,LENGTH(cRuta)) || SUBSTR(cNombre,1,LENGTH(cNombre)) || '''' ||
                  ' insert into bdicobranza:tmp_telefonos_buro_2 " > ' || SUBSTR(cRuta,1,LENGTH(cRuta)) || 'importa_telefonosburo.sql;';
      
    system SUBSTR(cCadena,1,LENGTH(cCadena));              
    --INSERT INTO bdicobranza:cb_mensajes_trace(nom_variable, descripcion) VALUES('cCadena', trim(cCadena));

    LET cCadena = 'dbaccess bdicobranza ' || SUBSTR(cRuta,1,LENGTH(cRuta)) || 'importa_telefonosburo.sql';
    
    system SUBSTR(cCadena,1,LENGTH(cCadena));
    --DESPUES QUE LOS IMPORTE SE DEBERAN PROCESAR para insertarlos a CB_TELEFONOS  con el SP "sp_cat_graba_telefono_adicional" usado por Cajera Capturista

    SELECT count(*) into v_count 
      FROM tmp_telefonos_buro_2;
      
     IF v_count <= 0 THEN
         LET vCodRet = '00001';
         LET vMensaje = 'NO SE CARGARON REGISTROS A LA TABLA TEMPORAL';
         RETURN vCodRet, vMensaje;  
     END IF;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    --SET pdqpriority 20;
   
     FOREACH 
           SELECT cuenta, telefono1, telefono2, telefono3, telefono4, telefono5               --LENGTH(telefono1)  
             INTO v_cuenta, v_telefono1, v_telefono2, v_telefono3, v_telefono4, v_telefono5   --v_longitud
             FROM bdicobranza:tmp_telefonos_buro_2

           SELECT FIRST 1 numcte INTO v_numcte
             FROM bdicred:sd_maecred
            WHERE num_credito = v_cuenta;

           
           IF LENGTH(v_telefono1)>= 10 THEN  --MÍNIMO QUE SEA DE 10 POSICIONES.
              -- VALIDAR QUE NO TRAIGA CARACTERES RAROS (bdinteg:sp_tipored solo recibe tels de 10 caracteres)
              EXECUTE procedure bdinteg:"informix".sp_validar_telefono(v_telefono1) into vCodRet_tel;

              IF vCodRet_tel = '00000' THEN
                  EXECUTE PROCEDURE "informix".sp_cat_graba_telefono_adicional(cEmpresa, 5, v_numcte, 1, v_telefono1, '', '', 0, user) INTO vCodRet_2;
              END IF;
           END IF;
           LET vCodRet_tel = '';
           
           IF LENGTH(v_telefono2)>= 10 THEN  
              EXECUTE procedure bdinteg:"informix".sp_validar_telefono(v_telefono2) into vCodRet_tel;

              IF vCodRet_tel = '00000' THEN
                  EXECUTE PROCEDURE "informix".sp_cat_graba_telefono_adicional(cEmpresa, 5, v_numcte, 2, v_telefono2, '', '', 0, user) INTO vCodRet_2;
              END IF;
           END IF;
           LET vCodRet_tel = '';
            
           IF LENGTH(v_telefono3)>= 10 THEN  
              EXECUTE procedure bdinteg:"informix".sp_validar_telefono(v_telefono3) into vCodRet_tel;

              IF vCodRet_tel = '00000' THEN
                  EXECUTE PROCEDURE "informix".sp_cat_graba_telefono_adicional(cEmpresa, 5, v_numcte, 3, v_telefono3, '', '', 0, user) INTO vCodRet_2;
              END IF;
           END IF;
           LET vCodRet_tel = '';
            
           IF LENGTH(v_telefono4)>= 10 THEN  
              EXECUTE procedure bdinteg:"informix".sp_validar_telefono(v_telefono4) into vCodRet_tel;

              IF vCodRet_tel = '00000' THEN
                  EXECUTE PROCEDURE "informix".sp_cat_graba_telefono_adicional(cEmpresa, 5, v_numcte, 4, v_telefono4, '', '', 0, user) INTO vCodRet_2;
              END IF;
           END IF;
           LET vCodRet_tel = '';

           IF LENGTH(v_telefono5)>= 10 THEN  
              EXECUTE procedure bdinteg:"informix".sp_validar_telefono(v_telefono5) into vCodRet_tel;

              IF vCodRet_tel = '00000' THEN
                  EXECUTE PROCEDURE "informix".sp_cat_graba_telefono_adicional(cEmpresa, 5, v_numcte, 5, v_telefono5, '', '', 0, user) INTO vCodRet_2;
              END IF;
           END IF;
                           
           LET iRegistros = iRegistros + 1;
      END FOREACH 

      DROP INDEX "informix".idx_tmp_telefonos_buro_2;
      --DROP TABLE "informix".tmp_telefonos_buro_2;
      
      LET cCadena = '';
      LET cCadena = 'bzip2 ' || SUBSTR(cRuta,1,LENGTH(cRuta)) || SUBSTR(cNombre,1,LENGTH(cNombre)); 
      system SUBSTR(cCadena,1,LENGTH(cCadena));
      
      CALL bdicobranza:"informix".sp_inserta_bitacora_cob(cEmpresa, cProceso, vCodRet, vMensaje, '03')
      RETURNING vvcCod_ret;
      
  END IF;
	  
   	
RETURN vCodRet, vMensaje;
END 
END PROCEDURE;

CREATE PROCEDURE "informix".sp_ctestelefonosactualizados()
       RETURNING CHAR(5), CHAR(80);

DEFINE vCodRet                  CHAR(5);
DEFINE vMensaje                 CHAR(80);
DEFINE SQL_ERR, ISAM_ERR        INTEGER;
DEFINE ERROR_INFO               VARCHAR(80);
DEFINE v_fecha                  DATE;
DEFINE iRegistros               INTEGER;
DEFINE cRuta, cNombre,cNombre2  CHAR(100);
DEFINE iParamRuta, iParamNombre INTEGER;
DEFINE cCadena                  CHAR(2000);
DEFINE v_empresa                CHAR(3);
DEFINE v_numcte                 CHAR(20);
DEFINE v_numcredito             CHAR(20);
DEFINE v_fecha_ant              DATE;
DEFINE v_fecha_ant_2            DATE;
DEFINE v_dia,  v_mes, v_mes_ant, v_mes_ant_2 CHAR(2);
DEFINE v_anio, v_anio_ant, v_anio_ant_2      CHAR(4);
DEFINE v_fecha_min_busq,     v_fecha_max_busq      DATE;
DEFINE v_fecha_ini_llamadas, v_fecha_fin_llamadas  DATE;
DEFINE v_tipo_telefono          SMALLINT;
DEFINE v_telefono               CHAR(13);
DEFINE v_fecha_insert, v_fecha_llamada  CHAR(10);
DEFINE v_descripcion            CHAR(50);
DEFINE cproceso                 CHAR(4);
DEFINE vvcCod_ret               CHAR(6);

LET vCodRet       = '11111';
LET vMensaje      = 'PROCESO EXITOSO';
LET SQL_ERR = 0;  LET ISAM_ERR = 0;  LET ERROR_INFO = '';
LET v_fecha = DATE(1);  LET v_fecha_ant_2 = DATE(1); 
LET cRuta = '';  LET cNombre = '';  LET cNombre2 = '';
LET iParamRuta    = 20;
LET iParamNombre  = 50;
LET v_empresa     = '001';
LET cproceso      = '0110';

LET iRegistros = 0;  LET cCadena = ''; LET v_numcte = '';  LET v_numcredito = ''; 
LET v_dia = '';  LET v_mes = '';  LET v_mes_ant  = ''; 
LET v_anio = ''; LET v_anio_ant = '';  LET vvcCod_ret = '';
LET v_fecha_min_busq     = '01-01-1900';  --Será la fecha 26 del mes anterior a la ejecución.
LET v_fecha_max_busq     = '01-01-1900';  --Será la fecha 29 del mes anterior a la ejecución.
LET v_fecha_ini_llamadas = '01-01-1900'; -- Será la fecha de inicio de la campaña  21
LET v_fecha_fin_llamadas = '01-01-1900'; -- Será la fecha de termino de la campaña 20 del mes siguiente 
LET v_fecha_insert = '';  LET v_fecha_llamada = '';  LET v_descripcion = '';

 --SET DEBUG FILE TO "/informix/macf/sp_ctestelefonosactualizados.out";    
 --TRACE ON; 

BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, ERROR_INFO
        LET vCodRet  = SQL_ERR;
        LET vMensaje  = ERROR_INFO;
  
        --insertar control de procesos
        CALL bdicobranza:"informix".sp_inserta_bitacora_cob(v_empresa, cproceso, vCodRet, vMensaje, '02')
        RETURNING vvcCod_ret;
        RETURN vCodRet, vMensaje;
    END EXCEPTION;
    
    SELECT valor  INTO cRuta
      FROM bdicobranza:cb_param
     WHERE empresa = v_empresa
       AND cod_param = iParamRuta;

    SELECT valor  INTO cNombre2
      FROM bdicobranza:cb_param
     WHERE empresa = v_empresa
       AND cod_param = iParamNombre;

    IF NVL(cRuta,'') = '' and NVL(cNombre, '') = '' THEN
      LET vCodRet = '00001';
      LET vMensaje = 'Faltan parámetros de ruta o nom. archivo.'; 
      RETURN vCodRet, vMensaje;
    END IF;
    
    SET LOCK MODE TO WAIT 3;
    CALL bdicobranza:"informix".sp_inserta_bitacora_cob(v_empresa, cproceso, vCodRet, vMensaje, '01') RETURNING vvcCod_ret;
    SET ISOLATION TO dirty READ;
    
    SELECT fecha_hoy 
      INTO v_fecha        
     FROM bdinteg:si_fechas 
     WHERE empresa = v_empresa;
    
    --Calcular meses anteriores
    LET v_fecha_ant = v_fecha - 1 UNITS MONTH;  
    LET v_fecha_ant_2 = v_fecha - 2 UNITS MONTH;  --SERÍA LO QUE SE INSERTO EN CB_TELEFONOS 2 MESES ATRÁS}
    LET v_anio_ant = year(v_fecha_ant);
    
    LET v_anio_ant_2 = year(v_fecha_ant_2);
    LET v_anio = year(v_fecha);
    
    IF day(v_fecha) < 10 THEN
    	LET v_dia = '0' || day(v_fecha);
    ELSE
    	LET v_dia = day(v_fecha);
    END IF;
    
    IF month(v_fecha) < 10 THEN
    	LET v_mes = '0' || month(v_fecha);
    ELSE
    	LET v_mes = month(v_fecha);
    END IF;

    IF month(v_fecha_ant) < 10 THEN
       LET v_mes_ant = '0' || month(v_fecha_ant);
    ELSE
       LET v_mes_ant = month(v_fecha_ant);
    END IF; 
    
    IF month(v_fecha_ant_2) < 10 THEN
       LET v_mes_ant_2 = '0' || month(v_fecha_ant_2);
    ELSE
       LET v_mes_ant_2 = month(v_fecha_ant_2);
    END IF; 
    
    
    -- CALCULAR FECHAS INICIALES Y FINALES
    LET v_fecha_min_busq = v_mes_ant_2 || '-' || '26' || '-' || v_anio_ant_2; 
    LET v_fecha_max_busq = v_mes_ant_2 || '-' || '29' || '-' || v_anio_ant_2;
    
    LET v_fecha_ini_llamadas = v_mes_ant || '-' || '21' || '-' || v_anio_ant;
    LET v_fecha_fin_llamadas = v_mes || '-' || '20' || '-' || v_anio;

    LET cNombre = trim(SUBSTR(cNombre2,1,LENGTH(cNombre2)) || v_dia || v_mes || v_anio || '.txt');

  --Inicializar archivo
    SYSTEM 'echo "num_cliente|num_credito|tipo_tel|telefono|fecha_insert|fecha_llamada|resultado"' || '> ' || SUBSTR(cRuta,1,LENGTH(cRuta)) || cNombre;
 
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    --SET pdqpriority 20;

     FOREACH 
          SELECT t.numcte, m.num_credito, t.tipo_telefono, t.telefono, to_char(t.fecha_insert, '%d/%m/%Y'), to_char(r.fecha_llamada, '%d/%m/%Y'), s.descripcion
            INTO v_numcte, v_numcredito, v_tipo_telefono, v_telefono, v_fecha_insert, v_fecha_llamada, v_descripcion
            FROM bdicobranza:cb_telefonos t, 
                 bdicobranza:cb_cat_resultado_llamada r, 
                 bdicobranza:cb_cat_tipo_resultado s, 
                 bdicred:sd_maecred m
           WHERE m.numcte = t.numcte
             AND t.numcte = r.numcte 
             AND r.codigo_resultado = s.codigo_resultado
             AND t.telefono = r.telefono 
             AND t.origen = 5
             AND ( t.fecha_insert >= v_fecha_min_busq and t.fecha_insert <= v_fecha_max_busq )
             AND ( r.fecha_llamada >= v_fecha_ini_llamadas and r.fecha_llamada <= v_fecha_fin_llamadas )

           
          IF nvl(v_numcte,'') <> '' THEN

            LET cCadena = 'echo "' || trim(v_numcte) || '|' || trim(v_numcredito) || '|' || v_tipo_telefono || '|' || v_telefono || '|' || v_fecha_insert || '|' || v_fecha_llamada || '|' || v_descripcion || '">> ' || SUBSTR(cRuta,1,LENGTH(cRuta)) || cNombre;
            System SUBSTR(cCadena,1,LENGTH(cCadena));
	          Let iRegistros = iRegistros + 1; 
            
          END IF;                      
             
      END FOREACH 

      LET vCodRet = '00000';      
      LET vMensaje = 'PROCESO FINALIZADO';

      CALL bdicobranza:"informix".sp_inserta_bitacora_cob(v_empresa, cproceso, vCodRet, vMensaje, '03')
      RETURNING vvcCod_ret;

		
RETURN vCodRet, vMensaje;
END 
END PROCEDURE
DOCUMENT
'AUTOR: Marco A. Campos',
'Fecha: 2012-05-24 ',
'BDICOBRANZA. Genera un archivo plano con los resultados de los tels. de ctes. actualizados con info de Buró';

CREATE PROCEDURE "informix".sp_rep_atendo_admin()
returning char (5);
------------------------------------------------------------------------------------
--Maria Elizabeth Anzures Ibarguen
--02-03-2012
--crea archivo con datos que se muestran en pantalla cat con cliente con mora 1
----DATOS QUE VAN EN LA TABLA
DEFINE vnumcte			char(20);
DEFINE vnum_credito		char(20);
DEFINE vnum_tarjeta		char(20);
DEFINE vint_moratorio	decimal(18,2);
DEFINE vsdo_tot_liq		decimal(18,2);
DEFINE vsdo_venc_tot	decimal(18,2);
DEFINE vmens_actual		decimal(18,2);
DEFINE vnum_venc_ini	smallint;
DEFINE vnum_venci_fin	smallint;
DEFINE vstatus_cred		char(2);
DEFINE vfecha_ult_pag	date;
DEFINE vpago_1_mora		decimal(18,2);
DEFINE vciudad			smallint;
DEFINE vdescripcion		char(40);
DEFINE vregion			char(30);
DEFINE vcallc			smallint;
DEFINE vnum_pagos		smallint;
DEFINE vmonto_pagos		decimal(18,2);
DEFINE vresultado_gestion smallint;


---VARIABLES PARA CAPTURAR ERRORES
DEFINE SQL_ERR                INTEGER;
DEFINE ISAM_ERR               INTEGER;
DEFINE ERROR_INFO             VARCHAR(80);
DEFINE P_COD_RET              VARCHAR(5);
DEFINE P_MENSAJE              VARCHAR(80);
DEFINE vproceso				  CHAR (4);
DEFINE cMensaje				  CHAR(80);

---VARIABLES PARA QUERYS
DEFINE cSQL                 CHAR(2204);
DEFINE cSQL1                CHAR(200);
DEFINE cSQL2                CHAR(2004);
DEFINE cSQL3                CHAR(100);
DEFINE icontador 			  SMALLINT;
DEFINE sPaso integer;
DEFINE cruta                CHAR(100);
DEFINE cdelimitador         CHAR(1);
DEFINE cnomarchivo          CHAR(100);
DEFINE cnomarchivo1			CHAR(100);
DEFINE cnombre				CHAR(100);
define vfecha				DATE;
define vfechas				DATE;
define keyx					integer;


	--Set debug file to '/informix/Elizabeth/cb_cat_atento_admin_reporte.out';
	--trace on;
BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, ERROR_INFO
        LET P_COD_RET = SQL_ERR;
        LET P_MENSAJE = ERROR_INFO;
		CALL bdicobranza:"informix".inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '02');
        RETURN P_COD_RET;
    END EXCEPTION;

----INICIALIZAN VARIABLES QUE VAN EN LA TABLA
LET vnumcte			='';
LET vnum_credito	='';
LET vnum_tarjeta	='';
LET vint_moratorio	=0;
LET vsdo_tot_liq	=0;
LET vsdo_venc_tot	=0;
LET vmens_actual	=0;
LET vnum_venc_ini	=0;
LET vnum_venci_fin	=0;
LET vstatus_cred	='';
LET vfecha_ult_pag	=date(1);
LET vpago_1_mora	=0;
LET vciudad			=0;
LET vdescripcion	='';
LET vregion			='';
LET vcallc			=0;
LET vnum_pagos		=0;
LET vmonto_pagos	=0;
LET vresultado_gestion	=0;


---INICIALIZAN VARIABLES PARA QUERYS
LET  cSql		="";
LET cSQL1                   = "";
LET cSQL2                   = "";
LET cSQL3                   = "";
Let P_cod_ret	= "00000";
LET icontador 	= 0;
LET vproceso	='2064';
LET cMensaje    = 'PROCESO EXITOSO';
let sPaso =0;
let cruta       ='';
let cdelimitador  ='';
let cnomarchivo  ='';
let cnomarchivo1  ='';
let cnombre ='';
let vfecha = date(1);
let vfechas = date(1);
let keyx	=0;


	CALL bdicobranza:"informix".inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '01');
	
	SELECT COUNT(tabid)INTO sPaso FROM systables WHERE tabname= 'cb_cat_atento_admin_reporte';
            IF NVL(sPaso,0) > 0 THEN
                DROP TABLE cb_cat_atento_admin_reporte;
            END IF;

	create table cb_cat_atento_admin_reporte
        (numcte			char(20),
		num_credito		char(20),
		num_tarjeta		char(20),
		int_moratorio	decimal(18,2),
		sdo_tot_liq		decimal(18,2),
		sdo_venc_tot	decimal(18,2),
		mens_actual		decimal(18,2),
		num_venc_ini	smallint,
		num_venci_fin	smallint,
		status_cred		char(2),
		fecha_ult_pag	date,
		pago_1_mora		decimal(18,2),
		ciudad			smallint,
		descripcion		char(40),
		region			char(30),
		callc			smallint,
		num_pagos		smallint,
		monto_pagos		decimal(18,2),
		resultado_gestion smallint)  ;

	--Obtener caracter delimitador
	SELECT trim(valor_alfabetico)
	INTO cdelimitador
	FROM bdicobranza:cb_param_campania
	WHERE empresa = '001'
	AND tipo_campania = 1
	AND grupo_parametro = 'ARCHIVOS'
	AND num_parametro = 2;
	
	--Valida que exista el caracter
	IF NVL(cDelimitador,'') = '' THEN
        LET P_COD_RET= '104004';
        SELECT descripcion
        INTO cMensaje
        FROM cb_errores
        WHERE origen = 3
        AND codigo_error = P_COD_RET;
	
        IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
        END IF;

        CALL bdicobranza:"informix".inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '01');
        Return P_COD_RET;
	END IF;
	
	select trim(valor_alfabetico) into cruta
	from bdicobranza:cb_param_campania 
	where tipo_campania = 1
	and grupo_parametro = 'ARCHIVOS'
	and num_parametro = 36;
	
	--Valida que exista la carpeta
	IF NVL (cruta,'') = '' THEN
        LET P_COD_RET= '104005';
        SELECT descripcion
        INTO cMensaje
        FROM cb_errores
        WHERE origen = 3
        AND codigo_error = P_COD_RET;
	
        IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
        END IF;

        CALL bdicobranza:"informix".inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '01');
        Return P_COD_RET;
	END IF;
	
	select fecha_hoy into vfecha from bdicred:sd_fechas where empresa = '001';
--let vfecha = '04-21-2012';--pruebas
	let vfecha = mdy(month(vfecha),day(20),year(vfecha));
	LET vfechas = vfecha - 1 UNITS MONTH;
	LET vfechas = mdy(month(vfechas),day(21),year(vfechas));
	
    set isolation to dirty read;
    set lock mode to wait 3;
/*
	select tienda  
	from bdicobranza:cb_cat_movimientos 
		where horainicio <= date(vfecha) and horainicio >= date(vfechas)
		group by  tienda  into temp cat_movimientos;
	select tienda  
	from bdicobranza:cb_atento_movimientos 
		where horainicio <= date(vfecha) and horainicio >= date(vfechas)
		group by  tienda  into temp atento_movimientos;
*/	
	select num_credito tienda
	from cb_cat_directorio_cte_his 
	where pago_venc = 1 and fecha_insert = vfechas
	and tipo_cobranza = 'A'
	and call_c is null
	into temp cat_movimientos;
	
	select num_credito tienda
	from cb_cat_directorio_cte_his 
	where pago_venc = 1 and fecha_insert = vfechas
	and tipo_cobranza = 'A'
	and call_c = 2
	into temp atento_movimientos;
	
	FOREACH
		
		SELECT mae.numcte,t.tienda ,tar.num_tarjeta, maes.mto_fin_ven_trasp,mae.status_cred,anex.fecha_ult_pago,
				dir.ciudad,  ci.nombreciudadcoppel,r.nombre_region,1 call_c, maes.mto_venc_trasp
		INTO vnumcte, vnum_credito, vnum_tarjeta, vnum_venci_fin, vstatus_cred, vfecha_ult_pag,
				vciudad	,vdescripcion,vregion, vcallc,vsdo_venc_tot
		from  cat_movimientos t 
		JOIN bdicred:sd_maecred mae on (mae.num_credito = t.tienda)
		join bdicred:sd_maesdos maes on (maes.empresa =mae.empresa and maes.num_credito = mae.num_credito )
		join bdicred:sd_maecredanexo anex on (anex.empresa =mae.empresa and anex.num_credito = mae.num_credito)
		join bdinteg:si_direcciones_actual dir on (dir.numcte = mae.numcte and tipo_dir = 1)
		left join bdinteg:si_catciudades ci on (ci.numerociudad = dir.ciudad)
		left join bdinteg:si_regiones r on ( r.numero_region = ci.numero_region ) 
		left join bdicred:sd_tarjeta tar on (tar.num_credito = t.tienda and tar.secuencia = (select max(secuencia)
                                from bdicred:sd_tarjeta 
                                where empresa = '001'
                                and num_credito = t.tienda
                                and tipo_tarjeta ='T' and status_tar = 'A')
                                and tar.tipo_tarjeta ='T'  and tar.status_tar = 'A')  
		
		select first 1 max(keyx)keyx, finllamada  into keyx,vresultado_gestion
		from bdicobranza:cb_cat_movimientos 
		where cvemovimiento = 'L' and tipomovimiento =1
			and date(horainicio) <= vfecha
			and date(horainicio) >= vfechas           
			and tienda = vnum_credito
		group by finllamada;
	
		LET vnum_venc_ini = 1;
		
		SELECT  count(monto),SUM(MONTO) INTO Vnum_pagos	,Vmonto_pagos		
		FROM bdicred:sd_movhis 
		WHERE empresa= '001'
			and fecha_mov <= vfecha  --corre el 22
			and fecha_mov >=  vfechas
			AND num_credito = vnum_credito 
			and codigo_fun in ('033','334','335','336','337','904') AND codigo_ref = 1
			AND reversado = 'N';
		
	------------------------------SALDOS----------------------------------
	
		select pago_una_mora,mensualidad_actual,moratorio ,
		(sdo_capital +  monto_vencido + mto_venc_trasp + cap_tras_no_venci + moratorio + interes_iva ) sdo_tot_liquid
		into vpago_1_mora, vmens_actual, vint_moratorio, vsdo_tot_liq
		from bdicred:sd_sdos_cartera_linea 
		where num_credito = vnum_credito;
	
	-----------------------------------------------------------------------
	
        INSERT INTO  bdicobranza:cb_cat_atento_admin_reporte 
		(numcte,num_credito	,num_tarjeta,int_moratorio,sdo_tot_liq,sdo_venc_tot,mens_actual,num_venc_ini,num_venci_fin,
			status_cred,fecha_ult_pag,pago_1_mora,ciudad,descripcion,region,callc,num_pagos,monto_pagos,resultado_gestion)
	    VALUES (		nvl ( vnumcte,' ' ),
                        nvl ( replace ( replace( vnum_credito , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vnum_tarjeta , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vint_moratorio , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vsdo_tot_liq , '|' , ' ' ), '\' , ' ' ), ' ' ),
						nvl ( replace ( replace( vsdo_venc_tot , '|' , ' ' ), '\' , ' ' ), ' ' ),
						nvl ( replace ( replace( vmens_actual , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vnum_venc_ini , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vnum_venci_fin , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vstatus_cred , '|' , ' ' ), '\' , ' ' ), ' ' ),
						nvl ( vfecha_ult_pag, date(1) ),
						nvl ( replace ( replace( vpago_1_mora , '|' , ' ' ), '\' , ' ' ), ' ' ),
						nvl ( replace ( replace( vciudad , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vdescripcion , '|' , ' ' ), '\' , ' ' ), ' ' ),
						nvl ( replace ( replace( vregion , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vcallc , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vnum_pagos , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vmonto_pagos , '|' , ' ' ), '\' , ' ' ), ' ' ),
						nvl ( replace ( replace( vresultado_gestion , '|' , ' ' ), '\' , ' ' ), ' ' ));

        IF icontador >= 1000 then
            update statistics medium for table bdicobranza:cb_cat_atento_admin_reporte;
			LET icontador=1;
		ELSE
			LET icontador=icontador+1;
		END IF;
		
	LET vnumcte			='';
	LET vnum_credito	='';
	LET vnum_tarjeta	='';
	LET vint_moratorio	=0;
	LET vsdo_tot_liq	=0;
	LET vsdo_venc_tot	=0;
	LET vmens_actual	=0;
	LET vnum_venc_ini	=0;
	LET vnum_venci_fin	=0;
	LET vstatus_cred	='';
	LET vfecha_ult_pag	=date(1);
	LET vpago_1_mora	=0;
	LET vciudad			=0;
	LET vdescripcion	='';
	LET vregion			='';
	LET vcallc			=0;
	LET vnum_pagos		=0;
	LET vmonto_pagos	=0;
	LET vresultado_gestion	=0;
	
	END FOREACH;
	
LET vnumcte			='';
LET vnum_credito	='';
LET vnum_tarjeta	='';
LET vint_moratorio	=0;
LET vsdo_tot_liq	=0;
LET vsdo_venc_tot	=0;
LET vmens_actual	=0;
LET vnum_venc_ini	=0;
LET vnum_venci_fin	=0;
LET vstatus_cred	='';
LET vfecha_ult_pag	=date(1);
LET vpago_1_mora	=0;
LET vciudad			=0;
LET vdescripcion	='';
LET vregion			='';
LET vcallc			=0;
LET vnum_pagos		=0;
LET vmonto_pagos	=0;
LET vresultado_gestion	=0;	

	FOREACH
		
		SELECT mae.numcte,t.tienda ,tar.num_tarjeta, maes.mto_fin_ven_trasp,mae.status_cred,anex.fecha_ult_pago,
				dir.ciudad,  ci.nombreciudadcoppel,r.nombre_region,2 call_c, maes.mto_venc_trasp
		INTO vnumcte, vnum_credito, vnum_tarjeta, vnum_venci_fin, vstatus_cred, vfecha_ult_pag,
				vciudad	,vdescripcion,vregion, vcallc,vsdo_venc_tot
		from  atento_movimientos t 
		JOIN bdicred:sd_maecred mae on (mae.num_credito = t.tienda)
		join bdicred:sd_maesdos maes on (maes.num_credito = mae.num_credito )
		join bdicred:sd_maecredanexo anex on (anex.num_credito = mae.num_credito)
		join bdinteg:si_direcciones_actual dir on (dir.numcte = mae.numcte and tipo_dir = 1)
		left join bdinteg:si_catciudades ci on (ci.numerociudad = dir.ciudad)
		left join bdinteg:si_regiones r on ( r.numero_region = ci.numero_region ) 
		left join bdicred:sd_tarjeta tar on (tar.num_credito = t.tienda and tar.secuencia = (select max(secuencia)
                                from bdicred:sd_tarjeta 
                                where empresa = '001'
                                and num_credito = t.tienda
                                and tipo_tarjeta ='T' and status_tar = 'A')
                                and tar.tipo_tarjeta ='T'  and tar.status_tar = 'A') 
		
		select first 1 max(keyx)keyx, finllamada  into keyx,vresultado_gestion
		from bdicobranza:cb_cat_movimientos 
		where cvemovimiento = 'L' 
			and date(horainicio) <= vfecha
			and date(horainicio) >= vfechas           
			and tienda = vnum_credito
		group by finllamada;
	
		LET vnum_venc_ini = 1;
		
		SELECT  count(monto),SUM(MONTO) INTO Vnum_pagos	,Vmonto_pagos		
		FROM bdicred:sd_movhis 
		WHERE empresa= '001'
			and fecha_mov <= vfecha  --corre el 22
			and fecha_mov >=  vfechas
			AND num_credito = vnum_credito 
			and codigo_fun in ('033','334','335','336','337','904') AND codigo_ref = 1
			AND reversado = 'N';
		------------------------------SALDOS----------------------------------
		select pago_una_mora,mensualidad_actual,moratorio ,
			(sdo_capital +  monto_vencido + mto_venc_trasp + cap_tras_no_venci + moratorio + interes_iva ) sdo_tot_liquid
		into vpago_1_mora, vmens_actual, vint_moratorio, vsdo_tot_liq
		from bdicred:sd_sdos_cartera_linea 
		where num_credito = vnum_credito;

	-----------------------------------------------------------------------
	
        INSERT INTO  bdicobranza:cb_cat_atento_admin_reporte 
		(numcte,num_credito	,num_tarjeta,int_moratorio,sdo_tot_liq,sdo_venc_tot,mens_actual,num_venc_ini,num_venci_fin,
			status_cred,fecha_ult_pag,pago_1_mora,ciudad,descripcion,region,callc,num_pagos,monto_pagos,resultado_gestion)
	    VALUES (		nvl ( vnumcte,' ' ),
                        nvl ( replace ( replace( vnum_credito , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vnum_tarjeta , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vint_moratorio , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vsdo_tot_liq , '|' , ' ' ), '\' , ' ' ), ' ' ),
						nvl ( replace ( replace( vsdo_venc_tot , '|' , ' ' ), '\' , ' ' ), ' ' ),
						nvl ( replace ( replace( vmens_actual , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vnum_venc_ini , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vnum_venci_fin , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vstatus_cred , '|' , ' ' ), '\' , ' ' ), ' ' ),
						nvl ( vfecha_ult_pag, date(1) ),
						nvl ( replace ( replace( vpago_1_mora , '|' , ' ' ), '\' , ' ' ), ' ' ),
						nvl ( replace ( replace( vciudad , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vdescripcion , '|' , ' ' ), '\' , ' ' ), ' ' ),
						nvl ( replace ( replace( vregion , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vcallc , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vnum_pagos , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vmonto_pagos , '|' , ' ' ), '\' , ' ' ), ' ' ),
						nvl ( replace ( replace( vresultado_gestion , '|' , ' ' ), '\' , ' ' ), ' ' ));

        IF icontador >= 1000 then
            update statistics medium for table bdicobranza:cb_cat_atento_admin_reporte;
			LET icontador=1;
		ELSE
			LET icontador=icontador+1;
		END IF;
		
	LET vnumcte			='';
	LET vnum_credito	='';
	LET vnum_tarjeta	='';
	LET vint_moratorio	=0;
	LET vsdo_tot_liq	=0;
	LET vsdo_venc_tot	=0;
	LET vmens_actual	=0;
	LET vnum_venc_ini	=0;
	LET vnum_venci_fin	=0;
	LET vstatus_cred	='';
	LET vfecha_ult_pag	=date(1);
	LET vpago_1_mora	=0;
	LET vciudad			=0;
	LET vdescripcion	='';
	LET vregion			='';
	LET vcallc			=0;
	LET vnum_pagos		=0;
	LET vmonto_pagos	=0;
	LET vresultado_gestion	=0;
	
    END FOREACH;

--------------------------------------------------------GENERAR ARCHIVO--------------------------------------------------------
	--let cruta = '/informix/Elizabeth/';
	let cnombre = 'reporte_admin_atento_result';
	
    LET cnomarchivo1 =  trim(cnombre)||'Aux'||to_char(vfecha,'%d%m%Y')||'.txt';
    LET cnomarchivo =  trim(cnombre)||to_char(vfecha,'%d%m%Y')||'.txt';
	 
		let cSql='';
	LET cSQL1 = ' echo " SET ISOLATION TO DIRTY READ; UNLOAD TO ' || TRIM(cruta) || TRIM(cnomarchivo1) || ' DELIMITER ' || ''''|| cdelimitador || ''''||'';
	LET cSQL2 = " select * from bdicobranza:cb_cat_atento_admin_reporte ";
	LET cSQL3 = '">'||TRIM(cRuta)||'Ejecuta.sql';
	LET cSQL = trim(cSQL1) || cSQL2 || trim(cSQL3);
    System cSQL;

    LET cSQL='chmod 777 '|| TRIM(cRuta)||'Ejecuta.sql';
    System cSQL;

    let cSQL = 'dbaccess bdicobranza ' || TRIM(cRuta) || 'Ejecuta.sql';
    System cSQL;

    LET cSql = cSql;
    LET cSql = "sed 's/"||cDelimitador||"$//g' "|| TRIM(cRuta) || TRIM(cnomarchivo1) || " >> " || TRIM(cRuta) || TRIM(cnomarchivo);
    SYSTEM cSql;
	
		--SE COMPRIME EL ARCHIVO	
	LET cSql = "gzip " || trim(cruta) || trim(cnomarchivo); 
	system cSql;
	
	--Borra el archivo de control.
	LET cSQL = '';
	LET cSQL = 'rm ' || TRIM(cruta) || 'Ejecuta.sql';
	SYSTEM cSQL;

    LET cSQL = ''; 
	LET cSQL = 'rm ' || TRIM(cruta) || cnomarchivo1;
	SYSTEM cSQL; 
	
	CALL bdicobranza:"informix".inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '03');
    RETURN P_COD_RET;

end;
end procedure;

CREATE PROCEDURE "informix".sp_cilocinsertamarca(	pOrigen CHAR(1), --1 SUCURSAL/PLATAFORMA, 2 CENTRAL, 3 BPI
										pTpoMarca CHAR(4), --  LV, CM, 3BL
										pSucursal CHAR(4),
										pNumcte CHAR(20),
										pTpoDir CHAR(1),
										pCalle CHAR(40),
										pColonia CHAR(60),
										pEntre_calles CHAR(40),
										pPais CHAR(3),
										pEstado CHAR(2),
										pCiudad CHAR(3),
										pMunicipio CHAR(5),
										pCodPostal CHAR(5),
										pApartadoPostal CHAR(11),
										pTpoTel1 CHAR(1),
										pTel1 CHAR(13),
										pTpoTel2 CHAR(1),
										pTel2 CHAR(13),
										pTpoTel3 CHAR(1),
										pTel3 CHAR(13),
										pExtension CHAR(5),
										pEdoInegi CHAR(2),
										pMunicipioInegi CHAR(3),
										pLocalidadInegi CHAR(4),
										pNumCd SMALLINT,
										pNumExtCalle CHAR(10),
										pNumIntCalle CHAR(10),
										pDepto CHAR(6),
										pNumCalle INTEGER,
										pNumColonia INTEGER,
										pPuntoCardinal CHAR(1),
										pUnidadHab CHAR(1),
										pManzana SMALLINT,
										pOtros SMALLINT,
										pAndador SMALLINT,
										pEtapa SMALLINT,
										pLote SMALLINT,
										pEdificio SMALLINT,
										pEntrada SMALLINT,
										pObservaciones CHAR(80),
										pUserInsert CHAR(8),
										pIndCofetel1 CHAR(1), --DEFAULT F
										pIndCofetel2 CHAR(1),
										pIndCofetel3 CHAR(1),
										pDomCerificado CHAR(1),
										pLugarTrabajo	char(80)
										)
RETURNING CHAR(5);

--Declaracion de variables
------------------------------------------------------------
DEFINE sql_err 			    INTEGER;
DEFINE isam_err 		    INTEGER;
DEFINE error_info		    CHAR(80);
DEFINE cCod_ret             CHAR(6);
DEFINE dFechaHoy			DATE;
DEFINE iBandera				INTEGER;
DEFINE cNumcte				CHAR(20);
DEFINE cTpoDir				CHAR(1);
DEFINE cCalle				CHAR(40);
DEFINE cColonia				CHAR(60);
DEFINE cEntre_calles		CHAR(40);
DEFINE cPais				CHAR(3);
DEFINE cEstado				CHAR(2);
DEFINE cMunicipio			CHAR(5);
DEFINE cCodPostal			CHAR(5);
DEFINE cApartadoPostal		CHAR(11);
DEFINE cTpoTel1				CHAR(1);
DEFINE cTel1				CHAR(13);
DEFINE cTpoTel2				CHAR(1);
DEFINE cTel2				CHAR(13);
DEFINE cTpoTel3				CHAR(1);
DEFINE cTel3				CHAR(13);
DEFINE cExtension			CHAR(5);
DEFINE cEdoInegi			CHAR(2);
DEFINE cMunicipioInegi		CHAR(3);
DEFINE cLocalidadInegi		CHAR(4);
DEFINE sNumCd				SMALLINT;
DEFINE cNumExtCalle			CHAR(10);
DEFINE cNumIntCalle			CHAR(10);
DEFINE cDepto				CHAR(6);
DEFINE iNumCalle			INTEGER;
DEFINE iNumColonia			INTEGER;
DEFINE cPuntoCardinal		CHAR(1);
DEFINE cUnidadHab			CHAR(1);
DEFINE sManzana				SMALLINT;
DEFINE sOtros				SMALLINT;
DEFINE sAndador				SMALLINT;
DEFINE sEtapa				SMALLINT;
DEFINE sLote				SMALLINT;
DEFINE sEdificio			SMALLINT;
DEFINE sEntrada				SMALLINT;
DEFINE cObservaciones		CHAR(80);
DEFINE cIndCofetel1			CHAR(1);
DEFINE cIndCofetel2			CHAR(1);
DEFINE cIndCofetel3			CHAR(1);
DEFINE cSituacion			CHAR(1);
DEFINE cCausa				SMALLINT;
DEFINE cNombre				CHAR(40);
DEFINE iSecuencia			INTEGER;
DEFINE iSecuencia2			INTEGER;
DEFINE cSucursal			CHAR(4);
-----------------------------------------------------
LET cCod_ret  		= '00000';
LET sql_err   		= 0;
LET dFechaHoy		= '';	
LET iBandera		= 0;
LET cNumcte			= '';
LET cTpoDir			= '';
LET cCalle			= '';
LET cColonia		= '';
LET cEntre_calles 	= '';
LET cPais			= '';
LET cEstado			= '';
LET cMunicipio		= '';
LET cCodPostal		= '';
LET cApartadoPostal = '';
LET cTpoTel1		= '';
LET cTel1			= '';
LET cTpoTel2		= '';
LET cTel2			= '';
LET cTpoTel3		= '';
LET cTel3			= '';
LET cExtension		= '';
LET cEdoInegi		= '';
LET cMunicipioInegi	= '';
LET cLocalidadInegi	= '';
LET sNumCd			= '';
LET cNumExtCalle	= '';
LET cNumIntCalle	= '';
LET cDepto			= '';
LET iNumCalle		= 0;
LET iNumColonia		= 0;
LET cPuntoCardinal	= '';
LET cUnidadHab		= '';
LET sManzana		= 0;
LET sOtros			= 0;
LET sAndador		= 0;
LET sEtapa			= 0;
LET sLote			= 0;
LET sEdificio		= 0;
LET sEntrada		= 0;
LET cObservaciones	= '';
LET cIndCofetel1	= '';
LET cIndCofetel2	= '';
LET cIndCofetel3	= '';
LET cSituacion		= '';
LET cCausa			= 0;
LET cNombre			= '';
LET iSecuencia		= 0;
LET iSecuencia2		= 0;
LET cSucursal		= '';
		
  BEGIN

	ON EXCEPTION SET sql_err, isam_err, error_info
		LET cCod_ret = sql_err;		
		IF iBandera = 1 THEN
			ROLLBACK WORK;					
		END IF;
		RETURN cCod_ret;		
	END EXCEPTION;
	
	--SET DEBUG FILE TO "/home/sysifx/Antonio/sp_CiLocInsertaMarca.out";
	--TRACE ON;
	
	IF pOrigen = '' OR pTpoMarca = '' OR pSucursal = '' OR pNumcte = '' OR pTpoDir = '' THEN
		LET cCod_ret= '00002';
		RETURN cCod_ret;	
	END IF;
	
	SELECT fecha_hoy
	INTO dFechaHoy
	FROM bdinteg: si_fechas;	
	
	IF NOT EXISTS(SELECT 1 FROM bdicobranza:cb_tipo_marca WHERE tipo = pTpoMarca) THEN
		LET cCod_ret= '00001';
		RETURN cCod_ret;
	END IF;
	
	IF EXISTS(SELECT 1 FROM bdicobranza:cb_marcacliente 
		WHERE tipo_marca = pTpoMarca 
		AND fecha_insert = dFechaHoy 
		AND numcte = pNumcte 
		AND tipo_domicilio = pTpoDir) THEN
		LET cCod_ret= '00003';
		RETURN cCod_ret;
	END IF;
	
	BEGIN WORK;
	
		LET iBandera = 1;
		IF pTpoMarca= 'BL' THEN
		
			IF EXISTS(SELECT 1 FROM bdinteg:si_direcciones_loc WHERE numcte =  pNumcte
			AND secuencia = (SELECT MAX(secuencia) FROM bdinteg:si_direcciones_loc WHERE numcte= pNumcte AND tipo_dir = pTpoDir
			AND dom_verificado= 'N')
			AND tipo_dir = pTpoDir
			AND dom_verificado= 'N'	) THEN
			
			SET ISOLATION TO DIRTY READ;
			
				SELECT numcte, tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio, cod_postal,
					apart_postal, tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, estado_inegi,
					municipio_inegi, localidad_inegi, numerociudad, numeroextcalle, numerointcalle, departamento, numerocalle,
					numerocolonia, puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, entrada, observaciones,
					ind_cofeteltel1, ind_cofeteltel2, ind_cofeteltel3
				INTO cNumcte,  cTpoDir, cCalle, cColonia, cEntre_calles, cPais, cEstado, pCiudad ,cMunicipio, cCodPostal,
					cApartadoPostal, cTpoTel1, cTel1, cTpoTel2, cTel2, cTpoTel3, cTel3, cExtension, cEdoInegi, cMunicipioInegi, cLocalidadInegi,
					sNumCd, cNumExtCalle, cNumIntCalle, cDepto, iNumCalle, iNumColonia, cPuntoCardinal, cUnidadHab, sManzana, sOtros, sAndador,
					sEtapa, sLote, sEdificio, sEntrada, cObservaciones, cIndCofetel1, cIndCofetel2, cIndCofetel3
				FROM	bdinteg:si_direcciones_loc
				WHERE numcte =  pNumcte
				AND secuencia = (SELECT MAX(secuencia) FROM bdinteg:si_direcciones_loc WHERE numcte= pNumcte AND tipo_dir = pTpoDir AND dom_verificado= 'N')
				AND tipo_dir = pTpoDir
				AND dom_verificado= 'N';
			
				SELECT MAX(secuencia) 
				INTO iSecuencia2
				FROM bdinteg:si_direcciones_loc 
				WHERE numcte= pNumcte 
				AND tipo_dir = pTpoDir 
				AND dom_verificado= 'N';
				
				SET LOCK MODE TO WAIT 3;
				
				UPDATE bdinteg:si_direcciones_loc SET dom_verificado = 'S' WHERE numcte = pNumcte AND tipo_dir = pTpoDir AND 
				secuencia = iSecuencia2;
				
				SELECT MAX(secuencia)
				INTO iSecuencia
				FROM bdinteg:si_direcciones
				WHERE numcte= pNumcte;
				
				LET iSecuencia = iSecuencia + 1;			
			
				EXECUTE PROCEDURE bdinteg:direcciones(  '001',
														'A',
														cNumcte,
														iSecuencia,
														cTpoDir,
														cCalle,
														cColonia,
														cMunicipio,
														cEntre_calles,
														cPais,
														cEstado,
														pCiudad , 
														cCodPostal,
														cTpoTel1, 
														cTel1, 
														cTpoTel2, 
														cTel2, 
														cTpoTel3, 
														cTel3, 
														cExtension,
														cEdoInegi,
														cMunicipioInegi,
														cLocalidadInegi,
														sNumCd,
														cNumExtCalle, 
														cNumIntCalle, 
														cDepto, 
														iNumCalle, 
														iNumColonia, 
														cPuntoCardinal,
														cUnidadHab, 
														sManzana, 
														sOtros, 
														sAndador,
														sEtapa,
														sLote, 
														sEdificio,
														sEntrada,
														cObservaciones, 
														pUserInsert,
														dFechaHoy, 
														cSucursal
													 )
					INTO cCod_ret;		

					IF cCod_ret <> 0 THEN
						IF iBandera = 1 THEN
							ROLLBACK WORK;					
						END IF;
						RETURN cCod_ret;
					END IF;	
			END IF;
		
		SET LOCK MODE TO WAIT 3;

			IF EXISTS ( SELECT 1 FROM bdicobranza:cb_marcacliente WHERE numcte= pNumcte AND estatus = 'SA' AND tipo_domicilio = pTpoDir) THEN
				UPDATE cb_marcacliente SET estatus = 'AT', fecha_modificacion= dFechaHoy, usuario_desmarca = pUserInsert
				WHERE numcte= pNumcte AND estatus = 'SA' AND tipo_domicilio= pTpoDir;
			END IF;		
			
			INSERT INTO bdicobranza:cb_marcacliente ( numcte, tipo_domicilio, tipo_marca, fecha_insert, estatus, fecha_modificacion, usuario_marca, 
										usuario_desmarca, origen, sucursal)
			VALUES( pNumcte, pTpoDir, pTpoMarca, dFechaHoy, 'AT', '', pUserInsert, pUserInsert, pOrigen ,pSucursal);		--Origen: 1 SUC/PLATAFORMA, 2 CENTRAL, 3 BPI	
						
		ELIF pTpoMarca= 'LV' THEN	
			
			IF EXISTS ( SELECT 1 FROM bdicobranza:cb_marcacliente WHERE numcte= pNumcte AND estatus = 'SA' AND tipo_domicilio= pTpoDir ) THEN
			
			 SET LOCK MODE TO WAIT 3;
			
				UPDATE cb_marcacliente SET estatus = 'NA', fecha_modificacion= dFechaHoy, usuario_desmarca = pUserInsert
				WHERE numcte= pNumcte AND estatus = 'SA' AND tipo_domicilio= pTpoDir;	
				
				IF EXISTS( SELECT 1 FROM bdinteg:si_direcciones_loc WHERE numcte = pNumcte  AND tipo_dir = pTpoDir AND dom_verificado= 'N') THEN
					SELECT MAX(secuencia) 
					INTO iSecuencia
					FROM bdinteg:si_direcciones_loc 
					WHERE numcte= pNumcte 
					AND tipo_dir = pTpoDir 
					AND dom_verificado= 'N';
					
					UPDATE bdinteg:si_direcciones_loc SET dom_verificado = 'S' WHERE numcte = pNumcte AND tipo_dir = pTpoDir AND 
					secuencia = iSecuencia;
				END IF;				
			END IF;
			
			SELECT MAX(secuencia) 
			INTO iSecuencia2
			FROM bdinteg:si_direcciones_loc 
			WHERE numcte= pNumcte;
			
			IF iSecuencia2 IS NULL OR iSecuencia2 = '' THEN
					LET iSecuencia2 = 1;
				ELSE			
					LET iSecuencia2 = iSecuencia2 + 1;
			END IF;
			
			SELECT ciudad_coppel INTO sNumCd FROM bdinteg:si_ciudades WHERE pais = pPais  AND estado = pEstado AND ciudad = pCiudad;
			
			INSERT INTO bdinteg:si_direcciones_loc (numcte, secuencia, tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio, cod_postal,
						apart_postal, tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, estado_inegi,
						municipio_inegi, localidad_inegi, numerociudad, numeroextcalle, numerointcalle, departamento, numerocalle,
						numerocolonia, puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, entrada, observaciones,
						user_insert, fecha_insert, ind_cofeteltel1, ind_cofeteltel2, ind_cofeteltel3, dom_verificado, lugar_trabajo)
				VALUES (pNumcte, iSecuencia2, pTpoDir, pCalle, pColonia, pEntre_calles, pPais, pEstado, pCiudad ,pMunicipio, pCodPostal,
						pApartadoPostal, pTpoTel1, pTel1, pTpoTel2, pTel2, pTpoTel3, pTel3, pExtension, pEdoInegi, pMunicipioInegi, pLocalidadInegi,
						sNumCd, pNumExtCalle, pNumIntCalle, pDepto, pNumCalle, pNumColonia, pPuntoCardinal, pUnidadHab, pManzana, pOtros, pAndador,
						pEtapa, pLote, pEdificio, pEntrada, pObservaciones, pUserInsert, dFechaHoy, pIndCofetel1, pIndCofetel2, pIndCofetel3,
						pDomCerificado, pLugarTrabajo);			
				
			INSERT INTO cb_marcacliente ( numcte, tipo_domicilio, tipo_marca, fecha_insert, estatus, fecha_modificacion, usuario_marca, 
										usuario_desmarca, origen, sucursal)
				VALUES (pNumcte, pTpoDir, pTpoMarca, dFechaHoy, 'SA', '', pUserInsert, '', pOrigen ,pSucursal);
		
		ELIF pTpoMarca= 'CM' THEN
		  SET LOCK MODE TO WAIT 3;
			IF EXISTS ( SELECT 1 FROM cb_marcacliente WHERE numcte= pNumcte AND estatus = 'SA' AND tipo_domicilio= pTpoDir ) THEN
			
				UPDATE cb_marcacliente SET estatus = 'NA', fecha_modificacion= dFechaHoy, usuario_desmarca = pUserInsert
				WHERE numcte= pNumcte AND estatus = 'SA' AND tipo_domicilio= pTpoDir;						
			END IF;
			
			INSERT INTO cb_marcacliente ( numcte, tipo_domicilio, tipo_marca, fecha_insert, estatus, fecha_modificacion, usuario_marca, 
										usuario_desmarca, origen, sucursal)
				 VALUES (pNumcte, pTpoDir, pTpoMarca, dFechaHoy, 'SA', '', pUserInsert, '', pOrigen ,pSucursal);
			
		END IF;
		
		IF cCod_ret <> 0 THEN
			IF iBandera = 1 THEN
				ROLLBACK WORK;					
			END IF;
			RETURN cCod_ret;
		END IF;	
		
	COMMIT WORK;
	
	RETURN cCod_ret;
END;
END PROCEDURE

DOCUMENT
'AUTOR: ABIGAIL VASAVILBAZO CAÑEDO',
'DESCRIPCION: PROCEDIMIENTO ENCARGADO DE REGISTRAR LAS MARCAS.',
'BD: BDICOBRANZA',
'VERSION: 20110317.1834',
'MODIFICO:ABIGAIL VASAVILBAZO CAÑEDO',
'MODIFICACION: SE AGREGA PARAMETRO DE ENTRADA "LUGAR TRABAJO" Y SE AGREGA EN EL INSERT A LA SI_DIRECCIONES_LOC',
