 -- trace on;
	CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso,'000000', 'INICIA PROCESO EVALUA CTES CARTERA' ,'02' ) RETURNING P_COD_RET;
	CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '01') RETURNING P_COD_RET; 
	call bdicobranza:"informix".sp_cat_evalua_ctes_cartera('001','A') RETURNING P_COD_RET, cMensaje; --0090
     
/*	
	SELECT COUNT(tabid)INTO sPaso FROM systables WHERE tabname= 'cb_cat_atento_admin_saldos';
            IF NVL(sPaso,0) > 0 THEN
                DROP TABLE cb_cat_atento_admin_saldos;
            END IF;

	create table cb_cat_atento_admin_saldos
        (
        numcte			char(20),
		saldo_total		decimal(18,2),
		pago_min		decimal(18,2),
		pen_mes_ant		decimal(18,2),
		interes			decimal(18,2),
		pago_min_req	decimal(18,2),
		fecha_lim_pago	date,
		pagos_vencidos	smallint,
		ult_fecha_pago	date,
		monto_ult_pago	decimal(18,2),
		 fecha_compac date,
		 sucursal char(4),
		 importe decimal(18,2),
		 flag_pago char(1)) ;

	
	--Obtener caracter delimitador
	SELECT trim(valor_alfabetico)
	INTO cdelimitador
	FROM bdicobranza:cb_param_campania
	WHERE empresa = '001'
	AND tipo_campania = 1
	AND grupo_parametro = 'ARCHIVOS'
	AND num_parametro = 2;
	
	--Valida que exista el caracter
	IF NVL(cDelimitador,'') = '' THEN
        LET P_COD_RET= '104004';
        SELECT descripcion
        INTO cMensaje
        FROM cb_errores
        WHERE origen = 3
        AND codigo_error = P_COD_RET;
	
        IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
        END IF;

        CALL bdicobranza:"informix".inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '01');
        Return P_COD_RET;
	END IF;
	
		
	select trim(valor_alfabetico) into cruta
	from bdicobranza:cb_param_campania 
	where tipo_campania = 1
	and grupo_parametro = 'ARCHIVOS'
	and num_parametro = 36;
	
	--Valida que exista la carpeta
	IF NVL (cruta,'') = '' THEN
        LET P_COD_RET= '104005';
        SELECT descripcion
        INTO cMensaje
        FROM cb_errores
        WHERE origen = 3
        AND codigo_error = P_COD_RET;
	
        IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
        END IF;

        CALL bdicobranza:"informix".inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '01');
        Return P_COD_RET;
	END IF;
	
	--select fecha_hoy into vfecha from bdicred:sd_fechas where empresa = '001';
	LET vfecha = today - 1 units day;
	
    set isolation to dirty read;
    set lock mode to wait 3;
	
	select max(a.fecha_insert) into vfecha_insert
	from bdicobranza:cb_cat_directorio_cte a
	where a.tipo_cobranza = 'A' 
		AND a.pago_venc = 1 
		AND a.status_cliente  ='AT'
		--AND nvl(a.saldo_total,0) > 0
		--AND a.status_cliente NOT IN ('EX','IN')
		AND a.call_c = 2;

	FOREACH
	
    select  trim(a.numcte)numcte,a.num_credito,  anex.prox_fecha_pago, a.pago_venc, anex.fecha_ult_pago, 
			d.sucursal
	INTO vnumcte,vnum_credito,vfecha_lim_pago,	vpagos_vencidos,	vult_fecha_pago	,cSucursal
	FROM bdicobranza:cb_cat_directorio_cte a , bdinteg:si_cliente d, 	bdicred:sd_maecredanexo anex
	WHERE a.empresa = d.empresa
		AND a.numcte = d.numcte
		AND a.empresa = anex.empresa
		AND a.num_credito = anex.num_credito
		AND a.tipo_cobranza = 'A' 
		AND a.pago_venc = 1 
		AND a.status_cliente  ='AT'
		--AND nvl(a.saldo_total,0) > 0
		--AND a.status_cliente  NOT IN ('EX','IN')
		and a.call_c = 2
		and a.fecha_insert = vfecha_insert

		select limit 1
		TRIM(NVL(fecha_compac,'')),TRIM(NVL(sucursal,'')),TRIM(NVL(importe,'')),TRIM(NVL(flag_pago,''))
		INTO vfecha_compac,vsucursal,vimporte,vflag_pago
        from bdicobranza:cb_compac_his where empresa = '001' and numcliente = vnumcte
        and fecha_compac = (select max(fecha_compac) from bdicobranza:cb_compac_his where empresa = '001' and numcliente = vnumcte);
		
		SELECT limit 1 NVL(monto,0) INTO vmonto_ult_pago
        FROM bdicred:sd_movhis WHERE codigo_fun in ('033','334','335','336','337','904') AND codigo_ref = 1
        AND fecha_mov = (select max(fecha_mov)from bdicred:sd_movhis where num_credito = vnum_credito )  
        AND reversado = 'N' AND num_credito = vnum_credito ;
		
	-----------------------------SALDOS-------------------------------------------------------	
	execute PROCEDURE bdicred:"informix".sp_consulta_saldos_general('001', vnum_credito)
	into P_cod_ret,cMensaje,vnum_credito,cCodTipCred,dtFechaOrigen, dtFechaProxPago,
          dPagoMinimo, dtFechaUltPago, iPlazo, iPagosRealizados, dLineaOtorgada,
          dTasaInteres, dTasaMoratorios, dMontoSBC, dCapVig, dCapTrans, dCapVdoExig,
          dCapVdoNoExig, dSdoActCap, dIntVig, dIntVdo, dIntMoratorio, dIntMes,
          dSdoActInt,dIvaIntVig, dIvaIntVdo, dIvaIntMoratorio,dIvaIntMes, dSdoActIvaInt,
          dComPend, dIvaCom, dSdoRetenido, dSdoTotalLiq, dIntDevengado,dIvaIntDevengado, dLineaDisponible,
          dPagosVdos, cDescStatusCred, iIdUnidadProd,cDescBloqueoCta, cCodCaract2,
          cDescCausaBloqueoCta, cSitCte, cCausaCte, cDescSitEspCte,cSitCred,
          cCausaCred,cDescSitEspCred;
		  

		LET vsaldo_total = dSdoTotalLiq;	
		LET vpen_mes_ant = dCapTrans;
		LET vinteres = dIntVdo + dIntMoratorio + dSdoActIvaInt;
		LET vpago_min_req = dPagoMinimo;
		LET vpago_min = vpago_min_req - (vinteres + vpen_mes_ant);
		
        INSERT INTO bdicobranza:cb_cat_atento_admin_saldos 
		(numcte,	saldo_total,	pago_min,pen_mes_ant	,interes,	pago_min_req,	
		fecha_lim_pago,	pagos_vencidos,	ult_fecha_pago	,monto_ult_pago	, fecha_compac,sucursal,importe,flag_pago)
	    VALUES (		nvl ( vnumcte,' ' ),
                        nvl ( replace ( replace( vsaldo_total , '|' , ' ' ), '\' , ' ' ), ' ' ),
						nvl ( replace ( replace( vpago_min , '|' , ' ' ), '\' , ' ' ), ' ' ),
						nvl ( replace ( replace( vpen_mes_ant , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vinteres , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vpago_min_req , '|' , ' ' ), '\' , ' ' ), ' ' ),
						nvl ( vfecha_lim_pago, date(1) ),
						nvl ( replace ( replace( vpagos_vencidos , '|' , ' ' ), '\' , ' ' ), ' ' ),
						nvl ( vult_fecha_pago, date(1) ),
                        nvl ( replace ( replace( vmonto_ult_pago , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vfecha_compac , '|' , ' ' ), '\' , ' ' ), ' ' ),
						nvl ( replace ( replace( vsucursal , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vimporte , '|' , ' ' ), '\' , ' ' ), ' ' ),
                        nvl ( replace ( replace( vflag_pago , '|' , ' ' ), '\' , ' ' ), ' ' ));

        IF icontador >= 1000 then
            update statistics medium for table bdicobranza:cb_cat_atento_admin_saldos;
			LET icontador=1;
		ELSE
			LET icontador=icontador+1;
		END IF;
    End ForEach;

--------------------------------------------------------GENERAR ARCHIVO--------------------------------------------------------
	--let cruta = '/informix/Elizabeth/';
	let cnombre = 'reporte_admin_atento_saldos';
	
    LET cnomarchivo1 =  trim(cnombre)||'Aux'||to_char(vfecha,'%d%m%Y')||'.txt';
    LET cnomarchivo =  trim(cnombre)||to_char(vfecha,'%d%m%Y')||'.txt';
	 
	let cSql='';
	LET cSQL1 = ' echo " SET ISOLATION TO DIRTY READ; UNLOAD TO ' || TRIM(cruta) || TRIM(cnomarchivo1) || ' DELIMITER ' || ''''|| cdelimitador || ''''||'';
	LET cSQL2 = " select * from bdicobranza:cb_cat_atento_admin_saldos ";
	LET cSQL3 = '">'||TRIM(cRuta)||'Ejecuta.sql';
	LET cSQL = trim(cSQL1) || cSQL2 || trim(cSQL3);
    System cSQL;

    LET cSQL='chmod 777 '|| TRIM(cRuta)||'Ejecuta.sql';
    System cSQL;

    let cSQL = 'dbaccess bdicobranza ' || TRIM(cRuta) || 'Ejecuta.sql';
    System cSQL;

    LET cSql = cSql;
    LET cSql = "sed 's/"||cDelimitador||"$//g' "|| TRIM(cRuta) || TRIM(cnomarchivo1) || " >> " || TRIM(cRuta) || TRIM(cnomarchivo);
    SYSTEM cSql;
/*
	--SE COMPRIME  EL ARCHIVO	
	LET cSql = "gzip " || trim(cruta) || trim(cnomarchivo); 
	system cSql;
*/
	--Borra el archivo de control.
/*	LET cSQL = '' ;
	LET cSQL = 'rm ' || TRIM(cruta) || 'Ejecuta.sql';
	SYSTEM cSQL;

    LET cSQL = '' ;
	LET cSQL = 'rm ' || TRIM(cruta) || cnomarchivo1;
	SYSTEM cSQL; 
*/	
	CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '03')RETURNING P_COD_RET;
	CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso,'000000', 'FINALIZA PROCESO EVALUA CTES CARTERA' ,'02' ) RETURNING P_COD_RET;
	 RETURN P_COD_RET;

end;
end procedure;

CREATE PROCEDURE "informix".sp_cat_gb_pp_genarchex(pEmpresa  CHAR(3),pFecha_ex DATE)
RETURNING CHAR(6) AS codigo_retorno;

-- AUTOR : Abrham Lopez Lopez. El SP genera un archivo que extrae información de los clientes excluidos para campaña IVR prestamo personal',
-- FECHA : 05/NOVIEMBRE/2011   BD: BDICOBRANZA
-- Modificado por: MAHR. Abril 2012. Se asigna proceso: 2004 a fin de no repetir con otros procesos asignados.


--Declaración de variables        
DEFINE cCodRet              CHAR(6); 
DEFINE cMensajeRet          CHAR(80);
DEFINE iSqlErr              INTEGER;
DEFINE iIsamErr             INTEGER;
DEFINE cErrorInfo           CHAR(80);
DEFINE cSql                 CHAR(2400);
DEFINE cNombreArchivo1      CHAR(50);
DEFINE cNombreArchivo       CHAR(50);
DEFINE cRuta                CHAR(100);
DEFINE iNumreg              INTEGER;
DEFINE iDatos               INTEGER;
DEFINE cEmpresa             CHAR(3);
DEFINE cNombre              CHAR(100);
DEFINE cdelimitador         CHAR(1);
DEFINE cValor_status        CHAR(20);
DEFINE cSql1                CHAR(150);
DEFINE cSql2                CHAR(1500);
DEFINE cSql3                CHAR(100);
DEFINE cCodRetIB            CHAR(6);
DEFINE cMensaje             CHAR(80);
DEFINE cProceso             CHAR(4);
DEFINE vfecha_insert		DATE;


--Inicialización de variables
LET iSqlErr                = 0;
LET iIsamErr               = 0;
LET cErrorInfo             = "";
LET cCodRet                = "000000";
LET cRuta                  = "";
LET cNombreArchivo1        = "";
LET cNombreArchivo         = "";
LET iNumreg                = 0;
LET iDatos                 = 0;
LET cEmpresa               = "";
LET cNombre                = '';
LET cdelimitador           = '';
LET cSql                   = "";
LET cValor_status          = "";
LET cMensajeRet            = 'PROCESO EXITOSO';
LET cSql1                  = "";
LET cSql2                  = "";
LET cSql3                  = "";
LET cCodRetIB              = "000000";
LET cMensaje               = "";
LET cProceso               = '2004'; 
LET vfecha_insert		   = DATE(1);

BEGIN

    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
        IF iSqlErr != 0 THEN
            LET cCodRet     = iSqlErr;
            LET cMensajeRet = cErrorInfo;
            EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensajeRet,"02")
                     INTO cCodRetIB;
            RETURN cCodRet; 
        END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

--SET DEBUG FILE TO '/home/syscobra/cat/envios/sp_ctbcpl_gen_arcctesexcluidos.out';
--TRACE ON;

    -- Inserta bitacora de procesos
    EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,"","","01")
             INTO cCodRetIB;
        
    -- Validacion de los datos de entrada
    IF NVL(pEmpresa,"") = "" THEN
        LET cCodRet     = "104007";
        SELECT descripcion
            INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
            AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensaje,"02")
                 INTO cCodRetIB;
        RETURN cCodRet;
    END IF;
    
    SELECT empresa
        INTO cEmpresa 
        FROM bdinteg:si_empresas
        WHERE empresa = pEmpresa;

    IF NVL(cEmpresa,"")= "" then
        LET cCodRet = "104002";
        SELECT descripcion
            INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen     = 3
            AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensaje,"02")
                 INTO cCodRetIB;
        RETURN cCodRet;
    END IF;

    IF NVL(pFecha_ex,"") = "" THEN
        LET cCodRet     = "104008";
        SELECT descripcion
            INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
            AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensaje,"02")
                 INTO cCodRetIB;
        RETURN cCodRet;
    END IF;

    -- obtener la ruta donde se almacenara el archivo que sera enviado a buro de credito
    SELECT valor_alfabetico 
        INTO cRuta
        FROM bdicobranza:cb_param_campania
        WHERE empresa         = pEmpresa
        AND tipo_campania   = '1'
        AND grupo_parametro = 'ARCHIVOS'
        AND num_parametro   = 36;

    IF NVL(cRuta,"")    = "" THEN
        LET cCodRet     = "104005";
        SELECT descripcion
            INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
            AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensaje,"02")
                  INTO cCodRetIB;
        RETURN cCodRet;
    END IF;

    -- Se obtiene del nombre del archivo
    SELECT valor_alfabetico 
        INTO cNombre
        FROM bdicobranza:cb_param_campania
        WHERE empresa         = pEmpresa
        AND tipo_campania   = '1'
        AND grupo_parametro = 'ARCHIVOS'
        AND num_parametro   = 50;

    IF NVL(cNombre,"") = "" THEN
        LET cCodRet = "104006";
        SELECT descripcion
            INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
            AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensaje,"02")
                     INTO cCodRetIB;
        RETURN cCodRet;
    END IF;


    --Obtener caracter delimitador
    SELECT trim(valor_alfabetico)
        INTO cdelimitador
        FROM bdicobranza:cb_param_campania
        WHERE empresa = pempresa
        AND tipo_campania = 1
        AND grupo_parametro = 'ARCHIVOS'
        AND num_parametro = 25;
    
    IF NVL(cdelimitador,"") = "" THEN
        LET cCodRet     = "104004";
        SELECT descripcion
            INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
            AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensaje,"02")
                     INTO cCodRetIB;
        RETURN cCodRet;
    END IF;
     
    LET cNombreArchivo1 = 'prueba.txt';
    LET cNombreArchivo  = TRIM(cNombre) || LPAD(TRIM(DAY(pFecha_ex)::CHAR(2)),2,'0') || LPAD(TRIM(MONTH(pFecha_ex)::CHAR(2)),2,'0') || YEAR(pFecha_ex) || '.txt';
	
	select max(fecha_insert) INTO Vfecha_insert
    from bdicobranza:cb_cat_directorio_cte 
	WHERE empresa = '001' 
        and tipo_cobranza = 'E' 
        and num_producto = '6300';
   
    FOREACH
        SELECT trim(valor_alfabetico)
            INTO cValor_status
            FROM bdicobranza:cb_param_campania
            WHERE empresa         = pEmpresa
            AND tipo_campania   = '1'
            AND grupo_parametro = 'STATARCHCE'
            AND valor_alfabetico IN ('EX','IN','AC') -- mahr. Solo se contemplan estos status para CAT
     
        SELECT COUNT (numcte)
            INTO iNumreg
			FROM bdicobranza:cb_cat_directorio_cte
			WHERE empresa = pEmpresa
            AND tipo_cobranza = 'E'
            AND status_cliente = cValor_status
			AND fecha_modificacion = pFecha_ex
            AND num_producto = '6300';
		    

        IF iNumreg = 0 THEN
            CONTINUE FOREACH;
        END IF;

		LET iDatos = iDatos + 1;
			
		--se ejecuta para ponerle el encabezado
		let cSql='';
		let csql = 'echo "cliente'||','||'nombre'||','||'tipoproducto'||','||'telcasa'||','||'telcelular'||','||
				 'fechalimitepago'||','||'fechacorte'||'">'||TRIM(cruta)|| cNombreArchivo;   
		system csql; 

        -- para generar el archivo 
		LET cSql1 = ' echo "SET ISOLATION TO DIRTY READ; UNLOAD TO ' || TRIM(cRuta) || TRIM(cNombreArchivo1) || ' DELIMITER ' || ''''|| cdelimitador || ''''||'';

		LET cSql2 = " select  a.numcte as cliente , "
				|| " trim (h.apell_paterno) ||' '|| trim (h.apell_materno)||' '|| trim(h.nombre1) ||' '|| trim(h.nombre2) as nombre , "
				|| " a.num_producto as tipoproducto, " 
				|| " nvl(b.telefono,' ') as telcasa, "
                || " nvl((case when d.carrier = 1 then 5 || trim(substr(d.telefono,length(d.telefono)-9,10))  when d.carrier = 2 then 1 || trim(substr(d.telefono,length(d.telefono)-9,10))  else 1 || d.telefono end),'') as telcelular, "
				|| " (e.prox_fecha_pago) as fechalimitepago, "
				|| " (e.prox_fecha_pago) as fechacorte "
				|| " from bdicobranza:cb_cat_directorio_cte  a "
				|| " join bdinteg:si_cliente h on (h.empresa = a.empresa and h.numcte = a.numcte) "    
				|| " left outer join bdinteg:si_telefonos b on ( b.empresa = a.empresa and b.numcte = a.numcte and b.tipo_tel = 1) "
				|| " left outer join bdinteg:si_telefonos d on ( d.empresa = a.empresa and d.numcte = a.numcte and d.tipo_tel = 2) "
				|| " join bdicred:sd_maecredanexocrd e on (e.empresa= a.empresa and e.num_credito = a.num_credito) "
				|| " where a.empresa = '001' "
				|| " and a.tipo_cobranza = 'E' "
                || " and a.status_cliente = '" || cValor_status || "'"  -- IN ('EX','IN') "
                || " and a.fecha_modificacion = '" || pFecha_ex || "'"
				|| " and a.fecha_insert = '" || Vfecha_insert || "'"
				|| " and a.num_producto = '6300' "
				|| " and ((nvl(b.telefono,'')<> '') or (nvl(d.telefono,'') <> '')) ";
						
        LET cSql3 = ' " > '|| TRIM(cRuta) || 'Ejecuta_GenArchivoTelefonos.sql';
            
        LET cSql1 = TRIM(cSql1);
        LET cSql3 = TRIM(cSql3);
            
        LET cSql = cSql1 || cSql2 || cSql3;
			
		SYSTEM cSQL;
		--Permiso para la creacion de archivo.
		LET cSQL = '' ;
		LET cSQL = 'chmod 666 ' || TRIM(cRuta) || 'Ejecuta_GenArchivoTelefonos.sql' ;
		LET cSQL = '' ;
		LET cSQL = 'dbaccess bdicobranza ' || TRIM(cRuta) || 'Ejecuta_GenArchivoTelefonos.sql';
		SYSTEM cSQL;
			
		LET cSql = "sed 's/"||cdelimitador||"$//g' "|| TRIM(cRuta) || cNombreArchivo1 || " >> " || TRIM(cRuta) || cNombreArchivo;
        SYSTEM cSql;

		--Borra el archivo de control.
		LET cSQL = '' ;
		LET cSQL = 'rm ' || TRIM(cRuta) || 'Ejecuta_GenArchivoTelefonos.sql';
		SYSTEM cSQL;

		LET cSQL = '' ;
		LET cSQL = 'rm ' || TRIM(cRuta) || cNombreArchivo1;
		SYSTEM cSQL;
		
    END FOREACH;

    -- Por si el archivo no  se genera 
    IF iDatos = 0 THEN
        LET cCodRet = '104009';
        SELECT descripcion
            INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
            AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensaje,"02")
                 INTO cCodRetIB;
        RETURN cCodRet;
    END IF;

    EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,cProceso,cCodRet,cMensajeRet,"03")
             INTO cCodRetIB;

    RETURN cCodRet;

END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtcanalorigen(pNumParam INTEGER)
RETURNING 
		CHAR(5)			AS cCodRet,
		CHAR(80)		AS cMensajeRet,
		DECIMAL(18,2)	AS VALOR_NUMERICO,
		CHAR(100)		AS VALOR_ALFABETICO;
		
	--DECLARACIONES
    DEFINE cCodRet          CHAR(5);
    DEFINE iSqlErr          INTEGER;
    DEFINE iIsamErr         INTEGER;
    DEFINE sRegistros       SMALLINT; 
	DEFINE cErrorInfo		CHAR(80);
    DEFINE cMensajeRet      CHAR(85);
    
	DEFINE dValNum	    	DECIMAL(18,2);
    DEFINE cValorAlfa 	    CHAR(100);


    --INICIALIZACIONES
	LET cCodRet				= '00000';
	LET iSqlErr				= 0;
	LET iIsamErr			= 0;
	LET sRegistros			= 0;
	LET cErrorInfo			= '';
	LET cMensajeRet			= 'PROCESO EXITOSO';
	
	LET dValNum			= 0;
	LET cValorAlfa			= '';
	
	
	BEGIN
		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
		IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cMensajeRet = cErrorInfo;
			RETURN TRIM(cCodRet),TRIM(NVL(cMensajeRet,'')), NVL(dValNum,0),TRIM(NVL(cValorAlfa,''));
		END IF;
    END EXCEPTION;
    
	--SET DEBUG FILE TO '/home/sysifx/Morales/sp_obtcanalorigen';
	--TRACE ON;
	
	SET LOCK MODE TO WAIT 3;
	SET ISOLATION TO DIRTY READ;
	
		LET pNumParam = NVL(pNumParam,0);		
		-- TIPO DE CONSULTA PARA OBTENER TODA LA INFORMACION DEL CATALOGO SIEMPRE Y CUANDO EL PARAMETRO SEA IGUAL A CERO O INGRESANDO EL CODIGO
		FOREACH
			SELECT valor_numerico, valor_alfabetico 
			INTO dValNum, cValorAlfa 
			FROM bdicobranza:"informix".cb_param_campania
			WHERE grupo_parametro = 'CANALCONVE'
			AND valor_numerico = (CASE WHEN pNumParam = 0 THEN valor_numerico ELSE pNumParam END)
						
		RETURN TRIM(cCodRet),TRIM(NVL(cMensajeRet,'')), NVL(dValNum,0),TRIM(NVL(cValorAlfa,'')) WITH RESUME;
								

		END FOREACH;
		
		LET sRegistros = dbinfo("sqlca.sqlerrd2"); -- VALIDA SI EXISTE INFORMACION EN EL CATALOGO

		IF(sRegistros = 0) THEN					
			LET cCodRet = "00002";
			LET cMensajeRet = "NO SE ENCONTRO INFORMACIÓN DE ORIGEN DE CONVENIO";

		RETURN TRIM(cCodRet),TRIM(NVL(cMensajeRet,'')), NVL(dValNum,0),TRIM(NVL(cValorAlfa,''));
			
		END IF;					
				
END
END PROCEDURE
DOCUMENT
'DESCRIPCION: Creación de un procedimiento nuevo el cual consulta y regresa la información de los campos valor_numerico y descripcion de la tabla cb_param_campania', 
'AUTOR: Armando Morales Barraza ',
'FECHA: 24 de Agosto del 2012',
'VERSION: 20120807.1048',
'BD: bdicobranza';

CREATE PROCEDURE "informix".sp_rep_mail_diario ()
returning char (6);

------------------------------------------------------------------------------------
--Maria Elizabeth Anzures Ibarguen
--08-27-2012
--manda llamar sps que crean archivos de envio de mail que corren de manera diaria


----DATOS QUE VAN EN LA TABLA

--VARIABLES PARA CAPTURAR ERRORES
DEFINE SQL_ERR                INTEGER;
DEFINE ISAM_ERR               INTEGER;
DEFINE ERROR_INFO             VARCHAR(80);
DEFINE P_COD_RET              VARCHAR(5);
DEFINE P_MENSAJE              VARCHAR(80);
DEFINE vproceso				  CHAR (4);
DEFINE cMensaje				  CHAR(80);


BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, ERROR_INFO
        LET P_COD_RET = SQL_ERR;
        LET P_MENSAJE = ERROR_INFO;
		 CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '02')RETURNING P_COD_RET;	
	RETURN P_COD_RET;
    END EXCEPTION;

 -- Set debug file to 'mail.out';
 -- trace on;

---INICIALIZAN VARIABLES PARA QUERYS
Let P_cod_ret		= "00000";
LET vproceso		='2091';
LET cMensaje   		= 'PROCESO EXITOSO';
	CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '01') RETURNING P_COD_RET;
    
	
	-------------------------------------LLAMA A SPS QUE CORREN DIARO------------------------------------
	call "informix".sp_rep_envio_mail_compromiso() RETURNING P_COD_RET;  
	call "informix".sp_rep_envio_sms_pp() RETURNING P_COD_RET; 
	
	CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '03') RETURNING P_COD_RET;
    RETURN P_COD_RET;

end;
end procedure;

CREATE PROCEDURE "informix".sp_repos_cat(pfecha_rep DATE, pusuario CHAR(8))
RETURNING  CHAR(6), CHAR(150);

--Declaracion de variables
------------------------------------------------------------
DEFINE sql_err 			  INTEGER;
DEFINE isam_err 		  INTEGER;
DEFINE error_info		  CHAR(150);
DEFINE cCod_ret           CHAR(6);
DEFINE ccCod_ret          CHAR(6);
DEFINE cMensaje           CHAR(150);
DEFINE ccMensaje          CHAR(150);
DEFINE cCadena            CHAR (500);
DEFINE vNomArch           CHAR(30);
DEFINE vNomArch2          CHAR(30);
DEFINE vPathOri           CHAR(50);
DEFINE vPath              CHAR(50);
DEFINE vempresa           CHAR(3);
DEFINE vproceso           CHAR(20);
DEFINE cNum_sol			  CHAR(20);
DEFINE cNumCte			  CHAR(20);
DEFINE cStatus_sol		  CHAR(2);
DEFINE cSucursal		  CHAR(4);
DEFINE dFecha_insert      DATE;
DEFINE cNombre_completo   CHAR(80);
DEFINE cTel_casa		  CHAR(13);
DEFINE cCelular			  CHAR(13);
DEFINE cTel_trab		  CHAR(13);
DEFINE cExt_trab		  CHAR(5);
DEFINE deMonto_sol		  DECIMAL(18,2);
DEFINE pSeparador         CHAR(1);
DEFINE vpusuario          CHAR(8);
DEFINE dFecha_ini		  DATE;
DEFINE dDia				  DATE;
DEFINE dFecha_fin		  DATE;
DEFINE dFechaBorra		  DATE;
DEFINE eDias			  INTEGER;
DEFINE vmeses_historial   INTEGER;
DEFINE vtipo_comprobante  CHAR(4);
DEFINE vsql 			  CHAR(5054);


    LET dFecha_insert = '';	     
    LET cCod_ret      = '00000';
    LET sql_err       = 0;
    LET cMensaje      = 'PROCESO EXITOSO';
    LET cCadena       = '';
    LET vPathOri        = '';
    LET vPath         = '';
    LET vempresa      = '001';
    LET vproceso      = '1001';   
    LET cNum_sol            = '';		
    LET cNumCte             = '';	  
    LET cStatus_sol         = '';	 
    LET cSucursal           = '';		 
    LET cNombre_completo    ='';	
    LET cTel_casa	  = '';		
    LET cCelular	  = '';		
    LET cTel_trab	  = '';	
    LET cExt_trab	  = '';		
    LET deMonto_sol	  = 0.00;	
    LET pSeparador    = '|';
    LET vpusuario     = pusuario;
    LET dFecha_ini	  = '';
    LET dDia		  = '';
    LET dFecha_fin 	  = '';
    LET dFechaBorra = '';
    LET eDias         = '';
    LET vsql 	      = '';
       
      BEGIN

        ON EXCEPTION SET sql_err, isam_err, error_info
	        LET cCod_ret = sql_err;
            LET cMensaje = error_info;
            CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vproceso, cCod_ret, cMensaje, '02');
        RETURN cCod_ret, cMensaje;
	    END EXCEPTION;

            CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vproceso, cCod_ret, cMensaje, '01');
                
    --SET DEBUG FILE TO "/home/syscobra/sp_cat_arch_cartbase.out";
    --TRACE ON;

------------------------------------------------------------------------------------
    TRUNCATE cb_repos_cat;

    SELECT valor INTO vNomArch
	FROM bdicobranza:cb_param
	WHERE cod_param= '2' AND empresa= vempresa;

    LET vNomArch2 = vNomArch;

    -- ARMAR NOMBRE DEL ARCHIVO TXT
    LET vNomArch = TRIM(vNomArch) || TO_CHAR(pfecha_rep,'%Y%m%d') || '.txt';

------------------------------------------------------------------------------------
------------------------------------------------------------------------------------

    -- EXTRAER LA RUTA DEPOSITO DE ARCHIVO
    SELECT TRIM(valor) 
    INTO vPathOri
	FROM Bdicobranza:cb_param
	WHERE cod_param= '1' AND empresa= vempresa;
    SELECT valor INTO eDias
	FROM Bdicobranza:cb_param
	WHERE cod_param= '5' AND empresa= vempresa;
   
    Let vPath = TRIM(vPathOri);

        --obtiene el dia de la semana en que se genera el reporte
		LET dDia= weekday(pfecha_rep);

        IF dDia = 1 THEN
			LET dFecha_ini = pfecha_rep -3;
			LET dFecha_fin = pfecha_rep -1;
		ELSE
			LET dFecha_ini = pfecha_rep -1;
			LET dFecha_fin = pfecha_rep -1;
		END IF;

        

        LET dFechaBorra =  pfecha_rep - eDias;

        LET dFechaBorra = dFechaBorra;

        SET ISOLATION TO DIRTY READ;
		FOREACH

			SELECT a.num_solicitud,a.numcte,a.status_solicitud,a.sucursal,a.fecha_insert,
			TRIM(d.nombre1) || " " || TRIM(d.nombre2) || " " ||TRIM(d.apell_paterno) || " " || TRIM(d.apell_materno), 
			tel1.telefono , tel2.telefono , tel3.telefono , tel3.extension ,a.monto_solicitado
			INTO cNum_sol, cNumCte, cStatus_sol, cSucursal, dFecha_insert, cNombre_completo, 
			cTel_casa, cCelular, cTel_trab, cExt_trab, deMonto_sol
			FROM  bdisolic:ss_solicitudes a
			join bdinteg:si_cliente d on (a.numcte = d.numcte)
			left join bdinteg:si_telefonos tel1 on (tel1.numcte = a.numcte and tel1.tipo_tel = 1 and 
					tel1.secuencia = (select max(secuencia) from bdinteg:si_telefonos where numcte = a.numcte and tipo_tel = 1))
			left join bdinteg:si_telefonos tel2 on (tel2.numcte = a.numcte and tel2.tipo_tel = 2 and 
					tel2.secuencia = (select max(secuencia) from bdinteg:si_telefonos where numcte = a.numcte and tipo_tel = 2))
			left join bdinteg:si_telefonos tel3 on (tel3.numcte = a.numcte and tel3.tipo_tel = 3 and 
					tel3.secuencia = (select max(secuencia) from bdinteg:si_telefonos where numcte = a.numcte and tipo_tel = 3))
			WHERE a.fecha_insert  BETWEEN  dFecha_ini AND dFecha_fin
			AND a.status_solicitud in ('AP','OA','OS','EE','AT')  
		
            --SELECT nvl(meses_historia,0)
            SELECT NVL (MAX(meses_historia),0) as meses_historia
            INTO vmeses_historial
            FROM bdisolic:ss_resum_scor_fin                
            WHERE empresa = vempresa
            AND num_solicitud = cNum_sol;

            CALL bdidigital@coppelimg_tcp:sp_tipo_comprobante(cNumCte, cNum_sol)   
            RETURNING ccCod_ret, ccMensaje, vtipo_comprobante;
-- let vtipo_comprobante = '';---------------------------------------------------------------------------------PUEBAS
			--se insertan los datos generados 
			INSERT INTO cb_repos_cat (num_solicitud, numcte, status_solicitud, sucursal, fecha_insert, 
									 nombre_completo,tel_casa,  celular, tel_trab, ext_trab, monto_sol, meses_historial, tipo_comprobante)
			VALUES(cNum_sol, cNumCte, cStatus_sol, cSucursal, dFecha_insert, cNombre_completo, 
				   cTel_casa, cCelular, cTel_trab, cExt_trab, deMonto_sol, vmeses_historial, vtipo_comprobante);
                              
		END FOREACH;

------------------------------------------------------------------------------------
------------------------------------------------------------------------------------

            LET cCadena = 'echo "unload to ' || SUBSTR(vPath,1,LENGTH(vPath)) || SUBSTR(vNomArch,1,LENGTH(vNomArch)) || ' DELIMITER ''' || pSeparador || ''' SELECT * FROM cb_repos_cat'
                   || '" > ' || SUBSTR(vPath,1,LENGTH(vPath)) || 'reporte_os.sql';
            System cCadena;
            let cCadena = 'dbaccess bdicobranza ' || SUBSTR(vPath,1,LENGTH(vPath)) || 'reporte_os.sql';
            System cCadena;
            let cCadena = 'rm ' || SUBSTR(vPath,1,LENGTH(vPath)) || 'reporte_os.sql';
            System cCadena;
            

            --LET cMensaje = TRIM(vNomArch);

            LET vNomArch2 = TRIM(vNomArch2) || 
							NVL( YEAR(dFechaBorra) || 
							LPAD(MONTH(dFechaBorra),2,'0') || 
							LPAD(DAY(dFechaBorra),2,'0') , '') ||
							'.txt';

            LET vsql = '';  --SE BORRA ARCHIVO MAYOR A 7 DIAS 
            LET vsql = "rm -rf "||TRIM(vPathOri)||""||vNomArch2;
            SYSTEM vsql;

CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vproceso, cCod_ret, cMensaje, '03');
RETURN cCod_ret, cMensaje;

END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cartera_pagovencido(vfecha_insert DATE, vtipo_cobranza CHAR(1), vpago_venc INTEGER)
       RETURNING char(6), char(150);

--declaracion de variables
------------------------------------------------------------
DEFINE sql_err 			            INTEGER;
DEFINE isam_err 		            INTEGER;
DEFINE error_info		            CHAR(150);
DEFINE cMensaje 		            CHAR(150);
DEFINE cCod_ret                     CHAR(6);
DEFINE vvcCod_ret                   CHAR(6);
DEFINE vnombre                      CHAR(110);
DEFINE vempresa                     CHAR(3);
DEFINE vnumcte                      CHAR(20);
DEFINE vnum_credito                 CHAR(20);
DEFINE vnum_tarjeta                 CHAR(20);
DEFINE vtelefono_casa               CHAR (13);
DEFINE vtelefono_celular            CHAR(13);
DEFINE vtelefono_trabajo            CHAR(13);
DEFINE vext_trabajo                 CHAR(5);
DEFINE vsexo                        CHAR(1);
DEFINE vestado_civil                CHAR(2);
DEFINE vnombre_ref                  CHAR(110);
DEFINE vtelefono_ref                CHAR(13);
DEFINE vciudad                      CHAR(20);
DEFINE vestado                      CHAR(20);
DEFINE vsituacion                   CHAR(1);
DEFINE vcausa                       SMALLINT;
DEFINE vinstruccion                 CHAR(1);
DEFINE cproceso                     CHAR(4);
DEFINE vnombre1 CHAR(50);
DEFINE vnombre2 CHAR(50);
DEFINE vap CHAR(50);
DEFINE vam CHAR(50);

--SET DEBUG FILE TO 'sp_calcula_cobranza_administrativa_pbaaaa.out';
--TRACE ON;

      LET cCod_ret      = '000000';
	  LET sql_err       = 0;
	  LET isam_err      = 0;
	  LET error_info    = '';
	  LET cMensaje      = 'PROCESO EXITOSO';
      LET vempresa      = '001';
      LET cproceso      = '9999';

	BEGIN

        ON EXCEPTION SET sql_err, isam_err, error_info
	        LET cCod_ret = sql_err;
	        LET cMensaje = error_info;
                CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje, '02')
                RETURNING vvcCod_ret;
			RETURN cCod_ret, cMensaje;
	    END EXCEPTION;
	    
	    CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje, '01')
                RETURNING vvcCod_ret;

		SET ISOLATION TO dirty READ;

----------------------------------- Se obtienen DATOS del CLIENTE y SALDOS--------------------------------------------
FOREACH
            SELECT numcte, num_credito
            INTO vnumcte, vnum_credito
            FROM cb_cat_directorio_cte 
            WHERE empresa = vempresa 
            AND fecha_insert = vfecha_insert
            AND numcte > '0'
            AND tipo_cobranza = vtipo_cobranza
            AND pago_venc= vpago_venc

----------------------------------------------------------------------------------------------------------------------------------

            SELECT limit 1 e.num_tarjeta,                                                    --- tarjeta
                   b.numerociudad || '-' || trim(j.inicialciudad) Ciudad,            --- ciudad
                   j.numeroestado || '-' || trim(j.inicialestado) Estado,            --- estado
                   trim(a.nombre1), /*|| " " || */trim(a.nombre2), /*|| " " ||*/
                   trim(a.apell_paterno), /*|| " " ||*/ trim(a.apell_materno) ,     --- nombre
                   aa.sexo Sexo,                                                     --- sexo
                   aa.estado_civil Estado_Civil,                                     --- civil
                --   b.telefono1 Telefono_Casa,                                        --- t_casa
                 --  b.telefono2 Telefono_Celular,                                     --- t_celular
                 --  b.telefono3 Telefono_Trabajo,                                     --- t_trabajo
                 --  b.extension Ext_Trabajo,                                          --- ext
				   tel1.telefono Telefono_Casa,                                        --- t_casa
                   tel2.telefono Telefono_Celular,                                     --- t_celular
                   tel3.telefono Telefono_Trabajo,                                     --- t_trabajo
                   tel3.extension Ext_Trabajo,                                          --- ext
                   i.nombre_ref,                                                     --- nombre_ref
                   i.telefono_ref 
            INTO vnum_tarjeta, vciudad, vestado, vnombre1,vnombre2,vap,vam, vsexo, vestado_civil, vtelefono_casa
                ,vtelefono_celular, vtelefono_trabajo, vext_trabajo, vnombre_ref, vtelefono_ref
            FROM bdinteg:si_direcciones b
            LEFT JOIN bdinteg:si_cliente a ON (a.numcte = vnumcte)
            LEFT JOIN bdinteg:si_ctepf aa ON (aa.numcte = vnumcte)
            LEFT JOIN bdicred:sd_tarjeta e ON (e.empresa = vempresa AND e.num_credito = vnum_credito
                                                AND e.secuencia = (SELECT MAX(secuencia) FROM bdicred:sd_tarjeta ab
                                                                    WHERE ab.empresa = vempresa
                                                                    AND ab.num_credito= vnum_credito)
                                                AND e.status_tar = 'A'
                                                AND e.tipo_tarjeta = 'T')
            LEFT JOIN bdisolic:ss_refpersonales i ON (i.empresa = vempresa AND i.numcte = vnumcte AND i.numcte_ref = 'R1')
            LEFT JOIN bdinteg:si_catciudades j ON (b.numerociudad = j.numerociudad) --AND numeroestado)
			left join bdinteg:si_telefonos tel1 on (tel1.numcte = vnumcte and tel1.tipo_tel = 1 and 
						  tel1.secuencia = (select max(secuencia) from bdinteg:si_telefonos where numcte = vnumcte and tipo_tel = 1))
			left join bdinteg:si_telefonos tel2 on (tel2.numcte = vnumcte and tel2.tipo_tel = 2 and 
						  tel2.secuencia = (select max(secuencia) from bdinteg:si_telefonos where numcte = vnumcte and tipo_tel = 2))
			left join bdinteg:si_telefonos tel3 on (tel3.numcte = vnumcte and tel3.tipo_tel = 3 and 
						  tel3.secuencia = (select max(secuencia) from bdinteg:si_telefonos where numcte = vnumcte and tipo_tel = 3))
            WHERE b.numcte = vnumcte
            AND b.secuencia = ( select max(secuencia) from bdinteg:si_direcciones h
                              where h.tipo_dir = '1'
                              and h.numcte = vnumcte)
            AND b.tipo_dir = '1';

----------------------------------------------------------------------------------------------------------------------------------

                LET vtelefono_celular = '045' || substr(vtelefono_celular,length(vtelefono_celular)-9,10);

                IF vtelefono_celular = '045' THEN
                    LET vtelefono_celular = '';
                END IF;

----------------------------------------------------------------------

               IF (vpago_venc = 0) THEN
                   CONTINUE FOREACH;
               END IF;

                    LET vsituacion = NULL;
                    LET vcausa     = NULL;

                         SELECT  FIRST 1 situacion,  causa
                         INTO    vsituacion, vcausa
                         FROM    bdisitesp:se_ctessitespcte
                         WHERE   numcte = vnumcte;

                         LET vinstruccion = 1;
                   IF ((vsituacion IS NOT NULL) AND (vcausa IS NOT NULL)) THEN


                                SELECT FIRST 1 instruccion
                                INTO   vinstruccion
                                FROM   bdisitesp:se_situacionaccion
                                WHERE  situacion= vsituacion
                                AND    causa= vcausa
                                AND    idaccion = 9;

                    END IF;

                    IF (vinstruccion = 1) THEN

                        INSERT INTO cb_info_administrativa (cliente, credito, tarjeta, ciudad, estado, 
										nombre1 , nombre2,apell_paterno,  apell_materno, /*nombre, sexo, civil,
                                        t_casa,*/ t_celular, /*t_trabajo, ext, nombre_ref, t_ref,*/ pago_venc, 
                                        fecha_ejecucion)
                        VALUES(vnumcte, vnum_credito, vnum_tarjeta, vciudad, vestado,vnombre1,vnombre2,vap,vam,/* vnombre, vsexo, vestado_civil,
                                        vtelefono_casa,*/ vtelefono_celular, /*vtelefono_trabajo, vext_trabajo, vnombre_ref, 
                                        vtelefono_ref,*/ vpago_venc, current);
                    END IF;

END FOREACH;

        CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje, '03')
        RETURNING vvcCod_ret;
		RETURN cCod_ret, cMensaje;

	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_generatdcporentregar(pFechaEntrada DATE)
	RETURNING
		CHAR(5)  	AS CodRetorno;

	--DECLARARACION DE VARIBLES
	DEFINE cSqlErr					INTEGER;
	DEFINE cCodRet 					CHAR(5);	
	DEFINE cEmpresa        			CHAR(3);
	DEFINE cNumCte 					CHAR(20);
	DEFINE cNumCredito 				CHAR(20);
	DEFINE cCiudad 					CHAR(20);
	DEFINE cEstado 					CHAR(20);
	DEFINE cCelular			 		CHAR(13);
	--DEFINE cNombre 					CHAR(110);---Se comenta para mostrar el nombre por separado
	DEFINE cNumeroTarjeta 			CHAR(20);
	DEFINE cNombre1 				CHAR(50);
	DEFINE cNombre2 				CHAR(50);
	DEFINE cApellidoP 				CHAR(50);
	DEFINE cApellidoM 				CHAR(50);
	--Declaracion variables SP sp_tipored
	DEFINE 	cCodRetTipRed 			CHAR(5);
	DEFINE 	cTipoRed         		CHAR(10);
	DEFINE	cNum_Carrier_Cat 		CHAR (3);
	DEFINE cNumProducto 			CHAR(4);	
	DEFINE sNumCampania     		SMALLINT;
	DEFINE dtFechaHoy				DATE;
  DEFINE  cExiste           		CHAR(1);
	DEFINE cSituacion               CHAR(1);
	DEFINE sCausa                   SMALLINT;
  DEFINE cProceso         CHAR(4);	
  DEFINE vvcCod_ret       CHAR(6);
  DEFINE cMensaje 		CHAR(150);
		
	--INICIALIZACION DE VARIABLES	
	LET cSqlErr 			= 0;
	LET cCodRet 			= "000";
  LET cEmpresa      = '001';	
	LET cNumCte   			= '';
	LET cNumCredito 		= '';
	LET cCiudad  			= '';
	LET cEstado 			= '';
	LET cCelular 			= '';
	--LET cNombre 				= '';---Se comenta para mostrar el nombre por separado
	LET cNumeroTarjeta 		= ''; 
	LET cNombre1 			= '';
	LET cNombre2 			= '';
	LET cApellidoP 			= ''; 
	LET cApellidoM 			= ''; 
	---Inicializacion Variables SP sp_tipored
	LET cTipoRed        	='';
	LET cNum_Carrier_Cat 	='';
	LET cCodRetTipRed       ='00000';
	LET cNumProducto        = '';
	LET sNumCampania        = 0;
	LET dtFechaHoy          = '';
	LET cSituacion          = '';
	LET sCausa              = 0;
	LET cProceso      = '0054';
	LET vvcCod_ret = '';
	LET cMensaje   = 'PROCESO EXITOSO';
	
	--SET DEBUG FILE TO "/home/sysifx/SPs PAYAN/"informix".sp_generatdcporentregar.out";
	--TRACE ON;
	BEGIN
		ON EXCEPTION SET cSqlErr
			IF cSqlerr <> 0 THEN
				Let cCodRet = cSqlErr;
				CALL bdicobranza:"informix".sp_inserta_bitacora_cob(cEmpresa, cProceso, cCodRet, cMensaje, '02') RETURNING vvcCod_ret;
        RETURN cCodRet; 
				
			END IF;
		END EXCEPTION;
		
		SET LOCK MODE TO WAIT 3;
	  CALL bdicobranza:"informix".sp_inserta_bitacora_cob(cEmpresa, cProceso, cCodRet, '', '01') RETURNING vvcCod_ret; 
		
		IF pFechaEntrada IS NULL THEN 
		
			LET cCodRet = '001'; --Parametros no validos 
			RETURN cCodRet;
			
		END IF;
		
		--obtengo la fecha de hoy.
		SELECT NVL(fecha_hoy,'')
		INTO dtFechaHoy
		FROM bdicred:"informix".sd_fechas
	  WHERE empresa = cEmpresa;
		
		--obtengo el numero de producto de la campaña 8
		SELECT num_campania,num_producto
		INTO sNumCampania,cNumProducto
		FROM bdicobranza:"informix".cb_cat_campania
		WHERE empresa = cEmpresa 
      AND num_campania = 8;
		
		FOREACH
			---obtengo a los clientes con tdc por entregar.
			SELECT NVL(a.numcte,''), a.num_solicitud
			INTO  cNumCte, cNumCredito
			FROM  bdisolic:"informix".ss_solicitudes a, bdisolic:"informix".ss_autorizacion b
			WHERE b.empresa = a.empresa
				AND b.num_solicitud = a.num_solicitud
				AND b.status_solicitud = 'AT'
				AND b.fecha_entrada > DATE((pFechaEntrada) -7 units DAY)
						
				--obtengo el credito, ciudad y estado del cliente			
				/* No se actualiza cb_ctes_mensajes 
				SELECT NVL(a.credito,''), NVL(a.ciudad,''),NVL(a.estado,''),NVL(a.situacion,''),NVL(a.causa,0)
				INTO cNumCredito,cCiudad,cEstado,cSituacion,sCausa					
				FROM bdicobranza:"informix".cb_ctes_mensajes a, bdicred:"informix".sd_maecredanexo b
				WHERE a.empresa = cEmpresa
					AND a.cliente = cNumCte
					AND a.credito = b.num_credito
				*/
          SELECT LIMIT 1 e.nombre, c.nombre INTO cEstado, cCiudad
            FROM bdinteg:si_direcciones_actual d, bdinteg:si_estados e, bdinteg:si_ciudades c
           WHERE d.numcte = cNumCte
             AND d.ciudad = c.ciudad
             AND d.estado = e.estado
             AND c.estado = e.estado
             AND d.tipo_dir = 1;				
										
					--valido si ya existe el credito en la tabla si es true pues que continue con el siguiente credito						
					IF EXISTS (SELECT credito FROM bdicobranza:"informix".cb_info_administrativa WHERE credito = cNumCredito) THEN
						LET cExiste = 1;
					ELSE
						LET cExiste = 0;
					END IF;

					--si existe que continue con el siguiente credito y no inserte ningun registro
					IF cExiste = 1 THEN	
						DELETE bdicobranza:"informix".cb_info_administrativa WHERE num_campania = 8 AND credito = cNumCredito;
						CONTINUE FOREACH;
					END IF;	
		
					---obtengo el nombre del cliente por separado
					SELECT NVL(TRIM(nombre1),''), NVL(TRIM(nombre2),''), NVL(TRIM(apell_paterno),''), 
						 NVL(TRIM(apell_materno),'')
					INTO cNombre1,cNombre2,cApellidoP,cApellidoM
					FROM bdinteg:"informix".si_cliente
					WHERE empresa = cEmpresa
						AND numcte = cNumCte;
				/*	
					--obtengo el celular del cliente.
					SELECT limit 1 NVL(a.telefono2,'')
					INTO cCelular
					FROM bdinteg:"informix".si_direcciones_actual a
					WHERE a.numcte = cNumCte
            AND a.tipo_dir = '1';*/
			
				--obtengo el celular del cliente.
					SELECT limit 1 NVL(a.telefono,'')
					INTO cCelular
					FROM bdinteg:"informix".si_telefonos a
					WHERE a.numcte = cNumCte and tipo_tel = 2;
					 
					IF cCelular <> '' then
            LET cCelular = SUBSTR(cCelular,4,10);
          END IF;

					--valido celular
	                EXECUTE PROCEDURE bdinteg:"informix".sp_tipored (cEmpresa,cCelular)				
					INTO cCodRetTipRed,cTipoRed,cNum_Carrier_Cat;
						
					--valido si truena el sp por un error controlado o un error de informix.		
					IF cCodRetTipRed IS NULL OR cCodRetTipRed = '' THEN				 				  	
						CONTINUE FOREACH;
					ELIF cCodRetTipRed < "00000" THEN 
					        LET cCodRet =  '002';						    EXIT FOREACH;
					END IF ;
					
					--valida si es un celular correcto.
					IF cNum_Carrier_Cat NOT IN ( '0', '1', '2')  THEN
						CONTINUE FOREACH;
					END IF;	 
					
					--obtengo numero de tarjeta
					/* En este momento aún no hay tarjeta
					SELECT NVL(a.num_tarjeta,'') 
					INTO cNumeroTarjeta
					FROM bdicred:"informix".sd_tarjeta a				
					WHERE a.empresa = cEmpresa
					AND a.num_credito = cNumCredito
						AND a.tipo_tarjeta = 'T'
						AND a.secuencia = (SELECT NVL(MAX(b.secuencia),0)
											FROM bdicred:"informix".sd_tarjeta b
											WHERE b.empresa = a.empresa
												AND b.num_credito = a.num_credito
												AND tipo_tarjeta = 'T');
           */
           				
					--inserta informacion recabada 				
					INSERT INTO bdicobranza:"informix".cb_info_administrativa(empresa,num_campania,producto,fecha_ejecucion,cliente,credito,cuenta,tarjeta,ciudad,estado,nombre1,nombre2,
														apell_paterno,apell_materno,t_celular,sdo_total,pago_min,fecha_pago,sdo_venc_int_mora,pago_venc,
														pago_min_sin_vdo,situacion,causa)
								VALUES(cEmpresa,sNumCampania,cNumProducto,dtFechaHoy,cNumCte,cNumCredito,'',cNumeroTarjeta,cCiudad,cEstado,cNombre1,cNombre2,cApellidoP,cApellidoM,cCelular,0,0,'',0,0,0,cSituacion,sCausa);												
	
		END FOREACH;

    CALL bdicobranza:"informix".sp_inserta_bitacora_cob(cEmpresa, cProceso, cCodRet, cMensaje, '03')  RETURNING vvcCod_ret;
		
		IF DBINFO("sqlca.sqlerrd2") = 0 THEN
			LET cCodRet= '003';  --No hay informacion
			RETURN cCodRet;			
		END IF;	
		
       RETURN cCodRet;
	END;
END PROCEDURE

