LET cNombreArchivo2= 'CifrasControlDirectorioCtesBancoppel' || LPAD(TRIM(DAY(CURRENT::DATE)::CHAR(2)),2,'0') || LPAD(TRIM(MONTH(CURRENT::DATE)::CHAR(2)),2,'0') ||YEAR(CURRENT::DATE) || '.txt';

---INICIALIZAN VARIABLES PARA QUERYS
LET  vsql="";
LET  cSql="";
LET  vsql2="";
LET  cSql2="";

Let P_cod_ret = "00000";
--  Set debug file to 'directorioaltasycambios.out';
--  trace on;
    DROP TABLE bdicred:sd_directorioaltasycambios;

    create table sd_directorioaltasycambios
    (
         empresa                 CHAR(3) NOT NULL,
         numctebancoppel         CHAR(20) NOT NULL,
         apell_paterno           CHAR(26),
         apell_materno           CHAR(26),
         nombre1                 CHAR(26),
         nombre2                 CHAR(26),
         fecha_nac               DATE,
         rfc                     CHAR(13),
         curp                    CHAR(20),
         sexo                    CHAR(1),
         estado_civil            CHAR(2),
         apell_casada            CHAR(26),
         num_dependientes        SMALLINT,
         nacionalidad            CHAR(15),
         ocupacion_oficio        CHAR(30),
         actividad_gironegocio   CHAR(30),
         identificacion          CHAR(40),
         num_identificacion      CHAR(30),
         correo_electronico      CHAR(60),
         escolaridad             CHAR(2),
         num_estado              integer,
         num_ciudad              SMALLINT,
--       ciudad                  CHAR(15),
--       delegacion_municipio    CHAR(15),
         num_colonia             INTEGER,
         num_calle               INTEGER,
         numeroext               CHAR(10),
         numeroint               CHAR(10),
         cod_postal              CHAR(5),
         punto_cardinal          CHAR(1),
         manzana                 SMALLINT,
         andador                 SMALLINT,
         etapa                   SMALLINT,
         lote                    SMALLINT,
         edificio                SMALLINT,
         entrada                 SMALLINT,
         departamento            CHAR(6),
         complemento             CHAR(80),
         entre_calles            CHAR(40),
         antiguedad_domicilio    VARCHAR(80),
         otros                   SMALLINT,
         situacion_esp           CHAR(1),
         fecha_sit_esp           DATE,
         causa_sit_esp           SMALLINT,
         sector                  CHAR(2),
         actividad_economica     CHAR(45),
         empresa_labora          CHAR(60),
         antiguedad_trabajo      VARCHAR(80),
         puesto                  CHAR(30),
         ingreso_mensual         MONEY,
         num_ciudad_trab         SMALLINT,
--         ciudad_trabajo          CHAR(15),
--         delegacion_municipio_trabajo    CHAR(15),
         num_colonia_trabajo         INTEGER,
         num_calle_trabajo           INTEGER,
         numeroext_trab          CHAR(10),
         numeroint_trab          CHAR(10),
         cod_postal_trab         CHAR(5),
         punto_cardinal_trabajo  CHAR(1),
         manzana_trabajo         SMALLINT,
         andador_trabajo         SMALLINT,
         etapa_trabajo           SMALLINT,
         lote_trabajo            SMALLINT,
         edificio_trabajo        SMALLINT,
         entrada_trabajo         SMALLINT,
         departamento_trabajo    CHAR(6),
         complemento_trabajo     CHAR(80),
         entre_calles_trabajo    CHAR(40),
         otros_trabajo           SMALLINT,
         existenciaCC            char(2),
         antig_cliente           SMALLINT,
         sucursal_cliente        CHAR(4),
         tipo_casa               CHAR(2),
         tel_casa                CHAR(13),
         tel_Celular             CHAR(13),
         num_pers_domici         char(3),
         num_pers_trab           char(3),
         rumbo_trab              char(3),
         tel_trabajo             CHAR(13),
         ext_trab                CHAR(5),
         monto_solicitado        DECIMAL(18,2),
         clave_movimiento        char(1),
         num_sucursal_realizo_movimiento    char(4),
         nombre_empleado_realizo_movimiento char(45),
         fecha_movimiento    date,
         numcte_coppel       CHAR(20)
    ) extent size 6004 next size 8232 lock mode row;

--  SELECT fecha_ant INTO fecha_movto FROM bdicred:sd_fechas;
    set isolation to dirty read;
    set lock mode to wait 3;

    SELECT nvl(MAX(fecha_generacion),date(1)) INTO dFechaMax FROM bdicred:sd_cifracontroldirectorioaltasycambios
    where empresa = '001';


    select numcte,'A' Status
        from bdinteg:si_cliente
        where fecha_insert >= dFechaMax
        and fecha_insert <= current
    into temp clientes_alta with no log;

--    select numcte,'A' Status
--    from bdicred:sd_maecred
--    where fecha_apertura >= dFechaMax - 1
--    group by 1,2
--    into temp clientes_alta with no log;

--    create unique index inx_clientes_alta on clientes_alta (numcte) using btree;

    insert into clientes_alta
    select numcte, 'C' Status
        from bdinteg:si_direcciones_actual
        where tipo_dir = '1'
        and fecha_insert >= dFechaMax
        and fecha_insert <= current
        and numcte not in (select numcte from clientes_alta)
        group by 1;

    create unique index inx_clientes_alta on clientes_alta (numcte) using btree;

    update statistics high for table clientes_alta;

    FOREACH   -- Datos del Cliente
        SELECT
            --nvl(mcr.num_credito,' ') AS numcredito,    -- numero de credito ::CHAR(20)
            nvl(cte.numcte,' ') AS numcte,     --  numero de cliente ::date
            nvl(cte.fecha_insert,' ') as fecha,
            nvl(cte.sucursal,' ') AS sucursal,
            rpad(TRIM(cte.apell_paterno),20,' ') AS apellpaterno,       --apellido 1
            rpad(TRIM(cte.apell_materno),20,' ') AS apellmaterno,     --apellido 2
            rpad(TRIM(cte.nombre1),20,' ') AS nombre1,      -- nombre 1
            rpad(TRIM(cte.nombre2),20,' ') AS nombre2,      -- nombre 2
            nvl(ctepf.fecha_nac,date(1)) AS anionac,    -- año de nacimiento
            rpad(TRIM(cte.rfc),13,' ') as rfc, -- rfc
            rpad(TRIM(ctepf.curp),20,' ') as curp, -- curp
            rpad(TRIM(ctepf.sexo),1,' ') as sexo, -- sexo
            rpad(TRIM(ctepf.estado_civil),2,' ') as edocivil, -- estado civil
            rpad(TRIM(cte.apell_casada),26,' ') as apellcasada, -- apellido de casada
            nvl(ctepf.dependientes,' ') as dependientes, --numero de dependientes
            rpad(TRIM(nac.descripcion),15,' ') as nacionalidad, -- nacionalidad
--            rpad(TRIM(puest.descripcion),30,' ') as puesto, -- descripcion puesto
            lpad(TRIM(actesp.descripcion),45,' ') as actividad, --actividad o giro de negocio
            rpad(TRIM(tipoidentif.descripcion),40,' ') as tipoidentificacion, -- tipo de identificación
            rpad(TRIM(ctepf.numidentifi),30,' ') as numidentificacion, --numero de identificación
--            rpad(TRIM(ctepf.email),60,' ') as email, -- correo electronico--------------------------se cambia por si_correos
            rpad(TRIM(co.correo_elec),60,' ') as correo_elec ,
			nvl(TRIM(ctepf.escolaridad),' ') AS escolaridad, -- escolaridad del cliente
--            rpad(TRIM(edo.nombre),30,' ') as estado, -- descripcion del estado
            rpad(TRIM(dir.estado),30,' ') as estado, -- numero estado
            lpad(dir.numerociudad,4,'0') AS numciudad, -- numero cd
--            rpad(TRIM(ciudad.nombreciudad),25,' ') as ciudad, -- descripcion de la ciudad
--            rpad(TRIM(ciudad.nombreciudad),25,' ') AS municipio,  -- descripcion municipio
            lpad(dir.numerocolonia,4,'0') AS numcolonia,  -- numero de colonia de cliente
            lpad(dir.numerocalle,6,'0') AS numcalle,  -- numero de calle de cliente
            TRIM(dir.numeroextcalle) AS numextcalle,   -- numero exterior
            TRIM(dir.numerointcalle) AS numintecalle,  -- numero interior
            lpad(TRIM(dir.cod_postal),5,'0') AS cod_postal,     -- codigo postal
            rpad(TRIM(dir.puntocardinal),1,' ') AS puntocardinal,   -- punto cardinal
            lpad(dir.manzana,5,'0') AS manzana,     -- manzana
            lpad(dir.andador,5,'0') AS andador,     -- andador
            lpad(dir.etapa,5,'0') AS etapa,     --etapa
            lpad(dir.lote,5,'0') AS lote,       -- lote
            lpad(dir.edificio,5,'0') AS edificio,   --edificio
            lpad(dir.entrada,5,'0') AS entrada,   -- entrada
            rpad(TRIM(dir.departamento),6,' ') AS departamento,     -- departamento
            rpad(TRIM(dir.observaciones),80,' ') AS complemento,  --   complemento
            rpad(TRIM(dir.entre_calles),40,' ') AS entre_calles,    -- entre calles
            lpad(dir.otros,2,'0') AS otros,     -- otros
            rpad(TRIM(cte.sector),2,' ') AS sector, -- sector
            nvl(TRIM(ctepf.actividadogiro),' ') AS ActividadDelCte, -- actividad del cliente
--            nvl(rpad(TRIM(ing.nombre_empresa),25,' '),' ') AS lugartrabajo,    -- lugar de trabajo
--            nvl(ing.ingreso_mensual,' ') AS ingresomensual,     -- ingreso mensual
              --nvl(rpad(TRIM(ctepf.habita_en),2,'0'),' ') AS tipo_casa,
            nvl(TRIM(ctepf.habita_en),'') AS tipo_casa,
--            nvl(rpad(TRIM(dir.telefono1),13,' '),' ') AS tel_casa,   -- telefono casa---------------se cambia por si_telefonos
--            nvl(rpad(TRIM(dir.telefono2),13,' '),' ') AS celular,    -- celular ---------------se cambia por si_telefonos
			nvl(rpad(TRIM(tel1.telefono),13,' '),' ') AS tel_casa,   -- telefono casa
			nvl(rpad(TRIM(tel2.telefono),13,' '),' ') AS celular,    -- celular
			nvl(dir.fecha_insert,' ') AS fecha_insert,
            nvl(rpad(TRIM(dir.user_insert),8,' '),' ') AS empleado_inserto,
            ( case when bdinteg:val_num(nvl(cte.numcte_ref,'')) then cte.numcte_ref else '' end)  AS cliente_coppel
            INTO  --cNumCredito ,
                cNumCliente, dFechaInsertCte, cSucursalCliente, cApellido1,
                cApellido2, cNombre1, cNombre2, dFechaNac, cRfc, cCurp, cSexo, cEdoCivil, cApellidoCasada,
                sNumDependientes, cNacionalidad, --cPuesto,
                cActividad, cTipoIdentificacion, cNumIdentificacion, cEmail,
--                cEscolaridad, cNumEstado, sNumCiudad , cNomCiudad, cNomMunicipio, iNumColonia, iNumCalle, cNumExterior,
                cEscolaridad, cNumEstado, sNumCiudad , iNumColonia, iNumCalle, cNumExterior,
                cNumInterior, cCodPostal, cPuntoCardinal, iManzana, iAndador, iEtapa, iLote, iEdificio, iEntrada,
                cDepartamento, cComplemento, cEntreCalles, sOtros, cSector, cActividadCte, --cLugarTrabajo, mIngresoMensual,
                cTipoCasa, cTelefonoCasa, cCelular,dFechaInsert,cEmpleadoInsert,cNumCte_Coppel
            from bdinteg:si_cliente cte
                INNER JOIN clientes_alta cte_paso ON (cte.numcte = cte_paso.numcte)
                INNER JOIN bdinteg:si_direcciones_actual dir ON (dir.numcte = cte.numcte and dir.tipo_dir = '1')                                                               
--                                                               AND dir.fecha_insert > dFechaMax )
                LEFT OUTER JOIN bdinteg:si_actesp actesp ON (actesp.empresa= cte.empresa and actesp.codigo=cte.actividad_esp)
--                LEFT OUTER JOIN bdinteg:si_catciudades ciudad ON (ciudad.numerociudad = dir.numerociudad)
--                LEFT OUTER JOIN bdinteg:si_estados edo ON (edo.estado = dir.estado)
                LEFT OUTER JOIN bdinteg:si_ctepf ctepf ON (ctepf.numcte = cte.numcte)
                LEFT OUTER JOIN bdinteg:si_tipoidentif tipoidentif ON (tipoidentif.codidentif=ctepf.codidentifi)
                LEFT OUTER JOIN bdinteg:si_nacion nac ON (nac.nacion=ctepf.nacionalidad)
				left outer join bdinteg:si_correos co on (co.empresa = cte.empresa and co.numcte = cte.numcte)
				left outer join bdinteg:si_telefonos tel1 on (tel1.empresa = cte.empresa and tel1.numcte = cte.numcte and tel1.tipo_tel = 1
															 and tel1.secuencia = (select max(secuencia) from bdinteg:si_telefonos
																					where numcte =tel1.numcte and tipo_tel =1))
				left outer join bdinteg:si_telefonos tel2 on(tel2.empresa = cte.empresa and tel2.numcte = cte.numcte and tel2.tipo_tel = 2
															and tel2.secuencia = (select max(secuencia) from bdinteg:si_telefonos
																					where numcte =tel2.numcte and tipo_tel =2))
--                where sucursal = '0002'
--                where mcr.empresa='001'
--                AND mcr.status_cred in ('AA','BA','BT')
			
			
        -- determina si es credito

        LET cNumCredito = null;
        LET sElementoRes = 0;
        LET cDescripcion = '';
        LET sElemResTrabajo = 0;
        LET cDescripPermTrabajo = '';
        LET CreditoAutoriza = 0.00;
        LET cExisteCC = '';

        select max(num_credito)
            into cNumCredito
            from bdicred:sd_maecred
            where empresa = '001'
            and numcte = cNumCliente;

        if ( cNumCredito is not null) then
        --  Se obtiene el elemento respondido en la pregunta de tiempo de residencia
            SELECT elemento
                INTO sElementoRes
                FROM bdisolic:ss_detalle_scoring
                WHERE num_solicitud= cNumCredito
                AND seccion=2 AND grupo=6;

        -- Se obtiene la descripcion del elemento respondido en la pregunta tiempo de residencia
            SELECT descripcion
                INTO cDescripcion
                FROM bdisolic:ss_scoring_element
                WHERE seccion=2
                AND grupo=6
                AND elemento= sElementoRes;

        --  Se obtiene el elemento respondido en la pregunta Tiempo de permanencia en la ocupacion actual
            SELECT elemento
                INTO sElemResTrabajo
                FROM bdisolic:ss_detalle_scoring
                WHERE num_solicitud= cNumCredito
                AND seccion=2 AND grupo=8 ;

        -- Se obtiene la descripcion del elemento respondido  en la pregunta Tiempo de permanencia en la ocupacion actual
            SELECT descripcion
                INTO cDescripPermTrabajo
                FROM bdisolic:ss_scoring_element
                WHERE seccion=2
                AND grupo=8
                AND elemento= sElemResTrabajo;

                      -- Trae la linea de credito autorizada
            SELECT monto_solicitado
                INTO CreditoAutoriza
                FROM bdisolic:ss_solicitudes
                WHERE empresa='001'
                AND num_solicitud= cNumCredito;

            SELECT resscorfin.evalua_cc,meses_historia --, ingreso_mensual
                INTO cEvaluacionCC,cAntigCliente --, mIngresoMensual
                FROM bdisolic:ss_resum_scor_fin resscorfin
                WHERE empresa= '001'
                AND resscorfin.num_solicitud= cNumCredito;

            IF TRIM(cEvaluacionCC) = '0' OR TRIM(cEvaluacionCC)= '1' THEN
                LET cExisteCC= 'SI';
            ElSE
                LET cExisteCC= 'NO';
            END IF;
        end if;
        
        --- Informacion del Trabajo
        SELECT limit 1
            lpad(dir.numerociudad,4,'0') AS numciudad_trab, -- numero cd  trabajo
--            rpad(TRIM(ciudad.nombreciudad),25,' ') AS ciudad_trab, -- descripcion de la ciudad trabajo
--            rpad(TRIM(ciudad.nombreciudad),25,' ') AS municipio_trab,  -- descripcion municipio trabajo
            lpad(dir.numerocolonia,4,'0') AS numcolonia_trab,  -- numero de colonia de cliente trabajo
            lpad(dir.numerocalle,6,'0') AS numcalle_trab,  -- numero de calle del trabajo
            TRIM(dir.numeroextcalle) AS numextcalle_trab,   -- numero exterior  trabajo
            TRIM(dir.numerointcalle) AS numintecalle_trab,  -- numero interior  trabajo
            lpad(TRIM(dir.cod_postal),5,'0') AS cod_postal_trab,     -- codigo postal trabajo
            rpad(TRIM(dir.puntocardinal),1,' ') AS puntocardinal_trab,   -- punto cardinal trabajo
            lpad(dir.manzana,5,'0') AS manzana_trab,     -- manzana  trabajo
            lpad(dir.andador,5,'0') AS andador_trab,     -- andador trabajo
            lpad(dir.etapa,5,'0') AS etapa_trab,     --etapa trabajo
            lpad(dir.lote,5,'0') AS lote_trab,       -- lote trabajo
            lpad(dir.edificio,5,'0') AS edificio_trab,   --edificio trabajo
            lpad(dir.entrada,5,'0') AS entrada_trab,   -- entrada trabajo
            rpad(TRIM(dir.departamento),6,' ') AS departamento_trab,     -- departamento trabajo
            rpad(TRIM(dir.observaciones),80,' ') AS complemento_trab,  --   complemento trabajo
            rpad(TRIM(dir.entre_calles),40,' ') AS entre_calles_trab,    -- entre calles trabajo
            lpad(dir.otros,2,'0') AS otros,  -- otros trabajo
--            nvl(rpad(TRIM(dir.telefono3),13,' '),' ')  AS tel_trabajo_trab, -- telefono trabajo---------------se cambia por si_telefonos
--            nvl(rpad(TRIM(dir.extension),5,' '),' ')  AS ext_trabajo_trab -- extension trabajo---------------se cambia por si_telefonos
            nvl(rpad(TRIM(tel3.telefono),13,' '),' ')  AS tel_trabajo_trab, -- telefono trabajo
			nvl(rpad(TRIM(tel3.extension),5,' '),' ')  AS ext_trabajo_trab -- extension trabajo
--            INTO sNumCiudadTrab, cNomCiudadTrab, cNomMunicipioTrab, iNumColoniaTrab, iNumCalleTrab,  cNumExteriorTrab,
            INTO sNumCiudadTrab, iNumColoniaTrab, iNumCalleTrab,  cNumExteriorTrab,
                cNumInteriorTrab, cCodPostalTrab, cPuntoCardinalTrab, iManzanaTrab, iAndadorTrab, iEtapaTrab, iLoteTrab, iEdificioTrab,
                iEntradaTrab, cDepartamentoTrab, cComplementoTrab, cEntreCallesTrab, sOtrosTrab,cTelefonoTrabajo, cExtensionTrabajo
            FROM  bdinteg:si_cliente cte
            LEFT OUTER JOIN bdinteg:si_direcciones_actual dir ON (dir.numcte = cNumCliente AND dir.tipo_dir = '2')
			left outer join bdinteg:si_telefonos tel3 on (tel3.empresa = cte.empresa and tel3.numcte = cte.numcte and tel3.tipo_tel = 3
															and tel3.secuencia = (select max(secuencia) from bdinteg:si_telefonos
																					where numcte =tel3.numcte and tipo_tel =3))
				
--            LEFT OUTER JOIN bdinteg:si_catciudades ciudad ON (ciudad.numerociudad = dir.numerociudad)
            WHERE cte.numcte= cNumCliente;


            -- Informacion de empleo.
        SELECT a.descripcion, b.nombre_empresa,b.ingreso_mensual   INTO cPuesto, cLugarTrabajo, mIngresoMensual
            FROM bdinteg:si_ingresos b
            LEFT OUTER JOIN bdinteg:si_puestos a ON (a.puesto=b.puesto)
            WHERE numcte=cNumCliente
            AND sec_ingreso=(select max(sec_ingreso) from bdinteg:si_ingresos b1 where b1.numcte=cNumCliente and b1.tipo_ingreso = 'T');


            -- Informacion de situacion especial.
        SELECT nvl(ctessit.situacion,' '), nvl(ctessit.causa,' '), nvl(ctessit.fechamovto,' ')
            INTO cSituacion, sCausa, dFechaMovtoSit
            FROM bdisitesp:se_ctessitespcte ctessit
            WHERE ctessit.numcte=cNumCliente;
            --  Condiciones para Generar Informacion Altas y Cambios.
        IF dFechaInsertCte =  dFechaInsert  THEN
            LET cClaveMov= 'A';
            LET iContadorAltas= iContadorAltas +1 ;
            LET Ac= '0';
        ELSE
            LET cClaveMov= 'C';
            LET iContadorCambios= iContadorCambios +1 ;
            LET Cc= '0';
        END IF;

            -- Se obtiene el numero de sucursal y
        SELECT nvl(nombre,' '), nvl(sucursal,' ')
            INTO cNomEjecutivo, cSucursalEjecutivo
            FROM bdinteg:si_ejecut
            WHERE ejecutivo= cEmpleadoInsert;

           --- Se inserta la informacion en la tabla cb_directorioctesbancoppel .
        INSERT INTO sd_directorioaltasycambios (empresa, numctebancoppel,apell_paterno,apell_materno,nombre1,nombre2,fecha_nac,rfc,curp,sexo,estado_civil,apell_casada,
                    num_dependientes,nacionalidad,ocupacion_oficio,actividad_gironegocio,identificacion,num_identificacion,correo_electronico,
--                    escolaridad,estado,num_ciudad,ciudad,delegacion_municipio,colonia,calle,numeroext,numeroint,cod_postal,punto_cardinal,
                    escolaridad,num_estado,num_ciudad,num_colonia,num_calle,numeroext,numeroint,cod_postal,punto_cardinal,
                    manzana,andador,etapa,lote,edificio,entrada,departamento,complemento,entre_calles,antiguedad_domicilio,otros,
                    situacion_esp,fecha_sit_esp,causa_sit_esp,sector,actividad_economica,empresa_labora,antiguedad_trabajo,puesto,
--                    ingreso_mensual,num_ciudad_trab,ciudad_trabajo,delegacion_municipio_trabajo,colonia_trabajo,calle_trabajo,numeroext_trab,
                    ingreso_mensual,num_ciudad_trab,num_colonia_trabajo,num_calle_trabajo,numeroext_trab,
                    numeroint_trab,cod_postal_trab,punto_cardinal_trabajo,manzana_trabajo,andador_trabajo,etapa_trabajo,lote_trabajo,
                    edificio_trabajo,entrada_trabajo,departamento_trabajo,complemento_trabajo,entre_calles_trabajo,otros_trabajo,existenciaCC,
                    antig_cliente,sucursal_cliente,tipo_casa,tel_casa,tel_Celular,num_pers_domici,num_pers_trab,rumbo_trab,tel_trabajo,ext_trab,
                    monto_solicitado,clave_movimiento,num_sucursal_realizo_movimiento,nombre_empleado_realizo_movimiento,fecha_movimiento,numcte_coppel)

            VALUES ('001', nvl ( cNumCliente,' ' ),
                    nvl ( replace ( replace( cApellido1 , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cApellido2 , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cNombre1 , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cNombre2 , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( dFechaNac, date(1) ),
                    nvl ( replace ( replace( cRfc , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cCurp , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( cSexo,' ' ),
                    nvl ( cEdoCivil,' ' ),
                    nvl ( replace ( replace( cApellidoCasada , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( sNumDependientes, 0 ),
                    nvl ( replace ( replace( cNacionalidad , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cPuesto , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cActividad , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cTipoIdentificacion , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cNumIdentificacion , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace(cEmail, '|' , '' ), '\' , ' ' ), ' ' ),
                    nvl ( cEscolaridad,' ' ),
                    nvl ( replace ( replace( cNumEstado , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( sNumCiudad, 0 ),
--                        nvl ( replace ( replace( cNomCiudad , '|' , ' ' ), '\' , ' ' ), ' ' ),
--                        nvl ( replace ( replace( cNomMunicipio , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( iNumColonia, 0 ),
                    nvl ( iNumCalle, 0 ),
                    nvl ( replace ( replace( cNumExterior , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cNumInterior , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cCodPostal , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( cPuntoCardinal,' ' ),
                    nvl ( iManzana, 0 ),
                    nvl ( iAndador, 0 ),
                    nvl ( iEtapa, 0 ),
                    nvl ( iLote, 0 ),
                    nvl ( iEdificio, 0 ),
                    nvl ( iEntrada, 0 ),
                    nvl ( replace ( replace( cDepartamento , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cComplemento , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cEntreCalles , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cDescripcion , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( sOtros, 0 ),
                    nvl ( replace ( replace( cSituacion , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( dFechaMovtoSit, date(1) ),
                    nvl ( sCausa, 0 ),
                    nvl ( replace ( replace( cSector , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cActividadCte , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cLugarTrabajo , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cDescripPermTrabajo , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cPuesto , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( mIngresoMensual, 0 ),
                    nvl ( sNumCiudadTrab, 0 ),
--                    nvl ( replace ( replace( cNomCiudadTrab , '|' , ' ' ), '\' , ' ' ), ' ' ),
--                    nvl ( replace ( replace( cNomMunicipioTrab , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( iNumColoniaTrab, 0 ),
                    nvl ( iNumCalleTrab, 0 ),
                    nvl ( replace ( replace( cNumExteriorTrab , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cNumInteriorTrab , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cCodPostalTrab , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cPuntoCardinalTrab , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( iManzanaTrab, 0 ),
                    nvl ( iAndadorTrab, 0 ),
                    nvl ( iEtapaTrab, 0 ),
                    nvl ( iLoteTrab, 0 ),
                    nvl ( iEdificioTrab, 0 ),
                    nvl ( iEntradaTrab, 0 ),
                    nvl ( replace ( replace( cDepartamentoTrab , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cComplementoTrab , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cEntreCallesTrab , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( sOtrosTrab, 0 ),
                    nvl ( replace ( replace( cExisteCC , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( cAntigCliente, 0 ),
                    nvl ( replace ( replace( cSucursalCliente , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cTipoCasa , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cTelefonoCasa , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cCelular , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cnumpersdomici , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cnumperstrab , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( Crumbotrab , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cTelefonoTrabajo , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cExtensionTrabajo , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( CreditoAutoriza, 0 ),
                    nvl ( replace ( replace( cClaveMov , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cSucursalEjecutivo , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    nvl ( replace ( replace( cNomEjecutivo , '|' , ' ' ), '\' , ' ' ), ' ' ),
                    current,cNumCte_Coppel );

        LET iContadorRegistros= iContadorRegistros+1;
        LET cNumCte_Coppel= "";
    End ForEach;

    update statistics medium for table bdicred:sd_directorioaltasycambios;

    LET cCteFinal=cNumCliente;

    -- insertar tabla si_cifracontroldirectoriocte de cifras.
    INSERT INTO  sd_cifracontroldirectorioaltasycambios (empresa,num_registros,num_altas,num_cambios,fecha_generacion)
    VALUES ('001', iContadorRegistros, iContadorAltas,iContadorCambios,current);

    -- para Generar el archivo de Salida.
    LET cSql = 'echo "UNLOAD TO ' || '''/resplogifx/archivoscartera/DirectorioCtesBancoppelRegistros.unl''' || ' DELIMITER ' || '''|'''  ||
                   ' SELECT * FROM bdicred:sd_directorioaltasycambios d ' ||
                   ' WHERE d.fecha_movimiento = current::date  ' ||
                   ' " > /resplogifx/archivoscartera/DirectorioCtesBancoppelQuerys.sql';
    SYSTEM cSql;

    LET cSql = '';
    LET cSql = 'dbaccess bdicred /resplogifx/archivoscartera/DirectorioCtesBancoppelQuerys.sql';
    SYSTEM cSql;

    LET cSql = '';
    LET cSql = "sed 's/|$//g' /resplogifx/archivoscartera/DirectorioCtesBancoppelRegistros.unl > /resplogifx/archivoscartera/paso001.txt ";
    SYSTEM cSql;

    LET cSql = '';
    LET cSql = "sed 's/" || '"' ||  "//g' /resplogifx/archivoscartera/paso001.txt > /resplogifx/archivoscartera/" || trim(cNombreArchivo1);
    SYSTEM cSql;

    LET cSql = '';
    LET cSql = "rm /resplogifx/archivoscartera/DirectorioCtesBancoppelRegistros.unl /resplogifx/archivoscartera/DirectorioCtesBancoppelQuerys.sql /resplogifx/archivoscartera/paso001.txt";
    SYSTEM cSql;

    -- para Generar el archvio de Cifras.
    LET cSql = '';
    LET cSql = 'echo "UNLOAD TO ' || '''/resplogifx/archivoscartera/DirectorioCifrasControlRegistros.unl''' || ' DELIMITER ' || '''|'''  ||
                ' SELECT * FROM bdicred:sd_cifracontroldirectorioaltasycambios c ' ||
                ' WHERE c.fecha_generacion = current::date  ' ||
                ' " > /resplogifx/archivoscartera/DirectorioCifrasControlQuerys.sql';
    SYSTEM cSql;

    LET cSql = '';
    LET cSql = 'dbaccess bdicred /resplogifx/archivoscartera/DirectorioCifrasControlQuerys.sql';
    SYSTEM cSql;

    LET cSql = '';
    LET cSql = "sed 's/|$//g' /resplogifx/archivoscartera/DirectorioCifrasControlRegistros.unl > /resplogifx/archivoscartera/" || trim(cNombreArchivo2);
    SYSTEM cSql;

    let cSql = '';
    LET cSql = "rm /resplogifx/archivoscartera/DirectorioCifrasControlRegistros.unl /resplogifx/archivoscartera/DirectorioCifrasControlQuerys.sql";
    SYSTEM cSql;

    RETURN P_COD_RET;

END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_telactualizartelefonoscliente()
RETURNING CHAR(6), INTEGER;
-- execute PROCEDURE "informix".sp_telactualizartelefonoscliente();
	--Declaracion de Variables  Si_Direcciones
	DEFINE   iNumcte        	CHAR(20);
	DEFINE   iSecuencia   		INTEGER;
	DEFINE   iTipo_dir      	CHAR(1);
	DEFINE   cCalle         	CHAR(40);
	DEFINE   cColonia      		CHAR(60);
	DEFINE   cEntre_calles  	CHAR(40);
	DEFINE   cPais          	CHAR(3);
	DEFINE   cEstado        	CHAR(2);
	DEFINE   cCiudad        	CHAR(3);
	DEFINE   cMunicipio     	CHAR(5);
	DEFINE   cCod_postal    	CHAR(5);
	DEFINE   cApart_postal  	CHAR(11);
	DEFINE   cTipo_telef1   	CHAR(1);
	DEFINE   cTelefono1     	CHAR(13);
	DEFINE   cTipo_telef2   	CHAR(1);
	DEFINE   cTelefono2     	CHAR(13);
	DEFINE   cTipo_telef3      	CHAR(1);
	DEFINE   cTelefono3        	CHAR(13);
	DEFINE   iExtension         CHAR(5);
	DEFINE   cEstado_inegi      CHAR(2);
	DEFINE   cMunicipio_inegi   CHAR(3);
	DEFINE   cLocalidad_inegi   CHAR(4);
	DEFINE   cNumerociudad     	smallint;
	DEFINE   cNumeroextcalle    CHAR(10);
	DEFINE   cNumerointcalle    CHAR(10);
	DEFINE   cDepartamento      CHAR(6);
	DEFINE   cNumerocalle       CHAR(10);
	DEFINE   cNumerocolonia     INTEGER;
	DEFINE   cPuntocardinal     CHAR(1);
	DEFINE   cUnidadhabitac     CHAR(1);
	DEFINE   iManzana           smallint;
	DEFINE   iOtros             smallint;
	DEFINE   iAndador           smallint;
	DEFINE   iEtapa             smallint;
	DEFINE   iLote              smallint;
	DEFINE   iEdIFicio          smallint;
	DEFINE   iEntrada           smallint;
	DEFINE   cObservaciones    	CHAR(80);
	DEFINE   cUser_insert       CHAR(8);
	DEFINE   dFecha_insert      DATE;

   --Declaracion  de Variables CB_GESTIONES_TELEFONICAS
	DEFINE   cNum_Sol       CHAR(20); 
	DEFINE   cNumcTel       CHAR(20);
	DEFINE   cTel           CHAR(10);
	DEFINE   cTipo_tel      CHAR(10);
	DEFINE   sSecuencia     INTEGER;

-- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- 
	DEFINE  dFechaHoy	       	DATE;
	DEFINE  MAXSecuencia        CHAR(10); 
	DEFINE  MAXSecuencia2      	CHAR(10); 
	DEFINE  iCont			    INTEGER;
	DEFINE  cCodret			   	CHAR(6);
	DEFINE  cCodret1		  	CHAR(6);
	DEFINE  iSqlErr		  		INTEGER;
	DEFINE  iContador           INTEGER;
	
	DEFINE  cCodret2      CHAR(6);
	DEFINE  cBandera1     CHAR(1);  
	DEFINE  cBandera2     CHAR(1);
	DEFINE  cBandera3     CHAR(1);
	
	DEFINE  cCodret3      CHAR(6);

	LET iCont 		= 0;
	LET cCodret 	= "000000";
	LET iSqlErr	    = 0;
    LET  iContador  = 0;

-- SET DEBUG FILE TO  "sp_telActualizarTelefonosCliente.out";
-- TRACE ON;
 
BEGIN
	ON EXCEPTION SET iSqlErr
		IF iSqlErr != 0 THEN
			LET cCodret = iSqlErr;
			RETURN cCodret,iContador;
		END IF;
	END EXCEPTION;

	SET ISOLATION TO DIRTY READ;
	
	SELECT fecha_hoy 
	INTO dFechaHoy
	FROM bdicred:sd_fechas
	WHERE empresa = '001';

	FOREACH

		SELECT num_solicitud, numcte, telefono, tipo_telefono ,secuencia
		INTO cNum_sol, cNumcTel, cTel, cTipo_tel ,sSecuencia
		FROM Bdicobranza:cb_gestion_telefonica
		WHERE status = 'NP'

		--Verifica Existe el Cliente en Bdinteg:si_direcciones
		IF NOT EXISTS ( SELECT DISTINCT numcte  FROM Bdinteg:si_direcciones WHERE  numcte = cNumcTel ) THEN
			LET iCont = 2;
			UPDATE Bdicobranza:cb_gestion_telefonica SET status = 'ER'  WHERE num_solicitud = cNum_sol and numcte = cNumcTel and secuencia = sSecuencia;			
			CONTINUE FOREACH;
		END IF;
		
		--LET iContador = iContador + 1;
		
		-- BANDERA PARA LA VALIDACION DE LA EJECUCION DEL PROCESO
		LET iCont = 1;

		IF cTipo_tel  = 'P'  THEN
		
			SELECT MAX(secuencia)
			INTO MAXSecuencia
			FROM Bdinteg:si_direcciones
			WHERE numcte =  cNumcTel     --'000018538' 
			AND tipo_dir = 1;

			SELECT numcte, secuencia, tipo_dir, calle, colonia, municipio, entre_calles, pais, estado, ciudad, cod_postal,
				   /*tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension,*/ estado_inegi, municipio_inegi,
			       localidad_inegi, numerociudad, numeroextcalle, numerointcalle, departamento, numerocalle, numerocolonia, 
				   puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, entrada, observaciones,
				   user_insert, fecha_insert
			INTO iNumcte,iSecuencia, iTipo_dir,cCalle, cColonia, cMunicipio, cEntre_calles, cPais , cEstado, cCiudad, cCod_postal,
			     /*cTipo_telef1, cTelefono1, cTipo_telef2, cTelefono2, cTipo_telef3, cTelefono3, iExtension,*/ cEstado_inegi, cMunicipio_inegi,
				 cLocalidad_inegi, cNumerociudad, cNumeroextcalle, cNumerointcalle, cDepartamento, cNumerocalle, cNumerocolonia,
				 cPuntocardinal, cUnidadhabitac, iManzana, iOtros , iAndador, iEtapa, iLote, iEdificio, iEntrada, cObservaciones,
				 cUser_insert, dFecha_insert
			FROM Bdinteg:si_direcciones
			WHERE numcte = cNumcTel         --'000018538' 
			AND secuencia = MAXSecuencia   --168 
			AND tipo_dir = 1;
			
			select  tipo_tel,telefono 
			into  cTipo_telef1, cTelefono1
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 1 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 1);
										
			select  tipo_tel,telefono 
			into  cTipo_telef2, cTelefono2
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 2 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 2);
												
			select  tipo_tel,telefono ,extension
			into  cTipo_telef3, cTelefono3, iExtension
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 3 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 3);
		
			EXECUTE PROCEDURE Bdinteg:direcciones('001', 'A', iNumcte, iSecuencia, iTipo_dir, cCalle, cColonia, cMunicipio,
												  cEntre_calles, cPais, cEstado, cCiudad, cCod_postal, 'P', cTel, cTipo_telef2,
												  cTelefono2, cTipo_telef3, cTelefono3, iExtension, cEstado_inegi, cMunicipio_inegi,
												  cLocalidad_inegi, cNumerociudad, cNumeroextcalle, cNumerointcalle, cDepartamento,
												  cNumerocalle, cNumerocolonia, cPuntocardinal, cUnidadhabitac, iManzana, iOtros,
												  iAndador, iEtapa, iLote, iEdificio, iEntrada, cObservaciones, cUser_insert, dFecha_insert, null)
			INTO cCodret1;
			IF cCodret1 = '000' then
				EXECUTE PROCEDURE bdinteg:sp_validatelefono('001',cTel,cTelefono2,cTelefono3)
				INTO cCodret2, cBandera1,cBandera2,cBandera3;
				EXECUTE PROCEDURE bdinteg:sp_actvalidacioncofetel('001',iNumcte,cBandera1,cBandera2,cBandera3,iTipo_dir,1)
				INTO cCodret3;
			ELSE 
				LET iCont = 3;
            END IF;
			
		ELIF  cTipo_tel  = 'C'  THEN
		
			SELECT MAX(secuencia)
			INTO MAXSecuencia
			FROM Bdinteg:si_direcciones
			WHERE numcte =  cNumcTel     --'000018538' 
			AND tipo_dir = 1;

			SELECT numcte, secuencia, tipo_dir, calle, colonia, municipio, entre_calles, pais, estado, ciudad, cod_postal,
				/*   tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension,*/ estado_inegi, municipio_inegi,
			       localidad_inegi, numerociudad, numeroextcalle, numerointcalle, departamento, numerocalle, numerocolonia, 
				   puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, entrada, observaciones,
				   user_insert, fecha_insert
			INTO iNumcte,iSecuencia, iTipo_dir,cCalle, cColonia, cMunicipio, cEntre_calles, cPais , cEstado, cCiudad, cCod_postal,
			    /* cTipo_telef1, cTelefono1, cTipo_telef2, cTelefono2, cTipo_telef3, cTelefono3, iExtension,*/ cEstado_inegi, cMunicipio_inegi,
				 cLocalidad_inegi, cNumerociudad, cNumeroextcalle, cNumerointcalle, cDepartamento, cNumerocalle, cNumerocolonia,
				 cPuntocardinal, cUnidadhabitac, iManzana, iOtros , iAndador, iEtapa, iLote, iEdIFicio, iEntrada, cObservaciones,
				 cUser_insert, dFecha_insert
			FROM Bdinteg:si_direcciones
			WHERE numcte = cNumcTel         --'000018538' 
			AND secuencia = MAXSecuencia   --168 
			AND tipo_dir = 1;
			
				select  tipo_tel,telefono 
			into  cTipo_telef1, cTelefono1
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 1 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 1);
										
			select  tipo_tel,telefono 
			into  cTipo_telef2, cTelefono2
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 2 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 2);
												
			select  tipo_tel,telefono ,extension
			into  cTipo_telef3, cTelefono3, iExtension
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 3 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 3);
													
			EXECUTE PROCEDURE Bdinteg:direcciones('001' , 'A' ,iNumcte,  iSecuencia,   iTipo_dir, cCalle, cColonia, cMunicipio,
                                        		  cEntre_calles ,cPais  ,cEstado  ,cCiudad      ,cCod_postal , cTipo_telef1 ,cTelefono1,
												  'C' ,  cTel , cTipo_telef3 , cTelefono3 ,iExtension   ,cEstado_inegi     ,cMunicipio_inegi,
												  cLocalidad_inegi , cNumerociudad ,cNumeroextcalle ,cNumerointcalle  ,cDepartamento ,cNumerocalle,
												  cNumerocolonia ,cPuntocardinal ,cUnidadhabitac ,iManzana ,iOtros        ,iAndador   ,iEtapa,
												  iLote   ,iEdIFicio ,iEntrada   ,cObservaciones  ,cUser_insert   ,dFecha_insert ,null)
			INTO cCodret1;
            IF cCodret1 = '000' THEN		
				EXECUTE PROCEDURE bdinteg:sp_validatelefono('001',cTelefono1,cTel,cTelefono3)
				INTO cCodret2, cBandera1,cBandera2,cBandera3;
				EXECUTE PROCEDURE bdinteg:sp_actvalidacioncofetel('001',iNumcte,cBandera1,cBandera2,cBandera3,iTipo_dir,1)
				INTO cCodret3;
			ELSE
			   LET iCont = 3;
			END IF;
		ELIF  cTipo_tel  = 'A'  THEN
		
			SELECT MAX(secuencia)
			INTO MAXSecuencia
			FROM Bdinteg:si_direcciones
			WHERE numcte =  cNumcTel     --'000018538' 
			AND tipo_dir = 1;

			SELECT numcte, secuencia, tipo_dir, calle, colonia, municipio, entre_calles, pais, estado, ciudad, cod_postal,
				 /*  tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension,*/ estado_inegi, municipio_inegi,
			       localidad_inegi, numerociudad, numeroextcalle, numerointcalle, departamento, numerocalle, numerocolonia, 
				   puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, entrada, observaciones,
				   user_insert, fecha_insert
			INTO iNumcte,iSecuencia, iTipo_dir,cCalle, cColonia, cMunicipio, cEntre_calles, cPais , cEstado, cCiudad, cCod_postal,
			     /*cTipo_telef1, cTelefono1, cTipo_telef2, cTelefono2, cTipo_telef3, cTelefono3, iExtension,*/ cEstado_inegi, cMunicipio_inegi,
				 cLocalidad_inegi, cNumerociudad, cNumeroextcalle, cNumerointcalle, cDepartamento, cNumerocalle, cNumerocolonia,
				 cPuntocardinal, cUnidadhabitac, iManzana, iOtros , iAndador, iEtapa, iLote, iEdificio, iEntrada, cObservaciones,
				 cUser_insert, dFecha_insert
			FROM Bdinteg:si_direcciones
			WHERE numcte = cNumcTel         --'000018538' 
			AND secuencia = MAXSecuencia    --168 
			AND tipo_dir = 1;	
		
			select  tipo_tel,telefono 
			into  cTipo_telef1, cTelefono1
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 1 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 1);
										
			select  tipo_tel,telefono 
			into  cTipo_telef2, cTelefono2
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 2 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 2);
												
			select  tipo_tel,telefono ,extension
			into  cTipo_telef3, cTelefono3, iExtension
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 3 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 3);
		    
		
			IF cTelefono1  =  ''  THEN 
				EXECUTE PROCEDURE Bdinteg:direcciones('001' , 'A' , iNumcte,  iSecuencia,   iTipo_dir, cCalle, cColonia, cMunicipio,
                                 				      cEntre_calles ,cPais  ,cEstado  ,cCiudad      ,cCod_postal , 'P' ,cTel ,cTipo_telef2 ,
													  cTelefono2 ,cTipo_telef3 , cTelefono3 ,iExtension   ,cEstado_inegi     ,cMunicipio_inegi,
													  cLocalidad_inegi , cNumerociudad ,cNumeroextcalle ,cNumerointcalle  ,cDepartamento,
													  cNumerocalle ,cNumerocolonia ,cPuntocardinal ,cUnidadhabitac ,iManzana ,iOtros,
													  iAndador ,iEtapa ,iLote,iEdIFicio,iEntrada,cObservaciones,cUser_insert,dFecha_insert  ,null)
				INTO cCodret1;
				
            IF cCodret1 ='000' THEN
				EXECUTE PROCEDURE bdinteg:sp_validatelefono('001',cTel,cTelefono2,cTelefono3)
				INTO cCodret2, cBandera1,cBandera2,cBandera3;
				EXECUTE PROCEDURE bdinteg:sp_actvalidacioncofetel('001',iNumcte,cBandera1,cBandera2,cBandera3,iTipo_dir,1)
				INTO cCodret3;
		    ELSE
			   LET iCont = 3;
			END IF;

			ELIF  cTelefono2  =  ''  THEN 
				EXECUTE PROCEDURE Bdinteg:direcciones('001' , 'A' ,iNumcte,  iSecuencia,   iTipo_dir, cCalle, cColonia, cMunicipio,
				                                      cEntre_calles ,cPais  ,cEstado ,cCiudad ,cCod_postal, cTipo_telef1 ,cTelefono1,'P', cTel,
													  cTipo_telef3 , cTelefono3 ,iExtension,cEstado_inegi,cMunicipio_inegi,cLocalidad_inegi,
													  cNumerociudad ,cNumeroextcalle,cNumerointcalle ,cDepartamento,cNumerocalle,cNumerocolonia,
													  cPuntocardinal ,cUnidadhabitac ,iManzana ,iOtros ,iAndador ,iEtapa ,iLote,iEdIFicio,
													  iEntrada ,cObservaciones  ,cUser_insert   ,dFecha_insert ,null)
				INTO cCodret1;

            IF cCodret1 ='000' THEN
				EXECUTE PROCEDURE bdinteg:sp_validatelefono('001',cTelefono1,cTel,cTelefono3)
				INTO cCodret2, cBandera1,cBandera2,cBandera3;
				EXECUTE PROCEDURE bdinteg:sp_actvalidacioncofetel('001',iNumcte,cBandera1,cBandera2,cBandera3,iTipo_dir,1)
				INTO cCodret3;
			ELSE
			   LET iCont = 3;
			END IF;

			ELIF  cTelefono3  =  ''  THEN 
				EXECUTE PROCEDURE Bdinteg:direcciones('001' , 'A'  ,iNumcte, iSecuencia, iTipo_dir, cCalle, cColonia, cMunicipio, cEntre_calles ,
				                                      cPais  ,cEstado ,cCiudad ,cCod_postal , cTipo_telef1 ,cTelefono1 ,cTipo_telef2, cTelefono2,
													  'P'  , cTel ,iExtension ,cEstado_inegi ,cMunicipio_inegi ,cLocalidad_inegi , cNumerociudad,
													  cNumeroextcalle,cNumerointcalle ,cDepartamento ,cNumerocalle ,cNumerocolonia ,cPuntocardinal,
													  cUnidadhabitac ,iManzana ,iOtros ,iAndador ,iEtapa ,iLote ,iEdIFicio ,iEntrada ,cObservaciones,
													  cUser_insert   ,dFecha_insert  ,null)
				INTO cCodret1;

            IF cCodret1 ='000' THEN
				EXECUTE PROCEDURE bdinteg:sp_validatelefono('001',cTelefono1,cTelefono2,cTel)
				INTO cCodret2, cBandera1,cBandera2,cBandera3;
				EXECUTE PROCEDURE bdinteg:sp_actvalidacioncofetel('001',iNumcte,cBandera1,cBandera2,cBandera3,iTipo_dir,1)
				INTO cCodret3;
			ELSE
			   LET iCont = 3;
			END IF;
			
			END IF
		END IF
		
		IF cTipo_tel = 'I' THEN

			SELECT MAX(secuencia)
			INTO MAXSecuencia
			FROM Bdinteg:si_direcciones
			WHERE numcte =  cNumcTel     --'000018538' 
			AND tipo_dir = 1;

			SELECT numcte, secuencia, tipo_dir, calle, colonia, municipio, entre_calles, pais, estado, ciudad, cod_postal,
				 /*  tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, */estado_inegi, municipio_inegi,
			       localidad_inegi, numerociudad, numeroextcalle, numerointcalle, departamento, numerocalle, numerocolonia, 
				   puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, entrada, observaciones,
				   user_insert, fecha_insert
			INTO iNumcte,iSecuencia, iTipo_dir,cCalle, cColonia, cMunicipio, cEntre_calles, cPais , cEstado, cCiudad, cCod_postal,
			     /*cTipo_telef1, cTelefono1, cTipo_telef2, cTelefono2, cTipo_telef3, cTelefono3, iExtension, */cEstado_inegi, cMunicipio_inegi,
				 cLocalidad_inegi, cNumerociudad, cNumeroextcalle, cNumerointcalle, cDepartamento, cNumerocalle, cNumerocolonia,
				 cPuntocardinal, cUnidadhabitac, iManzana, iOtros , iAndador, iEtapa, iLote, iEdIFicio, iEntrada, cObservaciones,
				 cUser_insert, dFecha_insert
			FROM Bdinteg:si_direcciones
			WHERE numcte = cNumcTel         --'000018538' 
			AND secuencia = MAXSecuencia   --168 
			AND tipo_dir = 1;	

				select  tipo_tel,telefono 
			into  cTipo_telef1, cTelefono1
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 1 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 1);
										
			select  tipo_tel,telefono 
			into  cTipo_telef2, cTelefono2
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 2 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 2);
												
			select  tipo_tel,telefono ,extension
			into  cTipo_telef3, cTelefono3, iExtension
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 3 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 3);
		    

			IF cTel = cTelefono1 THEN 
				EXECUTE PROCEDURE Bdinteg:direcciones('001' , 'A' , iNumcte,  iSecuencia, iTipo_dir, cCalle, cColonia, cMunicipio, cEntre_calles ,cPais ,cEstado,
				                                      cCiudad ,cCod_postal ,' ',' ',cTipo_telef2 , cTelefono2 ,cTipo_telef3 ,cTelefono3,iExtension,
													  cEstado_inegi ,cMunicipio_inegi ,cLocalidad_inegi, cNumerociudad ,cNumeroextcalle ,cNumerointcalle,
													  cDepartamento ,cNumerocalle ,cNumerocolonia ,cPuntocardinal ,cUnidadhabitac ,iManzana ,iOtros,
													  iAndador ,iEtapa ,iLote ,iEdificio ,iEntrada ,cObservaciones ,cUser_insert ,dFecha_insert ,null)
				INTO cCodret1;
			ELIF cTel = cTelefono2 THEN 
				EXECUTE PROCEDURE Bdinteg:direcciones('001' , 'A' ,iNumcte, iSecuencia, iTipo_dir, cCalle, cColonia, cMunicipio, cEntre_calles,
				                                     cPais ,cEstado,cCiudad ,cCod_postal ,cTipo_telef1,cTelefono1,' ' ,' ' ,cTipo_telef3,
													 cTelefono3,iExtension ,cEstado_inegi ,cMunicipio_inegi ,cLocalidad_inegi, cNumerociudad,
													 cNumeroextcalle ,cNumerointcalle ,cDepartamento ,cNumerocalle ,cNumerocolonia ,cPuntocardinal,
													 cUnidadhabitac ,iManzana ,iOtros, iAndador,iEtapa,iLote,iEdIFicio ,iEntrada ,cObservaciones,
													 cUser_insert ,dFecha_insert  ,null)
				INTO cCodret1;
			ELIF cTel = cTelefono3 THEN 
				EXECUTE PROCEDURE Bdinteg:direcciones('001' , 'A' , iNumcte, iSecuencia, iTipo_dir, cCalle, cColonia, cMunicipio, cEntre_calles,
				                                     cPais ,cEstado ,cCiudad  ,cCod_postal ,cTipo_telef1,cTelefono1,cTipo_telef2,  cTelefono2,
													 ' ', ' ',iExtension ,cEstado_inegi ,cMunicipio_inegi ,cLocalidad_inegi, cNumerociudad,
													 cNumeroextcalle ,cNumerointcalle ,cDepartamento ,cNumerocalle ,cNumerocolonia ,cPuntocardinal,
													 cUnidadhabitac ,iManzana ,iOtros, iAndador,iEtapa,iLote,iEdIFicio ,iEntrada ,cObservaciones,
													 cUser_insert ,dFecha_insert ,null)
				INTO cCodret1;
			ELSE
				SELECT MAX(secuencia)
				INTO MAXSecuencia2
				FROM Bdinteg:si_direcciones
				WHERE numcte = cNumcTel --'000018538'
				AND tipo_dir = 2;
				
				IF MAXSecuencia2 IS NULL THEN
					LET iCont = 3;
					UPDATE Bdicobranza:cb_gestion_telefonica SET status = 'ER'  WHERE num_solicitud = cNum_sol and numcte = cNumcTel and secuencia = sSecuencia;			
					CONTINUE FOREACH;				
				END IF;

				SELECT numcte,secuencia,tipo_dir,calle,colonia,municipio,entre_calles,pais,estado,ciudad,cod_postal,/*tipo_telef1,telefono1,tipo_telef2,
				      telefono2,tipo_telef3,telefono3,extension,*/estado_inegi,municipio_inegi,localidad_inegi,numerociudad,numeroextcalle,
					  numerointcalle,departamento,numerocalle,numerocolonia,puntocardinal,unidadhabitac,manzana,otros,Andador,etapa,lote,edificio,
					  entrada,observaciones,user_insert,fecha_insert
				INTO iNumcte,iSecuencia, iTipo_dir,cCalle, cColonia, cMunicipio, cEntre_calles, cPais , cEstado, cCiudad,  cCod_postal, /*cTipo_telef1,
				     cTelefono1, cTipo_telef2, cTelefono2, cTipo_telef3, cTelefono3,*/ iExtension, cEstado_inegi, cMunicipio_inegi, cLocalidad_inegi,
					 cNumerociudad, cNumeroextcalle, cNumerointcalle, cDepartamento, cNumerocalle, cNumerocolonia, cPuntocardinal, cUnidadhabitac,
					 iManzana, iOtros , iAndador, iEtapa, iLote, iEdIFicio, iEntrada, cObservaciones, cUser_insert, dFecha_insert
				FROM Bdinteg:si_direcciones
				WHERE numcte =  cNumcTel                 --'000018538'
				AND secuencia =  MAXSecuencia2    -- 29				
				AND tipo_dir = 2;
			
				select  tipo_tel,telefono 
			into  cTipo_telef1, cTelefono1
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 1 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 1);
										
			select  tipo_tel,telefono 
			into  cTipo_telef2, cTelefono2
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 2 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 2);
												
			select  tipo_tel,telefono ,extension
			into  cTipo_telef3, cTelefono3, iExtension
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 3 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 3);
		    
				
				IF cTel = cTelefono1 THEN 
					EXECUTE PROCEDURE Bdinteg:direcciones('001' , 'A' , iNumcte, iSecuencia, iTipo_dir, cCalle, cColonia, cMunicipio, cEntre_calles ,cPais ,cEstado,
					                                      cCiudad  ,cCod_postal ,'','',cTipo_telef2, cTelefono2 ,cTipo_telef3 ,cTelefono3,iExtension,cEstado_inegi,
														  cMunicipio_inegi   ,cLocalidad_inegi , cNumerociudad ,cNumeroextcalle ,cNumerointcalle  ,cDepartamento ,
														  cNumerocalle ,cNumerocolonia ,cPuntocardinal ,cUnidadhabitac ,iManzana ,iOtros ,iAndador ,iEtapa ,iLote,
														  iEdIFicio ,iEntrada ,cObservaciones ,cUser_insert ,dFecha_insert ,null)
					INTO cCodret1;
				ELIF cTel = cTelefono2 THEN 
					EXECUTE PROCEDURE Bdinteg:direcciones('001' , 'A' , iNumcte, iSecuencia, iTipo_dir, cCalle, cColonia, cMunicipio, cEntre_calles,
					                                      cPais,cEstado,cCiudad,cCod_postal,cTipo_telef1,cTelefono1,'','',cTipo_telef3, cTelefono3,
														  iExtension,cEstado_inegi,cMunicipio_inegi,cLocalidad_inegi, cNumerociudad,cNumeroextcalle,
														  cNumerointcalle,cDepartamento,cNumerocalle,cNumerocolonia,cPuntocardinal,cUnidadhabitac,
														  iManzana,iOtros,iAndador,iEtapa,iLote,iEdIFicio,iEntrada,cObservaciones,cUser_insert,
														  dFecha_insert,null)
					INTO cCodret1;
				ELIF cTel = cTelefono3 THEN 
					EXECUTE PROCEDURE Bdinteg:direcciones('001','A',iNumcte,iSecuencia,iTipo_dir,cCalle,cColonia,cMunicipio,cEntre_calles,cPais,
					                                      cEstado,cCiudad,cCod_postal,cTipo_telef1,cTelefono1,cTipo_telef2,cTelefono2 ,'' , '',
														  iExtension,cEstado_inegi,cMunicipio_inegi,cLocalidad_inegi,cNumerociudad,cNumeroextcalle,
														  cNumerointcalle,cDepartamento,cNumerocalle,cNumerocolonia,cPuntocardinal,cUnidadhabitac,
														  iManzana,iOtros,iAndador,iEtapa,iLote,iEdificio,iEntrada,cObservaciones,cUser_insert,
														  dFecha_insert ,null)
					INTO cCodret1;
				END IF
			END IF 
		END IF 
----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		IF cTipo_tel  = 'T'  THEN
			SELECT MAX(secuencia)
			INTO MAXSecuencia2
			FROM Bdinteg:si_direcciones
			WHERE tipo_dir = 2
			AND numcte = cNumcTel; --'000018538'
			
			IF MAXSecuencia2 IS NULL THEN
				LET iCont = 3;
				UPDATE Bdicobranza:cb_gestion_telefonica SET status = 'ER'  WHERE num_solicitud = cNum_sol and numcte = cNumcTel and secuencia = sSecuencia;			
				CONTINUE FOREACH;				
			END IF;

			SELECT numcte,secuencia,tipo_dir,calle,colonia,municipio,entre_calles,pais,estado,ciudad,cod_postal,/*tipo_telef1,telefono1,tipo_telef2,
			       telefono2,tipo_telef3,telefono3,extension,*/estado_inegi,municipio_inegi,localidad_inegi,numerociudad,numeroextcalle,
				   numerointcalle,departamento,numerocalle,numerocolonia,puntocardinal,unidadhabitac,manzana,otros,Andador,etapa,lote,edificio,
				   entrada,observaciones,user_insert,fecha_insert
			INTO iNumcte,iSecuencia, iTipo_dir,cCalle, cColonia, cMunicipio, cEntre_calles, cPais , cEstado, cCiudad,  cCod_postal, /*cTipo_telef1,
			     cTelefono1, cTipo_telef2, cTelefono2, cTipo_telef3, cTelefono3, iExtension, */cEstado_inegi, cMunicipio_inegi, cLocalidad_inegi,
				 cNumerociudad, cNumeroextcalle, cNumerointcalle, cDepartamento, cNumerocalle, cNumerocolonia, cPuntocardinal, cUnidadhabitac,
				 iManzana, iOtros , iAndador, iEtapa, iLote, iEdIFicio, iEntrada, cObservaciones, cUser_insert, dFecha_insert
			FROM Bdinteg:si_direcciones
			WHERE numcte =  cNumcTel                 -- '000018538'
			AND secuencia =  MAXSecuencia2
			AND tipo_dir = 2;		

				select  tipo_tel,telefono 
			into  cTipo_telef1, cTelefono1
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 1 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 1);
										
			select  tipo_tel,telefono 
			into  cTipo_telef2, cTelefono2
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 2 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 2);
												
			select  tipo_tel,telefono ,extension
			into  cTipo_telef3, cTelefono3, iExtension
			from bdinteg:si_telefonos 
			where numcte = iNumcte 
				and tipo_tel = 3 and secuencia = (select max(secuencia) from bdinteg:si_telefonos 
													where numcte = iNumcte and tipo_tel = 3);
		    
			EXECUTE PROCEDURE Bdinteg:direcciones('001','A',iNumcte,iSecuencia,iTipo_dir,cCalle,cColonia,cMunicipio,cEntre_calles,cPais,cEstado,
			                                     cCiudad,cCod_postal,cTipo_telef1,cTelefono1,cTipo_telef2,cTelefono2,'T',cTel,iExtension,
												 cEstado_inegi,cMunicipio_inegi,cLocalidad_inegi,cNumerociudad,cNumeroextcalle,cNumerointcalle,
												 cDepartamento,cNumerocalle,cNumerocolonia,cPuntocardinal,cUnidadhabitac,iManzana,iOtros,
												 iAndador,iEtapa,iLote,iEdIFicio,iEntrada,cObservaciones,cUser_insert,dFecha_insert  ,null)
			INTO cCodret1;	
			
            IF cCodret1 ='000' THEN
				EXECUTE PROCEDURE bdinteg:sp_validatelefono('001',cTelefono1,cTelefono2,cTel)
				INTO cCodret2, cBandera1,cBandera2,cBandera3;
				EXECUTE PROCEDURE bdinteg:sp_actvalidacioncofetel('001',iNumcte,cBandera1,cBandera2,cBandera3,iTipo_dir,1)
				INTO cCodret3;
		    ELSE
			   LET iCont = 3;
			END IF;

		END IF;

		--Se valida la ejecucion del procedimiento direcciones para cualquier tipo de telefono
		IF cCodret1 <> '000' THEN
			LET iCont = 3;
			UPDATE Bdicobranza:cb_gestion_telefonica SET status = 'ER'  WHERE num_solicitud = cNum_sol and numcte = cNumcTel and secuencia = sSecuencia;			
			CONTINUE FOREACH;
		END IF;
-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	  IF  iCont <> 3 THEN 
       LET iContador = iContador + 1;
		UPDATE Bdicobranza:cb_gestion_telefonica SET status = 'PR', fecha_ejecucion = dFechaHoy WHERE num_solicitud = cNum_sol and numcte = cNumcTel and secuencia = sSecuencia;			
		CONTINUE FOREACH;
      END IF;

	END FOREACH

	IF iCont = 0 THEN
		LET cCodret = '000001'; -- NO EXISTEN REGISTROS EN LA TABLA cb_gestion_telefonica para los NP
		RETURN cCodret,iContador;
	ELIF iCont = 2 THEN
		LET cCodret = '000002'; -- NO EXISTE EL REGISTRO EN si_direcciones
		RETURN cCodret,iContador;
	ELIF iCont = 3 THEN
		LET cCodret = '000003'; -- PROBLEMAS EN LA EJECUCION DEL PROCEDIMIENTO direcciones
		RETURN cCodret,iContador;
	END IF;

	RETURN cCodret,iContador;

END;
END PROCEDURE
DOCUMENT
'CREACION     : VALENTIN LOPEZ',
'DESCRIPCION  : Actualiza los Telefonos de los Clientes con Base ala Tabla "cb_gestion_telefonica" ',
'FECHA    	  : AGOSTO 2010',
'VERSION  	  : 20100813.1630';

CREATE PROCEDURE "informix".sp_carga_sms_latinia()
RETURNING CHAR(6), CHAR(80);

/* 	MARIA ELIZABETH ANZURES IBARGUEN
	24-OCTUBRE-2012
	ARCHIVO QUE CARGA MOVIMEINTOS SMS LATINIA A TABLA CB_SMS_LATINIA PARA TOMAR LA INFORMACION EN LA GENERACIN DE REPORTES*/

--DECLARACION DE VARIABLES
	DEFINE sql_err		INTEGER;
	DEFINE isam_err		INTEGER;
	DEFINE error_info	CHAR(80);
	DEFINE cCod_ret		CHAR(6);
	DEFINE vempresa     CHAR(3);
	DEFINE cproceso     CHAR(4);
	DEFINE vvcCod_ret   CHAR(6);
	DEFINE cMensaje		CHAR(80);
	DEFINE cCadena		CHAR(500);
	DEFINE vRuta		CHAR(100);
	DEFINE cSql         CHAR(2204);	
	DEFINE pNomArch 	CHAR(100);
	DEFINE vNomArch		CHAR(100);
	DEFINE X 			CHAR(100);
	DEFINE vfecha 		DATE;
	DEFINE vfecha_cat 	DATE;
	
	----variables
	DEFINE vnumcte					CHAR(20);
	DEFINE vtelefonoreconstruido	CHAR(13);
	DEFINE vtipotelefono			SMALLINT;
	DEFINE vsecuencia				SMALLINT;
	DEFINE vnumext					CHAR(5);
	DEFINE vfinllamada				SMALLINT;
	DEFINE vnumempleado				CHAR(8);
	DEFINE vnumcuenta				CHAR(20);
	DEFINE vplazo					CHAR(2);
	DEFINE vimporte					DECIMAL(18,2);
	DEFINE vtipoconvenio			CHAR(1);
	DEFINE vhorainicio				DATE;

--	SET DEBUG FILE TO "carga_sms.out ";
--	TRACE ON;

--DEFINICIAON DE VARIABLES
	LET cCod_ret  	= "000000";
	LET sql_err   	= 0;
	LET cMensaje  	= "PROCESO EXITOSO";
	LET cCadena   	= "";
	LET vRuta     	= "";
	LET cSql      	= "";
	LET vempresa    = '001';
	LET cproceso    = '2077';
	LET pNomArch 	= '';
	let vfecha 		= DATE(1);
	let vfecha_cat	= date(1);
	let vNomArch	= '';
	let X ='';
	
	---VARIABLES
	LET vnumcte					='';
	LET vtelefonoreconstruido	='';
	LET vtipotelefono			=0;
	LET vsecuencia				=0;
	LET vnumext					='';
	LET vfinllamada				=0;
	LET vnumempleado			='';
	LET vnumcuenta				='';
	LET vplazo					='';
	LET vimporte				=0;
	LET vtipoconvenio			='';
	LET vhorainicio				=DATE(1);

      BEGIN
  
        ON EXCEPTION SET sql_err, isam_err, error_info
	        LET cCod_ret = sql_err;
			LET cMensaje = error_info;
		  CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje, '02')
            RETURNING vvcCod_ret;
			    RETURN cCod_ret, cMensaje;	    
	    END EXCEPTION;
		
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
		
	--SE MANDA LLAMAR SP PARA INSERTAR EN BITACORA EL INICIO DE LA EJECUCION DE SP
		CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje, '01')
        RETURNING vvcCod_ret;
 
	--SELECCIONAMOS LA FECHA DEL DIA
	select fecha_hoy 
		into vfecha 
	from bdicred:sd_fechas 
	where empresa = '001';

		--SELECCIONAMOS LA RUTA 
    select valor_alfabetico 
		into vRuta 
    from bdicobranza:cb_param_campania
    where empresa = '001'
		and tipo_campania = 1
		and grupo_parametro = 'ARCHIVOS'
		and num_parametro = 36;	

--let vfecha = '10-23-2012';----------------------pruebas
--let vRuta ='/informix/eli/'; --------------------pruebas	
	---------------------------------------------CARGAR ARCHIVO A LA TABLA	---------------------------------------------------------------------
	
		--ASIGNAMOS NOMBRE AL ARCHIVO
		LET pNomArch = 'sms_latinia'|| to_char(vfecha,'%d%m%Y')||'.txt';
		let vNomArch = pNomArch;
	
		LET cCadena = 'echo " load from ' || SUBSTR(vRuta,1,LENGTH(vRuta)) || SUBSTR(vNomArch,1,
			LENGTH(vNomArch))  || ' insert into bdicobranza:cb_sms_latinia " >' || SUBSTR(vRuta,1,LENGTH(vRuta)) || 'smsmovimientoslatinia.sql';
			System SUBSTR(cCadena,1,LENGTH(cCadena));
			let cCadena = 'dbaccess bdicobranza ' || SUBSTR(vRuta,1,LENGTH(vRuta)) || 'smsmovimientoslatinia.sql';
		System SUBSTR(cCadena,1,LENGTH(cCadena));
		  
		--BORRA EL ARCHIVO 
        let cCadena = 'rm ' || SUBSTR(vRuta,1,LENGTH(vRuta)) || 'smsmovimientoslatinia.sql';
        System SUBSTR(cCadena,1,LENGTH(cCadena));
		
		--SE COMPRIME DE NUEVO EL ARCHIVO	
/*		LET cSql = "gzip " || trim(vRuta) || trim(vNomArch); 
*/		system cSql;
	
	
	--SE MANDA LLAMAR SP PARA INSERTAR EN BITACORA EL FINAL DE LA EJECUCION DE SP
		CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje, '03')
		RETURNING vvcCod_ret;
		
RETURN cCod_ret, cMensaje;

END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_replica_cobranza_administrativa()
       RETURNING char(6), char(80);

--declaracion de variables
------------------------------------------------------------
DEFINE sql_err 			            INTEGER;
DEFINE isam_err 		            INTEGER;
DEFINE error_info		            CHAR(80);
DEFINE cMensaje 		            CHAR(80);
DEFINE cCod_ret                     CHAR(6);
define v_fecha_hoy					date;
------------------------------------------------------------
DEFINE pFechaEjecucion              DATE;
DEFINE iDia                         INTEGER;
DEFINE pUsuario                     CHAR(8);
----------------------------------------------------------------------
DEFINE vcliente                     CHAR(20);
DEFINE vcredito                     CHAR(20);
DEFINE vtarjeta                     CHAR(20);
DEFINE vciudad                      CHAR(20);
DEFINE vestado                      CHAR(20);
DEFINE vnombre                      CHAR(110);
DEFINE vsexo                        CHAR(1);
DEFINE vcivil                       CHAR(2);
DEFINE vt_casa                      CHAR(13);
DEFINE vt_celular                   CHAR(13);
DEFINE vt_trabajo                   CHAR(13);
DEFINE vext                         CHAR(5);
DEFINE vnombre_ref                  CHAR(110);
DEFINE vt_ref                       CHAR(13);
DEFINE vsdo_total                   DECIMAL(18,2);
DEFINE vpago_min                    DECIMAL(18,2);
DEFINE vsdo_venc_int_mora           DECIMAL(18,2);
DEFINE vf_ult_pago_monto            CHAR(40);
DEFINE vpago_venc                   INTEGER;
DEFINE vpago_min_sin_vdo            DECIMAL(18,2);        
DEFINE vcausa                       SMALLINT;
DEFINE vsituacion                   CHAR(1);
DEFINE vdia							DATE;
DEFINE vhora						char(8);
DEFINE vdia2    					DATE;
DEFINE vproceso						char(4);
DEFINE Vempresa						char(3);
DEFINE Vnum_campana					smallint;
DEFINE Vproducto					char(4);
DEFINE Vfecha_ejecucion				DATE;
define vcuenta 				char(20);
DEFINE cNombre1				CHAR(26);
DEFINE cNombre2				CHAR(26);
DEFINE cApellPat			CHAR(26);
DEFINE cApellMat			CHAR(26);
DEFINE vfecha_pago 			date;
DEFINE vtipo_transacc 		CHAR(1);
DEFINE vpago_vencido  		DECIMAL(18,2);   
DEFINE vpago_req_sms		DECIMAL(18,2);  
-------------------------------cb_mail_cliente_his
DEFINE 	pempresa 			CHAR(3);
define  ctipo_mensaje    	SMALLINT;
define  cfecha_insert    	DATE;
define  cnumcte          	CHAR(20);
define  cnum_credito     	CHAR(20);
define  cemail           	CHAR(60);
define  cpago_minimo     	DECIMAL(18,2);
define  csaldo_total     	DECIMAL(18,2);
define  cpagos_vencidos  	DECIMAL(18,2);
define  cmonto_convenio  	DECIMAL(18,2);
define  cfecha_convenio  	DATE;
define  cfecha_compac    	DATE;
define  cfecha_primercons	DATE;
define  cestatus         	CHAR(2);
define  cenviado         	SMALLINT;
define  ccumplio_compac  	SMALLINT;
define  vpago_min_sin_venc 	DECIMAL(18,2);   
define  v_sdo_venc_int_mora 	DECIMAL(18,2);

--------------------------------------------
LET Vempresa 			= '';
LET Vnum_campana 		= 0;
LET Vproducto 			= '';
LET Vfecha_ejecucion 	= DATE(1);
let vcuenta 			= '';
LET cNombre1			= '';
LET cNombre2			= '';
LET cApellPat			= '';
LET cApellMat			= '';
LET vfecha_pago 		= date(1);
LET vtipo_transacc		= 0;
LET vpago_vencido  		= 0; 
LET vpago_req_sms		= 0;
---------------------------------------
LET  pempresa 			= '';
LET  ctipo_mensaje    	= 0;
LET  cfecha_insert      = date(1);
LET  cnumcte          	= '';
LET  cnum_credito     	= '';
LET  cemail           	= '';
LET  cpago_minimo     	= 0;
LET  csaldo_total     	= 0;
LET  cpagos_vencidos  	= 0;
LET  cmonto_convenio  	= 0;
LET  cfecha_convenio  	= date(1);
LET  cfecha_compac    	= date(1);
LET  cfecha_primercons	= date(1);
LET  cestatus         	= '';
LET  cenviado         	= 0;
LET  ccumplio_compac  	= 0;
LET  vpago_min_sin_venc 	= 0;
LET  v_sdo_venc_int_mora 	= 0;
--SET DEBUG FILE TO 'sp_calcula_cobranza_administrativa_pbaaaa.out';
--trACE ON;

      LET cCod_ret      = '000000';
	  LET sql_err       = 0;
	  LET isam_err      = 0;
	  LET error_info    = '';
	  LET cMensaje      = 'PROCESO EXITOSO';
	  LET vproceso		= '0105';
      LET pUsuario      = user;
      LET pFechaEjecucion = today;
	  let v_fecha_hoy = date(1);
    --LET iDia = day(pFechaEjecucion);

	BEGIN

        ON EXCEPTION SET sql_err, isam_err, error_info
	        LET cCod_ret = sql_err;
	        LET cMensaje = error_info;
			CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, cCod_ret, cMensaje, '02')RETURNING cCod_ret; 

		RETURN cCod_ret, cMensaje;
		END EXCEPTION;
     
--------------------------------------------------------------------------
--se borra cb_info_administrativa datos antiguos
--------------------------------------------------------------------------

    SELECT fecha_hoy INTO v_fecha_hoy FROM bdinteg:si_fechas;
    --SELECT DBINFO('utc_to_datetime', sh_curtime)::DATE  INTO v_fecha_hoy from sysmaster:sysshmvals;
    --DELETE cb_info_administrativa WHERE fecha_ejecucion < v_fecha_hoy -1;
/*    SELECT MAX(fecha_ejecucion) INTO vdia2 FROM bdicobranza:cb_info_administrativa_his;
      IF(vdia2 = vdia ) THEN
        DELETE bdicobranza:cb_info_administrativa WHERE fecha_ejecucion = vdia2;
    ELSE
    DELETE bdicobranza:cb_info_administrativa WHERE fecha_ejecucion < vdia2;
     END IF;
*/
    
--------------------------------------------------------------------------
--------------------------------------------------------------------------
CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, cCod_ret, cMensaje, '01')RETURNING cCod_ret; 


        --se obtiene la informacion
		SET ISOLATION TO dirty READ;

----------------------------------- Se obtienen DATOS del CLIENTE y SALDOS--------------------------------------------

FOREACH
            SELECT  empresa,num_campania,producto,fecha_ejecucion,cliente,credito, cuenta,tarjeta,ciudad,estado,
			  nombre1 ,nombre2,apell_paterno,apell_materno, t_celular,
			  sdo_total,pago_min,fecha_pago,sdo_venc_int_mora , pago_venc,pago_min_sin_vdo,causa,situacion,
			  tipo_transacc,pago_vencido,pago_req_sms
			INTO Vempresa,Vnum_campana,Vproducto,vfecha_ejecucion,vcliente,vcredito,vcuenta,vtarjeta ,vciudad, vestado,
				cNombre1,cNombre2,cApellPat,cApellMat,vt_celular,
				vsdo_total, vpago_min,vfecha_pago, vsdo_venc_int_mora,vpago_venc,vpago_min_sin_vdo, vcausa, vsituacion,
				vtipo_transacc,vpago_vencido,vpago_req_sms
            FROM bdicobranza:cb_info_administrativa
            WHERE fecha_ejecucion = v_fecha_hoy

---------------SE INCERTAN DATOS GENERADOS----------------------------------------------------------

			 INSERT INTO cb_info_administrativa_his (
			  empresa,num_campania,producto,fecha_ejecucion,cliente,credito, cuenta,tarjeta,ciudad,estado,
			  nombre1 ,nombre2,apell_paterno,apell_materno, t_celular,
			  sdo_total,pago_min,fecha_pago,sdo_venc_int_mora , pago_venc,pago_min_sin_vdo,causa,situacion,tipo_transacc,pago_vencido,pago_req_sms)
			  VALUES(Vempresa,Vnum_campana,Vproducto,vfecha_ejecucion,vcliente,vcredito,vcuenta,vtarjeta ,vciudad, vestado,
				cNombre1,cNombre2,cApellPat,cApellMat,vt_celular,
				vsdo_total, vpago_min,vfecha_pago, vsdo_venc_int_mora,vpago_venc,vpago_min_sin_vdo, vcausa, vsituacion,
				vtipo_transacc,vpago_vencido,vpago_req_sms);
                    
END FOREACH;

-----------------------------------------------INSERTAR----CB_MAIL_CLIENTE_HIS-------------------------------------

	FOREACH
	
		select  empresa,tipo_mensaje, fecha_insert, numcte,num_credito,	email,pago_minimo,
	        saldo_total,pagos_vencidos,	monto_convenio,	fecha_convenio,	fecha_compac, fecha_primercons,
			estatus,enviado ,cumplio_compac , pago_venc , pago_min_sin_venc , sdo_venc_int_mora 
		into 	pempresa,ctipo_mensaje,	cfecha_insert,cnumcte,cnum_credito,cemail,cpago_minimo,
			csaldo_total,cpagos_vencidos ,cmonto_convenio,cfecha_convenio,cfecha_compac, cfecha_primercons,
			cestatus,cenviado,ccumplio_compac,vpago_venc,vpago_min_sin_venc,v_sdo_venc_int_mora
		from bdicobranza:cb_mail_cliente
		where empresa = '001' and fecha_insert = v_fecha_hoy    
			
		insert into bdicobranza:"informix".cb_mail_cliente_his(
	        empresa,tipo_mensaje,fecha_insert,numcte,num_credito,email,pago_minimo,saldo_total,pagos_vencidos ,
			monto_convenio, fecha_convenio,fecha_compac, fecha_primercons,estatus,enviado ,cumplio_compac,
			pago_venc , pago_min_sin_venc , sdo_venc_int_mora )
		values(pempresa,ctipo_mensaje,cfecha_insert,cnumcte,cnum_credito,cemail,cpago_minimo,csaldo_total,cpagos_vencidos,
			cmonto_convenio,cfecha_convenio,cfecha_compac, cfecha_primercons,cestatus,cenviado ,ccumplio_compac,vpago_venc,
			vpago_min_sin_venc,v_sdo_venc_int_mora);
			
	end FOREACH;

	CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, cCod_ret, cMensaje, '01')RETURNING cCod_ret; 
	RETURN cCod_ret, cMensaje;

	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_busca_totalero(pnumcredito char(20), pfechacortec char(10), pfechacorte date ) 
  
RETURNING char(6), char(1);

DEFINE cMensaje CHAR(1);
DEFINE vdia, vmes       CHAR(2);
DEFINE cfecha_armada    CHAR(300);
DEFINE v_empresa        CHAR(3);
DEFINE cproceso, vanio, vanioant, vanio_actual  CHAR(4);
DEFINE cCod_ret, vvcCod_ret            CHAR(6);
DEFINE cfecha_dia                      CHAR(8);
DEFINE vfechafin_mesanterior           CHAR(10);
DEFINE cfecha_corte, cfecha_corte_2    CHAR(10);

DEFINE error_info  			               CHAR(80);
DEFINE cRuta                           CHAR(100);
DEFINE cCadena                         CHAR(500);

DEFINE vMesTope, i        INTEGER;

DEFINE sql_err				    INTEGER;
DEFINE isam_err				    INTEGER;
DEFINE vRegistros         INTEGER;

DEFINE dtFechaHoy		       DATE;
DEFINE dfecha_corte        DATE;
DEFINE dfecha_ant1, dfecha_ant2, dfecha_ant3, dfecha_ant4, dfecha_ant5, dfecha_ant6  DATE;
DEFINE dfecha_ant7, dfecha_ant8, dfecha_ant9, dfecha_ant10, dfecha_ant11  DATE;
DEFINE cConsulta		  	CHAR(500);   
DEFINE cSql          		CHAR(1024);
DEFINE vnumcredito      CHAR(20);
DEFINE vnumcredito2      CHAR(20);

LET cCod_ret            = '000000';
LET sql_err             = 0;
LET isam_err            = 0;
LET error_info          = '';
LET cMensaje            = '0';
LET v_empresa           = '001';
LET cproceso            = '0625';
LET dtFechaHoy	        = DATE(1);
 
LET vfechafin_mesanterior = '';
LET vdia       = '';           LET vmes = '';                    LET vanio = ''; 
LET vanioant = '';
LET dfecha_corte = DATE(1);  
LET dfecha_ant1 = DATE(1); LET dfecha_ant2 = DATE(1); LET dfecha_ant3 = DATE(1); LET dfecha_ant4 = DATE(1);
LET dfecha_ant5 = DATE(1); LET dfecha_ant6 = DATE(1); LET dfecha_ant7 = DATE(1); LET dfecha_ant8 = DATE(1);
LET dfecha_ant9 = DATE(1); LET dfecha_ant10 = DATE(1); LET dfecha_ant11 = DATE(1);
LET cfecha_corte = '';         LET cfecha_corte_2 = '';
LET cRuta = '';                  
LET cfecha_dia = '';           LET cCadena    = '';              LET vMesTope   = 0;
LET i = 0;                      
LET cConsulta = "";  LET cSql = "";
LET cfecha_armada = '';  LET vnumcredito = ''; LET vnumcredito2 = '';

  --SET DEBUG FILE TO '/informix/macf/sp_busca_totalero.trc';
  --TRACE ON;

 BEGIN
        
        ON EXCEPTION SET sql_err, isam_err, error_info
          LET cCod_ret = sql_err;
          LET cMensaje = error_info;
          CALL bdicobranza:"informix".sp_inserta_bitacora_cob(v_empresa, cProceso, cCod_ret, cMensaje, '02')
          RETURNING vvcCod_ret;
          RETURN cCod_ret, '1';
    END EXCEPTION;
      
    LET dfecha_ant1 = pfechacorte - i UNITS MONTH;
    LET dfecha_ant2 = pfechacorte - 2 UNITS MONTH;
    LET dfecha_ant3 = pfechacorte - 3 UNITS MONTH;
    LET dfecha_ant4 = pfechacorte - 4 UNITS MONTH;
    LET dfecha_ant5 = pfechacorte - 5 UNITS MONTH;
    LET dfecha_ant6 = pfechacorte - 6 UNITS MONTH;
    LET dfecha_ant7 = pfechacorte - 7 UNITS MONTH;
    LET dfecha_ant8 = pfechacorte - 8 UNITS MONTH;
    LET dfecha_ant9 = pfechacorte - 9 UNITS MONTH;
    LET dfecha_ant10 = pfechacorte - 10 UNITS MONTH;
    LET dfecha_ant11 = pfechacorte - 11 UNITS MONTH;

    SELECT limit 1 num_credito INTO vnumcredito
      FROM bdicred:sd_movhis WHERE empresa = v_empresa
       AND (fecha_mov = pfechacorte or fecha_mov = dfecha_ant1 or fecha_mov = dfecha_ant2 
        OR  fecha_mov = dfecha_ant3 or fecha_mov = dfecha_ant4 or fecha_mov = dfecha_ant5 
        OR  fecha_mov = dfecha_ant6 or fecha_mov = dfecha_ant7 or fecha_mov = dfecha_ant8
        OR  fecha_mov = dfecha_ant9 or fecha_mov = dfecha_ant10 or fecha_mov = dfecha_ant11)
       AND num_credito = pnumcredito 
       AND codigo_fun= '605' AND codigo_ref in(2,3)
       AND reversado = 'N';

       --LET sRegistros=dbinfo("sqlca.sqlerrd2");
      IF  nvl(vnumcredito,'') <> '' then
           LET cMensaje = 'N';
       ELSE
           LET cMensaje = 'S';
       END IF;          
             
      RETURN cCod_ret, cMensaje;
 END

END PROCEDURE;

