                        nvl ( replace ( replace( vvariables_pantilla , '|' , ' ' ), '\' , ' ' ), ' ' ));

        IF icontador >= 1000 then
            update statistics medium for table sms_latinia;
			LET icontador=1;
		ELSE
			LET icontador=icontador+1;
		END IF;
	end if;
    End ForEach;
	end if;
end if;
