create procedure "informix".sp_latinia_contador(pcampania char(10),pcontador integer)
returning VARCHAR(6);

DEFINE cCod_ret  	smallint;
DEFINE cMensaje  	char (100);
DEFINE SQL_ERR         INTEGER;
DEFINE ISAM_ERR        INTEGER;
DEFINE ERROR_INFO      VARCHAR(80);
DEFINE P_COD_RET      	VARCHAR(6);
DEFINE P_MENSAJE       	VARCHAR(80);
define vmaxfecha 		date;
define vfecha			date;

	let P_COD_RET = '000000';
	let cCod_ret = '';
    let cMensaje = '';
	let SQL_ERR            = 0;
	let ISAM_ERR           = 0;
	let ERROR_INFO         = '';
	let P_MENSAJE          = '';
	let vmaxfecha = date(1);
	let vfecha = date(1);


BEGIN 
  
    ON exception SET SQL_ERR, ISAM_ERR, ERROR_INFO
        LET P_COD_RET = SQL_ERR;
        LET P_MENSAJE = ERROR_INFO;
     RETURN P_COD_RET;
     END exception;
-- SET DEBUG FILE TO 'compac.out';
-- TRACE ON;
		
	select fecha_hoy into vfecha from bdicred:sd_fechas where empresa = '001';
		
		if exists (select fecha_insert from  bdicred:sd_totalcte_campania where month(fecha_insert) = month(vfecha)
						and year(fecha_insert) = year(vfecha)	and tipocampania = pcampania) then
		
			update bdicred:sd_totalcte_campania  set total = total + pcontador 
				where month(fecha_insert) = month(vfecha) and year(fecha_insert) = year(vfecha)
				and tipocampania = pcampania ;
		else
			insert into bdicred:sd_totalcte_campania (empresa,fecha_insert,tipocampania,total)  
			values('001',today,pcampania,pcontador);
		end if;
	
	
end
RETURN P_COD_RET;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_carga_telefonos(ptipo_campania char(1))
       RETURNING char(6), char(150);

-- Modificado por: Martha A Hernandez. Noviembre 2011. Se modifica para que procese tipo cobranza = R  de manera diaria.
-- Modificado por: MAHR Abril 2012. Se limita la generacion de archivos CAT, parametrizado por tipo cobranza.


--declaracion de variables
----------------------------------------------------------------------------------------------
DEFINE sql_err 			            INTEGER;
DEFINE isam_err 		            INTEGER;
DEFINE error_info		            CHAR(150);
DEFINE cMensaje 		            CHAR(150);
DEFINE cCod_ret                     CHAR(6);
DEFINE vvcCod_ret                   CHAR(6);
DEFINE vempresa                     CHAR(3);
DEFINE vnumcte                      CHAR(20);
DEFINE vtelefono_casa               CHAR (13);
DEFINE vtelefono_celular            CHAR(13);
DEFINE vtelefono_trabajo            CHAR(13);
DEFINE vextension                   CHAR(5);
DEFINE vestatus                     CHAR(2);
DEFINE cproceso                     CHAR(4);
DEFINE wCod_Ret						CHAR(6);
DEFINE vtipored						CHAR(10);
DEFINE vnumero_carrier				CHAR(3);
DEFINE vtelefono_ref                CHAR(13);
DEFINE vnum_credito                 CHAR(20);
DEFINE vfech_insert                 DATE;

--SET DEBUG FILE TO "/ids10_uc9/jtrujillo/sp_carga_telefonos.out";
--TRACE ON; 

LET cCod_ret      = '000000';
LET sql_err       = 0;
LET isam_err      = 0;
LET error_info    = '';
LET cMensaje      = 'PROCESO EXITOSO';
LET vempresa      = '001';
LET vestatus      = 'AC';
LET cproceso      = '0008';   
LEt vnumcte       = '';      
      
BEGIN

    ON EXCEPTION SET sql_err, isam_err, error_info
        LET cCod_ret = sql_err;
	    LET cMensaje = error_info;
        CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje, '02')
            RETURNING vvcCod_ret;
		RETURN cCod_ret, cMensaje;
    END EXCEPTION;

    CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje, '01')
            RETURNING vvcCod_ret;

    SELECT MAX(fecha_insert)  INTO vfech_insert 
        FROM bdicobranza:"informix".cb_cat_directorio_cte 
        WHERE empresa = vempresa 
        AND tipo_cobranza = ptipo_campania;
            
/*    SET ISOLATION TO dirty READ;
    SELECT {+INDEX(cb_cat_directorio_cte idx_cat_directorio2)} b.numcte, b.num_credito  
        FROM bdicobranza:"informix".cb_cat_directorio_cte b
        WHERE b.empresa = vempresa
        AND b.tipo_cobranza = ptipo_campania
        AND b.fecha_insert = vfech_insert
        AND b.numcte not in (select numcte from cb_telefonos)
        INTO TEMP tmp_dir_cte WITH NO LOG;

    ------------------------------- Se obtienen DATOS del CLIENTE y SALDOS---------------------------------------
    SET ISOLATION TO dirty READ;
    FOREACH

        SELECT     {+INDEX(bdinteg:si_direcciones_actual idx_diract_ctetpo)} b.numcte,   --- cliente
                       a.telefono1,                                                     --- t_casa
                       substr(a.telefono2,length(a.telefono2)-9,10),                    --- t_celular
                       a.telefono3,                                                     --- t_trabajo
                       a.extension,                                                     --- ext
                       b.num_credito
            INTO vnumcte, vtelefono_casa, vtelefono_celular,
                 vtelefono_trabajo, vextension, vnum_credito
            FROM bdinteg:"informix".si_direcciones_actual a, tmp_dir_cte b
            WHERE a.numcte = b.numcte
            AND a.tipo_dir = '1'
                       
        SELECT LIMIT 1 telefono_ref INTO vtelefono_ref
            FROM bdisolic:"informix".ss_refpersonales
            WHERE empresa = vempresa
            AND num_solicitud = vnum_credito
            AND numcte = vnumcte
            AND numcte_ref = 'R1';


        IF NOT EXISTS(SELECT {+INDEX (cb_telefonos idx_cons_telefono)} empresa FROM bdicobranza:"informix".cb_telefonos
                      WHERE empresa= vempresa and numcte = vnumcte AND telefono = vtelefono_casa and tipo_telefono = 1) THEN

            IF (vtelefono_casa <> '' AND vtelefono_casa <> '0' ) THEN
                EXECUTE PROCEDURE bdinteg:"informix".sp_tipored (vempresa, vtelefono_casa) into wCod_ret , vtipored , vnumero_carrier;
                INSERT INTO bdicobranza:"informix".cb_telefonos (empresa,origen, numcte, tipo_telefono, telefono, extension, 
                                          estatus, tipored , fecha_insert, user_insert , numero_carrier)
                    VALUES(vempresa,2, vnumcte, 1, vtelefono_casa, '', vestatus, vtipored , today, user , vnumero_carrier);
            END IF;
        END IF;

        IF NOT EXISTS(SELECT {+INDEX (cb_telefonos idx_cons_telefono) } empresa FROM bdicobranza:"informix".cb_telefonos
                      WHERE empresa= vempresa and numcte = vnumcte AND telefono = vtelefono_celular and tipo_telefono = 2) THEN

            IF ( vtelefono_celular <> '' AND vtelefono_celular <> '0' ) THEN
                EXECUTE PROCEDURE bdinteg:"informix".sp_tipored (vempresa, vtelefono_celular) into wCod_ret , vtipored , vnumero_carrier;

                INSERT INTO bdicobranza:"informix".cb_telefonos (empresa,origen, numcte, tipo_telefono, telefono, extension, 
                                          estatus, tipored , fecha_insert, user_insert , numero_carrier)
                    VALUES(vempresa, 2,vnumcte, 2, vtelefono_celular, '', vestatus, vtipored , today, user , vnumero_carrier);
            END IF;
        END IF;

        IF NOT EXISTS(SELECT {+INDEX (cb_telefonos idx_cons_telefono) } empresa FROM bdicobranza:"informix".cb_telefonos
                      WHERE empresa= vempresa AND numcte = vnumcte AND telefono = vtelefono_trabajo AND tipo_telefono= 3) THEN

            IF (vtelefono_trabajo <> '' AND vtelefono_trabajo <> '0' ) THEN

                EXECUTE PROCEDURE bdinteg:"informix".sp_tipored (vempresa, vtelefono_trabajo) into wCod_ret , vtipored , vnumero_carrier;
                INSERT INTO bdicobranza:"informix".cb_telefonos (empresa,origen, numcte, tipo_telefono, telefono, extension, 
                                          estatus, tipored , fecha_insert, user_insert , numero_carrier)
                    VALUES(vempresa,2, vnumcte, 3, vtelefono_trabajo, '', vestatus, vtipored , today, user , vnumero_carrier);
            END IF;
        END IF;

        IF NOT EXISTS(SELECT {+INDEX (cb_telefonos idx_cons_telefono) } empresa FROM bdicobranza:"informix".cb_telefonos
                      WHERE empresa= vempresa and numcte = vnumcte AND telefono = vtelefono_ref and tipo_telefono = 4) THEN

            IF (vtelefono_ref <> '' AND vtelefono_ref <> '0' ) THEN
                EXECUTE PROCEDURE bdinteg:"informix".sp_tipored (vempresa, vtelefono_ref) into wCod_ret , vtipored , vnumero_carrier;
                INSERT INTO bdicobranza:"informix".cb_telefonos (empresa,origen, numcte, tipo_telefono, telefono, extension, 
                                          estatus, tipored , fecha_insert, user_insert , numero_carrier)
                    VALUES(vempresa,2, vnumcte, 4, vtelefono_ref, '', vestatus, vtipored , today, user , vnumero_carrier);
            END IF;
        END IF;
               
    END FOREACH;
*/
    CALL bdicobranza:sp_cat_sintelefonos(ptipo_campania)
        RETURNING cCod_ret, cMensaje;

    CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje , '03')
        RETURNING vvcCod_ret;

if (ptipo_campania = 'R') then
    IF (SELECT valor_numerico FROM bdicobranza:cb_param_campania WHERE empresa = '001' AND tipo_campania = 1
            AND grupo_parametro = 'CATARCHACT' AND valor_alfabetico = ptipo_campania) = 1 THEN

        CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso,cCod_ret, ' Inicia Archivos CAT' ,'02' ) RETURNING vvcCod_ret;

        CALL bdicobranza:"informix".sp_ctbcpl_gen_arcgeneracion(vempresa,vfech_insert,ptipo_campania) RETURNING vvcCod_ret ;
        CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso,cCod_ret, 'Finaliza Generacion:'||vvcCod_ret,'02' ) RETURNING vvcCod_ret;  

        CALL bdicobranza:"informix".sp_ctbcpl_gen_arctelefonos(vempresa, ptipo_campania,vfech_insert,'AC') RETURNING vvcCod_ret;    
        CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso,cCod_ret, 'Finaliza Telefonos:'||vvcCod_ret,'02' ) RETURNING vvcCod_ret;

    END IF;
end if;
   
    RETURN cCod_ret, cMensaje;  

END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_rep_envio_sms_reest ()
returning char (6);

------------------------------------------------------------------------------------
--Maria Elizabeth Anzures Ibarguen
--08-27-2012
--crea archivo de sms y email enviados


----DATOS QUE VAN EN LA TABLA
DEFINE  vnumcte			char(20);
DEFINE  vnum_credito 	char(20);
DEFINE	vciudad 		char(6) ;
DEFINE	vestado 		char(6);
DEFINE	vcorreo_sms 	char(100) ;
DEFINE	vnombre1 		char(20) ;
DEFINE	vnombre2 		char(20);
DEFINE	vapell_p 		char(30) ;
DEFINE	vapell_m 		char(30);
DEFINE	vmora 			smallint;
DEFINE	vsdo_venc_int_mora  DECIMAL(18,2);
DEFINE	vpago_minimo_total  DECIMAL(18,2);
DEFINE	vpago_min_sin_vdo   DECIMAL(18,2) ;
DEFINE	vpago_vencido 		DECIMAL(18,2);
DEFINE	vpago_req_mail		DECIMAL(18,2);
DEFINE	vcosto 				decimal (18,2) ;
DEFINE	vfecha_envio 		datetime year to second;
DEFINE	vresultado 			char(10);
DEFINE	vpag1 decimal (18,2); DEFINE vpag2 decimal (18,2);
DEFINE	vpag3 decimal (18,2); DEFINE vpag4 decimal (18,2);
DEFINE	vpag5 decimal (18,2); DEFINE vpag6 decimal (18,2);
DEFINE	vtotal decimal (18,2);
DEFINE vestatus smallint;
define vfechahoy date;
--VARIABLES PARA CAPTURAR ERRORES
DEFINE SQL_ERR                INTEGER;
DEFINE ISAM_ERR               INTEGER;
DEFINE ERROR_INFO             VARCHAR(80);
DEFINE P_COD_RET              VARCHAR(5);
DEFINE P_MENSAJE              VARCHAR(80);
DEFINE vproceso				  CHAR (4);
DEFINE cMensaje				  CHAR(80);

---VARIABLES PARA QUERYS
DEFINE cSQL                 CHAR(2204);
DEFINE cSQL1                CHAR(200);
DEFINE cSQL2                CHAR(2004);
DEFINE cSQL3                CHAR(100);
DEFINE vsql					CHAR(2204);
DEFINE sPaso				integer;
DEFINE cruta                CHAR(100);
DEFINE cdelimitador         CHAR(1);
DEFINE cnomarchivo          CHAR(100);
DEFINE cnomarchivo1			CHAR(100);
DEFINE cnombre				CHAR(100);
define vfecha				DATE;
define vfecha1				DATE;



BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, ERROR_INFO
        LET P_COD_RET = SQL_ERR;
        LET P_MENSAJE = ERROR_INFO;
		 CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '02')RETURNING P_COD_RET;	
	RETURN P_COD_RET;
    END EXCEPTION;

----INICIALIZAN VARIABLES QUE VAN EN LA TABLA

LET  vnumcte 		="";
LET  vnum_credito	="";
LET	vciudad 		="";
LET	vestado 		="";
LET	vcorreo_sms 	="";
LET	vnombre1 		="";
LET	vnombre2 		="";
LET	vapell_p 		="";
LET	vapell_m 		="";
LET	vmora 			=0;
LET	vsdo_venc_int_mora  =0;
LET	vpago_minimo_total  =0;
LET	vpago_min_sin_vdo   =0;
LET	vpago_vencido 		=0;
LET	vpago_req_mail 		=0;
LET	vcosto 				=0;
LET	vfecha_envio 		=date(1);
LET	vresultado 			="";
LET	vpag1 =0; LET vpag2 =0;
LET	vpag3 =0; LET vpag4 =0;
LET	vpag5 =0; LET vpag6 =0;
LET	vtotal =0;
let vestatus =0;
let vfechahoy = date(1);
---INICIALIZAN VARIABLES PARA QUERYS
LET  cSql			="";
LET cSQL1           = "";
LET cSQL2           = "";
LET cSQL3           = "";
let vsql			= '';
Let P_cod_ret		= "00000";
LET vproceso		='2072';
LET cMensaje   		= 'PROCESO EXITOSO';
let sPaso 			=0;
let cruta      		='';
let cdelimitador 	='';
let cnomarchivo  	='';
let cnomarchivo1 	='';
let cnombre 		='';
let vfecha			= date(1);
let vfecha1			= date(1);



 -- Set debug file to 'reestructura.out';
 -- trace on;
    CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '01')RETURNING P_COD_RET;	
	
	SELECT COUNT(tabid)INTO sPaso FROM systables WHERE tabname= 'reestructura';
            IF NVL(sPaso,0) > 0 THEN
                DROP TABLE reestructura;
            END IF;

	create table reestructura
	(numcte char(20), num_credito char(20),
	ciudad char(6), estado char(6),
	correo_sms char(100), 
	nombre1 char(20), nombre2 char(20),
	apell_p char(30), apell_m char(30),
	mora smallint,
	sdo_venc_int_mora  DECIMAL(18,2),pago_minimo_total   DECIMAL(18,2),
	pago_min_sin_vdo   DECIMAL(18,2), pago_vencido DECIMAL(18,2),
	pago_req_mail DECIMAL(18,2),
	costo decimal (18,2), fecha_envio date,
	resultado char(10),
	pag1 decimal (18,2),pag2 decimal (18,2),
	pag3 decimal (18,2),pag4 decimal (18,2),
	pag5 decimal (18,2),pag6 decimal (18,2),
	total decimal (18,2)
	);
	
	--Obtener caracter delimitador
	SELECT trim(valor_alfabetico)
	INTO cdelimitador
	FROM bdicobranza:cb_param_campania
	WHERE empresa = '001'
	AND tipo_campania = 1
	AND grupo_parametro = 'ARCHIVOS'
	AND num_parametro = 2;
	--Valida que exista el caracter
	IF NVL(cDelimitador,'') = '' THEN
        LET P_COD_RET= '104004';
        SELECT descripcion
        INTO cMensaje
        FROM cb_errores
        WHERE origen = 3
        AND codigo_error = P_COD_RET;
	
        IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
        END IF;

        CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '01')RETURNING P_COD_RET;	
        Return P_COD_RET;
	END IF;
		
	select trim(valor_alfabetico) into cruta
	from bdicobranza:cb_param_campania 
	where tipo_campania = 1
	and grupo_parametro = 'ARCHIVOS'
	and num_parametro = 34;
	--Valida que exista la carpeta
	IF NVL (cruta,'') = '' THEN
        LET P_COD_RET= '104005';
        SELECT descripcion
        INTO cMensaje
        FROM cb_errores
        WHERE origen = 3
        AND codigo_error = P_COD_RET;
	
        IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
        END IF;

         CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '01')RETURNING P_COD_RET;	
	     Return P_COD_RET;
	END IF;

	select fecha_hoy into vfecha from bdicred:sd_fechas where empresa = '001';
--let vfecha = '12-18-2012';-------------pruebas
--let cruta = '/informix/eli/';
	let vfechahoy = vfecha;
	let vfecha = vfecha - 4 units day;
	
    set isolation to dirty read;
    set lock mode to wait 3;
	
---------------------------------------------------PREVENTIVA---EMAIL----------------------------------------

if 	(day(vfechahoy) in (18,3))then
	select *
	from bdimnsj:mnsjr_trx_batch where id_mensaje ='REST_PREV'
		and date(fecha_hora_registro) = vfecha
	into temp batch_mprev_reest;
	
	select mov.num_credito, mov.fecha_mov , mov.monto
	from batch_mprev_reest his, bdicred:sd_movhis mov
	where mov.empresa= '001' and mov.fecha_mov >= vfecha and mov.fecha_mov <= date(vfecha) + 3 units day 
		and his.cuenta =  mov.num_credito  
		and mov.codigo_fun in ('033','334','335','336','337','904')	and mov.codigo_ref = 1 	and mov.reversado = 'N'
	into temp movhis_reest_mprev;
	
	create index idx_movhis_reest_mprev on movhis_reest_mprev(num_credito,fecha_mov);   UPDATE STATISTICS medium FOR TABLE movhis_reest_mprev; 

	
	FOREACH
		select his.numcte, his.num_credito, 
                his.email,  his.pagos_vencidos,
				nvl(his.sdo_venc_int_mora,0) , nvl(his.pago_minimo,0)  , nvl(his.pago_min_sin_venc,0)  , nvl(his.pago_venc,0)  , nvl(his.monto_convenio,0) ,
				bat.fecha_hora_registro, nvl(bat.estatus,0)
		into  vnumcte,vnum_credito,vcorreo_sms ,vmora ,
				vsdo_venc_int_mora  ,vpago_minimo_total ,	vpago_min_sin_vdo  ,vpago_vencido ,vpago_req_mail,
				vfecha_envio, vestatus 	
		from bdicobranza:cb_mail_cliente_his his,	 batch_mprev_reest bat
		where his.numcte = bat.cliente and his.num_credito = bat.cuenta 
			and his.tipo_mensaje = 4 and pagos_vencidos = 0
			--and bat.id_mensaje ='REST_PREV'
			and his.fecha_insert = vfecha 
		
		select cte.nombre1, cte.nombre2 , cte.apell_paterno  ,cte.apell_materno 
		into vnombre1 ,vnombre2 ,vapell_p ,vapell_m 
		from bdinteg:si_cliente cte
		where cte.empresa = '001' and cte.numcte = vnumcte;
		
		
		select  est.estado||'-'||est.siglas, cid.numerociudad||'-'||cid.inicialciudad
		into vciudad,vestado 
		from bdinteg:si_direcciones_actual act,  bdinteg:si_estados est,bdinteg:si_catciudades cid
		where act.estado = est.estado
			and act.ciudad = cid.numerociudad 
			and act.numcte = vnumcte
			and act.tipo_dir = 1;
		
		select nvl(sum(monto),0) into vpag1
		from movhis_reest_mprev
		where num_credito = vnum_credito AND fecha_mov = vfecha;
		
		select nvl(sum(monto),0) into vpag2
		from movhis_reest_mprev
		where  num_credito = vnum_credito AND fecha_mov = vfecha + 1 units day;
		
		select nvl(sum(monto),0) into vpag3
		from movhis_reest_mprev
		where  num_credito = vnum_credito AND fecha_mov = vfecha + 2 units day;
		
		select nvl(sum(monto),0) into vpag4
		from movhis_reest_mprev
		where  num_credito = vnum_credito AND fecha_mov = vfecha + 3 units day;
	
		
		let vtotal =  vpag1 + vpag2 + vpag3 + vpag4;
		if (vestatus = 1 )then	let vresultado = 'COMPLETO';	end if;
		if (vestatus <> 1 )then	let vresultado = 'INCOMPLETO';	end if;
		
		
	insert into reestructura
	values( vnumcte,vnum_credito,vciudad,vestado ,vcorreo_sms ,vnombre1 ,vnombre2 ,vapell_p 	,	
	vapell_m ,	vmora ,vsdo_venc_int_mora  ,vpago_minimo_total ,vpago_min_sin_vdo  ,vpago_vencido ,vpago_req_mail ,	
	0 ,	vfecha_envio ,	vresultado ,vpag1 ,vpag2 ,vpag3 , vpag4 ,vpag5 ,vpag6,vtotal );
	
		
    End ForEach;

	----------------------------------------------------GENERAR ARCHIVO--------------------------------------------------------
	let cnombre = 'rep_envio_email_rees_prev_'||day(today)||LPAD (MONTH(today),2,"0")||year(today)||'.txt';
		let vsql = '';
		let cSql='';
		LET cSQL1 = ' echo " SET ISOLATION TO DIRTY READ; UNLOAD TO ' || TRIM(cruta) || 'archivo_reest.unl' || ' DELIMITER ' || ''''|| cdelimitador || ''''||'';
		LET cSQL2 = " select * from reestructura";
		LET cSQL3 = '">'||TRIM(cRuta)||'archivo_reest.sql';
		LET cSQL = trim(cSQL1) || cSQL2 || trim(cSQL3);
		System cSQL;
	
		LET vsql='chmod 777 '|| TRIM(cRuta)||'archivo_reest.sql';
		System vsql;
		let vsql = '';
		let vsql= 'dbaccess bdicobranza ' || TRIM(cruta)||'archivo_reest.sql';
		system vsql;
		let vsql ='';
		let vsql ='rm '|| TRIM(cruta)||'archivo_reest.sql';
		system vsql;
		let vsql ='';
		let vsql = "sed 's/|$//g' "||TRIM(cruta)||"archivo_reest.unl >>"||TRIM(cruta)|| cnombre;		
		system vsql;
		let vsql ='rm '|| TRIM(cruta)||'archivo_reest.unl ' ;
		system vsql; 

-----------------------
truncate reestructura;
let vfecha = vfecha - 2 units day;
-----------------------------------------------PREVENTIVA SMS-------------------------------------------
	select *
