	select *
	from bdimnsj:mnsjr_trx_batch where id_mensaje in ('CRE_PAGS')
		and date(fecha_hora_registro) = vfecha
	into temp latinia_cre_prevsms;
	
	select mov.num_credito, mov.fecha_mov , mov.monto
	from latinia_cre_prevsms his, bdicred:sd_movhis mov
	where mov.empresa= '001' and mov.fecha_mov >= vfecha and mov.fecha_mov <= date(vfecha) + 4 units day 
		and his.cuenta =  mov.num_credito  
		and mov.codigo_fun in ('033','334','335','336','337','904')	and mov.codigo_ref = 1 	and mov.reversado = 'N'
	into temp movhis_cre_smsprev;
	
	create index idx_movhis_cre_smsprev on movhis_cre_smsprev(num_credito,fecha_mov);   UPDATE STATISTICS medium FOR TABLE movhis_cre_smsprev; 

	
	FOREACH
	
	select his.cliente, his.credito, 
                his.t_celular, his.nombre1, his.nombre2 , his.apell_paterno  ,his.apell_materno , his.pago_venc,
				nvl(his.sdo_venc_int_mora,0) , nvl(his.pago_min,0) , nvl(his.pago_min_sin_vdo,0) , nvl(his.pago_vencido,0) , nvl(his.pago_req_sms,0)
		into  vnumcte,vnum_credito,vcorreo_sms ,vnombre1 ,vnombre2 ,vapell_p 	,	vapell_m 	,	vmora 	,
				vsdo_venc_int_mora  ,vpago_minimo_total ,	vpago_min_sin_vdo  ,vpago_vencido ,vpago_req_mail	
		from bdicobranza:cb_info_administrativa_his his
			where his.num_campania = 17
			and his.fecha_ejecucion = vfecha 
			
		select  est.estado||'-'||est.siglas, cid.numerociudad||'-'||cid.inicialciudad
		into vciudad,vestado 
		from bdinteg:si_direcciones_actual act,  bdinteg:si_estados est,bdinteg:si_catciudades cid
		where act.estado = est.estado
			and act.ciudad = cid.numerociudad 
			and act.numcte = vnumcte
			and act.tipo_dir = 1;	
			
		select limit 1 nvl(estatus,0),  date(fecha_hora_registro) 
			into vestatus,vfecha_envio
		from latinia_cre_prevsms
		where cliente = vnumcte and   cuenta  = vnum_credito;
	
		select nvl(sum(monto),0) into vpag1
		from movhis_cre_smsprev
		where num_credito = vnum_credito AND fecha_mov = vfecha;
		
		select nvl(sum(monto),0) into vpag2
		from movhis_cre_smsprev
		where  num_credito = vnum_credito AND fecha_mov = vfecha + 1 units day;
		
		select nvl(sum(monto),0) into vpag3
		from movhis_cre_smsprev
		where  num_credito = vnum_credito AND fecha_mov = vfecha + 2 units day;
		
		select nvl(sum(monto),0) into vpag4
		from movhis_cre_smsprev
		where  num_credito = vnum_credito AND fecha_mov = vfecha + 3 units day;
		
		select nvl(sum(monto),0) into vpag5
		from movhis_cre_smsprev
		where num_credito = vnum_credito AND fecha_mov = vfecha + 4 units day;
		
		let vtotal =  vpag1 + vpag2 + vpag3 + vpag4 + vpag5;
		if (vestatus = 1 )then	let vresultado = 'COMPLETO';	end if;
		if (vestatus <> 1 )then	let vresultado = 'INCOMPLETO';	end if;
		
		
	insert into credinominas
	values( vnumcte,vnum_credito,vciudad,vestado ,vcorreo_sms ,vnombre1 ,vnombre2 ,vapell_p 	,	
	vapell_m ,	vmora ,vsdo_venc_int_mora  ,vpago_minimo_total ,vpago_min_sin_vdo  ,vpago_vencido ,vpago_req_mail ,	
	0 ,	vfecha_envio ,	vresultado ,vpag1 ,vpag2 ,vpag3 , vpag4 ,vpag5 ,vpag6,vtotal );
	
		
    End ForEach;

--------------------------------------------------------GENERAR ARCHIVO--------------------------------------------------------
	let cnombre = 'rep_envio_sms_creprev_'||day(today)||LPAD (MONTH(today),2,"0")||year(today)||'.txt';
		let vsql = '';
		let cSql='';
		LET cSQL1 = ' echo " SET ISOLATION TO DIRTY READ; UNLOAD TO ' || TRIM(cruta) || 'archivo_credinomina.unl' || ' DELIMITER ' || ''''|| cdelimitador || ''''||'';
		LET cSQL2 = " select * from credinominas";
		LET cSQL3 = '">'||TRIM(cRuta)||'archivo_credinomina.sql';
		LET cSQL = trim(cSQL1) || cSQL2 || trim(cSQL3);
		System cSQL;
	
		LET vsql='chmod 777 '|| TRIM(cRuta)||'archivo_credinomina.sql';
		System vsql;
		let vsql = '';
		let vsql= 'dbaccess bdicobranza ' || TRIM(cruta)||'archivo_credinomina.sql';
		system vsql;
		let vsql ='';
		let vsql ='rm '|| TRIM(cruta)||'archivo_credinomina.sql';
		system vsql;
		let vsql ='';
		let vsql = "sed 's/|$//g' "||TRIM(cruta)||"archivo_credinomina.unl >>"||TRIM(cruta)|| cnombre;		
		system vsql;
		let vsql ='rm '|| TRIM(cruta)||'archivo_credinomina.unl ' ;
		system vsql; 
------------------------------------------	
truncate credinominas;

	CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '03') RETURNING P_COD_RET;
    RETURN P_COD_RET;

end;
end procedure;

CREATE PROCEDURE "informix".sp_rep_envio_mail_compromiso()
returning char (6);
------------------------------------------------------------------------------------
--Maria Elizabeth Anzures Ibarguen
--08-27-2012
--crea archivo de sms y email enviados


----DATOS QUE VAN EN LA TABLA
DEFINE  vnumcte			char(20);
DEFINE  vnum_credito 	char(20);
DEFINE	vciudad 		char(6) ;
DEFINE	vestado 		char(6);
DEFINE	vcorreo_sms 	char(100) ;
DEFINE	vnombre1 		char(20) ;
DEFINE	vnombre2 		char(20);
DEFINE	vapell_p 		char(30) ;
DEFINE	vapell_m 		char(30);
DEFINE	vmora 			smallint;
DEFINE	vsdo_venc_int_mora  DECIMAL(18,2);
DEFINE	vpago_minimo_total  DECIMAL(18,2);
DEFINE	vpago_min_sin_vdo   DECIMAL(18,2) ;
DEFINE	vpago_vencido 		DECIMAL(18,2);
DEFINE	vpago_req_mail		DECIMAL(18,2);
DEFINE	vcosto 				decimal (18,2) ;
DEFINE	vfecha_envio 		datetime year to second;
DEFINE	vresultado 			char(10);
DEFINE	vpag1 decimal (18,2); DEFINE vpag2 decimal (18,2);
DEFINE	vpag3 decimal (18,2); DEFINE vpag4 decimal (18,2);
DEFINE	vpag5 decimal (18,2); DEFINE vpag6 decimal (18,2);
DEFINE	vtotal decimal (18,2);
DEFINE vestatus smallint;
--VARIABLES PARA CAPTURAR ERRORES
DEFINE SQL_ERR                INTEGER;
DEFINE ISAM_ERR               INTEGER;
DEFINE ERROR_INFO             VARCHAR(80);
DEFINE P_COD_RET              VARCHAR(5);
DEFINE P_MENSAJE              VARCHAR(80);
DEFINE vproceso				  CHAR (4);
DEFINE cMensaje				  CHAR(80);

---VARIABLES PARA QUERYS
DEFINE cSQL                 CHAR(2204);
DEFINE cSQL1                CHAR(200);
DEFINE cSQL2                CHAR(2004);
DEFINE cSQL3                CHAR(100);
DEFINE vsql					CHAR(2204);
DEFINE sPaso				integer;
DEFINE cruta                CHAR(100);
DEFINE cdelimitador         CHAR(1);
DEFINE cnomarchivo          CHAR(100);
DEFINE cnomarchivo1			CHAR(100);
DEFINE cnombre				CHAR(100);
define vfecha				DATE;
define vfecha1				DATE;



BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, ERROR_INFO
        LET P_COD_RET = SQL_ERR;
        LET P_MENSAJE = ERROR_INFO;
		 CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '02')RETURNING P_COD_RET;	
	RETURN P_COD_RET;
    END EXCEPTION;

----INICIALIZAN VARIABLES QUE VAN EN LA TABLA

LET  vnumcte 		="";
LET  vnum_credito	="";
LET	vciudad 		="";
LET	vestado 		="";
LET	vcorreo_sms 	="";
LET	vnombre1 		="";
LET	vnombre2 		="";
LET	vapell_p 		="";
LET	vapell_m 		="";
LET	vmora 			=0;
LET	vsdo_venc_int_mora  =0;
LET	vpago_minimo_total  =0;
LET	vpago_min_sin_vdo   =0;
LET	vpago_vencido 		=0;
LET	vpago_req_mail 		=0;
LET	vcosto 				=0;
LET	vfecha_envio 		=date(1);
LET	vresultado 			="";
LET	vpag1 =0; LET vpag2 =0;
LET	vpag3 =0; LET vpag4 =0;
LET	vpag5 =0; LET vpag6 =0;
LET	vtotal =0;
let vestatus =0;
---INICIALIZAN VARIABLES PARA QUERYS
LET  cSql			="";
LET cSQL1           = "";
LET cSQL2           = "";
LET cSQL3           = "";
let vsql			= '';
Let P_cod_ret		= "00000";
LET vproceso		='2100';
LET cMensaje   		= 'PROCESO EXITOSO';
let sPaso 			=0;
let cruta      		='';
let cdelimitador 	='';
let cnomarchivo  	='';
let cnomarchivo1 	='';
let cnombre 		='';
let vfecha			= date(1);
let vfecha1			= date(1);



--  Set debug file to 'comprmisos.out';
--  trace on;
    CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '01')RETURNING P_COD_RET;	
	
	SELECT COUNT(tabid)INTO sPaso FROM systables WHERE tabname= 'compromisos';
            IF NVL(sPaso,0) > 0 THEN
                DROP TABLE compromisos;
            END IF;

	create table compromisos
	(numcte char(20), num_credito char(20),
	ciudad char(6), estado char(6),
	correo_sms char(100), 
	nombre1 char(20), nombre2 char(20),
	apell_p char(30), apell_m char(30),
	mora smallint,
	sdo_venc_int_mora  DECIMAL(18,2),pago_minimo_total   DECIMAL(18,2),
	pago_min_sin_vdo   DECIMAL(18,2), pago_vencido DECIMAL(18,2),
	pago_req_mail DECIMAL(18,2),
	costo decimal (18,2), fecha_envio date,
	resultado char(10),
	pag1 decimal (18,2),pag2 decimal (18,2),
	pag3 decimal (18,2),pag4 decimal (18,2),
	pag5 decimal (18,2),pag6 decimal (18,2),
	total decimal (18,2)
	);
	
	--Obtener caracter delimitador
	SELECT trim(valor_alfabetico)
	INTO cdelimitador
	FROM bdicobranza:cb_param_campania
	WHERE empresa = '001'
	AND tipo_campania = 1
	AND grupo_parametro = 'ARCHIVOS'
	AND num_parametro = 2;
	--Valida que exista el caracter
	IF NVL(cDelimitador,'') = '' THEN
        LET P_COD_RET= '104004';
        SELECT descripcion
        INTO cMensaje
        FROM cb_errores
        WHERE origen = 3
        AND codigo_error = P_COD_RET;
	
        IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
        END IF;

        CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '01')RETURNING P_COD_RET;	
        Return P_COD_RET;
	END IF;
		
	select trim(valor_alfabetico) into cruta
	from bdicobranza:cb_param_campania 
	where tipo_campania = 1
	and grupo_parametro = 'ARCHIVOS'
	and num_parametro = 34;
	--Valida que exista la carpeta
	IF NVL (cruta,'') = '' THEN
        LET P_COD_RET= '104005';
        SELECT descripcion
        INTO cMensaje
        FROM cb_errores
        WHERE origen = 3
        AND codigo_error = P_COD_RET;
	
        IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
        END IF;

         CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '01')RETURNING P_COD_RET;	
	     Return P_COD_RET;
	END IF;
	
	select fecha_hoy into vfecha from bdicred:sd_fechas where empresa = '001';
	let vfecha = vfecha - 5 units day;
	
    set isolation to dirty read;
    set lock mode to wait 3;
	
	select mov.num_credito, mov.fecha_mov , mov.monto
	from bdimnsj:mnsjr_trx_batch bat, bdicred:sd_movhis mov
	where mov.empresa= '001' and mov.fecha_mov >= vfecha and mov.fecha_mov <= date(vfecha) + 4 units day 
		and bat.cuenta =  mov.num_credito  
		and mov.codigo_fun in ('033','334','335','336','337','904')	and mov.codigo_ref = 1 	and mov.reversado = 'N'
		and bat.id_mensaje in ('COMPAC_ADE','COMPAC_SIN','COMPAC_PAG','COMPAC_FRA')
		and date(bat.fecha_hora_registro) =  vfecha
	into temp mov_compromiso;
	
	create index idx_mov_compromiso on mov_compromiso(num_credito,fecha_mov);   UPDATE STATISTICS medium FOR TABLE mov_compromiso; 

	
	FOREACH
		select his.numcte, his.num_credito,  est.estado||'-'||est.siglas, cid.numerociudad||'-'||cid.inicialciudad,
                his.email, cte.nombre1, cte.nombre2 , cte.apell_paterno  ,cte.apell_materno , his.pagos_vencidos,
				nvl(his.sdo_venc_int_mora,0) , nvl(his.pago_minimo,0) , nvl(his.pago_min_sin_venc,0) , nvl(his.pago_venc,0) , nvl(his.monto_convenio,0),
				bat.fecha_hora_registro, nvl(bat.estatus,0)
		into  vnumcte,vnum_credito,vciudad,vestado ,vcorreo_sms ,vnombre1 ,vnombre2 ,vapell_p 	,	vapell_m 	,	vmora 	,
				vsdo_venc_int_mora  ,vpago_minimo_total ,	vpago_min_sin_vdo  ,vpago_vencido ,vpago_req_mail,
				vfecha_envio, vestatus 	
		from bdicobranza:cb_mail_cliente_his his, bdinteg:si_cliente cte,
			bdinteg:si_direcciones_actual act , bdinteg:si_estados est,bdinteg:si_catciudades cid,
			bdimnsj:mnsjr_trx_batch bat
		where his.empresa = cte.empresa and his.numcte = cte.numcte
			and his.numcte = bat.cliente and his.num_credito = bat.cuenta 
			and his.numcte = act.numcte
			and act.estado = est.estado
			and act.ciudad = cid.numerociudad
			and act.tipo_dir = 1
			and his.tipo_mensaje = 3
			and bat.id_mensaje in ('COMPAC_ADE','COMPAC_SIN','COMPAC_PAG','COMPAC_FRA')
			and his.fecha_compac = vfecha 
		
		select nvl(sum(monto),0) into vpag1
		from mov_compromiso
		where  num_credito = vnum_credito and fecha_mov = vfecha;
			
		select nvl(sum(monto),0) into vpag2
		from mov_compromiso
		where  num_credito = vnum_credito and fecha_mov = vfecha + 1 units day;
			
		
		select nvl(sum(monto),0) into vpag3
		from mov_compromiso 
		where num_credito = vnum_credito and fecha_mov = vfecha + 2 units day;
		
		select nvl(sum(monto),0) into vpag4
		from mov_compromiso 
		where num_credito = vnum_credito and fecha_mov = vfecha + 3 units day;
		
		select nvl(sum(monto),0) into vpag5
		from mov_compromiso 
		where  num_credito = vnum_credito and fecha_mov = vfecha + 4 units day;
		
		let vtotal =  vpag1 + vpag2 + vpag3 + vpag4 + vpag5;
		if (vestatus = 1 )then	let vresultado = 'COMPLETO';	end if;
		if (vestatus <> 1 )then	let vresultado = 'INCOMPLETO';	end if;
		
		
	insert into compromisos
	values( vnumcte,vnum_credito,vciudad,vestado ,vcorreo_sms ,vnombre1 ,vnombre2 ,vapell_p 	,	
	vapell_m ,	vmora ,vsdo_venc_int_mora  ,vpago_minimo_total ,vpago_min_sin_vdo  ,vpago_vencido ,vpago_req_mail ,	
	0 ,	vfecha_envio ,	vresultado ,vpag1 ,vpag2 ,vpag3 , vpag4 ,vpag5 ,vpag6,vtotal );
	
	LET  vnumcte 		="";LET  vnum_credito	="";LET	vciudad 		="";LET	vestado 		="";LET	vcorreo_sms 	="";LET	vnombre1 		="";
	LET	vnombre2 		="";LET	vapell_p 		="";LET	vapell_m 		="";LET	vmora 			=0;LET	vsdo_venc_int_mora  =0;
	LET	vpago_minimo_total  =0;LET	vpago_min_sin_vdo   =0;LET	vpago_vencido 		=0;LET	vpago_req_mail 		=0;
	LET	vfecha_envio 		=date(1);LET	vresultado 			="";LET	vpag1 =0; LET vpag2 =0;LET	vpag3 =0; LET vpag4 =0;
	LET	vpag5 =0; LET vpag6 =0;LET	vtotal =0;let vestatus =0;
		
    End ForEach;

--------------------------------------------------------GENERAR ARCHIVO--------------------------------------------------------
--	let cruta = '/informix/eli/';
	let cnombre = 'rep_envio_email_compromiso_'||day(today)||LPAD (MONTH(today),2,"0")||year(today)||'.txt';
		let vsql = '';
		let cSql='';
		LET cSQL1 = ' echo " SET ISOLATION TO DIRTY READ; UNLOAD TO ' || TRIM(cruta) || 'archivo_compromiso.unl' || ' DELIMITER ' || ''''|| cdelimitador || ''''||'';
		LET cSQL2 = " select * from compromisos";
		LET cSQL3 = '">'||TRIM(cRuta)||'archivo_compromiso.sql';
		LET cSQL = trim(cSQL1) || cSQL2 || trim(cSQL3);
		System cSQL;
	
		LET vsql='chmod 777 '|| TRIM(cRuta)||'archivo_compromiso.sql';
		System vsql;
		let vsql = '';
		let vsql= 'dbaccess bdicobranza ' || TRIM(cruta)||'archivo_compromiso.sql';
		system vsql;
		let vsql ='';
		let vsql ='rm '|| TRIM(cruta)||'archivo_compromiso.sql';
		system vsql;
		let vsql ='';
		let vsql = "sed 's/|$//g' "||TRIM(cruta)||"archivo_compromiso.unl >>"||TRIM(cruta)|| cnombre;		
		system vsql;
		let vsql ='rm '|| TRIM(cruta)||'archivo_compromiso.unl ' ;
		system vsql; 
------------------------------------------

	
	CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '03') RETURNING P_COD_RET;
    RETURN P_COD_RET;

end;
end procedure;

create procedure "informix".sp_rep_convenios()
returning VARCHAR(6);


DEFINE SQL_ERR            INTEGER;
DEFINE ISAM_ERR           INTEGER;
DEFINE ERROR_INFO         VARCHAR(80);
DEFINE P_COD_RET          VARCHAR(6);
DEFINE P_MENSAJE          VARCHAR(80);
DEFINE cProceso  char(4);
DEFINE cMensaje  char (100);
DEFINE cCod_ret  smallint;
DEFINE sPaso				integer;

DEFINE cSQL                 CHAR(2204);
DEFINE vsql					CHAR(2204);
DEFINE cSQL1                CHAR(200);
DEFINE cSQL2                CHAR(2004);
DEFINE cSQL3                CHAR(100);
DEFINE cruta                CHAR(100);
DEFINE cdelimitador         CHAR(1);
DEFINE cnombre          CHAR(100);

DEFINE pnumcredito   char(20);
DEFINE pnumcte		 char(20);
DEFINE vstatus 		char(15);
DEFINE pfechacompac  DATE;
DEFINE pfecha_venci  DATE;
DEFINE vplazo		smallint;
DEFINE pimporte      DECIMAL(18,2);
define vmSuma1 		 DECIMAL(18,2);
define vmSuma2 		 DECIMAL(18,2);
DEFINE vpago_venc	 smallint;
DEFINE vpago_venc2	 smallint;
DEFINE vfecha_envio	date;
DEFINE vstatus_envio	char(15);
DEFINE pfechahoy     date;
define vfecha_ant	date;
define vfecha	date;


	let P_COD_RET = '111111';
	let cCod_ret = '';
    let cMensaje = '';
	let cproceso = '2074';
	let SQL_ERR            = 0;
	let ISAM_ERR           = 0;
	let ERROR_INFO         = '';
	let P_MENSAJE          = '';
	let sPaso 			=0;
	
let cSQL           = '';
let vsql			 = '';
let cSQL1           = '';
let cSQL2           = '';
let cSQL3            = '';
let cruta            = '';
let cdelimitador    = '';
let cnombre           = '';
	
let pnumcredito  	 = '';
let pnumcte			= '';
let vstatus 		= '';
let pfechacompac 	 =DATE(1);
let pfecha_venci 	 =DATE(1);
let vplazo			 = 0;
let pimporte    	   = 0;
let vmSuma1 		 = 0;
let vmSuma2 		 = 0;
let vpago_venc		 = 0;
let vpago_venc2	 	 = 0;
let vfecha_envio		= date(1);
let vstatus_envio	= '';
let pfechahoy   	 = date(1);
let vfecha_ant 		 = date(1);
let vfecha	 		 = date(1);
	

BEGIN 
  
    ON exception SET SQL_ERR, ISAM_ERR, ERROR_INFO
    CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', cproceso, P_COD_RET, P_MENSAJE, '02')
        RETURNING P_COD_RET;
        LET P_COD_RET = SQL_ERR;
        LET P_MENSAJE = ERROR_INFO;
     RETURN P_COD_RET;
     END exception;
	 
-- SET DEBUG FILE TO 'compacrep.out';
-- TRACE ON;	
	
	SELECT COUNT(tabid)INTO sPaso FROM systables WHERE tabname= 'convenios';
            IF NVL(sPaso,0) > 0 THEN
                DROP TABLE convenios;
            END IF;
			
	create table convenios
	( numcte		char(20),
	status 		char(15),
	fechacompac  	DATE,
	fecha_venci  	DATE,
	plazo			smallint,
	importe     	DECIMAL(18,2),
	mSuma1 		DECIMAL(18,2),
	mSuma2 		DECIMAL(18,2),
	pago_venc	 	smallint,
	pago_venc2	 	smallint,
	fecha_envio		date,
	status_envio	char(15));
	
	--Obtener caracter delimitador
	SELECT trim(valor_alfabetico)
	INTO cdelimitador
	FROM bdicobranza:cb_param_campania
	WHERE empresa = '001'
	AND tipo_campania = 1
	AND grupo_parametro = 'ARCHIVOS'
	AND num_parametro = 2;
	--Valida que exista el caracter
	IF NVL(cDelimitador,'') = '' THEN
        LET P_COD_RET= '104004';
        SELECT descripcion
        INTO cMensaje
        FROM cb_errores
        WHERE origen = 3
        AND codigo_error = P_COD_RET;
	        IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
			END IF;
        CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', cproceso, cCod_ret, cMensaje, '01')RETURNING P_COD_RET;	
        Return P_COD_RET;
	END IF;
		
	select trim(valor_alfabetico) into cruta
	from bdicobranza:cb_param_campania 
	where tipo_campania = 1
	and grupo_parametro = 'ARCHIVOS'
	and num_parametro = 34;
	--Valida que exista la carpeta
	IF NVL (cruta,'') = '' THEN
        LET P_COD_RET= '104005';
        SELECT descripcion
        INTO cMensaje
        FROM cb_errores
        WHERE origen = 3
        AND codigo_error = P_COD_RET;
	        IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
			END IF;
         CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', cproceso, cCod_ret, cMensaje, '01')RETURNING P_COD_RET;	
	     Return P_COD_RET;
	END IF;
	
    Select Fecha_Hoy
        Into pfechahoy 
    From bdicred:sd_fechas
    Where empresa = '001'; 

--let pfechahoy = '07-03-2013'; ---pruebas-------------********************************

	let vfecha_ant = pfechahoy - 3 units day;
	let vfecha = pfechahoy - 1 units month;
	let vfecha = mdy(month(vfecha),day(01),year(vfecha));
	
    CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', cproceso, cCod_ret, cMensaje, '01')
        RETURNING P_COD_RET;

	set isolation to dirty read;

	select cliente,cuenta,decode(estatus , 1,'ENVIADO' ,'NO ENVIADO' )estatus, date(fecha_hora_registro)fecha_hora_registro
	from bdimnsj:mnsjr_trx_batch
	where id_mensaje = 'TC_COMPACS' and date(fecha_hora_registro) <= vfecha_ant and  date(fecha_hora_registro) >= vfecha
	into temp batch;
		
	insert into batch 
	select cliente,cuenta,decode(estatus , 1,'ENVIADO' ,'NO ENVIADO' )estatus, date(fecha_hora_registro)fecha_hora_registro
	from bdimnsj:mnsjr_trx_batch_his
	where id_mensaje = 'TC_COMPACS' and date(fecha_hora_registro) <= vfecha_ant and  date(fecha_hora_registro) >= vfecha;
	
		create index idx_batch on batch(cliente,cuenta);   UPDATE STATISTICS medium FOR TABLE batch; 
	
			
	foreach 
		select bat.cuenta,bat.cliente,decode(c.flag_pago,1,'CUMPLIDO','NO CUMPLIDO'),c.fecha_compac,c.fecha_insert,c.plazo,c.importe,
		bat.fecha_hora_registro,bat.estatus 
		into pnumcredito,pnumcte,vstatus,pfechacompac,pfecha_venci,vplazo,pimporte,vfecha_envio,vstatus_envio
		from batch bat, bdicobranza:cb_compac_his c
		where c.empresa = '001' and bat.cuenta = c.numcuenta 
				and fecha_insert >=  vfecha + 2 units day and fecha_insert <= pfechahoy - 1 units day
		
		select pago_venc into vpago_venc
		from bdicobranza:cb_info_administrativa_his 
		where empresa = '001' and credito = pnumcredito	and num_campania = 15 and fecha_ejecucion = vfecha_envio;
		
		select mto_fin_ven_trasp into vpago_venc2 
		from bdicred:sd_maesdos where empresa = '001' and num_credito = pnumcredito; 
		
		-- SUMA DE LOS PAGOS DE LOS DÍAS ANTERIORES AL ENVI0(sc_movhis)  POR VENTANILLA, INTERNET y CHEQUES.
		SELECT {+INDEX(bdicred:sd_movhis inx_movhis)} NVL(SUM(monto),0) INTO vmSuma1 
		FROM bdicred:sd_movhis 
		WHERE empresa = '001' and num_credito = pnumcredito and codigo_fun in ('033', '334', '335', '336', '337') and codigo_ref = 1
			and fecha_mov >= pfechacompac and fecha_mov <= pfecha_venci  and reversado = 'N';	
			
		-- SUMA DE LOS PAGOS DE LOS DÍAS POSTERIOES AL ENVIO (sc_movhis)  POR VENTANILLA, INTERNET y CHEQUES.
		SELECT {+INDEX(bdicred:sd_movhis inx_movhis)} NVL(SUM(monto),0) INTO vmSuma2 
		FROM bdicred:sd_movhis 
		WHERE empresa = '001' and num_credito = pnumcredito and codigo_fun in ('033', '334', '335', '336', '337') and codigo_ref = 1
			and fecha_mov >= pfecha_venci - 2 units day and fecha_mov <= pfecha_venci and reversado = 'N';
			
		INSERT INTO convenios (numcte,status,fechacompac,fecha_venci,plazo,importe,mSuma1,mSuma2,pago_venc,pago_venc2,fecha_envio,status_envio)
		VALUES(pnumcte,vstatus,pfechacompac,pfecha_venci,vplazo,pimporte,vmSuma1,vmSuma2,vpago_venc,vpago_venc2,vfecha_envio,vstatus_envio);

	end foreach 
	
	--------------------------------------------------------GENERAR ARCHIVO--------------------------------------------------------
-- pruebas ruta*********************************
--let cruta = '/informix/eli/';
--**********************************************
	
	let cnombre = 'vencimiento_previo_convenio_'||day(today)||LPAD (MONTH(today),2,"0")||year(today)||'.txt';
		let vsql = '';
		let cSql='';
		LET cSQL1 = ' echo " SET ISOLATION TO DIRTY READ; UNLOAD TO ' || TRIM(cruta) || 'archivo_convenios.unl' || ' DELIMITER ' || ''''|| cdelimitador || ''''||'';
		LET cSQL2 = " select * from convenios";
		LET cSQL3 = '">'||TRIM(cRuta)||'archivo_convenios.sql';
		LET cSQL = trim(cSQL1) || cSQL2 || trim(cSQL3);
		System cSQL;
	
		LET vsql='chmod 777 '|| TRIM(cRuta)||'archivo_convenios.sql';
		System vsql;
		let vsql = '';
		let vsql= 'dbaccess bdicobranza ' || TRIM(cruta)||'archivo_convenios.sql';
		system vsql;
		let vsql ='';
		let vsql ='rm '|| TRIM(cruta)||'archivo_convenios.sql';
		system vsql;
		let vsql ='';
		let vsql = "sed 's/|$//g' "||TRIM(cruta)||"archivo_convenios.unl >>"||TRIM(cruta)|| cnombre;		
		system vsql;
		let vsql ='rm '|| TRIM(cruta)||'archivo_convenios.unl ' ;
		system vsql; 
	 	
	CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', cproceso, cCod_ret, cMensaje, '03')
    RETURNING P_COD_RET;
	
end
RETURN P_COD_RET;
END PROCEDURE;

create procedure "informix".sp_guardarcompromisosacuerdoscat(pempresa char(3), prutaarchivos char(255), pplazominimo smallint, pplazomaximo smallint)
    returning char (6), char(200)
    
    ---Elaborado por: Lorenzo Ibarra García
    --Fecha: 15-10-2009
    --Objetivo: Realizar la carga de archivos de texto que contienen compromisos y acuerdos generados por el CAT.

    --Declaracion de variables
    DEFINE v_sqlerr             INTEGER;
    DEFINE v_isam_err           INTEGER;
    DEFINE v_error_info         CHAR(80);
    DEFINE cCodigoRetorno       CHAR(6);
    DEFINE cMensajeProceso      CHAR(200);
    DEFINE cNombreProceso       CHAR(30);
    DEFINE tFechaHoy            DATE;
    DEFINE cSQL                 CHAR(250);
    DEFINE cRegistroArchivos    LVARCHAR(500);
    DEFINE bExisteArchivo       BOOLEAN;
    DEFINE cTipoCompAc          CHAR(1);
    DEFINE cSucursal            CHAR(4);
    DEFINE iOrigen              smallint;
    DEFINE iImporteSinPunto     INTEGER;
    DEFINE cRetornoSPgraga      CHAR(6);
    DEFINE bPlazoEnRango        BOOLEAN;
    DEFINE bImporteEnRango      BOOLEAN;
    DEFINE iCodigoErrorInsert   SMALLINT;
    DEFINE iNumRegProcesado     SMALLINT;
    DEFINE bTransaccionIniciada BOOLEAN;
    DEFINE tFechaLlamadaMDY     DATE;
    --datos tabla temporal
    DEFINE iEmpleado INTEGER;
    DEFINE cNumCliente CHAR(20);
    DEFINE cNumCuenta CHAR(20);
    DEFINE cPlazo CHAR(2);
    DEFINE dImporte DECIMAL(14,2);
    DEFINE iPagosVencidos SMALLINT;
    DEFINE cFechaLlamada CHAR(10);

    --SET DEBUG FILE TO "/respaldosbd/Lorenzo/sp_GuardarCompromisosAcuerdosCAT.out";
    --TRACE ON; 
    
    --Inicializacion de variables
    LET v_sqlerr          = 0;
    LET v_isam_err        = 0;
    LET v_error_info      = '';
    LET cCodigoRetorno    = '11111';
    LET cMensajeProceso   = 'PROCESO INICIALIZADO';
    LET cNombreProceso    = '';
    LET tFechaHoy = '01-01-1900';
    LET cSQL = '';
    LET bExisteArchivo = 'f';
    LET cTipoCompAc = '';
    LET cSucursal = '5003';
    LET iOrigen = 3;
    LET iImporteSinPunto = 0;
    LET cRetornoSPgraga = '';
    LET bPlazoEnRango = 'f';
    LET bImporteEnRango = 'f';
    LET iCodigoErrorInsert = 1;
    LET iNumRegProcesado = 0;
    LET bTransaccionIniciada = 'f';
    LET tFechaLlamadaMDY = '01-01-1900';
    --datos tabla temporal    
    LET iEmpleado = 0;
    LET cNumCliente = '';
    LET cNumCuenta = '';
    LET cPlazo = '';
    LET dImporte = 0;
    LET iPagosVencidos = 0;
    LET cFechaLlamada = '';

BEGIN
    ON EXCEPTION SET v_sqlerr, v_isam_err, v_error_info
        IF v_sqlerr != 0 THEN
            --verificar si la transacción ya fue iniciada
            IF bTransaccionIniciada = 't' THEN
                ROLLBACK WORK;
            END IF;
            
            --borrar tablas temporales en caso de que existan
            IF EXISTS (SELECT tabname FROM systables WHERE tabname = 'archivosacucomp_tmp') THEN
                DROP TABLE archivosacucomp_tmp;
            END IF
            IF EXISTS (SELECT tabname FROM systables WHERE tabname = 'datosarchivo_tmp') THEN
                DROP TABLE datosarchivo_tmp;
            END IF;
            
            LET cCodigoRetorno = v_sqlerr;
            LET cMensajeProceso = v_error_info;
            
            --insertar control de procesos
            INSERT INTO cb_bitacora_cob (proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc) 
            VALUES (cNombreProceso, cCodigoRetorno, cMensajeProceso, USER, (SELECT DBINFO('utc_to_datetime', sh_curtime) from sysmaster:sysshmvals),
                (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals), iNumRegProcesado);
            
            RETURN cCodigoRetorno, cMensajeProceso;
        END IF;
    END EXCEPTION;
    
    --verificar que los parámetros sean correctos
    IF TRIM(pEmpresa) = '' OR pEmpresa IS NULL OR 
        TRIM(pRutaArchivos) = '' OR pRutaArchivos IS NULL 
        OR pPlazoMinimo < 0 OR pPlazoMinimo IS NULL 
        OR pPlazoMaximo < 0 OR pPlazoMaximo IS NULL THEN
        LET cCodigoRetorno    = '00001';
        LET cMensajeProceso   = 'LOS PARAMETROS NO SON CORRECTOS';
        RETURN cCodigoRetorno, cMensajeProceso;
    END IF;
    
    LET tFechaHoy = CURRENT;
    
    --armar el nombre del archivo
    LET cNombreProceso = 'compac_trad_'|| TO_CHAR(tFechaHoy,'%d%m%Y') ||'.txt';
    
    --si el archivo existe y ya fue procesado correctamente salir de la ejecución
    IF EXISTS(SELECT proceso FROM cb_bitacora_cob WHERE cod_ret = '00000' AND proceso = cNombreProceso) THEN
        LET cCodigoRetorno    = '00002';
        LET cMensajeProceso   = 'EL ARCHIVO YA FUE PROCESADO';
        RETURN cCodigoRetorno, cMensajeProceso;
    END IF;
    
    --obtener el último registro procesado de la bitacora para cuando marque error y se vuelva a ejecutar el proceso
    SELECT num_ult_reg_proc
    INTO iNumRegProcesado
    FROM cb_bitacora_cob 
    WHERE cod_ret NOT IN('00000' ,'11111')
    AND proceso = cNombreProceso
    AND hora_insert = (SELECT MAX(hora_insert) FROM cb_bitacora_cob WHERE cod_ret NOT IN('00000' ,'11111')
                        AND proceso = cNombreProceso);
    
    IF iNumRegProcesado IS NULL THEN
        LET iNumRegProcesado = 0;
    END IF;
    
    --insertar control de procesos
    INSERT INTO cb_bitacora_cob (proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc) 
    VALUES (cNombreProceso, cCodigoRetorno, cMensajeProceso, USER, (SELECT DBINFO('utc_to_datetime', sh_curtime) from sysmaster:sysshmvals),
        (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals), iNumRegProcesado);
    
    --buscar el archivo en la ruta proporcionada
    --borrar la tabla temporal en caso de que exista
	IF EXISTS (SELECT tabname FROM systables WHERE tabname = 'archivosacucomp_tmp') THEN
		DROP TABLE archivosacucomp_tmp;
	END IF

	--crear la tabla de temporal
	CREATE TABLE archivosacucomp_tmp (linea LVARCHAR(500));

	LET cSQL = '';
	--guarda los nombres de los archivos existentes en la ruta proporcionada en listaarchivos.car
	LET cSQL = 'ls ' || TRIM(pRutaArchivos) || ' > ' || TRIM(pRutaArchivos) || 'listaarchivos.car';
	SYSTEM cSQL;

	LET cSQL = '';
	--guarda el query del load en el archivo .sql
	LET cSQL = 'echo "LOAD FROM ' || TRIM(pRutaArchivos) || 'listaarchivos.car' || ' INSERT INTO archivosacucomp_tmp" > '|| TRIM(pRutaArchivos) || 'Temporal.sql';
	SYSTEM cSQL;

	LET cSQL = '';
	--ejecuta las instrucciones que estan dentro del archivo .sql
	LET cSQL = 'dbaccess bdicobranza ' || TRIM(pRutaArchivos) || 'Temporal.sql';
	SYSTEM cSQL;

	SET LOCK MODE TO WAIT 3;
	SET ISOLATION TO DIRTY READ;
	--ciclo para buscar el nombre del archivo
	FOREACH
		SELECT linea INTO cRegistroArchivos FROM archivosacucomp_tmp
		IF cRegistroArchivos = cNombreProceso THEN
			LET bExisteArchivo = 't';
			EXIT FOREACH;
		END IF;
	END FOREACH;
    
    --borrar la tabla temporal
	DROP TABLE archivosacucomp_tmp;
    
    --si el archivo no existe terminar el proceso y actualizar la bitacora
    IF bExisteArchivo = 'f' THEN
        LET cMensajeProceso   = 'PROCESO INICIALIZADO NO EXISTE ARCHIVO PARA PROCESAR';
        
        UPDATE cb_bitacora_cob SET mensaje = cMensajeProceso
        WHERE proceso = cNombreProceso
        AND cod_ret = '11111';
        
        RETURN cCodigoRetorno, cMensajeProceso;
    END IF;
    
    --guardar los archivos temporalmente
    --borrar la tabla temporal en caso de que exista
	IF EXISTS (SELECT tabname FROM systables WHERE tabname = 'datosarchivo_tmp') THEN
		DROP TABLE datosarchivo_tmp;
	END IF;

	--crear la tabla de temporal para cargar el archivo
	CREATE TABLE datosarchivo_tmp (Empleado INTEGER,
                                   NumCliente CHAR(20),
                                   NumCuenta CHAR(20),
                                   Plazo CHAR(2),
                                   Importe DECIMAL(14,2),
                                   PagosVencidos SMALLINT,
                                   FechaLlamada CHAR(10)); --este campo va como texto para despues aplicar el formato de fecha correcto
    
    --cargar los datos del archivo a la tabla temporal
    Let  cSQL = 'echo "load from '||TRIM(pRutaArchivos) || TRIM(cNombreProceso) ||
                ' delimiter ''	'' insert into datosarchivo_tmp; " > '||TRIM(pRutaArchivos) ||'query.sql';
    System cSQL;
    Let cSQL = 'dbaccess bdicobranza '||TRIM(pRutaArchivos) ||'query.sql';
    System cSQL;
    
    --guardar los datos en las tablas que les corresponde
    FOREACH WITH HOLD
        SELECT SKIP iNumRegProcesado Empleado, NumCliente, NumCuenta, Plazo, Importe, PagosVencidos, FechaLlamada
        INTO iEmpleado, cNumCliente, cNumCuenta, cPlazo, dImporte, iPagosVencidos, cFechaLlamada
        FROM datosarchivo_tmp
        
        LET tFechaLlamadaMDY = MDY(SUBSTR(cFechaLlamada,4,2), SUBSTR(cFechaLlamada,1,2), SUBSTR(cFechaLlamada,7,4));
        LET cNumCliente = LPAD(TRIM(cNumCliente),9,0);
        
        --verificar si el plazo y el importe estan dentro del rango correcto
        IF dImporte > 0 THEN
            LET bImporteEnRango = 't';
        ELSE
            LET bImporteEnRango = 'f';
            LET iCodigoErrorInsert = 4;
        END IF;
        IF cPlazo >= pPlazoMinimo AND cPlazo <= pPlazoMaximo THEN
            LET bPlazoEnRango = 't';
        ELSE
            LET bPlazoEnRango = 'f';
            LET iCodigoErrorInsert = 3;
        END IF;
        
        IF bPlazoEnRango = 't' AND bImporteEnRango = 't' THEN
            --verificar si es un compromiso o acuerdo
            IF iPagosVencidos <= 3 THEN
                LET cTipoCompAc = '1';
            ELSE
                LET cTipoCompAc = '2';
            END IF;
            --si ya existe el registro que se va a insertar en la cb_compac insertarlo en la cb_compac_error
            IF NOT EXISTS(SELECT empresa
                            FROM cb_compac 
                            WHERE empresa = pEmpresa 
                            AND empleado_captura = iEmpleado 
                            AND numcliente = cNumCliente
                            AND numcuenta = cNumCuenta
                            AND plazo = cPlazo
                            AND importe = dImporte
                            AND tipo_compac = cTipoCompAc
                            AND efectuo_compac = iEmpleado 
                            AND fecha_compac = tFechaLlamadaMDY ) THEN
                            
                --quitar el punto decimal al importe, ya que el SP lo recive como integer
                LET iImporteSinPunto = dImporte * 100;
                
                --insertar en la tabla cb_compac
                EXECUTE PROCEDURE sp_grabacompromisosacuerdos (pEmpresa, cSucursal, iOrigen, iEmpleado, cNumCliente,
                    cNumCuenta, cPlazo, iImporteSinPunto, cTipoCompAc, iEmpleado, '', tFechaLlamadaMDY)
                INTO cRetornoSPgraga;
                
                --si ocurrio un error guardar en la tabla cb_compac_error
                IF cRetornoSPgraga <> '000' AND cRetornoSPgraga <> '001' THEN
                    IF cRetornoSPgraga = '003' THEN --falta algun parámetro
                        LET iCodigoErrorInsert = 2;
                    ELIF cRetornoSPgraga = '002' THEN--Compromiso o Acuerdo de Pago Activo
                        LET iCodigoErrorInsert = 1;
                    ELSE --Tipo de error desconocido
                        LET iCodigoErrorInsert = 5;
                    END IF;
                    
                    BEGIN WORK;
                    LET bTransaccionIniciada = 't';
                    
                    INSERT INTO cb_compac_error (empresa, sucursal, origen, empleado_captura, numcliente, numcuenta, plazo,
                        importe, tipo_compac, activo, flag_pago, efectuo_compac, nombre_efectuo, fecha_compac,
                        fecha_insert, quien_convenio, nom_convenio, email, referenciacoppel, codigo_error, hora_insert) 
                    VALUES (pEmpresa, cSucursal, iOrigen, iEmpleado, cNumCliente, cNumCuenta, cPlazo,
                        dImporte, cTipoCompAc, '0', '0', iEmpleado, '', tFechaLlamadaMDY,
                        tFechaHoy, '', '', '', '', iCodigoErrorInsert, current);
                                            
                    COMMIT WORK;
                    LET bTransaccionIniciada = 'f';
                    
                END IF;
                
            ELSE
                --insertar en la tabla cb_compac_error
                LET iCodigoErrorInsert = 1;
                                
                BEGIN WORK;
                LET bTransaccionIniciada = 't';
                
                INSERT INTO cb_compac_error (empresa, sucursal, origen, empleado_captura, numcliente, numcuenta, plazo,
                        importe, tipo_compac, activo, flag_pago, efectuo_compac, nombre_efectuo, fecha_compac,
                        fecha_insert, quien_convenio, nom_convenio, email, referenciacoppel, codigo_error, hora_insert) 
                VALUES (pEmpresa, cSucursal, iOrigen, iEmpleado, cNumCliente, cNumCuenta, cPlazo,
                    dImporte, cTipoCompAc, '0', '0', iEmpleado, '', tFechaLlamadaMDY,
                    tFechaHoy, '', '', '', '', iCodigoErrorInsert, current);
                           
                COMMIT WORK;
                LET bTransaccionIniciada = 'f';
                
            END IF;
            
        ELSE
            --insertar en la tabla cb_compac_error

            BEGIN WORK;
            LET bTransaccionIniciada = 't';
            
            INSERT INTO cb_compac_error (empresa, sucursal, origen, empleado_captura, numcliente, numcuenta, plazo,
                    importe, tipo_compac, activo, flag_pago, efectuo_compac, nombre_efectuo, fecha_compac,
                    fecha_insert, quien_convenio, nom_convenio, email, referenciacoppel, codigo_error, hora_insert) 
            VALUES (pEmpresa, cSucursal, iOrigen, iEmpleado, cNumCliente, cNumCuenta, cPlazo,
                dImporte, cTipoCompAc, '0', '0', iEmpleado, '', tFechaLlamadaMDY,
                tFechaHoy, '', '', '', '', iCodigoErrorInsert, current);
                
            COMMIT WORK;
            LET bTransaccionIniciada = 'f';
                
        END IF;
        
        LET iNumRegProcesado = iNumRegProcesado + 1;
        
    END FOREACH;
    
    --borrar la tabla temporal
    DROP TABLE datosarchivo_tmp;
    
    --insertar control de procesos    
    LET cCodigoRetorno    = '00000';
    LET cMensajeProceso   = 'PROCESO EXITOSO';
    
    INSERT INTO cb_bitacora_cob (proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc) 
    VALUES (cNombreProceso, cCodigoRetorno, cMensajeProceso, USER, (SELECT DBINFO('utc_to_datetime', sh_curtime) from sysmaster:sysshmvals),
        (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals), iNumRegProcesado);
        
    RETURN cCodigoRetorno, cMensajeProceso;
    
END
end procedure;

CREATE PROCEDURE "informix".sp_marcaracuerdoscumplidos_rep(pEmpresa char(3), pTipo char(1), pFecha date)
RETURNING CHAR(5);

--Fecha de creación: 13/01/2009
--Programó: Anselmo Verdugo
--Objetivo: Store Procedure que realiza el marcaje de los compromisos y acuerdos que ya fueron
--cumplidos o en su defecto los que ya s evencieron.

--Fecha de Modificación: 24/01/2009
--Programó: Walber Castro
--Objetivo: Se agregan 2 parámetros de entrada al spl; una fecha y un tipo de
--ejecución que puede ser 0 (cero para automático) o 1 (uno para manual).
--Tomar la fecha de ejecución de la tabla bdinteg:si_fechas (campo
--fecha_hoy)y considerarla para el procesamiento de los Compromisos / Acuerdos
--cuando el parámetro de tipo de ejecución sea cero. En otro caso considerar
--como fecha de ejecución la fecha que pasa como parámetro.

--Fecha de Modificación: 07/02/2009
--Programó: Bernardo Carlos Baez Gonzalez
--Objetivo: Se modifica para que se actualize el campo flag_pago de el compromizo de pago 
--en base a los campos numcuenta y fecha_compac ya que antes solo se validaba el campo numcuenta
--Se modifica el borrado para que se borren los mismos registros que se han pasado al historico

--Fecha de Modificación: 09/03/2009
--Programó: Bernardo Carlos Baez Gonzalez
--Objetivo: Se modifica para que para que sean procesados, únicamente, los Compromisos y Acuerdos 
--que se vencen en la fecha de ejecución del proceso.

/*Fecha de Modificación: 03/11/2009
  Faviola Martínez Juárez
  Se integra monto pagado cuando un convenio es cumplido 
*/
 
--Modifico: Adilene Lara                                                                               
--Fecha: 17/03/2010                                                                                    
--Se modifica para que en caso de ocurrir un error guarde el detalle del convenio en cb_compac_error y en la cb_bitacora_cob
-- ademas de registrar el inicio y el fin del proceso en la tabla cb_bitacora_cob                                                 

/*Fecha de Modificación: 30/12/2010
  Enrique Lizárraga Lugo
  Se añade validación para evitar que se marque mas de un convenio en caso de que esté repetido. Se marca únicamente el convenio
  que tenga el valor mayor en keyx.
*/
--Modificó: Marco A. Campos
--Fecha: 2011-06-23
--Se modifica condición de fecha_compac de obtención de compromisos y acuerdos para que diario se califiquen los convenios que reciben pago y  aún no es su fecha de vencimiento  

--Modificó: Abrham Lopez L
--Fecha: 2013-08-01
--Se modifica agrega condición del campo hora_mov de la tabla sd_movhis sea > hora_inser de la tabla cb_compac

DEFINE vcCodRet CHAR(5);
DEFINE viSqlErr INTEGER;
DEFINE vdFechaHoy DATE;
DEFINE vdFechaAcuerdo DATE;
DEFINE vFechaCumplimiento DATE;

DEFINE vcNumCuenta CHAR(20);
DEFINE vmSumaPagos  MONEY(16,2);
DEFINE vmSuma   MONEY(16,2);
DEFINE vmCatidadAcordada   DECIMAL(14,2);
DEFINE vcEsTransaccion  CHAR(1);
DEFINE vOrigen SMALLINT;
DEFINE vProceso CHAR(30);
DEFINE cMensaje CHAR(80);
DEFINE isam_err INTEGER;
DEFINE error_info CHAR(80);
DEFINE vdia DATE;
DEFINE vHora CHAR(8);
DEFINE vmaxkeyx INTEGER;
DEFINE vPlazo char(2);
DEFINE vlFlagPago char(1);
DEFINE vHorainsert DATETIME HOUR to FRACTION(3);

LET viSqlErr = 0;
LET vOrigen = 4;
LET vProceso = 'MAC';
LET cMensaje = 'PROCESO EXITOSO';
LET isam_err = 0;
LET error_info = '';
LET vdFechaAcuerdo = '01/01/1900';
LET vdFechaHoy = CURRENT::DATE;
LET vcCodRet = '00000';
LET vcNumCuenta = '';
LET vmSumaPagos = 0.00;
LET vmCatidadAcordada = 0.00;
LET vmSuma = 0.00;
LET vcEsTransaccion = 'N';
LET vmaxkeyx = 0;
LET vPlazo = '';
LET vlFlagPago = '0';
LET vHorainsert = CURRENT;
LET vFechaCumplimiento = '01/01/1900';





    BEGIN    
        ON EXCEPTION SET viSqlErr, isam_err, error_info
            LET vcCodret = viSqlErr;
	        LET cMensaje = error_info;
            CALL bdicobranza:"informix".inserta_bitacora_cob(pempresa, vProceso, vcCodRet, cMensaje, '02');
			RETURN vcCodRet;            
        END EXCEPTION;

--      SET DEBUG FILE TO "/informix/ALL/sp_marcaracuerdoscumplidos.out";
--      TRACE ON;
        
    CALL bdicobranza:"informix".inserta_bitacora_cob(pempresa, vProceso, vcCodret, cMensaje, '01');

IF pEmpresa IS NULL OR pEmpresa = "" THEN
    LET vcCodRet = '00001';
    LET viSqlErr = '00001';
    LET cMensaje = 'FALTA PARAMETRO EMPRESA';
ELSE
    IF pTipo = "0" OR pTipo = "" THEN
        SELECT {+INDEX(bdinteg:si_fechas idx_si_fechas)} fecha_hoy
        INTO vdFechaHoy
        FROM bdinteg:si_fechas
        WHERE empresa = pEmpresa;
    ELSE
        IF pFecha IS NULL OR pFecha = "" THEN
            LET vcCodRet = '00002';      --CÓDIGO DE ERROR PARÁMETRO INCORRECTO
            LET viSqlErr = '00002';
            LET cMensaje = 'FALTA PARAMETRO FECHA';
        ELSE
            LET vdFechaHoy = pFecha;
        END IF;
    END IF;

    IF vcCodRet = '00000' THEN
--        BEGIN WORK;

        LET vcEsTransaccion = 'S';

        FOREACH WITH HOLD
            SELECT {+INDEX(bdicobranza:cb_compac idx_compac3)} numcuenta, importe, fecha_compac, plazo, hora_insert
                   INTO vcNumCuenta, vmCatidadAcordada, vdFechaAcuerdo, vPlazo, vHorainsert
              FROM BDICOBRANZA:CB_COMPAC
			       WHERE empresa = pEmpresa 
               AND ( vdFechaHoy + ( plazo * 7 ) ) >= fecha_compac  
               and fecha_compac <= vdFechaHoy
               AND activo = 1
		   
			LET vFechaCumplimiento = vdFechaAcuerdo + (vPlazo * 7) UNITS DAY; 
			
		--A.L.L Sacamos si la facha es inhabil para sumarle un dia  
			IF EXISTS (SELECT fecha FROM bdinteg:si_feriado WHERE pais = '001' and fecha = vFechaCumplimiento AND laborable = 'N') THEN

    			LET vFechaCumplimiento = vFechaCumplimiento - 1 UNITS DAY; 

            END IF;
			
			SELECT max(keyx)
			INTO vmaxkeyx
			FROM bdicobranza:cb_compac
			where empresa = pEmpresa and fecha_compac = vdFechaAcuerdo and numcuenta = vcNumCuenta;
			
            LET vmSumaPagos = 0.00;
            LET vmSuma = 0.00;
			
			IF NOT EXISTS (select numcuenta from cb_compac_his where numcuenta = vcNumCuenta and fecha_compac = vdFechaAcuerdo) THEN
			
            -- SUMA DE LOS PAGOS DEL DÍA ACTUAL (sc_movdia) POR VENTANILLA, INTERNET y CHEQUES.
         
				if vdFechaAcuerdo = vdFechaHoy then
					SELECT NVL(SUM(monto),0) 
					INTO vmSuma 
					FROM bdicred:sd_movhis 
					WHERE empresa = pEmpresa and num_credito = vcNumCuenta 
					and fecha_mov = vdFechaHoy
					and codigo_fun in ('033', '334', '335', '336', '337') and codigo_ref = 1
					and reversado = 'N'
					and hora_mov > vHorainsert;

			   
					LET vmSumaPagos = vmSumaPagos + vmSuma;
				 else

					-- SUMA DE LOS PAGOS DE LOS DÍAS ANTERIORES (sc_movhis)  POR VENTANILLA, INTERNET y CHEQUES.
					SELECT {+INDEX(bdicred:sd_movhis inx_movhis)} NVL(SUM(monto),0) 
					INTO vmSuma 
					FROM bdicred:sd_movhis 
					WHERE empresa = pEmpresa and num_credito = vcNumCuenta and codigo_fun in ('033', '334', '335', '336', '337') and codigo_ref = 1
					and fecha_mov > vdFechaAcuerdo 
					and fecha_mov <= vdFechaHoy 
					and reversado = 'N';
				
					LET vmSumaPagos = vmSumaPagos + vmSuma;
				 END IF;

	--            IF ( vmSumaPagos > 0  AND ( vdFechaHoy  <>  vdFechaAcuerdo +  (vPlazo * 7) )  )  OR  ( vdFechaHoy  =  vdFechaAcuerdo +  (vPlazo * 7) )     THEN
				IF ( vmSumaPagos > 0  )  OR  ( vdFechaHoy  >=  vFechaCumplimiento )     THEN

					BEGIN WORK;
				
						IF vmSumaPagos >= (vmCatidadAcordada/2) THEN
							UPDATE BDICOBRANZA:CB_COMPAC set flag_pago = 1, imp_pagado = vmSumaPagos
							WHERE empresa = pEmpresa and numcuenta = vcNumCuenta and fecha_compac = vdFechaAcuerdo and keyx = vmaxkeyx;
							Let vlFlagPago = '1';
						ELSE
							UPDATE BDICOBRANZA:CB_COMPAC set flag_pago = 0, imp_pagado = vmSumaPagos 
							WHERE empresa = pEmpresa and numcuenta = vcNumCuenta and fecha_compac = vdFechaAcuerdo and keyx = vmaxkeyx;
							Let vlFlagPago = '0';
						END IF;
						

						--El sistema replica los compromisos marcados como cumplidos y los compromisos vencidos  a la tabla de movimientos historicos.
						INSERT INTO bdicobranza:cb_compac_his(empresa, sucursal, origen, empleado_captura, numcliente, 
															  numcuenta, plazo, importe, tipo_compac, activo, flag_pago, 
															  efectuo_compac, tipo_movto, nombre_efectuo,  fecha_compac, 
															  fecha_insert, keyx,imp_pagado, hora_insert )

						SELECT empresa, sucursal, origen, empleado_captura, numcliente, 
							   numcuenta, plazo, importe, tipo_compac, '0', flag_pago, 
							   efectuo_compac, '', nombre_efectuo,  fecha_compac, 
							   pFecha, keyx, nvl(imp_pagado, 0), current
						 FROM bdicobranza:CB_COMPAC 
						WHERE empresa = pEmpresa AND numcuenta = vcNumCuenta AND fecha_compac = vdFechaAcuerdo AND keyx = vmaxkeyx;


						UPDATE bdicred:sd_indicador_cred SET cumplio_convenio = vlFlagPago WHERE empresa = pEmpresa AND num_credito = vcNumCuenta;
						-- El sistema elimina los compromisos marcados como cumplidos y los compromisos vencidos de la tabla de movimientos.
						DELETE FROM BDICOBRANZA:CB_COMPAC 
						WHERE empresa = pEmpresa AND numcuenta = vcNumCuenta AND fecha_compac = vdFechaAcuerdo AND keyx = vmaxkeyx;

					COMMIT WORK;
					
				END IF;

			END IF;

        END FOREACH;
        
        LET vcEsTransaccion = 'N';
        
    END IF;
END IF;

--IF vcCodRet <> '00000' then

CALL bdicobranza:"informix".inserta_bitacora_cob(pempresa, vproceso, vcCodret, cMensaje, '03');

--END IF;

RETURN vcCodRet;
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_repcob_cartera_env()
	RETURNING
		CHAR(6) 		AS COD_RET,
		CHAR(80)		AS MENSAJE_RET;		
			
		---DECLARACIONES
		DEFINE iSqlErr				                               INTEGER;
		DEFINE iIsamErr				                               INTEGER;
		DEFINE iPagoVenc			                               INTEGER;
		DEFINE cTabla		      	                             CHAR(1);
		DEFINE cStatusCred			                             CHAR(2);
		DEFINE cCiudad, v_empresa				                     CHAR(3);
		DEFINE cProceso                                      CHAR(4);
		DEFINE cCodRet,vvcCod_ret                            CHAR(6);
		DEFINE vhora                                         CHAR(8);
		DEFINE cNumcte, cNumCredito, cNumTarjeta				     CHAR(20);
    DEFINE vHora3                                        CHAR(22);
		DEFINE vCurrent                                      CHAR(25);
    DEFINE cNombreRegion		                             CHAR(30);
		DEFINE cDescripcion			                             CHAR(50);
		DEFINE cDescripcionFinllam                           CHAR(50);
		DEFINE vcNombre				                               VARCHAR(60);
		DEFINE cMensajeRet, cNombreArchivo, cRuta			       CHAR(80);						
    DEFINE cTipoLogica			                             CHAR(100);
    DEFINE cSql          		                             CHAR(1024); 
		DEFINE cConsulta		  	                             CHAR(2200);
		   										
		DEFINE dtFechaHoy, dtFechaCorteIniCte  			         DATE;
		DEFINE dtFechaCorteFinCte, dtFechaUltPago	           DATE;
		DEFINE dtFechaMax, dtFechaMaxCart                    DATE;
		define vdia                                          DATE;
		
		DEFINE sNumVencidos, sNumPagos			                 SMALLINT;
		DEFINE sFinLlamada			                             SMALLINT;
		DEFINE sTipo_logica                                  SMALLINT;
		
		DEFINE dMoratorio, dSaldoTotal, dSdoVencidoTot		   DECIMAL(18,2);
		DEFINE dPagoMinimo, dMensActual, dPagoUnaMora 		   DECIMAL(18,2);
		DEFINE dMontoPagos			                             DECIMAL(18,2);
    DEFINE iCuenta                                       INTEGER;
    --DEFINE vHoraFinLLamada DATETIME HOUR to FRACTION(3);
    DEFINE vHoraFinLLamada DATETIME HOUR to second;
                
		---INICIALIZACIONES
		LET iSqlErr      = 0;   LET iIsamErr      = 0;    LET dMoratorio      = 0.00;   LET dSaldoTotal      = 0.00;
		LET iPagoVenc		 = 0;	  LET sNumVencidos	= 0; 		LET dSdoVencidoTot  = 0.00; 	LET dPagoMinimo			 = 0.00;
		LET dMensActual	 = 0.00;LET dPagoUnaMora  = 0.00;	LET sNumPagos			  = 0;   		LET dMontoPagos			= 0.00;
		LET sFinLlamada	 = 0;
    
    LET cCodRet      = "000000";    LET cMensajeRet      = "Proceso exitoso";  		LET v_empresa          = '001'; 		LET cProceso            = '0073';
		LET cTabla		 	 = "N";         LET cNombreArchivo 	 = "";                		LET cConsulta	         = "";  		  LET cSql		 		        = "";
 		LET cRuta		 		 =  "";		      LET dtFechaHoy       = ""; 	                  LET dtFechaCorteIniCte = "";        LET dtFechaCorteFinCte  = "";
		LET cNumcte 		 = "";  		    LET cNumCredito			 = ""; 		                LET cNumTarjeta			   = "";        LET cDescripcion		    = ""; 
		LET cStatusCred	 = ""; 		      LET dtFechaUltPago	 = "";  		              LET cCiudad				     = "";        LET cNombreRegion		    = "";      
		LET vcNombre		 = "";		      LET cTipoLogica			 = "";                    LET vvcCod_ret         = '';        LET vdia                = '';  
		LET vhora        = '';          LET vCurrent         = '';                    LET vHora3             = '';        LET cDescripcionFinllam = '';   
    LET dtFechaMax   = date(1);     LET dtFechaMaxCart   = date(1);               LET iCuenta            = 0;         LET sTipo_logica        = 0;
    LET vHoraFinLLamada = CURRENT;
    	
	BEGIN 
		ON EXCEPTION SET iSqlErr, iIsamErr, cMensajeRet
			IF iSqlErr != 0 THEN
				LET cCodRet = iSqlErr;	
				LET cMensajeRet = TRIM(cMensajeRet) || '--> ' || cNumcte || cNumCredito;			  				
     			
			 RETURN cCodRet, cMensajeRet;
				
		   END IF;
		END EXCEPTION;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;


		--SET DEBUG FILE TO "/informix/macf/sp_repcob_cartera_env.trc";
		--TRACE ON;
		 
		--DETERMINACION DE FECHA CORTE:
		SELECT fecha_hoy   INTO dtFechaHoy
		FROM bdicred:"informix".sd_fechas
		WHERE empresa = v_empresa;
		
		SELECT max(fecha_insert) INTO dtFechaMax 
      FROM bdicobranza:"informix".cb_cat_directorio_cte
     WHERE tipo_cobranza = 'A';
    
    SELECT max(date(fechacartera)) INTO dtFechaMaxCart
		  FROM bdicobranza:"informix".cb_cat_movimientos
		 WHERE tipocobranza = 'A';  
		
   
    TRUNCATE bdicobranza:cb_encabezadosexcelenviada; 
    			 					
		--SE AGREGA ENCABEZADO AL REPORTE PARA EL ARCHIVO EXCEL.
		INSERT INTO bdicobranza:"informix".cb_encabezadosexcelenviada (NumeroCliente,NumeroCredito,NumeroTarjeta,InteresMoratorio,SdoTotalLiquidacion,SdoVencidoTotal,PagoMinimo,MensualidadActual,NumVencidosInicial,NumVencidosFinal,StatusCred,FechaUltPago,PagoUnaMora,Ciudad,Descripcion,Region,LogicaCampana,NumPagos,MontoPagos,ResultGestion,NombreGestion)
		VALUES("No. De cliente","No. De credito","No. Tarjeta","Int. Moratorio","Sdo. Tot. Liquidacion","Sdo. Vencido Tot.","Pago min.","Mens. Actual","No. Vencidos inicial","No. Vencidos final","Status cred.","Fech. Ult Pago","Pago 1 mora","Ciudad","Descripcion","Region","Logica o campana","No. Pagos","Monto pagos","Resultado de gestion","Nombre de gestion");		
	
		SELECT empresa,
           numcte,
           num_credito, 
           SUM(NVL(moratorio,0.00)) AS IntMoratorio,
           SUM(NVL(saldo_total,0.00)) AS SdoTotLiqui,
			     SUM(NVL(NVL(monto_vencido,0.00) + NVL(mto_venc_trasp,0.00) + NVL(moratorio,0.00) + NVL(interes_iva,0.00),0.00)) AS SdoVencidoTot,
				   SUM(NVL(pago_minimo,0.00)) AS PagMinimo,
				   SUM(NVL((NVL(pago_minimo,0.00) + NVL(mto_venc_trasp,0.00) + NVL(moratorio,0.00)),0.00)) AS MensActual,
				   SUM(NVL(pago_venc,0)) AS NumVencIni,
           NVL(fecha_ult_pago,"") AS FechUltPag,
           SUM(NVL(pago_una_mora,0.00)) AS Pago1Mora,
           SUM(NVL(num_pagos,0)) AS NumPagos,
           SUM(NVL(monto_pagos,0)) AS MontosPag,
           NVL(ciudad,"") AS Ciudad,
           NVL(tipo_logica,0) tipo_logica, NVL(codigo_resultado,0) codigo_resultado
      FROM bdicobranza:cb_cat_directorio_cte 
      WHERE tipo_cobranza = "A"    
        AND fecha_insert >= dtFechaMax
        AND status_cliente <> "NT" AND status_cliente <> "TE"
        AND tipo_logica = 2                --- TEST MACF  49,814
      GROUP BY empresa, numcte, num_credito, fecha_ult_pago, ciudad, tipo_logica, codigo_resultado, tipo_cobranza
			 INTO TEMP paso_catdir WITH NO LOG;

      CREATE INDEX idx_paso_catdir ON paso_catdir (numcte, num_credito);
      UPDATE statistics medium FOR TABLE "informix".paso_catdir;    

		--SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND INTO vHora3 from sysmaster:sysshmvals;
    --INSERT INTO bdicobranza:cb_bitacora(empresa, num_proceso, fecha_ejecucion, cod_ret, mensaje, user_insert, fecha_insert, hora_insert) 
    --VALUES(v_empresa, cProceso, today, '000000', 'Termina creación de tabla temporal paso_catdir', 'informix', vdia, vHora3);
		
		FOREACH WITH HOLD
		 			SELECT NVL(a.numcte,""),  NVL(a.num_credito,""), a.intmoratorio,
                 a.sdototliqui, a.sdovencidotot, a.pagminimo, a.mensactual, a.numvencini,  
                 a.fechultpag, a.pago1mora, a.ciudad, NVL(e.descripcion,""), a.numpagos,
                 a.montospag, NVL(g.descripcion,""), a.tipo_logica				   
    			INTO cNumcte, cNumCredito, dMoratorio, dSaldoTotal, dSdoVencidoTot, dPagoMinimo, dMensActual,iPagoVenc, dtFechaUltPago, dPagoUnaMora,
               cCiudad, cTipoLogica, sNumPagos, dMontoPagos, cDescripcion, sTipo_logica				 				 
    			FROM "informix".paso_catdir a
		            LEFT OUTER JOIN bdicobranza:cb_param_campania e ON(e.valor_numerico = a.tipo_logica and e.grupo_parametro = 'LOGICA')
		            LEFT OUTER JOIN bdicobranza:cb_cat_tipo_resultado g	ON (g.codigo_resultado = a.codigo_resultado)
		      /*      
    			SELECT NVL(a.numcte,"") AS NumDeCliente, NVL(a.num_credito,"") AS NumDeCredito, NVL(c.num_tarjeta,"") AS NumTarjeta, a.intmoratorio AS IntMoratorio,
                 a.sdototliqui AS SdoTotLiqui, a.sdovencidotot, a.pagminimo AS PagMinimo,
    				     a.mensactual AS MensActual, a.numvencini AS NumVencIni, NVL(d.num_vencidos,0) AS NumVencFin, NVL(b.status_cred,"") AS StatusCred, 
                 a.fechultpag AS FechUltPag, a.pago1mora AS Pago1Mora, a.ciudad AS Ciudad, NVL(e.descripcion,"") AS LogicaCampana, a.numpagos AS NumPagos,
                 a.montospag AS MontosPag, NVL(g.descripcion,"") AS NombreGestion				   
    			INTO cNumcte,cNumCredito,cNumTarjeta,dMoratorio,dSaldoTotal,dSdoVencidoTot,dPagoMinimo,dMensActual,iPagoVenc,sNumVencidos,cStatusCred,dtFechaUltPago,
    			 	   dPagoUnaMora,cCiudad,cTipoLogica,sNumPagos,dMontoPagos,cDescripcion  --sFinLlamada,cDescripcion				 				 
    			FROM "informix".paso_catdir a
    				LEFT OUTER JOIN bdicred:"informix".sd_maecred b ON( b.num_credito = a.num_credito)
    				INNER join bdicred:sd_tarjeta c on a.empresa = c.empresa and a.num_credito = c.num_credito and c.secuencia = (select max(secuencia) from bdicred:sd_tarjeta where a.empresa = empresa AND a.num_credito = num_credito and tipo_tarjeta = 'T' AND status_tar = 'A')
    				LEFT OUTER JOIN bdicred:"informix".sd_indicador_cred d ON(d.num_credito = a.num_credito)			
    				LEFT OUTER JOIN bdicobranza:"informix".cb_param_campania e ON(e.valor_numerico = a.tipo_logica)
    				LEFT OUTER JOIN  bdicobranza:"informix".cb_cat_movimientos f ON( LPAD(TRIM(f.cliente),9,"0") = a.numcte )
    				LEFT OUTER JOIN bdicobranza:"informix".cb_cat_tipo_resultado g	ON (g.codigo_resultado = a.codigo_resultado)
    			WHERE b.num_producto = "6001" 
    				AND b.num_producto = c.prodtarjeta
    				AND e.grupo_parametro = "LOGICA"
    				AND f.tipologica = a.tipo_logica
    				AND f.tipocobranza = "A"
    				AND date(f.fechacartera) >= dtFechaMaxCart
          */
          
          SELECT LIMIT 1 nvl(m.finllamada,0) as finllamada, nvl(c.descripcion,'') as descripcion,
                   (SELECT MAX(horafinllamada) FROM bdicobranza:cb_cat_movimientos WHERE cvemovimiento = m.cvemovimiento AND cliente = m.cliente 
                                                AND tipologica = m.tipologica AND tipocobranza = m.tipocobranza
                                                AND date(fechacartera) = date(m.fechacartera) ) AS HoraFinLLamada  
              INTO sFinLlamada, cDescripcionFinllam, vHoraFinLLamada
              FROM bdicobranza:cb_cat_movimientos m, 
                   bdicobranza:cb_cat_tipo_resultado c
             WHERE m.cvemovimiento = 'L' 
               --AND m.cliente = cNumcte  -- no coincide porque m.cliente no tiene ceros a la izq.
               AND m.tienda = cNumCredito 
               AND m.tipologica = sTipo_logica 
               AND m.tipocobranza = 'A'
               /*AND m.horafinllamada = (SELECT MAX(horafinllamada) 
                                         FROM bdicobranza:cb_cat_movimientos 
                                        WHERE cvemovimiento = m.cvemovimiento 
                                          AND cliente = m.cliente 
                                          AND tipologica = m.tipologica
                                          AND tipocobranza = m.tipocobranza
                                          --AND horafinllamada = horafinllamada
                                          AND date(fechacartera) = date(m.fechacartera) --dtFechaMaxCart
                                             
               )*/ 
               AND date(m.fechacartera) = dtFechaMaxCart
               AND m.finllamada = c.codigo_resultado;
               
               IF nvl(sFinLlamada,'') = '' THEN continue foreach; END IF;  
          
          --SELECT NVL(num_tarjeta,"") INTO cNumTarjeta 
          SELECT LIMIT 1 NVL(num_tarjeta,""), m.status_cred INTO cNumTarjeta, cStatusCred 
    			  FROM bdicred:sd_tarjeta a, bdicred:sd_maecred m 
    			 WHERE a.empresa = v_empresa
             AND a.empresa = m.empresa  
             AND a.num_credito = cNumCredito
             AND a.num_credito = m.num_credito
             AND a.secuencia = (select max(secuencia) from bdicred:sd_tarjeta 
                                 where empresa = a.empresa AND num_credito = a.num_credito and tipo_tarjeta = 'T' AND status_tar = 'A'); 
			
			    SELECT NVL(num_vencidos,0) INTO sNumVencidos 
            FROM bdicred:sd_indicador_cred 
           WHERE empresa = v_empresa
             AND num_credito = cNumCredito;
			
      			--SELECT LIMIT 1 nvl(m.finllamada,0) finllamada, nvl(c.descripcion,'') descripcion INTO sFinLlamada, cDescripcion   -- NEW BY MACF
            --  FROM bdicobranza:cb_cat_movimientos m, 
            --       bdicobranza:cb_cat_tipo_resultado c 
            -- WHERE date(m.fechacartera) = dtFechaMaxCart 
            --   AND m.tienda = cNumCredito 
            --   AND m.cvemovimiento = 'L'
            --   AND m.horafinllamada = (SELECT MAX(horafinllamada) FROM bdicobranza:cb_cat_movimientos 
            --                            WHERE date(fechacartera) = dtFechaMaxCart 
            --                              AND tienda = cNumCredito and cvemovimiento = 'L')
            --   AND c.codigo_resultado = m.finllamada ; 
            
            --- modif 2013/07/05   
            
			
      			SELECT LIMIT 1 NVL(b.nombre,"") AS NombreCiudad,NVL(c.nombre_region,"") AS NombreRegion  
      			INTO vcNombre,cNombreRegion
      			FROM bdinteg:"informix".si_catciudades a
      				               LEFT OUTER JOIN bdinteg:"informix".si_ciudades b ON(b.ciudad_coppel::INT = a.numerociudad) 	
      				               LEFT OUTER JOIN bdinteg:"informix".si_regiones c ON(c.numero_region	= a.regioncobranzas)
      			WHERE a.numerociudad = cCiudad::INT;
			
      			BEGIN WORK;
              --SE INSERTA TODA LA INFORMACION EN LA TABLA FINAL.
        			INSERT INTO bdicobranza:"informix".cb_encabezadosexcelenviada (NumeroCliente, NumeroCredito, NumeroTarjeta, InteresMoratorio, SdoTotalLiquidacion,
                         SdoVencidoTotal, PagoMinimo, MensualidadActual, NumVencidosInicial, NumVencidosFinal, StatusCred, FechaUltPago, PagoUnaMora, Ciudad,
                         Descripcion, Region, LogicaCampana, NumPagos, MontoPagos, ResultGestion, NombreGestion)
        			--VALUES(cNumcte,cNumCredito,cNumTarjeta,dMoratorio,dSaldoTotal,dSdoVencidoTot,dPagoMinimo,dMensActual,iPagoVenc,sNumVencidos,cStatusCred,dtFechaUltPago,dPagoUnaMora,cCiudad,vcNombre,cNombreRegion,cTipoLogica,sNumPagos,dMontoPagos,sFinLlamada,cDescripcion);
        		  VALUES( "'" || lpad(TRIM(cNumcte),9,'000000000'), cNumCredito, cNumTarjeta, dMoratorio, dSaldoTotal, dSdoVencidoTot, dPagoMinimo, dMensActual,
                     iPagoVenc, sNumVencidos, cStatusCred, dtFechaUltPago, dPagoUnaMora, cCiudad, vcNombre, cNombreRegion, cTipoLogica, sNumPagos, dMontoPagos, 
                     sFinLlamada,cDescripcionFinllam);
            COMMIT WORK;
    
            		  
		END FOREACH
						
		--SE OBTIENE EL NOMBRE DEL ARCHIVO.
		SELECT valor 
		INTO cNombreArchivo
		FROM bdicobranza:"informix".cb_param 
		WHERE cod_param = 73;	

		--SE OBTINE LA RUTA DONDE SE GENERARÁ EL ARCHIVO.
		SELECT valor_alfabetico
		INTO cRuta
		FROM bdicobranza:"informix".cb_param_campania
		WHERE tipo_campania = 11
			AND grupo_parametro = "RUTAS" 
			AND num_parametro = 1;

-- COMENTAR QUE SE GENERE EL ARCHIVO PARA QUE SE GUARDE TODO EN LA TABLA cb_encabezadosexcelenviada Y VER QUE CANT. DE REGS. GENERA
			
		LET cNombreArchivo = TRIM(cNombreArchivo)||YEAR(dtFechaHoy)||LPAD(MONTH(dtFechaHoy),2,0)||LPAD(DAY(dtFechaHoy),2,0); 
		-- lpad(trim(NumeroCliente),9,'00000000')
		LET cConsulta = "SELECT NumeroCliente,NumeroCredito,NumeroTarjeta,InteresMoratorio,SdoTotalLiquidacion,SdoVencidoTotal,PagoMinimo,MensualidadActual,NumVencidosInicial,NumVencidosFinal,StatusCred,FechaUltPago,PagoUnaMora,Ciudad,Descripcion,Region,LogicaCampana,NumPagos,MontoPagos,ResultGestion,NombreGestion FROM bdicobranza:'informix'.cb_encabezadosexcelenviada";		
    
    LET cSql = '';
		LET cSql = 'echo "set isolation to dirty read; UNLOAD TO ' ||TRIM(cRuta)||TRIM(cNombreArchivo)||'.xls'|| ' DELIMITER '|| '''	'''||' '||TRIM(cConsulta)||'" > '|| TRIM(cRuta) ||'query1.sql';
		
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = "dbaccess bdicobranza " ||TRIM(cRuta)||'query1.sql';
		SYSTEM cSql;
		LET cSql = '';
		LET cSQL = "rm " ||TRIM(cRuta)||'query1.sql';		
		SYSTEM cSql; 
		
		--IF cTabla="S" THEN
		--		DROP TABLE bdicobranza:"informix".cb_encabezadosexcelenviada;
		--END IF;
		
    LET cMensajeRet = TRIM(cNombreArchivo)||'.xls';					
		
    --CALL bdicobranza:"informix".sp_inserta_bitacora_cob(v_empresa, cProceso, cCodRet, cMensajeRet, '03') RETURNING vvcCod_ret;  --TEST
    		
		RETURN cCodRet, cMensajeRet;
		
	END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para obtener el Resultado de cartera enviada.', 
'AUTOR: Guadalupe Payan',
