CREATE PROCEDURE "informix".sp_borra_cteduplicados() 
       RETURNING char(8);

--declaracion de variables
------------------------------------------------------------
DEFINE sql_err 			  INTEGER;
DEFINE isam_err 		  INTEGER;
DEFINE error_info		  CHAR(150);
DEFINE cMensaje 		  CHAR(80);
DEFINE cCod_ret           CHAR(6);
DEFINE vNumcte            CHAR(20);
DEFINE vUsuarioInset      CHAR(8);
--SET DEBUG FILE TO '/tmp/sp_datos_admin_auronix.out';
--TRACE ON;
    LET cCod_ret      = '000000';
	  LET sql_err       = 0;
	  LET isam_err      = 0;
	  LET error_info    = '';
	  LET cMensaje      = 'PROCESO EXITOSO';
	  LET vNumcte       = '';
	  LET vUsuarioInset = '';
	BEGIN
        ON EXCEPTION SET sql_err, isam_err, error_info
            LET cCod_ret = sql_err;
            LET cMensaje = error_info;
            RETURN cCod_ret;
        END EXCEPTION;
		
		SELECT numcte, usuario_insert FROM bdicobranza:cb_cat_directorio_cte
			WHERE empresa = '001' AND tipo_cobranza = 'P'
			AND fecha_insert= '11-12-2013' AND usuario_insert = 'syscobra'
			AND status_cliente = 'AC'
		INTO temp cte_dup WITH NO LOG;
		
	FOREACH	WITH HOLD 
		SELECT numcte, usuario_insert 
		INTO vNumcte, vUsuarioInset
		FROM cte_dup WHERE usuario_insert = 'syscobra'

			BEGIN;
			DELETE FROM bdicobranza:cb_cat_directorio_cte WHERE empresa = '001' AND tipo_cobranza='P'
				AND numcte = vNumcte AND fecha_insert= '11-12-2013'
				AND usuario_insert = vUsuarioInset AND status_cliente='AC';
			COMMIT;
END FOREACH;
	
    RETURN cCod_ret;
    END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_grabacompromisosacuerdos_pba(pEmpresa char(3), pSucursal char(4), pOrigen smallint,
pEmpleadoCaptura integer, pNumCliente char(20), pNumCuenta char(20),pPlazo char(2), pImporte integer, pTipo char(1),
pEmpleadoSup integer, pNombreSup char(40), pFechaCompac date)

RETURNING CHAR(6);


    DEFINE cVarDataErr      VARCHAR(64);
    DEFINE iSqlErr                INTEGER;
    DEFINE iSamErr             INTEGER;

    DEFINE vCodRet            CHAR(6);
    DEFINE vNumcliente     CHAR(20);
    DEFINE vNumCuenta    CHAR(20);
    DEFINE vActivo                CHAR(1);
    DEFINE vTipoCompac   CHAR(1);
    DEFINE dtefecha             DATE;
    DEFINE chrplazo	    	CHAR(2);
    DEFINE intactivo		  SMALLINT;
    DEFINE intdiasplazo	      SMALLINT;
    DEFINE intdiasfecha	      SMALLINT;    
    define v_codret char(5);

BEGIN
    ON EXCEPTION
        SET iSqlErr, iSamErr, cVarDataErr
        IF iSqlErr <> 0 THEN
            LET vCodRet=iSqlErr;
            Rollback;
            RETURN vCodRet;
        END IF;
    END EXCEPTION;


    --SET DEBUG FILE TO "/tmp/grabacompromisosacuerdos.out";
    --TRACE ON;

    --INICIALIZACION DE VARIABLES--
    LET vCodRet        	     = "000";
    LET dtefecha       	      = '01-01-1900';
    LET chrplazo	      = '';
    LET intactivo	        = 0;
    LET intdiasplazo	   = 0;
    LET intdiasfecha	   = 0;
    LET v_codret = '000';

BEGIN WORK;

IF pEmpresa IS NOT NULL AND pSucursal IS NOT NULL AND pOrigen <> 0 AND pEmpleadoCaptura <> 0
    AND pNumCliente IS NOT NULL AND pNumCuenta IS NOT NULL AND pPlazo IS NOT NULL AND pImporte <> 0
    AND pTipo IS NOT NULL AND pEmpleadoSup <> 0 AND pNombreSup IS NOT NULL AND pFechaCompac IS NOT NULL THEN

      --while (length(pPlazo) < 2)
      --    LET pPlazo= "0" || pPlazo;
      --end while;
      if (substr(pPlazo,1,1) = '0') then
          let pPlazo = substr(pPlazo,2,1);
      end if;

      if pOrigen = '1' then
        let pImporte = pImporte / 100;
      end if;

       IF NOT EXISTS(select {+INDEX(bdicobranza:cb_compac idx_compac2)} numcliente 
            from bdicobranza:cb_compac 
            where empresa = pEmpresa and numcliente = pNumCliente and numcuenta = pNumCuenta) then

            insert into bdicobranza:cb_compac (empresa, sucursal, origen, empleado_captura, numcliente, numcuenta, plazo, importe, tipo_compac,
            activo, flag_pago, efectuo_compac, nombre_efectuo, fecha_compac, fecha_insert, hora_insert)
            values (pEmpresa, pSucursal, pOrigen, pEmpleadoCaptura, pNumCliente, pNumCuenta, pPlazo, pImporte, pTipo, '1', '0', pEmpleadoSup, pNombreSup, pFechaCompac, current, current);

            
            LET vCodRet        = "000";   --Insercion Correcta

       ELSE

            Select {+INDEX(bdicobranza:cb_compac idx_compac2)} numcliente, numcuenta, activo, tipo_compac, fecha_compac, plazo
            into vNumcliente, vNumCuenta, vActivo, vTipoCompac, dtefecha, chrplazo
            From bdicobranza:cb_compac
            where empresa = pEmpresa and numcliente = pNumCliente and numcuenta = pNumCuenta;

            IF vTipoCompac = '1' and pTipo = '2'  THEN

                    Update bdicobranza:cb_compac
                    set empresa = pEmpresa, sucursal = pSucursal, origen = pOrigen, empleado_captura = pEmpleadoCaptura, plazo = pPlazo,
                    importe=pImporte, tipo_compac = '2', activo = '1', flag_pago = '0', efectuo_compac = pEmpleadoSup, nombre_efectuo = pNombreSup,
                    fecha_compac = pFechaCompac
                    where empresa = pEmpresa and numcliente = pNumCliente and numcuenta = pNumCuenta;

                    
                    LET vCodRet        = "001";   --Acuerdo Actualizado por un Compromiso

            ELSE
					LET intactivo = 0;
					LET intdiasplazo = NVL(chrplazo,0) * 7;
                    LET intdiasfecha = CURRENT::DATE - dtefecha;
                    IF intdiasfecha <= intdiasplazo THEN
                        LET intactivo = 1;
                    END IF;

                    IF pTipo = '1' and vTipoCompac = '1' then

                         IF intactivo = 0 then                             
							           Update bdicobranza:cb_compac
                    	    set empresa = pEmpresa, sucursal = pSucursal, origen = pOrigen, empleado_captura = pEmpleadoCaptura, plazo = pPlazo,
                            importe=pImporte, tipo_compac = '1', activo = '1', flag_pago = '0', efectuo_compac = pEmpleadoSup, nombre_efectuo = pNombreSup,
                            fecha_compac = pFechaCompac
                    	    where empresa = pEmpresa and numcliente = pNumCliente and numcuenta = pNumCuenta;

							
                            LET vCodRet        = "001";   --Acuerdo Actualizado por un Compromiso

                         ELSE
                             LET vCodRet        = "002";   --Compromiso o Acuerdo de Pago Activo
                         END IF;

					ELSE
						IF pTipo = '2' and vTipoCompac = '2' AND intactivo = 0 then
						    Update bdicobranza:cb_compac
                    	    set empresa = pEmpresa, sucursal = pSucursal, origen = pOrigen, empleado_captura = pEmpleadoCaptura, plazo = pPlazo,
                            importe=pImporte, tipo_compac = '2', activo = '1', flag_pago = '0', efectuo_compac = pEmpleadoSup, nombre_efectuo = pNombreSup,
                            fecha_compac = pFechaCompac
                    	    where empresa = pEmpresa and numcliente = pNumCliente and numcuenta = pNumCuenta;							
						else
						    LET vCodRet        = "002";   --Compromiso o Acuerdo de Pago Activo
						end if;
                    END IF;

            END IF;

       END IF;
ELSE
    LET vCodRet        = "003";   --Falta algun parametro
END IF;

COMMIT WORK;
  if v_codret = '000' then  
    execute procedure bdicred:sp_graba_indicador(pempresa, pNumCuenta,pImporte,'' , current, 5) into v_codret;
  end if;
    RETURN vCodRet;

END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultacompromisosacuerdos_pba( pEmpresa CHAR(3), pSucursal CHAR(4), pNumCte CHAR(20), pTipo CHAR(1) )
RETURNING CHAR(6), CHAR(20), CHAR(40), CHAR(2), INTEGER, DATE, SMALLINT, SMALLINT, CHAR(1), CHAR(1), CHAR(1), SMALLINT;

--------------------------------------------------------------
--ACTIVIDAD: Consulta la informacion de los convenios activos
--por determinado numero de cliente.
--------------------------------------------------------------

--Definicion de variables
DEFINE chrcodret        CHAR(6);
DEFINE chrnumcredito    CHAR(20);
DEFINE chrplazo         CHAR(2);
DEFINE chrnombreprod    CHAR(40);
DEFINE chrtipo          CHAR(1);
DEFINE chractivo        CHAR(1);
DEFINE chrflagcompac    CHAR(1);

DEFINE intimporte       INTEGER;
DEFINE intcodret        INTEGER;
DEFINE intempcaptura    INTEGER;
DEFINE intefectuo       INTEGER;

DEFINE intflag          SMALLINT;
DEFINE inttotalctas     SMALLINT;
DEFINE inttotalconv     SMALLINT;
DEFINE intorigen        SMALLINT;
DEFINE intdiasplazo     SMALLINT;
DEFINE intdiasfecha     SMALLINT;
DEFINE intactivo        SMALLINT;

DEFINE dtefecha         DATE;

--DEBUG FLAG
--SET debug file to "/pisa/pisabanco/pisa_ftes/cobranza/sp_consultacompromisosacuerdos.out";
--TRACE ON;

BEGIN

ON EXCEPTION SET intcodret
   IF intcodret <> 0 THEN
      LET chrcodret = intcodret;
      RETURN chrcodret, chrnumcredito, chrnombreprod, chrplazo, intimporte, dtefecha,
             inttotalctas, inttotalconv, chrtipo, chractivo, chrflagcompac, intorigen;
   END IF;
END EXCEPTION;

--Inicializacion de variables
LET chrcodret        = '000';
LET chrnumcredito    = '';
LET chrplazo         = '';
LET chrnombreprod    = '';
LET chrtipo          = '';
LET chractivo        = '';
LET chrflagcompac    = '';
LET intimporte       = 0;
LET intcodret        = 0;
LET intflag          = 0;
LET inttotalctas     = 0;
LET inttotalconv     = 0;
LET intorigen        = 0;
LET intdiasplazo     = 0;
LET intdiasfecha     = 0;
LET intactivo        = 0;
LET dtefecha         = '01-01-1900';

IF EXISTS ( SELECT numcte FROM bdinteg:si_cliente WHERE empresa = pEmpresa AND numcte = pNumCte ) THEN

    IF pTipo = '1' THEN
        SELECT count(*) INTO inttotalctas
        FROM bdicred:sd_maecred
        WHERE empresa = pEmpresa AND status_cred <> 'CC' AND numcte = pNumCte;

        IF inttotalctas <> 0 THEN

            SELECT count(*) INTO inttotalconv FROM bdicobranza:cb_compac
            WHERE empresa = pEmpresa AND numcliente = pNumCte;

            FOREACH
                SELECT a.num_credito, b.nombre_prod INTO chrnumcredito, chrnombreprod
                FROM bdicred:sd_maecred a, bdicred:sd_definicion b
                WHERE a.empresa = b.empresa AND a.num_producto = b.num_producto
                AND a.empresa = pEmpresa AND status_cred <> 'CC' AND numcte = pNumCte
                GROUP BY a.num_credito, b.nombre_prod

                SELECT plazo, importe, fecha_compac, tipo_compac, activo, flag_pago, origen
                INTO chrplazo, intimporte, dtefecha, chrtipo, chractivo, chrflagcompac, intorigen
                FROM bdicobranza:cb_compac
                WHERE empresa = pEmpresa AND numcliente = pNumCte AND numcuenta = chrnumcredito;

                LET intactivo = 0;
                LET intdiasplazo = 0;
                LET intdiasfecha = 0;
                IF not chrplazo IS NULL THEN
                    LET intdiasplazo = NVL(chrplazo,0) * 7;
                    LET intdiasfecha = CURRENT::DATE - dtefecha;
                    LET intactivo = intdiasplazo;
                    LET intactivo = intdiasfecha;
                    LET intactivo = intdiasplazo + intdiasfecha;
                    LET intactivo = intdiasfecha;
                    LET intactivo = 0;
                    IF intdiasfecha <= intdiasplazo THEN
                        LET intactivo = 1;
                    END IF;
                END IF;



                IF intactivo = 1 THEN

                    SELECT plazo, importe, fecha_compac, tipo_compac, activo, flag_pago, origen
                    INTO chrplazo, intimporte, dtefecha, chrtipo, chractivo, chrflagcompac, intorigen
                    FROM bdicobranza:cb_compac
                    WHERE empresa = pEmpresa AND numcliente = pNumCte AND numcuenta = chrnumcredito;
                ELSE
                    LET chrplazo = '';
                    LET intimporte = 0;
                    LET dtefecha = '01-01-1900';
                    LET chrtipo = '';
                    LET chractivo = '';
                    LET chrflagcompac = '';
                    LET intorigen = 0;
                END IF;

                RETURN chrcodret, chrnumcredito, chrnombreprod, chrplazo, intimporte, dtefecha,
                    inttotalctas, inttotalconv, chrtipo, chractivo, chrflagcompac, intorigen  WITH RESUME;

            END FOREACH;
        ELSE
            -- Cliente no tiene cuentas de credito
            LET chrcodret = '002';
            RETURN chrcodret, chrnumcredito, chrnombreprod, chrplazo, intimporte, dtefecha,
                   inttotalctas, inttotalconv, chrtipo, chractivo, chrflagcompac, intorigen;
        END IF;

    ELIF pTipo = '2' THEN

        SELECT count(*) INTO inttotalctas
        FROM bdicred:sd_maecred
        WHERE empresa = pEmpresa AND status_cred <> 'CC' AND numcte = pNumCte;

        IF inttotalctas <> 0 THEN
            SELECT count(*) INTO inttotalconv FROM bdicobranza:cb_compac_his
            WHERE empresa = pEmpresa AND numcliente = pNumCte;

            FOREACH
                SELECT a.num_credito, b.nombre_prod INTO chrnumcredito, chrnombreprod
                FROM bdicred:sd_maecred a, bdicred:sd_definicion b
                WHERE a.empresa = b.empresa AND a.num_producto = b.num_producto AND a.empresa = pEmpresa
                AND status_cred <> 'CC' AND numcte = pNumCte
                GROUP BY a.num_credito, b.nombre_prod
                ORDER BY a.num_credito

                LET chrplazo = '';
                LET intimporte = 0;
                LET dtefecha = '01-01-1900';
                LET chrtipo = '';
                LET chractivo = '';
                LET chrflagcompac = '';
                LET intorigen = 0;


                IF EXISTS ( SELECT numcuenta FROM bdicobranza:cb_compac_his WHERE empresa = pEmpresa
                            AND numcliente = pNumCte AND numcuenta = chrnumcredito ) THEN
                    LET intflag = 1;

                    FOREACH
                        SELECT plazo, importe, fecha_compac, tipo_compac, activo, flag_pago, origen
                        INTO chrplazo, intimporte, dtefecha, chrtipo, chractivo, chrflagcompac, intorigen
                        FROM bdicobranza:cb_compac_his
                        WHERE empresa = pEmpresa AND numcliente = pNumCte AND numcuenta = chrnumcredito
                        ORDER BY fecha_compac

                        RETURN chrcodret, chrnumcredito, chrnombreprod, chrplazo, intimporte, dtefecha,
                            inttotalctas, inttotalconv, chrtipo, chractivo, chrflagcompac, intorigen WITH RESUME;

                        LET chrplazo = '';
                        LET intimporte = 0;
                        LET dtefecha = '01-01-1900';
                        LET chrtipo = '';
                        LET chractivo = '';
                        LET chrflagcompac = '';
                        LET intorigen = 0;

                    END FOREACH;

                END IF;

            END FOREACH;

            IF intflag = 0 THEN
                -- Por si el cliente no tiene convenios en ninguno de sus creditos
                LET chrcodret = '003';
                LET chrnumcredito = '';
                LET chrnombreprod = '';
                RETURN chrcodret, chrnumcredito, chrnombreprod, chrplazo, intimporte, dtefecha,
                    inttotalctas, inttotalconv, chrtipo, chractivo, chrflagcompac, intorigen;
            END IF;
        ELSE
            -- Cliente no tiene cuentas de credito
            LET chrcodret = '002';
            RETURN chrcodret, chrnumcredito, chrnombreprod, chrplazo, intimporte, dtefecha,
                   inttotalctas, inttotalconv, chrtipo, chractivo, chrflagcompac, intorigen;
        END IF;
    END IF;
ELSE
    -- No existe numero de cliente
    LET chrcodret = '001';
    RETURN chrcodret, chrnumcredito, chrnombreprod, chrplazo, intimporte, dtefecha,
           inttotalctas, inttotalconv, chrtipo, chractivo, chrflagcompac, intorigen;
END IF;

END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultacompromisosacuerdos( pEmpresa CHAR(3), pSucursal CHAR(4), pNumCte CHAR(20), pTipo CHAR(1) )
RETURNING CHAR(6), CHAR(20), CHAR(40), CHAR(2), INTEGER, DATE, SMALLINT, SMALLINT, CHAR(1), CHAR(1), CHAR(1), SMALLINT;

--------------------------------------------------------------
--ACTIVIDAD: Consulta la informacion de los convenios activos
--por determinado numero de cliente.
--------------------------------------------------------------

--Definicion de variables
DEFINE chrcodret        CHAR(6);
DEFINE chrnumcredito    CHAR(20);
DEFINE chrplazo         CHAR(2);
DEFINE chrnombreprod    CHAR(40);
DEFINE chrtipo          CHAR(1);
DEFINE chractivo        CHAR(1);
DEFINE chrflagcompac    CHAR(1);

DEFINE intimporte       INTEGER;
DEFINE intcodret        INTEGER;
DEFINE intempcaptura    INTEGER;
DEFINE intefectuo       INTEGER;

DEFINE intflag          SMALLINT;
DEFINE inttotalctas     SMALLINT;
DEFINE inttotalconv     SMALLINT;
DEFINE intorigen        SMALLINT;
DEFINE intdiasplazo     SMALLINT;
DEFINE intdiasfecha     SMALLINT;
DEFINE intactivo        SMALLINT;

DEFINE dtefecha         DATE;

--DEBUG FLAG
--SET debug file to "/pisa/pisabanco/pisa_ftes/cobranza/sp_consultacompromisosacuerdos.out";
--TRACE ON;

BEGIN

ON EXCEPTION SET intcodret
   IF intcodret <> 0 THEN
      LET chrcodret = intcodret;
      RETURN chrcodret, chrnumcredito, chrnombreprod, chrplazo, intimporte, dtefecha,
             inttotalctas, inttotalconv, chrtipo, chractivo, chrflagcompac, intorigen;
   END IF;
END EXCEPTION;

    set isolation to dirty read;
    set lock mode to wait 3;

--Inicializacion de variables
LET chrcodret        = '000';
LET chrnumcredito    = '';
LET chrplazo         = '';
LET chrnombreprod    = '';
LET chrtipo          = '';
LET chractivo        = '';
LET chrflagcompac    = '';
LET intimporte       = 0;
LET intcodret        = 0;
LET intflag          = 0;
LET inttotalctas     = 0;
LET inttotalconv     = 0;
LET intorigen        = 0;
LET intdiasplazo     = 0;
LET intdiasfecha     = 0;
LET intactivo        = 0;
LET dtefecha         = '01-01-1900';

IF EXISTS ( SELECT numcte FROM bdinteg:si_cliente WHERE empresa = pEmpresa AND numcte = pNumCte ) THEN

    IF pTipo = '1' THEN
        SELECT count(*) INTO inttotalctas
        FROM bdicred:sd_maecred
        WHERE empresa = pEmpresa AND status_cred <> 'CC' AND numcte = pNumCte;

        IF inttotalctas <> 0 THEN

            SELECT count(*) INTO inttotalconv FROM bdicobranza:cb_compac
            WHERE empresa = pEmpresa AND numcliente = pNumCte;

            FOREACH
                SELECT a.num_credito, b.nombre_prod INTO chrnumcredito, chrnombreprod
                FROM bdicred:sd_maecred a, bdicred:sd_definicion b
                WHERE a.empresa = b.empresa AND a.num_producto = b.num_producto
                AND a.empresa = pEmpresa AND status_cred <> 'CC' AND numcte = pNumCte
                GROUP BY a.num_credito, b.nombre_prod

                SELECT plazo, importe, fecha_compac, tipo_compac, activo, flag_pago, origen
                INTO chrplazo, intimporte, dtefecha, chrtipo, chractivo, chrflagcompac, intorigen
                FROM bdicobranza:cb_compac
                WHERE empresa = pEmpresa AND numcliente = pNumCte AND numcuenta = chrnumcredito;

                LET intactivo = 0;
                LET intdiasplazo = 0;
                LET intdiasfecha = 0;
                IF not chrplazo IS NULL THEN
                    LET intdiasplazo = NVL(chrplazo,0) * 7;
                    LET intdiasfecha = CURRENT::DATE - dtefecha;
                    LET intactivo = intdiasplazo;
                    LET intactivo = intdiasfecha;
                    LET intactivo = intdiasplazo + intdiasfecha;
                    LET intactivo = intdiasfecha;
                    LET intactivo = 0;
                    IF intdiasfecha <= intdiasplazo THEN
                        LET intactivo = 1;
                    END IF;
                END IF;



                IF intactivo = 1 THEN

                    SELECT plazo, importe, fecha_compac, tipo_compac, activo, flag_pago, origen
                    INTO chrplazo, intimporte, dtefecha, chrtipo, chractivo, chrflagcompac, intorigen
                    FROM bdicobranza:cb_compac
                    WHERE empresa = pEmpresa AND numcliente = pNumCte AND numcuenta = chrnumcredito;
                ELSE
                    LET chrplazo = '';
                    LET intimporte = 0;
                    LET dtefecha = '01-01-1900';
                    LET chrtipo = '';
                    LET chractivo = '';
                    LET chrflagcompac = '';
                    LET intorigen = 0;
                END IF;

                RETURN chrcodret, chrnumcredito, chrnombreprod, chrplazo, intimporte, dtefecha,
                    inttotalctas, inttotalconv, chrtipo, chractivo, chrflagcompac, intorigen  WITH RESUME;

            END FOREACH;
        ELSE
            -- Cliente no tiene cuentas de credito
            LET chrcodret = '002';
            RETURN chrcodret, chrnumcredito, chrnombreprod, chrplazo, intimporte, dtefecha,
                   inttotalctas, inttotalconv, chrtipo, chractivo, chrflagcompac, intorigen;
        END IF;

    ELIF pTipo = '2' THEN

        SELECT count(*) INTO inttotalctas
        FROM bdicred:sd_maecred
        WHERE empresa = pEmpresa AND status_cred <> 'CC' AND numcte = pNumCte;

        IF inttotalctas <> 0 THEN
            SELECT count(*) INTO inttotalconv FROM bdicobranza:cb_compac_his
            WHERE empresa = pEmpresa AND numcliente = pNumCte;

            FOREACH
                SELECT a.num_credito, b.nombre_prod INTO chrnumcredito, chrnombreprod
                FROM bdicred:sd_maecred a, bdicred:sd_definicion b
                WHERE a.empresa = b.empresa AND a.num_producto = b.num_producto AND a.empresa = pEmpresa
                AND status_cred <> 'CC' AND numcte = pNumCte
                GROUP BY a.num_credito, b.nombre_prod
                ORDER BY a.num_credito

                LET chrplazo = '';
                LET intimporte = 0;
                LET dtefecha = '01-01-1900';
                LET chrtipo = '';
                LET chractivo = '';
                LET chrflagcompac = '';
                LET intorigen = 0;


                IF EXISTS ( SELECT numcuenta FROM bdicobranza:cb_compac_his WHERE empresa = pEmpresa
                            AND numcliente = pNumCte AND numcuenta = chrnumcredito ) THEN
                    LET intflag = 1;

                    FOREACH
                        SELECT plazo, importe, fecha_compac, tipo_compac, activo, flag_pago, origen
                        INTO chrplazo, intimporte, dtefecha, chrtipo, chractivo, chrflagcompac, intorigen
                        FROM bdicobranza:cb_compac_his
                        WHERE empresa = pEmpresa AND numcliente = pNumCte AND numcuenta = chrnumcredito
                        ORDER BY fecha_compac

                        RETURN chrcodret, chrnumcredito, chrnombreprod, chrplazo, intimporte, dtefecha,
                            inttotalctas, inttotalconv, chrtipo, chractivo, chrflagcompac, intorigen WITH RESUME;

                        LET chrplazo = '';
                        LET intimporte = 0;
                        LET dtefecha = '01-01-1900';
                        LET chrtipo = '';
                        LET chractivo = '';
                        LET chrflagcompac = '';
                        LET intorigen = 0;

                    END FOREACH;

                END IF;

            END FOREACH;

            IF intflag = 0 THEN
                -- Por si el cliente no tiene convenios en ninguno de sus creditos
                LET chrcodret = '003';
                LET chrnumcredito = '';
                LET chrnombreprod = '';
                RETURN chrcodret, chrnumcredito, chrnombreprod, chrplazo, intimporte, dtefecha,
                    inttotalctas, inttotalconv, chrtipo, chractivo, chrflagcompac, intorigen;
            END IF;
        ELSE
            -- Cliente no tiene cuentas de credito
            LET chrcodret = '002';
            RETURN chrcodret, chrnumcredito, chrnombreprod, chrplazo, intimporte, dtefecha,
                   inttotalctas, inttotalconv, chrtipo, chractivo, chrflagcompac, intorigen;
        END IF;
    END IF;
ELSE
    -- No existe numero de cliente
    LET chrcodret = '001';
    RETURN chrcodret, chrnumcredito, chrnombreprod, chrplazo, intimporte, dtefecha,
           inttotalctas, inttotalconv, chrtipo, chractivo, chrflagcompac, intorigen;
END IF;

END;

END PROCEDURE;

