		system vsql;
		let vsql ='';
		let vsql ='rm '|| TRIM(cruta)||'archivo_sms.sql';
		system vsql;
		let vsql ='';
		let vsql = "sed 's/|$//g' "||TRIM(cruta)||"archivo_sms.unl >>"||TRIM(cruta)|| cnombre;		
		system vsql;
		let vsql ='rm '|| TRIM(cruta)||'archivo_sms.unl ' ;
		system vsql; 
