TRUNCATE credito;  
end if;
---------------------------------------------------------MORA-----SMS-------------------------------------------------------
--	let 	vfecha = '09-05-2013';					-----------------PRUEBAS
if(day(vfecha) = 5)then
	let vfecha = vfecha - 1 units month;
--	if(day(vfecha)= 1) then let vfecha = mdy(month(vfecha),day(22),year(vfecha)); end if;
--	if(day(vfecha)= 2) then let vfecha = mdy(month(vfecha),day(23),year(vfecha)); end if;
--	if(day(vfecha)= 3) then let vfecha = mdy(month(vfecha),day(24),year(vfecha)); end if;
--	if(day(vfecha)= 4) then let vfecha = mdy(month(vfecha),day(25),year(vfecha)); end if;
	if(day(vfecha)= 5) then let vfecha = mdy(month(vfecha),day(22),year(vfecha)); end if;
	
--	select mov.num_credito, mov.fecha_mov , mov.monto
	select {+INDEX(bdicobranza:cb_info_administrativa_his idx_admin3_his)} {+INDEX(bdicred:sd_movhis inx_movhis)} mov.num_credito, mov.fecha_mov , mov.monto
	from bdicobranza:cb_info_administrativa_his his, bdicred:sd_movhis mov
	where 
            his.num_campania = 5 
		and his.fecha_ejecucion >= vfecha and his.fecha_ejecucion <= date(vfecha) + 4 units day  
        and mov.empresa= '001' and mov.fecha_mov >= vfecha and mov.fecha_mov <= date(vfecha) + 8 units day 
		and his.credito =  mov.num_credito  
		and mov.codigo_fun in ('033','334','335','336','337','904')	and mov.codigo_ref = 1 	and mov.reversado = 'N'
        and producto in ('6001','6600')
	into temp movhis_tc_sms_mora;
	
	create index idx_movhis_tc_sms_mora on movhis_tc_sms_mora(num_credito,fecha_mov);   UPDATE STATISTICS medium FOR TABLE movhis_tc_sms_mora; 
		
	select {+INDEX(bdimnsj:mnsjr_trx_batch_his inxb_id_mensaje_his)} * from bdimnsj:mnsjr_trx_batch_his 
	where id_mensaje in ('TC_MORA1S','TC_MORA2S') 
	and date(fecha_hora_registro) >= vfecha and date(fecha_hora_registro) <= date(vfecha) + 4 units day 
	into temp latinia_tc1;
	
	FOREACH

--		select his.cliente, his.credito, 
		select {+INDEX(bdicobranza:cb_info_administrativa_his idx_admin3_his)} his.cliente, his.credito, 
                his.t_celular, his.nombre1, his.nombre2 , his.apell_paterno  ,his.apell_materno , pago_venc,
--				nvl(his.sdo_venc_int_mora,0) , nvl(his.pago_min,0) , nvl(his.pago_min_sin_vdo,0) , nvl(his.pago_vencido,0) , nvl(his.pago_req_sms,0)
				his.sdo_venc_int_mora, his.pago_min, his.pago_min_sin_vdo, his.pago_vencido, his.pago_req_sms
		into  vnumcte,vnum_credito,vcorreo_sms ,vnombre1 ,vnombre2 ,vapell_p 	,	vapell_m 	,	vmora 	,
				vsdo_venc_int_mora  ,vpago_minimo_total ,	vpago_min_sin_vdo  ,vpago_vencido ,vpago_req_mail	
		from bdicobranza:cb_info_administrativa_his his
			where his.num_campania = 5
			and his.fecha_ejecucion >= vfecha and his.fecha_ejecucion <= date(vfecha) + 4 units day  

        if vsdo_venc_int_mora is null then let vsdo_venc_int_mora = 0; end if;
        if vpago_minimo_total is null then let vpago_minimo_total = 0; end if;
        if vpago_min_sin_vdo is null then let vpago_min_sin_vdo = 0; end if;
        if vpago_vencido is null then let vpago_vencido = 0; end if;
        if vpago_req_mail is null then let vpago_req_mail = 0; end if;
		
		select  est.estado||'-'||est.siglas, cid.numerociudad||'-'||cid.inicialciudad
		into vciudad,vestado 
		from bdinteg:si_direcciones_actual act,  bdinteg:si_estados est,bdinteg:si_catciudades cid
		where act.estado = est.estado
			and act.ciudad = cid.numerociudad 
			and act.numcte = vnumcte
			and act.tipo_dir = 1;		
		
--		select limit 1 nvl(estatus,0),  date(fecha_hora_registro) 
		select limit 1 estatus,  fecha_hora_registro
			into vestatus,vfecha_envio
		from latinia_tc1
		where cliente = vnumcte and   cuenta  = vnum_credito;

        if vestatus is null then let vestatus = 0; end if;
			
		if (vestatus = 1 )then	let vresultado = 'COMPLETO';	end if;
		if (vestatus <> 1 )then	let vresultado = 'INCOMPLETO';	end if;
		
--		select nvl(sum(monto),0) into vpag1
		select sum(monto) into vpag1
		from movhis_tc_sms_mora
		where num_credito = vnum_credito AND fecha_mov = vfecha_envio;

        if vpag1 is null then let vpag1 = 0; end if;
		
--		select nvl(sum(monto),0) into vpag2
		select sum(monto) into vpag2
		from movhis_tc_sms_mora
		where  num_credito = vnum_credito AND fecha_mov = vfecha_envio + 1 units day;

        if vpag2 is null then let vpag2 = 0; end if;
		
--		select nvl(sum(monto),0) into vpag3
		select sum(monto) into vpag3
		from movhis_tc_sms_mora
		where  num_credito = vnum_credito AND fecha_mov = vfecha_envio + 2 units day;
		
        if vpag3 is null then let vpag3 = 0; end if;

--		select nvl(sum(monto),0) into vpag4
		select sum(monto) into vpag4
		from movhis_tc_sms_mora
		where  num_credito = vnum_credito AND fecha_mov = vfecha_envio + 3 units day;

        if vpag4 is null then let vpag4 = 0; end if;
		
--		select nvl(sum(monto),0) into vpag5
		select sum(monto) into vpag5
		from movhis_tc_sms_mora
		where  num_credito = vnum_credito AND fecha_mov = vfecha_envio + 4 units day;

        if vpag5 is null then let vpag5 = 0; end if;
		
		let vtotal =  vpag1 + vpag2 + vpag3 + vpag4 + vpag5;
			
	insert into credito
	values( vnumcte,vnum_credito,vciudad,vestado ,vcorreo_sms ,vnombre1 ,vnombre2 ,vapell_p 	,	
	vapell_m ,	vmora ,vsdo_venc_int_mora  ,vpago_minimo_total ,vpago_min_sin_vdo  ,vpago_vencido ,vpago_req_mail ,	
	0 ,	vfecha_envio ,	vresultado ,vpag1 ,vpag2 ,vpag3 , vpag4 ,vpag5 ,vpag6,vtotal );
	
		
    End ForEach;

--------------------------------------------------------GENERAR ARCHIVO--------------------------------------------------------
--	LET  cruta = '/informix/eli/';
	let cnombre = 'rep_envio_sms_tc_mora_'||day(today)||LPAD (MONTH(today),2,"0")||year(today)||'.txt';
		let vsql = '';
		let cSql='';
		LET cSQL1 = ' echo " SET ISOLATION TO DIRTY READ; UNLOAD TO ' || TRIM(cruta) || 'creditos.unl' || ' DELIMITER ' || ''''|| cdelimitador || ''''||'';
		LET cSQL2 = " select * from credito";
		LET cSQL3 = '">'||TRIM(cRuta)||'creditos.sql';
		LET cSQL = trim(cSQL1) || cSQL2 || trim(cSQL3);
		System cSQL;
	
		LET vsql='chmod 777 '|| TRIM(cRuta)||'creditos.sql';
		System vsql;
		let vsql = '';
		let vsql= 'dbaccess bdicobranza ' || TRIM(cruta)||'creditos.sql';
		system vsql;
		let vsql ='';
		let vsql ='rm '|| TRIM(cruta)||'creditos.sql';
		system vsql;
		let vsql ='';
		let vsql = "sed 's/|$//g' "||TRIM(cruta)||"creditos.unl >>"||TRIM(cruta)|| cnombre;		
		system vsql;
		let vsql ='rm '|| TRIM(cruta)||'creditos.unl ' ;
		system vsql; 

end if;
--------------------------------------------------------------------------------------------------
	
	CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, P_COD_RET, cMensaje, '03') RETURNING P_COD_RET;
    RETURN P_COD_RET;

end;
end procedure;

CREATE PROCEDURE "informix".sp_catpromo_prestamo_aut()
--  execute  PROCEDURE "informix".sp_catpromo_prestamo_aut();
RETURNING 	CHAR(5)  AS codigo_retorno;			
			
---DECLARACIONES
DEFINE cCodRet        	CHAR(6); 
DEFINE iSqlErr      	INTEGER;
DEFINE dtFechaHoy		DATE;
DEFINE cNumCte			CHAR(20);
DEFINE cNumCred			CHAR(20);

DEFINE cproceso         CHAR(4);
DEFINE vvalor_numerico	INTEGER;
DEFINE vtotal1			INTEGER;
DEFINE vtotal			INTEGER;
DEFINE vtotal2			INTEGER;
define vregistrostotal	integer;
define vcontador 		integer;
DEFINE cMensaje         VARCHAR(80);
DEFINE vproceso			CHAR (4);
DEFINE cCel				char(13);
DEFINE iCel 			smallint;
DEFINE vdia7			smallint;
DEFINE vdia14			smallint;
define vnombre			char(10);
define vnombre1			char(10);
define vnombre2			char(10);
define vfecha			DATE;
define vpri_dia_mes		DATE;
define vfechas			char(6);

--SET DEBUG FILE TO 'prestamoautorizacioncat.out';
--TRACE ON;
---INICIALIZACIONES
LET iSqlErr             = 0;
LET cCodRet             = "000000";
LET dtFechaHoy			= DATE(1);
LET cNumCte				= '';
LET cNumCred				= '';

LET vproceso	='2037';
LET cMensaje    = 'PROCESO EXITOSO';
let vvalor_numerico	= 0;
let vtotal1			= 0;
let vtotal			= 0;
let vregistrostotal = 0;
let vcontador 		= 0;
let cCel			= '';
LET iCel 			= 0;
let vdia7 = 0;
let vdia14 = 0;
let vnombre = '';
let vnombre1 = '';
let vnombre2 = '';
let vfecha = date(1);
let vpri_dia_mes = date(1);
let vfechas = '';


BEGIN
ON EXCEPTION SET iSqlErr
    LET cCodRet= iSqlErr;
	CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, cCodRet, cMensaje, '02') RETURNING cCodRet; 
    RETURN cCodRet;
END EXCEPTION;
--SET DEBUG FILE TO 'prestamoaper.out';
--TRACE ON;
	CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, cCodRet, cMensaje, '01') RETURNING cCodRet; 
	   
	SELECT NVL(fecha_hoy ,''),pri_dia_mes
	INTO dtFechaHoy, vpri_dia_mes
	FROM bdicred:"informix".sd_fechas
	WHERE empresa = '001';	
--let dtFechaHoy = '08-14-2012';	--PRUEBAS
	SET LOCK MODE TO WAIT 3;
	SET ISOLATION DIRTY READ;
	
	select valor_numerico into vdia7
	from bdicobranza:cb_param_campania	where tipo_campania = 50 and num_parametro = 64;
	select valor_numerico into vdia14
	from bdicobranza:cb_param_campania	where tipo_campania = 50 and num_parametro = 65;
	select valor_numerico into vvalor_numerico
	from bdicobranza:cb_param_campania	where tipo_campania = 50 and num_parametro = 67;
	
	
	/*select count(*) into vtotal1
	from bdicobranza:cb_administativa_latinia
	where num_campania = 6 and fecha_insert >= mdy(month(dtFechaHoy),day(01),year(dtFechaHoy));*/
	select count(*) into vtotal1
	from bdimnsj:mnsjr_trx_batch
	where id_mensaje = 'PREST_PERS' 
	  and to_char(fecha_hora_registro,'%m%Y') = to_char(vpri_dia_mes,'%m%Y');
	
	select count(*) into vtotal2
	from bdimnsj:mnsjr_trx_batch_his 
	where id_mensaje = 'PREST_PERS' 
	  and to_char(fecha_hora_registro,'%m%Y') = to_char(vpri_dia_mes,'%m%Y');
		
	---- consulta para saber cuantos registros faltan por buscar al mes	
	let vregistrostotal = vvalor_numerico - vtotal1;
	
	LET vtotal = vtotal1 + vtotal2;
	if (day(dtFechaHoy) = 1 ) then 
		let vtotal = 0; 
		let vregistrostotal = vvalor_numerico;
	end if;

	if(nvl(vtotal,0) < nvl(vvalor_numerico,0)) then
	FOREACH		
    	SELECT limit vregistrostotal NVL(sol.numcte,''), NVL(sol.num_solicitud,'')
    		INTo cNumCte, cNumCred
    	FROM bdisolic:ss_solicitudes sol, bdisolic:ss_autorizacion aut
    	WHERE sol.empresa = '001' 
			and sol.num_solicitud = aut.num_solicitud AND aut.status_solicitud = 'AT'
			AND aut.fecha_entrada=(SELECT MAX(aut_aux.fecha_entrada)
                                    FROM bdisolic:"informix".ss_autorizacion aut_aux
                                    WHERE aut_aux.empresa= sol.empresa
                                    AND aut_aux.num_solicitud= sol.num_solicitud
                                    AND aut_aux.status_solicitud= sol.status_solicitud)
			AND aut.ejecutivo_auto= aut.ejecutivo_auto
            AND sol.num_solicitud NOT IN 
						(select num_credito FROM bdicred:sd_maecredcrd WHERE empresa = '001' AND num_credito = sol.num_solicitud)
            AND sol.status_solicitud = 'AT'
            AND sol.num_producto = '6300'
            AND (aut.fecha_entrada = date(dtFechaHoy) - vdia7 units day or aut.fecha_entrada = date(dtFechaHoy) - vdia14 units day)
				
		  
		SELECT limit 1 d.telefono
			INTO cCel
		FROM bdinteg:"informix".si_telefonos_actual d
		WHERE d.numcte= cNumCte
			AND d.tipo_tel= '2' and cofetel ='V' ; 
			  
		if (cCel <> '') then	
			LET iCel = LENGTH(cCel) + 1 - 10;
    	  
			IF cCel <> '' then
				IF ( LENGTH(cCel) > 10 ) THEN
					LET cCel = SUBSTR(cCel,iCel,10);
				ELIF ( LENGTH(cCel) < 10 ) THEN
					LET cCel ='';
				END IF;
			END IF;
		end if;
		
		select nombre1,nombre2 into vnombre1 ,vnombre2
		from bdinteg:si_cliente
		where empresa = '001' and numcte = cNumCte ; -- SUBSTR(nombre1,1,10)
		
		if ( LENGTH(vnombre1) <=  3 ) then
			LET vnombre = TRIM(vnombre1)||' '||TRIM(SUBSTR(vnombre2,1,9 - LENGTH(vnombre1)));
		Else
			LET vnombre = TRIM(SUBSTR(vnombre1,1,10));
		end if;

		let vfecha = date(dtFechaHoy) + 1 units month;
		let vfechas = lpad(day(vfecha),2,'0')||'-'|| decode (month(vfecha),01,'Ene',02,'Feb',03,'Mar',04,'Abr',05,'May',06,'Jun',
																   07,'Jul',08,'Ago',09,'Sep',10,'Oct',11,'Nov',12,'Dic');
			
    	IF cCel <> '' then
			/*insert into bdicobranza:cb_administativa_latinia(num_campania,numcte,num_credito,telefono,tarjeta ,apellido_pat,fecha,fecha_insert)
			values (6,cNumCte,cNumCred, cCel, '', vnombre, vfecha,dtFechaHoy);*/
			
			call bdimnsj:"informix".sp_registra_evento (2, 'PREST_PERS' , cNumCte, cNumCred,'', 2,
							vnombre,vfechas,'','','',0,0,0,0,0, '', '')RETURNING cCodRet;
					--let vcontador = vcontador + 1;
    	end if;		
	END FOREACH;	
	end if;
	
	/*if(vtotal < vvalor_numerico and vcontador > 1) then  
		CALL bdicobranza:"informix".sp_sms_reporte(6,0,0,0) RETURNING 	cCodRet;
		CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, cCodRet, 'PP Apertura CampCat', '02')  RETURNING cCodRet;   
	end if;*/

	
	
	 CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, cCodRet, cMensaje, '03') RETURNING cCodRet;
	 RETURN cCodRet;  --Se ejecuto Exitosamente.
	 
END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_actualiza_contacto_historico()

RETURNING CHAR(6), CHAR(80);

--Creado: Mayo 2014 Guadalupe Espinoza.
--Descripción: Se crea sp para actualizar campo "contaco" de la tabla bdinteg:si_telefonos_actual que ya existen.

--DECLARACION DE VARIABLES
	DEFINE sql_err 			        INTEGER;
	DEFINE isam_err 		        INTEGER;
	DEFINE error_info		        CHAR(150);
	DEFINE cMensaje 		        CHAR(150);
	DEFINE cCod_ret                 CHAR(6);
	DEFINE vempresa                 CHAR(3);
	DEFINE vnumcte                  CHAR(20);
	DEFINE vtelefono                CHAR (13);
	DEFINE vtipo_telefono           INTEGER;
	DEFINE vcodigo_resultado        INTEGER;
	DEFINE cproceso                 CHAR(4);
	DEFINE vvcCod_ret               CHAR(6);
	DEFINE vfecha					DATE;

   --SET DEBUG FILE TO "/informix/gpe/sp_actualiza_contacto_historico.out";
   --TRACE ON; 

      LET cCod_ret      = '000000';
	  LET sql_err       = 0;
	  LET isam_err      = 0;
	  LET error_info    = '';
	  LET cMensaje      = 'PROCESO EXITOSO';
      LET vempresa      = '001';
      LET cproceso      = '3500';
	  LET vfecha		=DATE(1);
	  LET vtipo_telefono = 0;
                              
	BEGIN

        ON EXCEPTION SET sql_err, isam_err, error_info
	        LET cCod_ret = sql_err;
	        LET cMensaje = error_info;
            CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje, '02')
            RETURNING vvcCod_ret;
			RETURN cCod_ret, cMensaje;

	    END EXCEPTION;

            CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje, '01')
            RETURNING vvcCod_ret;
			
			--Directiva para lectura de tablas bloqueadas.
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
		

FOREACH WITH HOLD
		
		SELECT a.numcte,a.codigo_resultado,a.telefono,a.tipo_telefono
		INTO vnumcte,vcodigo_resultado,vtelefono,vtipo_telefono
		FROM bdicobranza:cb_registro_llamadas a
		INNER JOIN bdinteg:si_telefonos_actual tel on (tel.empresa = a.empresa and tel.numcte = a.numcte)
		WHERE a.empresa = vempresa
		--AND a.fecha_insert = vfecha
		AND a.codigo_resultado IN (1,2,3,4,5)
		AND tel.contacto = 0
		AND tel.tipo_tel = a.tipo_telefono
		AND tel.telefono = a.telefono
		
		begin work;
		UPDATE bdinteg:si_telefonos_actual SET contacto = 1
		 WHERE numcte = vnumcte 
		   AND tipo_tel = vtipo_telefono
		   AND telefono = vtelefono;
		commit work;
END FOREACH;
    
        CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, cProceso, cCod_ret, cMensaje, '03')
        RETURNING vvcCod_ret;
        RETURN cCod_ret, cMensaje;

	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cat_graba_telefono_adicional(pEmpresa             CHAR(3),
                                                            pOrigen              SMALLINT,
                                                            pNumcte              CHAR(20), 
                                                            pTipo_telefono       SMALLINT, 
                                                            pTelefono            CHAR(13),  
                                                            pExtension           CHAR(5), 
                                                            pParentesco          CHAR(1), 
                                                            pResultado_gestion   INTEGER, 
                                                            pEjecutivo           CHAR(8))
RETURNING
CHAR(6) AS  cCodRespuesta;

DEFINE sIsam_err        SMALLINT;
DEFINE sSql_err         SMALLINT;
DEFINE cCod_ret         CHAR(6);
DEFINE wcod_ret         CHAR(6);
DEFINE cError_info      CHAR(100);
DEFINE cEmpresa         CHAR(3);
DEFINE cNumcte          CHAR(20); 
DEFINE cEjecutivo       CHAR(8);
DEFINE cTelefono        CHAR(13);
DEFINE dFecha_hoy       DATE;
DEFINE vtipored         CHAR(1);
DEFINE vnumero_carrier  SMALLINT;

LET sIsam_err       = 0;
LET cCod_ret        = "000000";
LET cError_info     = "";
LET sSql_err        = 0;
LET cEmpresa        = "";
LET cNumcte         = "";
LET cEjecutivo      = '';
LET dFecha_hoy      = DATE(1);

BEGIN
ON EXCEPTION SET sSql_err,sIsam_err,cError_info
   LET cCod_ret = sSql_err;
   RETURN cCod_ret;
END EXCEPTION;

-- SET DEBUG FILE TO '/tmp/sp_cat_graba_telefono_adicional.out';
-- TRACE ON;
   
-- Se valida que los adatos de entrada sean validos.
IF NVL(pEmpresa,"") = "" THEN
   LET cCod_ret = "102005";
   RETURN cCod_ret;
END IF;

SELECT empresa
  INTO cEmpresa 
  FROM bdinteg:si_empresas
 WHERE empresa = pEmpresa;
       
IF NVL(cEmpresa,"")= "" then
    LET cCod_ret = "102003";
    RETURN cCod_ret;
END IF;

IF NVL(pNumcte,"") = "" THEN
   LET cCod_ret = "102006";
   RETURN cCod_ret;
END IF;

SELECT numcte
  INTO cNumcte 
  FROM bdinteg:si_cliente
 WHERE empresa = pEmpresa
   AND numcte  = pNumcte;

IF NVL(cNumcte ,"") = "" THEN
   LET cCod_ret = "102007";
   RETURN cCod_ret;
END IF; 
      
IF NVL(pEjecutivo,"") = "" THEN
   LET cCod_ret = "102008";
   RETURN cCod_ret;
END IF;
/*
SELECT ejecutivo
  INTO cEjecutivo
  FROM bdinteg:si_ejecut
 WHERE empresa   = pEmpresa
   AND ejecutivo = pEjecutivo;

IF NVL(cEjecutivo,"")= "" THEN
   LET cCod_ret = "102009";
   RETURN cCod_ret;
END IF;*/
     
IF pOrigen NOT IN(1,2,3,5) THEN
   LET cCod_ret = "102010";
   RETURN cCod_ret;
END IF;

IF NVL(pTelefono ,"")= "" THEN
    let cCod_ret = "102011";
    RETURN cCod_ret;
END IF;

-- // Valida que el teléfono sea numerico (válido)
IF bdinteg:val_num(pTelefono) = 'f' THEN
    LET cCod_ret = "30001";
    RETURN cCod_ret;
END IF

-- Se la valida que el telefono no exista 
IF NOT EXISTS (SELECT telefono 
             FROM bdicobranza:cb_telefonos
             WHERE numcte   = pNumcte
             AND telefono = pTelefono
             AND tipo_telefono  = pTipo_telefono) THEN


    SELECT fecha_hoy
    INTO dFecha_hoy
    FROM bdicred:sd_fechas
    WHERE empresa = pEmpresa;

    ---EXECUTE PROCEDURE bdinteg:"informix".sp_tipored (pEmpresa, pTelefono) 
    --INTO wCod_ret , vtipored , vnumero_carrier;
/*
        INSERT INTO bdicobranza:cb_telefonos(empresa,origen,numcte,telefono,tipo_telefono,
                                     extension, tipored, quiencontestouc,estatus,codigo_resultado,
                                     fecha_insert,user_insert, numero_carrier)
        VALUES(pEmpresa,pOrigen,pNumcte,pTelefono,pTipo_telefono,
            pExtension, vtipored, pParentesco,'AC',pResultado_gestion,
            dFecha_hoy,pEjecutivo, vnumero_carrier);  
*/---MAJF Insercion de Telefonos Abril 2012

    execute procedure bdinteg:"informix".sp_registra_telefonos (pEmpresa, pNumcte, pTelefono, pTipo_telefono, pExtension,1, 2, user  )
    into cCod_ret ;

      If cCod_ret = '000' then Let cCod_ret ='00000'; end if;

    --LET cCod_ret = "102012";
    RETURN cCod_ret;
END IF;
   
  RETURN cCod_ret;

END
END PROCEDURE
DOCUMENT
'Descrpcion: Graba un nuevo teléfono proporcionado a la cobranza telefónica',
'Autor:Leonardo Arellano',
'Fecha: 30-09-2010',
'Version:20100927.1300',
'Bdicobranza',
'Autor: Marco A. Campos',
'Modificación: 2012-03-01. Agregar el origen 5 (Buró) en validación de pOrigen';

CREATE PROCEDURE "informix".sp_cat_consulta_saldostc(pEmpresa      CHAR(3),
                                                     pCliente      CHAR(20),
                                                     pNumRegistros INTEGER)

RETURNING CHAR(6)        AS codigo_respuesta, 
          CHAR(2)        AS tipo_producto,
          CHAR(40)       AS producto,
          CHAR(20)       AS num_credito,
          CHAR(20)       AS num_tarjeta,
          DATE           AS Fecha_ult_cargo,
          DECIMAL(18,2)  AS imp_sdo_total,
          DECIMAL(18,2)  AS imp_int_moratorio,
          DECIMAL(18,2)  AS sdo_venc_int_mora,
          DECIMAL(18,2)  AS imp_siguiente_pagomin,
          DECIMAL(18,2)  AS imp_mensual,
          DECIMAL(18,2)  AS imp_vencido,
          SMALLINT       AS num_pagos_vencidos,
          DATE           AS fecha_ultimo_pago,
          DECIMAL(18,2)  AS imp_ultimo_pago,
          SMALLINT       AS tipo_convenio,
          DECIMAL(18,2)  AS importe_min,
          DATE           AS prox_fecha_pago;


DEFINE iSqlErr      	INTEGER;
DEFINE iIsamErr         INTEGER;
DEFINE cErrorInfo       CHAR(80);
DEFINE cCodRet          CHAR(6);
DEFINE cEmpresa         CHAR(3);
DEFINE cNumCte          CHAR(20);
DEFINE cEjecutivo       CHAR(10);
DEFINE iRegistros       INTEGER;
DEFINE cMensaje         CHAR(80);
DEFINE cNumCredito      CHAR(20);
DEFINE cNomProducto     CHAR(40);
DEFINE cNumTarjeta      CHAR(20);
DEFINE cNomCte          CHAR(150);
DEFINE iIntAux          INTEGER;
DEFINE cCharAux         CHAR(80);
DEFINE dDecAux          DECIMAL(18,2);
DEFINE dtDateAux        DATE;
DEFINE dImpSdoTotal     DECIMAL(18,2);
DEFINE dImpMensual      DECIMAL(18,2);
DEFINE dImpVdo          DECIMAL(18,2);
DEFINE dImpVdoT         DECIMAL(18,2);
DEFINE dImpIntMora      DECIMAL(18,2);
DEFINE dSdoVdoIntMora   DECIMAL(18,2);
DEFINE dImpSigPagoMin   DECIMAL(18,2);
DEFINE sNumPagosVdos    SMALLINT;
DEFINE dtFechaUltPago   DATE;
DEFINE dtFechaProxPago   DATE;
DEFINE dImpUltPago      DECIMAL(18,2);
DEFINE dtFechaHoy       DATE;
DEFINE sTpoConvenio     SMALLINT;
DEFINE iContador        INTEGER;
DEFINE cTipCred         CHAR(2);
DEFINE cTipCredAux      CHAR(2);
DEFINE dtUltFechaCargo  DATE;
DEFINE cint_vdo         DECIMAL(18,2);
DEFINE civa_int_vdo     DECIMAL(18,2);
DEFINE civa_int_mor     DECIMAL(18,2);
DEFINE dImporte      	DECIMAL(18,2);
DEFINE iMaximo_vencido  INTEGER;
DEFINE dPagoMinimoAux	DECIMAL(18,2);
DEFINE vPorcentaje      DECIMAL(18,2);
DEFINE tipo             char (4);
DEFINE vnumproducto     char (4);
DEFINE vexistenum       char (20);
DEFINE dfecha_insert    DATE;
DEFINE cTipProd6001     CHAR(2);
DEFINE cTipProd6300     CHAR(2);
DEFINE cTipProd6011     CHAR(2);
DEFINE cTipProd6400     CHAR(2);


LET iSqlErr          = 0;
LET iIsamErr         = 0;
LET cErrorInfo       = "";
LET cCodRet          = "000000";
LET cEmpresa         = "";
LET cNumCte          = "";
LET cEjecutivo       = "";
LET iRegistros       = 0;
LET cMensaje         = "";
LET cNumCredito      = "";
LET cNomProducto     = "";
LET cNumTarjeta      = "";
LET cNomCte          = "";
LET iIntAux          = 0;
LET cCharAux         = "";
LET dDecAux          = 0;
LET dtDateAux        = DATE(1);
LET dImpSdoTotal     = 0;
LET dImpMensual      = 0;
LET dImpVdo          = 0;
LET dImpVdoT         = 0;
LET dImpIntMora      = 0;
LET dSdoVdoIntMora   = 0;
LET dImpSigPagoMin   = 0;
LET sNumPagosVdos    = 0;
LET dtFechaUltPago   = DATE(1);
LET dtFechaProxPago  = DATE(1);
LET dImpUltPago      = 0;
LET dtFechaHoy       = DATE(1);
LET sTpoConvenio     = 0;
LET iContador        = 0;
LET cTipCred         = "TV";
LET cTipCredAux      = "";
LET cint_vdo         = 0;
LET civa_int_vdo     = 0;
LET civa_int_mor    = 0;
LET dtUltFechaCargo = DATE(1);
LET dImporte        = 0;
LET iMaximo_vencido = 0;
LET dPagoMinimoAux  = 0;
LET vPorcentaje     = 0;
LET tipo            = '';
LET vnumproducto    = '';
LET vexistenum      = '';
LET cTipProd6001    = '';
LET cTipProd6300    = '';
LET cTipProd6011    = '';
LET cTipProd6400    = '';

--SET DEBUG FILE TO "/tmp/sp_cat_consulta_saldostc.out";
--TRACE ON;

BEGIN  
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
        IF iSqlErr != 0 THEN
            LET cCodRet= iSqlErr;
            RETURN cCodRet, NVL(cTipCred,""), NVL(cNomProducto,""), NVL(cNumCredito,""), NVL(cNumTarjeta,""), NVL(dtUltFechaCargo,0),
                 NVL(dImpSdoTotal,0), NVL(dImpIntMora,0), NVL(dSdoVdoIntMora,0), NVL(dImpSigPagoMin,0), NVL(dImpMensual,0),
                NVL(dImpVdoT,0), NVL(sNumPagosVdos,0), NVL(dtFechaUltPago,DATE(1)), NVL(dImpUltPago,0), NVL(sTpoConvenio,0),NVL(dImporte,0), nvl(dtFechaProxPago, date(1));
        END IF;
    END EXCEPTION;
 

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    -- Se validan los parámetros de ejecución
    SELECT empresa
        INTO cEmpresa
        FROM bdinteg:"informix".si_empresas
        WHERE empresa= pEmpresa;

    IF cEmpresa IS NULL THEN
        LET cCodRet = "101001";
        RETURN cCodRet, NVL(cTipCred,""), NVL(cNomProducto,""), NVL(cNumCredito,""), NVL(cNumTarjeta,""), NVL(dtUltFechaCargo,0),
             NVL(dImpSdoTotal,0), NVL(dImpIntMora,0), NVL(dSdoVdoIntMora,0), NVL(dImpSigPagoMin,0), NVL(dImpMensual,0),
             NVL(dImpVdoT,0), NVL(sNumPagosVdos,0), NVL(dtFechaUltPago,DATE(1)), NVL(dImpUltPago,0), NVL(sTpoConvenio,0),NVL(dImporte,0), nvl(dtFechaProxPago, date(1));
    END IF;

    SELECT numcte
        INTO cNumCte
        FROM bdinteg:"informix".si_cliente
        WHERE numcte= pCliente;

    IF cNumCte IS NULL THEN
        LET cCodRet = "101003";
        RETURN cCodRet, NVL(cTipCred,""), NVL(cNomProducto,""), NVL(cNumCredito,""), NVL(cNumTarjeta,""), NVL(dtUltFechaCargo,0),
                 NVL(dImpSdoTotal,0), NVL(dImpIntMora,0), NVL(dSdoVdoIntMora,0), NVL(dImpSigPagoMin,0), NVL(dImpMensual,0),
                 NVL(dImpVdoT,0), NVL(sNumPagosVdos,0), NVL(dtFechaUltPago,DATE(1)), NVL(dImpUltPago,0), NVL(sTpoConvenio,0),NVL(dImporte,0), nvl(dtFechaProxPago, date(1));
    END IF;

    IF NVL(pNumRegistros,0) <= 0 THEN
        LET cCodRet = "101006";
        RETURN cCodRet, NVL(cTipCred,""), NVL(cNomProducto,""), NVL(cNumCredito,""), NVL(cNumTarjeta,""), NVL(dtUltFechaCargo,0),
             NVL(dImpSdoTotal,0), NVL(dImpIntMora,0), NVL(dSdoVdoIntMora,0), NVL(dImpSigPagoMin,0), NVL(dImpMensual,0),
             NVL(dImpVdoT,0), NVL(sNumPagosVdos,0), NVL(dtFechaUltPago,DATE(1)), NVL(dImpUltPago,0), NVL(sTpoConvenio,0),NVL(dImporte,0), nvl(dtFechaProxPago, date(1));
    ELSE
        LET iRegistros = pNumRegistros;
    END IF;

    -- Se obtiene la fecha hoy del sistema
    SELECT {+INDEX(bdicred:sd_fechas idx_sdfechas)} fecha_hoy
        INTO dtFechaHoy
        FROM bdicred:"informix".sd_fechas
        WHERE empresa = cEmpresa;

    -- Obtiene los tipos de producto dependiente del numero de producto        
    SELECT valor_alfabetico INTO cTipProd6001 FROM bdicobranza:cb_param_campania WHERE empresa = pempresa AND tipo_campania = 1
        AND grupo_parametro = 'TIPOCOBCAT' AND num_parametro = 1 AND valor_numerico = 6001;

    --- Obtiene datos del registro marcado en sp sp_cat_consulta_disponibilidad_cliente 
    SELECT first 1 tipo_cobranza, fecha_insert, num_producto, num_credito  
        INTO tipo, dfecha_insert, vnumproducto, cNumCredito
        FROM bdicobranza:"informix". cb_cat_directorio_cte
        WHERE empresa = pempresa
        AND numcte = pCliente 
        AND cobranza_aux_direct = '1';

    IF (nvl(vnumproducto,'') ='') THEN
        SELECT first 1 tipo_cobranza, fecha_insert, num_producto, num_credito
            INTO tipo, dfecha_insert, vnumproducto, cNumCredito
            FROM bdicobranza:"informix".cb_cat_directorio_cte
            WHERE empresa = pempresa
            AND numcte = pCliente;
    END IF;
  
    IF NVL(vnumproducto,'') = '' THEN
        LET vnumproducto = '6001';
    END IF;
  
/*  select first 1 tipo_cobranza into tipo
    from bdicobranza:cb_cat_directorio_cte
    where empresa = pEmpresa
    and numcte = pCliente;

    IF (tipo IN ('R','E')) THEN
        select  num_producto into vnumproducto
		from bdicred:sd_maecredcrd
			where empresa = pempresa and num_credito =
			(select num_credito from bdicobranza:cb_cat_directorio_cte where tipo_cobranza = tipo and  numcte=pCliente);
    ELSE
        select  num_producto into vnumproducto
            from bdicred:sd_maecred
            where empresa = pempresa and num_credito =
                (select num_credito from bdicobranza:cb_cat_directorio_cte where tipo_cobranza = tipo and  numcte=pCliente);
    END IF;
*/
    IF vnumproducto = '6011' THEN
        SELECT valor_alfabetico INTO cTipProd6011 
            FROM bdicobranza:cb_param_campania WHERE empresa = pempresa AND tipo_campania = 1
            AND grupo_parametro = 'TIPOCOBCAT' AND num_parametro = 3 AND valor_numerico = 6011;

        LET cTipCred = cTipProd6011;

    ELIF vnumproducto = '6300' THEN
        SELECT valor_alfabetico INTO cTipProd6300 
            FROM bdicobranza:cb_param_campania WHERE empresa = pempresa AND tipo_campania = 1
            AND grupo_parametro = 'TIPOCOBCAT' AND num_parametro = 2 AND valor_numerico = 6300;

        LET cTipCred = cTipProd6300;

    ELIF vnumproducto = '6400' THEN 
        SELECT valor_alfabetico INTO cTipProd6400 
            FROM bdicobranza:cb_param_campania WHERE empresa = pempresa AND tipo_campania = 1
            AND grupo_parametro = 'TIPOCOBCAT' AND num_parametro = 4 AND valor_numerico = 6400;

        LET cTipCred = cTipProd6400;

    ELSE
        LET cTipCred = cTipProd6001;
        LET vnumproducto = '6001'; 
    END IF

    FOREACH
        -- Se obtienen los datos generales del cliente  
        EXECUTE PROCEDURE bdicred:"informix".sp_consulta_datos_general(cEmpresa,cNumCte,cNumCredito,"","","",vnumproducto)
                    INTO cCodRet, cMensaje, cNumCredito, cNumCte, cNomProducto, cNumTarjeta, cNomCte
        IF cCodRet <> "000000" THEN
            LET cCodRet = "101007"; -- Ocurrió un error al ejecutar la consulta de datos general
            RETURN cCodRet, NVL(cTipCred,""), NVL(cNomProducto,""), NVL(cNumCredito,""), NVL(cNumTarjeta,""), NVL(dtUltFechaCargo,0),
                 NVL(dImpSdoTotal,0), NVL(dImpIntMora,0), NVL(dSdoVdoIntMora,0), NVL(dImpSigPagoMin,0), NVL(dImpMensual,0),
                 NVL(dImpVdo,0), NVL(sNumPagosVdos,0), NVL(dtFechaUltPago,DATE(1)), NVL(dImpUltPago,0), NVL(sTpoConvenio,0),NVL(dImporte,0), nvl(dtFechaProxPago, date(1));
        END IF;

        IF tipo in ('R','E') THEN  -- Obtiene el numero de cuenta para tipo cobranza = R  en la variable de Num Tarjeta
            SELECT num_cta INTO cNumTarjeta
                FROM bdicred:sd_ctascarg WHERE num_credito = cNumCredito AND naturaleza= 'A';
        END IF

        IF iContador > iRegistros THEN
            EXIT FOREACH;
        END IF;
        
        -- Se obtienen los datos generales del crédito
        EXECUTE PROCEDURE bdicred:"informix".sp_consulta_saldos_general(cEmpresa,cNumCredito)
                    INTO cCodRet,cMensaje,cCharAux,cTipCredAux,dtDateAux,dtDateAux,dImpMensual,dtFechaUltPago,
                         iIntAux,iIntAux,dDecAux,dDecAux,dDecAux,dDecAux,dDecAux,dImpVdo,dImpVdoT,dDecAux,
                         dDecAux,dDecAux,cint_vdo,dImpIntMora,dDecAux,dDecAux,dDecAux,civa_int_vdo,civa_int_mor,dDecAux,
                         dDecAux,dDecAux,dDecAux,dDecAux,dImpSdoTotal,dDecAux,dDecAux,dDecAux,sNumPagosVdos,cCharAux,
                         iIntAux,cCharAux,cCharAux,cCharAux,cCharAux,iIntAux,cCharAux,cCharAux,iIntAux,
                         cCharAux;


        IF cCodRet <> "000000" THEN
            LET cCodRet = "101005"; -- Ocurrió un error al ejecutar la consulta de saldos general
            RETURN cCodRet, NVL(cTipCred,""), NVL(cNomProducto,""), NVL(cNumCredito,""), NVL(cNumTarjeta,""), NVL(dtUltFechaCargo,0),
                 NVL(dImpSdoTotal,0), NVL(dImpIntMora,0), NVL(dSdoVdoIntMora,0), NVL(dImpSigPagoMin,0), NVL(dImpMensual,0),
                 NVL(dImpVdoT,0), NVL(sNumPagosVdos,0), NVL(dtFechaUltPago,DATE(1)), NVL(dImpUltPago,0), NVL(sTpoConvenio,0),NVL(dImporte,0), nvl(dtFechaProxPago, date(1));
        END IF;
        LET dImpVdoT    = dImpVdoT + dImpVdo; 
        LET dImpIntMora = dImpIntMora + civa_int_mor;
        --calcular el monto nimimo a negociar
		SELECT MAX(Meses_vencido)
            INTO iMaximo_vencido
            FROM bdicobranza:cb_compac_montomin;

        IF sNumPagosVdos > iMaximo_vencido THEN
            LET sNumPagosVdos = iMaximo_vencido;
        END IF;

		LET dPagoMinimoAux = ROUND(dImpMensual);

		SELECT Porcentaje
            INTO vPorcentaje
			FROM bdicobranza:cb_compac_montomin
			WHERE Meses_vencido = sNumPagosVdos
			AND Monto_vencido_min <= dPagoMinimoAux
			AND Monto_vencido_max >= dPagoMinimoAux;

        LET dImporte = (vPorcentaje * dImpMensual)/100;

        -- Se calcula el importe de saldo vencido de interes moratorio
        LET dSdoVdoIntMora = dImpMensual;

        --- calculo de intereses
        LET dImpIntMora = dImpIntMora+ cint_vdo + civa_int_vdo;
        -- Calculo del Saldo correspondiente del mes MAJF Julio 2011
        LET dImpMensual = dImpMensual - (dImpVdot +  dImpIntMora );

        -- Se calcula el importe de pago minimo siguiente
        LET dImpSigPagoMin = dSdoVdoIntMora + dImpMensual;

        SELECT num_credito
            INTO vexistenum
			FROM bdicred:"informix".sd_maecred
			WHERE num_credito = cNumCredito;

        IF (vexistenum = cNumCredito) THEN

            -- Se calcula el importe del último pago realizado en base al día en que se realizó
            IF dtFechaUltPago = dtFechaHoy THEN
                SELECT NVL(SUM(monto),0)
                    INTO dImpUltPago
                    FROM bdicred:sd_movdia
                    WHERE empresa     = cEmpresa
                    AND fecha_mov   = dtFechaUltPago
                    AND num_credito = cNumCredito
                    AND codigo_fun IN (select cod_fun from bdicred:sd_conceptospagomanual)
                    AND codigo_ref =1
                    AND reversado = "N";
            ELSE
                SELECT NVL(SUM(monto),0)
                    INTO dImpUltPago
                    FROM bdicred:sd_movhis
                    WHERE empresa     = cEmpresa
                    AND fecha_mov   = dtFechaUltPago
                    AND num_credito = cNumCredito
                    AND codigo_fun IN (select cod_fun from bdicred:sd_conceptospagomanual)
                    AND codigo_ref =1
                    AND reversado = "N";
            END IF;

            -- Se obtiene la fecha del último cargo realizado
            SELECT MAX(fecha_mov)
                INTO dtUltFechaCargo
                FROM bdicred:sd_movdia
                WHERE empresa = cEmpresa
                AND num_credito = cNumCredito
                AND codigo_fun ='002'
                AND codigo_ref = 37
                AND reversado = 'N';

            -- Obtener ultima fecha de disposiciones
            IF NVL(dtUltFechaCargo,DATE(1)) = DATE(1) THEN
                SELECT MAX(fecha_mov)
                    INTO dtUltFechaCargo
                    FROM bdicred:sd_movdia
                    WHERE empresa = cEmpresa
                    AND num_credito = cNumCredito
                    AND codigo_fun = '002'
                    AND codigo_ref IN (50,30,40,41,42)
                    AND reversado='N';
            END IF;

            IF NVL(dtUltFechaCargo,DATE(1)) = DATE(1) THEN
                SELECT MAX(fecha_mov)
                    INTO dtUltFechaCargo
                    FROM bdicred:sd_movhis
                    WHERE empresa = cEmpresa
                    AND num_credito = cNumCredito
                    AND codigo_fun ='002'
                    AND codigo_ref = 37
                    AND reversado = 'N';

                IF NVL(dtUltFechaCargo,DATE(1)) = DATE(1) THEN
                    SELECT MAX(fecha_mov)
                        INTO dtUltFechaCargo
                        FROM bdicred:sd_movhis
                        WHERE empresa = cEmpresa
                        AND num_credito = cNumCredito
                        AND codigo_fun = '002'
                        AND codigo_ref IN (50,30,40,41,42)
                        AND reversado='N';
                END IF;
            END IF;
            select prox_fecha_pago into dtFechaProxPago
              from bdicred:sd_maecredanexo
             where empresa = cEmpresa
               AND num_credito = cNumCredito;
        ELSE -- SI NO SE BUSCA EN LA MOVDIACRD

            -- Se calcula el importe del último pago realizado en base al día en que se realizó
            IF dtFechaUltPago = dtFechaHoy THEN
                SELECT NVL(SUM(monto),0)
                    INTO dImpUltPago
                    FROM bdicred:sd_movdiacrd
                    WHERE empresa     = cEmpresa
                    AND fecha_mov   = dtFechaUltPago
                    AND num_credito = cNumCredito
                    AND codigo_fun IN (select cod_fun from bdicred:sd_conceptospagomanualcrd)
                    AND codigo_ref =1
                    AND reversado = "N";
            ELSE
                SELECT NVL(SUM(monto),0)
                    INTO dImpUltPago
                    FROM bdicred:sd_movhiscrd
                    WHERE empresa     = cEmpresa
                    AND fecha_mov   = dtFechaUltPago
                    AND num_credito = cNumCredito
                    AND codigo_fun IN (select cod_fun from bdicred:sd_conceptospagomanualcrd)
                    AND codigo_ref =1
                    AND reversado = "N";
            END IF;

            -- Se obtiene la fecha del último cargo realizado
            SELECT MAX(fecha_mov)
                INTO dtUltFechaCargo
                FROM bdicred:sd_movdiacrd
                WHERE empresa = cEmpresa
                AND num_credito = cNumCredito
                AND codigo_fun ='002'
                AND codigo_ref = 37
                AND reversado = 'N';

            -- Obtener ultima fecha de disposiciones
            IF NVL(dtUltFechaCargo,DATE(1)) = DATE(1) THEN
                SELECT MAX(fecha_mov)
                INTO dtUltFechaCargo
                FROM bdicred:sd_movdiacrd
                WHERE empresa = cEmpresa
                AND num_credito = cNumCredito
                AND codigo_fun = '002'
                AND codigo_ref IN (50,30,40,41,42)
                AND reversado='N';
            END IF;

            IF NVL(dtUltFechaCargo,DATE(1)) = DATE(1) THEN
                SELECT MAX(fecha_mov)
                    INTO dtUltFechaCargo
                    FROM bdicred:sd_movhiscrd
                    WHERE empresa = cEmpresa
                    AND num_credito = cNumCredito
                    AND codigo_fun ='002'
                    AND codigo_ref = 37
                    AND reversado = 'N';

                IF NVL(dtUltFechaCargo,DATE(1)) = DATE(1) THEN
                    SELECT MAX(fecha_mov)
                        INTO dtUltFechaCargo
                        FROM bdicred:sd_movhiscrd
                        WHERE empresa = cEmpresa
                        AND num_credito = cNumCredito
                        AND codigo_fun = '002'
                        AND codigo_ref IN (50,30,40,41,42)
                        AND reversado='N';
                END IF;
            END IF;
             select prox_fecha_pago into dtFechaProxPago
              from bdicred:sd_maecredanexocrd
             where empresa = cEmpresa
               AND num_credito = cNumCredito;
        END IF;

        IF sNumPagosVdos <= 2 THEN
            LET sTpoConvenio = 1; -- Compromiso
        ELSE
            LET sTpoConvenio = 2; -- Acuerdo
        END IF;

        LET iContador = iContador + 1 ;

    END FOREACH;

    -- Elimina marca en el registro que se esta actualizando.
    UPDATE bdicobranza:"informix". cb_cat_directorio_cte
        SET cobranza_aux_direct = ''
        WHERE empresa       = pempresa
        AND numcte          = pCliente
        AND fecha_insert    = dfecha_insert
        AND tipo_cobranza   = tipo;


    RETURN cCodRet, NVL(cTipCred,""), NVL(cNomProducto,""), NVL(cNumCredito,""), NVL(cNumTarjeta,""), NVL(dtUltFechaCargo,DATE(1)),
             NVL(dImpSdoTotal,0), NVL(dImpIntMora,0), NVL(dSdoVdoIntMora,0), NVL(dImpSigPagoMin,0), NVL(dImpMensual,0),
             NVL(dImpVdoT,0), NVL(sNumPagosVdos,0), NVL(dtFechaUltPago,DATE(1)), NVL(dImpUltPago,0), NVL(sTpoConvenio,0),NVL(dImporte,0), nvl(dtFechaProxPago, date(1));

END
END PROCEDURE
DOCUMENT
'Función para consultar saldos en línea',
'AUTOR : Paul Ivan Quintero Varela',
'FECHA : 29/SEPT/2010',
'BD    : BDICOBRANZA';

CREATE PROCEDURE "informix".sp_migra_evaluacion_objetiva(pFecha date)
       RETURNING char(6), char(80);
 
DEFINE	sql_err			INTEGER;
DEFINE	isam_err		INTEGER;
DEFINE	error_info	CHAR(150);
DEFINE	cMensaje		CHAR(80);
DEFINE	cCod_ret		CHAR(6);
DEFINE  vvcCod_ret  CHAR(6);

DEFINE vcantReg		  SMALLINT;
DEFINE pEmpresa     CHAR(3);
DEFINE vtoday       date; 
DEFINE cProceso     CHAR(4); 

DEFINE c_sucursal       CHAR(4);
DEFINE d_fecha_insert  	DATE;
DEFINE c_usuario       	CHAR(8);
DEFINE c_num_credito   	CHAR(20);
DEFINE d_pago_min      	DECIMAL(14,2);
DEFINE d_saldo_vencido 	DECIMAL(14,2);
DEFINE d_pago_realizado	DECIMAL(14,2);
DEFINE d_pct_cump_pm   	DECIMAL(5,2);
DEFINE d_pct_cump_sv   	DECIMAL(5,2);
DEFINE c_folio_suc     	CHAR(16);
DEFINE c_reversado     	CHAR(1);
DEFINE c_folio_suc_2    CHAR(16);
 
DEFINE c_transacc_suc  	CHAR(4);
DEFINE c_codigo_fun     CHAR(3);
DEFINE dt_hora_mov    	DATETIME HOUR to FRACTION(3);  
DEFINE b_migrac_ok      CHAR(1); 
DEFINE i_result         INTEGER;
 
LET cCod_ret      = '000000';
LET sql_err       = 0;
LET isam_err      = 0;
LET error_info    = '';
LET cMensaje      = 'PROCESO EXITOSO';	
LET pEmpresa      = '001';
LET vtoday        = date(1);
LET vvcCod_ret    = '';
LET cProceso      = '0672'; 
LET c_sucursal       ='';
LET d_fecha_insert   = date(1);
LET c_usuario        = '';
LET c_num_credito    = '';
LET d_pago_min       = 0;
LET d_saldo_vencido  = 0;
LET d_pago_realizado = 0;
LET d_pct_cump_pm    = 0;
LET d_pct_cump_sv    = 0;
LET c_folio_suc      = '';
LET c_reversado      = '';
LET c_folio_suc_2    = '';
LET c_transacc_suc   = '';
LET c_codigo_fun     = '';
LET b_migrac_ok      = 'N';  
LET i_result         = 0;
  --SET DEBUG FILE TO '/informix/macf/sp_graba_indicador.trc';
  --TRACE ON;

	
BEGIN
        ON EXCEPTION SET sql_err, isam_err, error_info
            LET cCod_ret = sql_err;
            LET cMensaje = error_info;
			      --insert into bdicobranza:cb_bitacora (mensaje) values  (error_info);
            CALL "informix".sp_inserta_bitacora_cob(pEmpresa, cProceso, cCod_ret, cMensaje, '02') returning vvcCod_ret;
            		
            RETURN cCod_ret, cMensaje;
        END EXCEPTION;		
        
		SET LOCK MODE TO WAIT 3;		
    --select fecha_hoy into vtoday from bdicred:sd_fechas where empresa = '001';
    LET vtoday = pFecha;
  CALL "informix".sp_inserta_bitacora_cob(pEmpresa, cProceso, cCod_ret, cMensaje, '01')
            RETURNING vvcCod_ret;  


   FOREACH WITH HOLD
      select empresa, sucursal, fecha_insert, usuario, num_credito, pago_min, saldo_vencido, pago_realizado, pct_cump_pm, pct_cump_sv,
             folio_suc, reversado, hora_mov, transacc_suc, codigo_fun 
        into pEmpresa, c_sucursal, d_fecha_insert, c_usuario, c_num_credito, d_pago_min, d_saldo_vencido, d_pago_realizado, d_pct_cump_pm, d_pct_cump_sv,   
             c_folio_suc, c_reversado, dt_hora_mov, c_transacc_suc, c_codigo_fun    
        from bdicobranza:cb_evaluacion_objetiva
        where fecha_insert = vtoday
          AND folio_suc not in( select folio_suc 
                                  from bdicobranza:cb_evaluacion_objetiva_his 
                                 where fecha_insert = vtoday)
        
        begin;
            INSERT INTO bdicobranza:cb_evaluacion_objetiva_his(empresa, sucursal, fecha_insert, usuario, num_credito, pago_min, saldo_vencido, pago_realizado, 
                                                           pct_cump_pm, pct_cump_sv, folio_suc, reversado, hora_mov, transacc_suc, codigo_fun) 
            VALUES(pEmpresa, c_sucursal, d_fecha_insert, c_usuario, c_num_credito, d_pago_min, d_saldo_vencido, d_pago_realizado, 
                  d_pct_cump_pm, d_pct_cump_sv, c_folio_suc, c_reversado, dt_hora_mov, c_transacc_suc, c_codigo_fun);
        commit;   
        
        LET i_result = i_result + 1; 
        
        --LET b_migrac_ok = 'S';
  END FOREACH;

  LET cMensaje = trim(cMensaje) || '...Número de registros migrados: [ ' || i_result || ' ]';
  
  --CALL "informix".sp_inserta_bitacora_cob(pEmpresa, cProceso, cCod_ret, cMensaje, '03')
  --          RETURNING vvcCod_ret;
  
  IF i_result > 0 THEN
    BEGIN;  TRUNCATE bdicobranza:cb_evaluacion_objetiva; COMMIT;
  END IF;
  
  begin;
    INSERT INTO bdicobranza:cb_bitacora(empresa, num_proceso, fecha_ejecucion, cod_ret, mensaje, user_insert, fecha_insert, hora_insert)
            VALUES(pEmpresa, cProceso, vtoday, cCod_ret, cMensaje, user, today,  current);
  commit;
  
  RETURN cCod_ret, cMensaje;
  
  
 END
END PROCEDURE
DOCUMENT
'DESCRIPCION: Migra la tabla de evaluación objetiva (datos de pago mínimo, saldo vencido y pago realizado para los creds prod. 6001) a histórica de manera diaria.',
'AUTOR : Marco A. Campos. 20140918',
'BD: bdicobranza';

CREATE PROCEDURE "informix".sp_ctbcpl_gen_arctelefonos(pEmpresa         CHAR(3),
                                                       pTipoCobranza    CHAR(1),
                                                       pFechaGenCartera DATE,
                                                       pStatusTel       CHAR(2))
RETURNING CHAR(6) AS COD_RET;
-----------------------------------------------------------------------------------------------------------------------------------------------------
-- Modificado por: Martha A Hernandez
-- Fecha: Noviembre 2011
-- Modificacion: Se modifica proceso para que tome en cuenta tambien el tipo de cobranza R
-----------------------------------------------------------------------------------------------------------------------------------------------------
-- Modificado por: Elizabeth Anzures
-- Fecha: Marzo 2012
-- Modificacion: Se modifica proceso para que no tome clientes con estatus en AT
-----------------------------------------------------------------------------------------------------------------------------------------------------
-- Modificado por: Abrham Lopez L.
-- Fecha: 10 Diciembre 2012
-- Modificacion: Se modifica consulta principal para que a los tipotelefono = 2 les ponga el tipored = 'M'
-- execute procedure sp_ctbcpl_gen_arctelefonos ('001','A','01-20-2015','01');
-----------------------------------------------------------------------------------------------------------------------------------------------------

-- DECLARACIONES
DEFINE iSqlErr              INTEGER;
DEFINE iIsamErr             INTEGER;
DEFINE error_info		    CHAR(80);
DEFINE cCodRet              CHAR(6);
DEFINE cMensaje 		    CHAR(80);
DEFINE cRuta                CHAR(100);
DEFINE cNomArchivo          CHAR(100);
DEFINE cNomArchivoAux       CHAR(100);
DEFINE cNomArchivoEjecSql   CHAR(100);
DEFINE cSQL                 CHAR(2204);
DEFINE cSQL1                CHAR(100);
DEFINE cSQL2                CHAR(2004);
DEFINE cSQL3                CHAR(100);
DEFINE cFechaGenArchivo     CHAR(8);
DEFINE cEmpresa             CHAR(3);
DEFINE cDelimitador         CHAR(1);
DEFINE cTipoCampania        CHAR(1);
DEFINE cCodRetIB            CHAR(6);
DEFINE vnumparametro        SMALLINT;

-- INICIALIZACIONES
LET iSqlErr                 = 0;
LET iIsamErr                = 0;
LET cCodRet                 = "000000";
LET cMensaje                = 'PROCESO EXITOSO';
LET cRuta                   = "";
LET cNomArchivo             = "";
LET cNomArchivoAux          = "";
LET cNomArchivoEjecSql      = "";
LET cSQL                    = "";
LET cSQL1                   = "";
LET cSQL2                   = "";
LET cSQL3                   = "";
LET cEmpresa                = "000";
LET cDelimitador            = "";
LET cTipoCampania           = "";
LET cCodRetIB               = "000000";


BEGIN
    
    ON EXCEPTION SET iSqlErr, iIsamErr, error_info
        IF iSqlErr != 0 THEN
            LET cCodRet = iSqlErr;
            LET cMensaje = error_info;
           -- EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,"0028",cCodRet,cMensaje,"02")  INTO cCodRetIB;
            RETURN cCodRet;
        END IF;
    END EXCEPTION;

    -- DIRECTIVA PARA TENER LECTURA LECTURA DE TABLAS AUNQUE ESTEN BLOQUEADAS
    SET ISOLATION TO DIRTY READ;
    -- DIRECTIVA PARA QUE EXISTA UNA ESPERA DE TRES SEGUNDOS AL ACCESO 
    SET LOCK MODE TO WAIT 3;

-- SET DEBUG FILE TO "/tmp/sp_ctbcpl_gen_arctelefonos.out";
-- TRACE ON;

    --EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,"0028","","","01")INTO cCodRetIB;
    
    -- VALIDA LOS PARAMETROS DE ENTRADA   
    IF NVL(pEmpresa,"") = "" OR NVL(pTipoCobranza,"") = "" OR NVL(pFechaGenCartera,"")= "" OR NVL(pStatusTel,"") = "" THEN
        LET cCodRet = "104001";
        SELECT descripcion INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
            AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        --EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,"0028",cCodRet,cMensaje,"02")INTO cCodRetIB;
        RETURN cCodRet;
    END IF
    
    LET vnumparametro  =14; 
    IF (pTipoCobranza='A' OR pTipoCobranza='P'  ) THEN  LET vnumparametro  =14; END IF;
    IF (pTipoCobranza='E' OR pTipoCobranza='R'  ) THEN  LET vnumparametro  =16; END IF;

    SELECT empresa INTO cEmpresa
        FROM bdinteg: si_empresas
        WHERE empresa= pEmpresa;

    IF NVL(cEmpresa,'') = '' THEN
        LET cCodRet = "104002";
        SELECT descripcion INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
            AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

       -- EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,"0028",cCodRet,cMensaje,"02")INTO cCodRetIB;
        RETURN cCodRet;
    END IF;

    SELECT tipo_cobranza INTO cTipoCampania
        FROM bdicobranza:cb_cat_campania
        WHERE empresa         = pEmpresa
            AND tipo_cobranza = pTipoCobranza
            AND modulo_cob    = 3;

    IF NVL(cTipoCampania,'') = '' THEN
        LET cCodRet = "104003";
        SELECT descripcion INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
                AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        --EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,"0028",cCodRet,cMensaje,"02")INTO cCodRetIB;
        RETURN cCodRet;
    END IF;
   
    -- OBTIENE EL CARACTER SEPARADOR
    SELECT TRIM(valor_alfabetico) INTO cDelimitador
        FROM bdicobranza:cb_param_campania 
        WHERE empresa       = pEmpresa 
        AND tipo_campania   = 1 
        AND grupo_parametro = "ARCHIVOS" 
        AND num_parametro   = 2;
    
    -- VALIDA QUE EXISTA EL CARACTER
    IF NVL(cDelimitador,"") = "" THEN
        LET cCodRet = "104004";
        SELECT descripcion INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
              AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        --EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,"0028",cCodRet,cMensaje,"02") INTO cCodRetIB;
        RETURN cCodRet;
    END IF;

    -- OBTIENE LA RUTA DESTINO DEL ARCHIVO
    SELECT TRIM(valor_alfabetico) INTO cRuta
        FROM bdicobranza:cb_param_campania 
        WHERE empresa = pEmpresa
            AND tipo_campania   = 1 
            AND grupo_parametro = "ARCHIVOS" 
            AND num_parametro   = 3;
    
    -- VALIDA QUE EXISTA LA CARPETA
    IF NVL(cRuta,"") = "" THEN
        LET cCodRet = "104005";
        SELECT descripcion INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
            AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

        --EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,"0028",cCodRet,cMensaje,"02")INTO cCodRetIB;
        RETURN cCodRet;
    END IF

    -- OBTIENE EL NOMBRE DEL ARCHIVO
    SELECT TRIM(valor_alfabetico) INTO cNomArchivo
        FROM bdicobranza:cb_param_campania 
        WHERE empresa         = pEmpresa 
            AND tipo_campania   = 1
            AND grupo_parametro = "ARCHIVOS" 
            AND num_parametro   = vnumparametro;
    
    -- VALIDA QUE EXISTA EL NOMBRE DEL ARCHIVO
    IF NVL(cNomArchivo,"") = "" THEN
        LET cCodRet = "104006";
        SELECT descripcion INTO cMensaje
            FROM bdicobranza:"informix".cb_errores
            WHERE origen       = 3
            AND codigo_error = cCodRet; 

        IF cMensaje IS NULL THEN LET cMensaje = ""; END IF;

       -- EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,"0028",cCodRet,cMensaje,"02") INTO cCodRetIB;
        RETURN cCodRet;
    END IF
	
	let pFechaGenCartera = date(1);		
	SELECT MAX(fecha_insert) INTO pFechaGenCartera
	FROM bdicobranza:cb_cat_directorio_cte
	WHERE empresa = pempresa
	AND tipo_cobranza = ptipocobranza;

	LET cFechaGenArchivo = TRIM(LPAD(DAY(pFechaGenCartera),2,'0') || LPAD(MONTH(pFechaGenCartera),2,'0') || YEAR(pFechaGenCartera));

    LET cNomArchivoAux = TRIM(cNomArchivo) || cFechaGenArchivo || '_aux_' || pTipoCobranza ||'.txt';
    LET cNomArchivo = TRIM(cNomArchivo) || cFechaGenArchivo || '.txt';
    LET cNomArchivoEjecSql = 'Ejecuta_GenArchivoTelefonos_'|| pTipoCobranza || '.sql';
--LET cRuta = '/informix/Elizabeth/';---PRUEBAAAAAA
    LET cSQL1 = 'echo "UNLOAD TO ' || TRIM(cRuta) || TRIM(cNomArchivoAux) || " DELIMITER '" || cDelimitador || "' ";

    LET cSQL2 = " SELECT tel.numcte, tel.tipo_tel, 0, substr(tel.telefono,length(tel.telefono)-9,10),  "
                || " tel.extension, decode(tel.tipo_tel,1,'F',2,'M','M'), date(1) fultimocontacto,"  -- A.L.L. Se modifica en los 2 de 'F' a 'M'
                || " '' quiencontestouc, tel.fecha_hora,tel.carrier , tel.secuencia, decode(tel.status_tel,'A',0,1) "
                || " FROM bdicobranza:cb_cat_directorio_cte dir ,bdinteg:si_telefonos_actual tel "
                || " WHERE dir.tipo_cobranza = '" || pTipoCobranza || "' " 
                || " AND dir.fecha_insert = '" || pFechaGenCartera || "' "
                || " AND dir.tipo_logica > 0 "                
                || " AND dir.status_cliente NOT IN ('NT', 'EX') "        		
                || " AND tel.numcte  = dir.numcte "
				|| " AND tel.tipo_tel in (1,2,3) "
                || " AND tel.cofetel= 'V' ";

    LET cSQL3 = ' " > '|| TRIM(cRuta) || cNomArchivoEjecSql;
    
    LET cSQL1 = TRIM(cSQL1);
    LET cSQL3 = TRIM(cSQL3);

    LET cSQL = cSQL1 || cSQL2 || cSQL3;

    -- Verifica que no este vacia la consulta.
    IF ( cSQL <> '' ) THEN 
        SYSTEM cSQL;
        -- Permiso para la creacion de archivo.
        LET cSQL = '' ;
        LET cSQL = 'chmod 666 ' || TRIM(cRuta) || cNomArchivoEjecSql ;
        LET cSQL = '' ;
        LET cSQL = 'dbaccess bdicobranza ' || TRIM(cRuta) || cNomArchivoEjecSql ;
        SYSTEM cSQL;
		
		--A.L.L Se le dan permisos al archivo que se genera con el .sql con chmod 777
		LET cSQL = '';
		LET cSQL = 'chmod 666 '|| TRIM(cRuta) || TRIM(cNomArchivoAux);
		SYSTEM cSQL;

        LET cSql = cSql;
        LET cSql = "sed 's/"||cDelimitador||"$//g' "|| TRIM(cRuta) || TRIM(cNomArchivoAux) || " >> " || TRIM(cRuta) || TRIM(cNomArchivo);
        SYSTEM cSql;
		
		--A.L.L Se le dan permisos al archivo final con el chmod 777
		LET cSQL = '';
		LET cSQL = 'chmod 666 '|| TRIM(cRuta) || TRIM(cNomArchivo);
		SYSTEM cSQL;
 
        -- Borra el archivo de control.
        LET cSQL = '' ;
        LET cSQL = 'rm ' || TRIM(cRuta) || cNomArchivoEjecSql || '  ' || TRIM(cRuta) || TRIM(cNomArchivoAux);
        SYSTEM cSQL;

        -- Operacion exitosa "Archivo Generado".
        --EXECUTE PROCEDURE bdicobranza:"informix".sp_inserta_bitacora_cob(pEmpresa,"0028","","","03") INTO cCodRetIB;
        RETURN cCodRet;
    END IF;

END;

END PROCEDURE
DOCUMENT
'DESCRIPCION: Procedimiento para generar el archivo de Teléfonos del cliente', 
'AUTOR: Mohamed Carreón ',
'VERSION: 20101109.1545';

CREATE PROCEDURE "informix".sp_migra_tablas_smsmail()
       RETURNING CHAR(6), CHAR(80);

--DEClaracion de variables
-- execute procedure "informix".sp_migra_reporte_smsmail();
------------------------------------------------------------
DEFINE sql_err 			    INTEGER;
DEFINE isam_err 		    INTEGER;
DEFINE error_info		    CHAR(80);
DEFINE cMensaje 		    CHAR(100);
define P_MENSAJE			CHAR(80);
DEFINE cCod_ret             CHAR(6);
define v_fecha_hoy			DATE;

----------------------------------------------------------------------
DEFINE vproceso				CHAR(4);
DEFINE Vempresa				CHAR(3);
DEFINE Vnum_campana			SMALLINT;
DEFINE vcliente             CHAR(20);
DEFINE vcredito             CHAR(20);
DEFINE Vproducto			CHAR(4);
DEFINE VfechaEnvio			DATE;
DEFINE vciudad              CHAR(10);
DEFINE vestado              CHAR(10);
DEFINE vt_celular           CHAR(13);
DEFINE cNombre1				CHAR(26);
DEFINE cNombre2				CHAR(26);
DEFINE cApellPat			CHAR(26);
DEFINE cApellMat			CHAR(26);
DEFINE vMora				SMALLINT;
DEFINE vsdo_venc_int_mora   DEC(18,2);
DEFINE vpago_min            DEC(18,2);
DEFINE vpago_min_sin_vdo    DEC(18,2); 
DEFINE vpago_venc           DEC(18,2); 
DEFINE vpago_req_sms		DEC(18,2);
DEFINE vCosto				DEC(18,2);
DEFINE vResultadoEntrega	CHAR(15);
DEFINE vPagoDia1			DEC(18,2);
DEFINE vPagoDia2			DEC(18,2);
DEFINE vPagoDia3			DEC(18,2);
DEFINE vPagoDia4			DEC(18,2);
DEFINE vPagoDia5			DEC(18,2);
DEFINE vPagoNdias			DEC(18,2);
DEFINE vEstatusResultado	CHAR(02);
DEFINE vFechaCambioEstatus  DATE;
DEFINE vResultadoMora		SMALLINT;
DEFINE vFechaApertura		DATE;
DEFINE vFechaPrimerConsumo  DATE;
DEFINE vLineaCredito		DEC(18,2);
DEFINE vTipoTransaccion		CHAR(30);
DEFINE vMontoTransaccion	DEC(18,2);
DEFINE vPorcentaje_uso      DEC(18,2);
DEFINE vCorreoElec			CHAR(100);
DEFINE vPagoReqEmail		DEC(18,2);
DEFINE vCount				INTEGER;
DEFINE vCount1				INTEGER;
DEFINE iCuentasProcesadas     integer; 
DEFINE iCuentasInsertadas     integer; 
DEFINE iCuentasEliminadas     integer; 
DEFINE iCuentasExcluidasXMail integer;
DEFINE iOtrasExclusiones 	  integer;
DEFINE iCuentasExcluidasXCel  INTEGER;
  

--------------------------------------------
LET Vempresa 			= '';
LET Vnum_campana 		= 0;
LET vcliente         	= '';
LET vcredito        	= '';
LET Vproducto 			= '';
LET VfechaEnvio 		= '';
LET vciudad          = '';
LET vestado          = '';
LET cNombre1			= '';
LET cNombre2			= '';
LET cApellPat			= '';
LET cApellMat			= '';
LET vMora				= 0;
LET vCosto				= 0;
LET vResultadoEntrega	= '';
LET vPagoDia1			= 0;
LET vPagoDia2			= 0;
LET vPagoDia3			= 0;
LET vPagoDia4			= 0;
LET vPagoDia5			= 0;
LET vPagoNdias			= 0;
LET vEstatusResultado	= '';
LET vFechaCambioEstatus = '';
LET vResultadoMora		= 0;
LET vFechaApertura		= '';
LET vFechaPrimerConsumo = '';
LET vLineaCredito		= 0;
LET vTipoTransaccion	= '';
LET vMontoTransaccion	= 0;
LET vPorcentaje_uso		= 0;
LET vCorreoElec			= '';
LET vPagoReqEmail		= 0;
LET vpago_req_sms		= 0;
let vCount1 			= 0;
let iCuentasProcesadas     = 0;
let iCuentasInsertadas     = 0;
let iCuentasEliminadas     = 0; 

let iCuentasExcluidasXMail  = 0;
let iCuentasExcluidasXCel = 0;
---------------------------------------

--SET DEBUG FILE TO 'sp_migra_reporte_smsmail.out';
--TRACE ON;

      LET cCod_ret      = '000000';
	  LET sql_err       = 0;
	  LET isam_err      = 0;
	  LET error_info    = '';
	  LET cMensaje      = 'PROCESO EXITOSO';
	  LET P_MENSAJE      = 'El proceso de MIGRACION DE TABLAS SMSs MAILs se realizó correctamente.';
	  LET vproceso		= '0119';
      --LET pUsuario      = user;
	  let v_fecha_hoy = DATE(1);
 

	BEGIN

        ON EXCEPTION SET sql_err, isam_err, error_info
	        LET cCod_ret = sql_err;
	        LET P_MENSAJE = error_info;
			CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, cCod_ret, P_MENSAJE, '02')RETURNING cCod_ret; 
	        LET cCod_ret = sql_err;
    		RETURN cCod_ret, P_MENSAJE;
		END EXCEPTION;
     
--------------------------------------------------------------------------
--    SELECT fecha_hoy INTO v_fecha_hoy FROM bdinteg:si_fechas;
--------------------------------------------------------------------------

	CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, cCod_ret, cMensaje, '01')RETURNING cCod_ret; 


        --se obtiene la informacion
		SET ISOLATION TO dirty READ;
        SET LOCK MODE TO WAIT 3;

----------------------------------- Se obtienen DATOS del CLIENTE y SALDOS--------------------------------------------
FOREACH with hold
            SELECT empresa,num_campana,num_credito,numcte,num_producto,fecha_envio,ciudad,estado,num_celular,
				nombre1,nombre2,apell_paterno,apell_materno,mora,sdo_venc_int_mora,pago_min,pago_min_sin_vdo, 
				pago_ven,pago_req_sms,costo,resultado_entrega,pago_dia1,pago_dia2,pago_dia3,pago_dia4,pago_dia5, 
				pago_ndias,estatus_resultado,fecha_cambio_estatus,resultado_mora, fecha_apertura, 
				fecha_primer_consumo,linea_credito,tipo_transaccion,monto_transaccion,porcentaje_uso 
			INTO Vempresa,Vnum_campana,vcredito,vcliente,Vproducto,VfechaEnvio,vciudad,vestado,vt_celular,
				cNombre1,cNombre2,cApellPat,cApellMat,vMora,vsdo_venc_int_mora,vpago_min,vpago_min_sin_vdo,
				vpago_venc,vpago_req_sms,vCosto,vResultadoEntrega,vPagoDia1,vPagoDia2,vPagoDia3,vPagoDia4,vPagoDia5,
				vPagoNdias,vEstatusResultado,vFechaCambioEstatus,vResultadoMora,vFechaApertura,
				vFechaPrimerConsumo,vLineaCredito,vTipoTransaccion,vMontoTransaccion,vPorcentaje_uso
            FROM bdicobranza:cb_rep_resultado_sms
			
			--A.L.L.	
			let iCuentasProcesadas = iCuentasProcesadas + 1;
			
---------------SE INCERTAN DATOS GENERADOS----------------------------------------------------------

             BEGIN WORK;
			 INSERT INTO cb_rep_resultado_sms_hist (
                empresa,num_campana,num_credito,numcte,num_producto,fecha_envio,ciudad,estado,num_celular,
				nombre1,nombre2,apell_paterno,apell_materno,mora,sdo_venc_int_mora,pago_min,pago_min_sin_vdo, 
				pago_ven,pago_req_sms,costo,resultado_entrega,pago_dia1,pago_dia2,pago_dia3,pago_dia4,pago_dia5, 
				pago_ndias,estatus_resultado,fecha_cambio_estatus,resultado_mora, fecha_apertura, 
				fecha_primer_consumo,linea_credito,tipo_transaccion,monto_transaccion,porcentaje_uso)
			  VALUES(Vempresa,Vnum_campana,vcredito,vcliente,Vproducto,VfechaEnvio,vciudad,vestado,vt_celular,
				cNombre1,cNombre2,cApellPat,cApellMat,vMora,vsdo_venc_int_mora,vpago_min,vpago_min_sin_vdo,
				vpago_venc,vpago_req_sms,vCosto,vResultadoEntrega,vPagoDia1,vPagoDia2,vPagoDia3,vPagoDia4,vPagoDia5,
				vPagoNdias,vEstatusResultado,vFechaCambioEstatus,vResultadoMora,vFechaApertura,
				vFechaPrimerConsumo,vLineaCredito,vTipoTransaccion,vMontoTransaccion,vPorcentaje_uso);

            let iCuentasInsertadas = iCuentasInsertadas + 1;

			--A.L.L. Borramos los clientes de la tabla cb_rep_resultado_sms 	
			delete bdicobranza:cb_rep_resultado_sms where empresa = Vempresa and num_campana = Vnum_campana and num_credito = vcredito and fecha_envio = VfechaEnvio;

			let iCuentasEliminadas = iCuentasEliminadas +1;
			
			COMMIT WORK;
END FOREACH;

--Genera cifras de control
	    if iCuentasProcesadas > 0 then
	       let cMensaje = 'TOTAL cuentas PROCESADAS SMSs : ' || iCuentasProcesadas;
	       let cMensaje = trim(cMensaje) ||'    TOTAL cuentas INSERTADAS SMSs a histórica : ' || iCuentasInsertadas;
	       CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, cCod_ret, trim(cMensaje), '02') RETURNING cCod_ret;
	       let cMensaje = 'TOTAL cuentas ELIMINADAS SMSs : ' || iCuentasEliminadas;
	       CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, cCod_ret, trim(cMensaje), '02') RETURNING cCod_ret;
	    end if;
--Genera cifras de control
		let iCuentasProcesadas = 0;
		let iCuentasInsertadas = 0;
		let iCuentasEliminadas = 0;
--begin work;
-----------------------------------------------INSERTAR----CB_MAIL_CLIENTE_HIS------------------------------------
	FOREACH with hold
	
		select  empresa,num_campana,num_credito,numcte,num_producto,fecha_envio,ciudad,estado,correo_elec,
				nombre1,nombre2,apell_paterno,apell_materno,mora,sdo_venc_int_mora,pago_min,pago_min_sin_vdo, 
				pago_ven,pago_req_email,costo,resultado_entrega,pago_dia1,pago_dia2,pago_dia3,pago_dia4,pago_dia5, 
				pago_ndias,estatus_resultado,fecha_cambio_estatus,resultado_mora, fecha_apertura, 
				fecha_primer_consumo,linea_credito,tipo_transaccion,monto_transaccion,porcentaje_uso
		into 	Vempresa,Vnum_campana,vcredito,vcliente,Vproducto,VfechaEnvio,vciudad,vestado,vCorreoElec,
				cNombre1,cNombre2,cApellPat,cApellMat,vMora,vsdo_venc_int_mora,vpago_min,vpago_min_sin_vdo,
				vpago_venc,vPagoReqEmail,vCosto,vResultadoEntrega,vPagoDia1,vPagoDia2,vPagoDia3,vPagoDia4,vPagoDia5,
				vPagoNdias,vEstatusResultado,vFechaCambioEstatus,vResultadoMora,vFechaApertura,
				vFechaPrimerConsumo,vLineaCredito,vTipoTransaccion,vMontoTransaccion,vPorcentaje_uso
		from bdicobranza:cb_rep_resultado_mail
		
		let vCount = vCount1 +1;
		--A.L.L.	
		let iCuentasProcesadas = iCuentasProcesadas + 1;
		
        BEGIN WORK;
		insert into bdicobranza:"informix".cb_rep_resultado_mail_hist(
	        empresa,num_campana,num_credito,numcte,num_producto,fecha_envio,ciudad,estado,correo_elec,
				nombre1,nombre2,apell_paterno,apell_materno,mora,sdo_venc_int_mora,pago_min,pago_min_sin_vdo, 
				pago_ven,pago_req_email,costo,resultado_entrega,pago_dia1,pago_dia2,pago_dia3,pago_dia4,pago_dia5, 
				pago_ndias,estatus_resultado,fecha_cambio_estatus,resultado_mora, fecha_apertura, 
				fecha_primer_consumo,linea_credito,tipo_transaccion,monto_transaccion,porcentaje_uso)
		values(Vempresa,Vnum_campana,vcredito,vcliente,Vproducto,VfechaEnvio,vciudad,vestado,vCorreoElec,
				cNombre1,cNombre2,cApellPat,cApellMat,vMora,vsdo_venc_int_mora,vpago_min,vpago_min_sin_vdo,
				vpago_venc,vPagoReqEmail,vCosto,vResultadoEntrega,vPagoDia1,vPagoDia2,vPagoDia3,vPagoDia4,vPagoDia5,
				vPagoNdias,vEstatusResultado,vFechaCambioEstatus,vResultadoMora,vFechaApertura,
				vFechaPrimerConsumo,vLineaCredito,vTipoTransaccion,vMontoTransaccion,vPorcentaje_uso);

		let iCuentasInsertadas = iCuentasInsertadas + 1;
				
		--A.L.L. Borramos los clientes de la tabla cb_mail_cliente 
		delete bdicobranza:cb_rep_resultado_mail where empresa = Vempresa and num_campana = Vnum_campana and num_credito = vcredito and fecha_envio = VfechaEnvio;

		let iCuentasEliminadas = iCuentasEliminadas + 1;

        COMMIT WORK;
	end FOREACH;

	--Genera cifras de control
	    if iCuentasProcesadas > 0 then
	       let cMensaje = 'TOTAL cuentas PROCESADAS MAILs : ' || iCuentasProcesadas;
	       let cMensaje = trim(cMensaje) ||'    TOTAL cuentas INSERTADAS MAILs a histórica : ' || iCuentasInsertadas;
	       CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, cCod_ret, trim(cMensaje), '02') RETURNING cCod_ret;
	       let cMensaje = 'TOTAL cuentas ELIMINADAS MAILs : ' || iCuentasEliminadas;
	       CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, cCod_ret, trim(cMensaje), '02') RETURNING cCod_ret;
	    end if;
--Genera cifras de control

    UPDATE STATISTICS MEDIUM FOR TABLE bdicobranza:cb_rep_resultado_sms;
    UPDATE STATISTICS MEDIUM FOR TABLE bdicobranza:cb_rep_resultado_sms_hist;
    UPDATE STATISTICS MEDIUM FOR TABLE bdicobranza:cb_rep_resultado_mail;
    UPDATE STATISTICS MEDIUM FOR TABLE bdicobranza:cb_rep_resultado_mail_hist;
	

	CALL bdicobranza:"informix".sp_inserta_bitacora_cob('001', vproceso, cCod_ret, cMensaje, '03')RETURNING cCod_ret; 
	RETURN cCod_ret, P_MENSAJE;

END;
END PROCEDURE;

create procedure "informix".sp_inserta_info_rep_envios(pEmpresa CHAR(3), pMensaje char(05), pCampana SMALLINT, pNumCredito CHAR(20), pNumCte CHAR(20), pNumProducto CHAR(04),
                                                        pFechaCampana DATE, pCelularMail CHAR(100), psituacion CHAR(01), pcausa SMALLINT, pPpagoReqSms DEC(18,2))
returning VARCHAR(06);
-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
 --execute procedure "informix".sp_inserta_info_rep_envios('001','SMS',14,'630026577647','021022027','6300',today,'5512460212','',0,300);
DEFINE pfechahoy          DATE;
DEFINE SQL_ERR            INTEGER;
DEFINE ISAM_ERR           INTEGER;
DEFINE ERROR_INFO         VARCHAR(80);
DEFINE P_COD_RET          VARCHAR(6);
DEFINE P_MENSAJE          VARCHAR(80);
DEFINE cCiudad            CHAR(10);
DEFINE cEstado            CHAR(08);
DEFINE cNombre1			  CHAR(26);
DEFINE cNombre2			  CHAR(26);
DEFINE cApellidoP		  CHAR(26);
DEFINE cApellidoM		  CHAR(26);
DEFINE vsaldo_total         DECIMAL(18,2);
DEFINE dPagoMinimoTotal   DECIMAL(18,2);
DEFINE dSdoVencIntMora  DECIMAL(18,2);
DEFINE dPagosVencidos      SMALLINT;
DEFINE	vMensualidad		DECIMAL(18,2);
DEFINE vpago_vencido		DECIMAL(18,2);
DEFINE dFechaCarLinea       DATE;
DEFINE dCosto               DEC(9,2);


BEGIN 
   ON EXCEPTION SET SQL_ERR, ISAM_ERR, ERROR_INFO
     LET P_COD_RET = SQL_ERR;
     LET P_MENSAJE = ERROR_INFO;
--     ROLLBACK WORK;
     RETURN P_COD_RET;
   END EXCEPTION;

--SET DEBUG FILE TO "/informix/ALL/sp_inserta_info_rep_envios.out";
--TRACE ON;

LET P_COD_RET = '000000';
LET cCiudad            = '';
LET cEstado            = '';
LET cNombre1		   = '';
LET cNombre2           = '';
LET cApellidoP         = '';
LET cApellidoM		   = '';
LET vsaldo_total        = 0;
LET dPagoMinimoTotal  = 0;
LET dSdoVencIntMora = 0;
LET dPagosVencidos     = 0;
LET vMensualidad		= 0;
LET vpago_vencido		= 0;
LET dFechaCarLinea      = DATE(01);
LET dCosto              = 0;

IF nvl(pEmpresa,'') = '' THEN
   LET P_COD_RET ="200000";
END IF
IF nvl(pMensaje,'') = '' THEN
   LET P_COD_RET ="200001";
END IF
IF nvl(pCampana,'') = '' THEN
   LET P_COD_RET ="200002";
END IF
IF nvl(pNumCredito,'') = '' THEN
   LET P_COD_RET ="200003";
END IF
IF nvl(pNumCte,'') = '' THEN
   LET P_COD_RET ="200004";
END IF
IF nvl(pnumproducto,'') = '' THEN
   LET P_COD_RET ="200005";
END IF
IF nvl(pFechaCampana,'') = '' THEN
   LET P_COD_RET ="200006";
END IF

SELECT  est.estado||'-'||est.siglas, cid.numerociudad||'-'||cid.inicialciudad
  INTO cCiudad, cEstado
  FROM bdinteg:si_direcciones_actual act  
 INNER JOIN bdinteg:si_estados est on est.estado = act.estado
 INNER JOIN bdinteg:si_catciudades cid on cid.numerociudad = act.numerociudad 
 WHERE act.numcte = pNumCte
   AND act.tipo_dir = 1;		

SELECT nombre1,nombre2, apell_paterno,apell_materno
INTO cNombre1,cNombre2,cApellidoP,cApellidoM
FROM bdinteg:"informix".si_cliente
WHERE numcte=pNumCte;

SELECT cl.fecha,cl.mto_fin_ven_trasp                                                         --- pagos vencidos
    ,(cl.sdo_capital +  cl.monto_vencido + cl.mto_venc_trasp + cl.cap_tras_no_venci + cl.moratorio + cl.interes_iva ) SdoTotal1
    ,(cl.monto_vencido + cl.mto_venc_trasp + cl.moratorio + cl.interes_iva) MtoVencido1,
    cl.mensualidad_actual,
    cl.monto_vencido + cl.mto_venc_trasp     	
 INTO dFechaCarLinea,dPagosVencidos, 
    vsaldo_total, 
    dSdoVencIntMora,
    vMensualidad,
    vpago_vencido  
 FROM bdicred:"informix".sd_sdos_cartera_linea cl
WHERE cl.num_credito = pNumCredito;

LET dPagoMinimoTotal = dSdoVencIntMora  +  vMensualidad;  --- Pago minimo  

/*SELECT costo
INTO dCosto
FROM informix.cb_cat_costo_envios_mensajes
WHERE empresa = pEmpresa
AND cod_envio = pMensaje
AND secuencia = (SELECT max(secuencia) FROM informix.cb_cat_costo_envios_mensajes WHERE empresa = pEmpresa AND cod_envio = pMensaje);*/

IF pMensaje = 'SMS' THEN
    INSERT INTO informix.cb_rep_resultado_sms(empresa, num_campana, num_credito, numcte, num_producto, fecha_envio, ciudad, estado, num_celular, nombre1, nombre2, apell_paterno, apell_materno, 
            mora, sdo_venc_int_mora, pago_min, pago_min_sin_vdo, pago_ven, pago_req_sms, costo) --, resultado_entrega, pago_dia1, pago_dia2, pago_dia3, pago_dia4, pago_dia5, pago_ndias, estatus_resultado, fecha_cambio_estatus, resultado_mora, fecha_apertura, fecha_primer_consumo, linea_credito, tipo_transaccion, monto_transaccion, porcentaje_uso) 
        VALUES('001', pCampana, pNumCredito, pNumCte, pNumProducto, pFechaCampana, cCiudad, cEstado, pCelularMail, cNombre1, cNombre2, cApellidoP, cApellidoM, 
            dPagosVencidos, dSdoVencIntMora, dPagoMinimoTotal, vMensualidad, dPagoMinimoTotal, pPpagoReqSms, dCosto);
ELSE
    INSERT INTO informix.cb_rep_resultado_mail(empresa, num_campana, num_credito, numcte, num_producto, fecha_envio, ciudad, estado, correo_elec, nombre1, nombre2, apell_paterno, apell_materno, 
            mora, sdo_venc_int_mora, pago_min, pago_min_sin_vdo, pago_ven, pago_req_email, costo) --, resultado_entrega, pago_dia1, pago_dia2, pago_dia3, pago_dia4, pago_dia5, pago_ndias, estatus_resultado, fecha_cambio_estatus, resultado_mora, fecha_apertura, fecha_primer_consumo, linea_credito, tipo_transaccion, monto_transaccion, porcentaje_uso) 
        VALUES('001', pCampana, pNumCredito, pNumCte, pNumProducto, pFechaCampana, cCiudad, cEstado, pCelularMail, cNombre1, cNombre2, cApellidoP, cApellidoM, 
            dPagosVencidos, dSdoVencIntMora, dPagoMinimoTotal, vMensualidad, dPagoMinimoTotal, pPpagoReqSms, dCosto);
END IF;

END
RETURN P_COD_RET;
END PROCEDURE;

create procedure "informix".sp_genera_inf_rep_recuperado_sms()
returning VARCHAR(06),
          VARCHAR(80);
------------------------------------------------------------------------------
-- execute procedure "informix".sp_genera_inf_rep_recuperado_sms();

DEFINE pfechahoy          DATE;
DEFINE SQL_ERR            INTEGER;
DEFINE ISAM_ERR           INTEGER;
DEFINE ERROR_INFO         VARCHAR(80);
DEFINE cProceso           CHAR(4);
DEFINE P_COD_RET          VARCHAR(6);
DEFINE P_MENSAJE          VARCHAR(80);
DEFINE cCiudad            CHAR(10);
DEFINE cEstado            CHAR(08);
DEFINE cNombre1			  CHAR(26);
DEFINE cNombre2			  CHAR(26);
DEFINE cApellidoP		  CHAR(26);
DEFINE cApellidoM		  CHAR(26);
DEFINE vsaldo_total         DECIMAL(18,2);
DEFINE dPagoMinimoTotal   DECIMAL(18,2);
DEFINE dSdoVencIntMora  DECIMAL(18,2);
DEFINE dPagosVencidos      SMALLINT;
DEFINE	vMensualidad		DECIMAL(18,2);
DEFINE vpago_vencido		DECIMAL(18,2);
DEFINE dFechaCarLinea       DATE;
DEFINE dCosto               DECIMAL(9,2);
DEFINE dFechaConsulta       DATE;
DEFINE dPago                DECIMAL(18,2);
DEFINE sPago                SMALLINT;
DEFINE sNumPago             SMALLINT;
DEFINE sNumCampana          SMALLINT;
DEFINE cNumCredito          CHAR(20);
DEFINE cNumcte              CHAR(20);
DEFINE cNumProducto         CHAR(04);
DEFINE dFechaEnvio          DATE;
DEFINE dPagoDia1            DECIMAL(18,2);
DEFINE dPagoDia2            DECIMAL(18,2);
DEFINE dPagoDia3            DECIMAL(18,2);
DEFINE dPagoDia4            DECIMAL(18,2);
DEFINE dPagoDia5            DECIMAL(18,2);
DEFINE dPagoDiaN           DECIMAL(18,2);
DEFINE cEstatusResultado    CHAR(02);
DEFINE dFechaCambioEstatus  DATE;
DEFINE sResultadoMora       SMALLINT;
DEFINE dFechaApertura       DATE;
DEFINE dFechaPrimerConsumo  DATE;
DEFINE dLineaCredito        DECIMAL(18,2);
DEFINE cTipoTransaccion     CHAR(30);
DEFINE dMontoTransaccion    DECIMAL(18,2);
DEFINE dPorcentajeUso       DECIMAL(18,2);
DEFINE dFechaInicio         DATE;
DEFINE dFechaFin            DATE;
DEFINE sFinMes              SMALLINT;
DEFINE cResultadoEntrega    CHAR(15);
DEFINE cIdMensaje           CHAR(10);
DEFINE sEnviado             SMALLINT;
DEFINE dFPprimerCompra      DATE; 
DEFINE dFPrimerDisp         DATE;
DEFINE dMontoPrimerCompra   DECIMAL(18,2);
DEFINE dMontoPrimerDisp     DECIMAL(18,2);
DEFINE cEmpresa             CHAR(03);
DEFINE cTipoCobranza        CHAR(01);

BEGIN 
   ON EXCEPTION SET SQL_ERR, ISAM_ERR, ERROR_INFO
     LET P_COD_RET = SQL_ERR;
     LET P_MENSAJE = ERROR_INFO;
     CALL bdicobranza:"informix".sp_inserta_bitacora_cob(cEmpresa, cProceso, P_COD_RET, P_MENSAJE, '02')
     RETURNING P_COD_RET;
     LET P_COD_RET = SQL_ERR;

     RETURN P_COD_RET,P_MENSAJE;
   END EXCEPTION;

--SET DEBUG FILE TO "sp_genera_inf_rep_recuperado_sms.out";
--TRACE ON;

LET cEmpresa            = '001';
LET cProceso            = '0117';
LET P_COD_RET           = '000000';
LET P_MENSAJE           = 'El proceso de REPORTE RECUPERADO CAMPAÑAS SMSs se realizó correctamente.';
LET cCiudad            = '';
LET cEstado            = '';
LET cNombre1		   = '';
LET cNombre2           = '';
LET cApellidoP         = '';
LET cApellidoM		   = '';
LET vsaldo_total       = 0;
LET dPagoMinimoTotal   = 0;
LET dSdoVencIntMora    = 0;
LET dPagosVencidos     = 0;
LET vMensualidad		= 0;
LET vpago_vencido		= 0;
LET dFechaCarLinea      = DATE(01);
LET dCosto              = 0;
LET dFechaConsulta      = DATE(1);
LET dPago               = 0;
LET sPago               = 0;
LET sNumPago            = 0;
LET sNumCampana         = 0;
LET cNumCredito         = '';
LET cNumcte             = '';
LET cNumProducto        = '';
LET dFechaEnvio          = DATE(1);
LET dPagoDia1            = 0;
LET dPagoDia2            = 0;
LET dPagoDia3            = 0;
LET dPagoDia4            = 0;
LET dPagoDia5            = 0;
LET dPagoDiaN           = 0;
LET cEstatusResultado    = '';
LET dFechaCambioEstatus  = DATE(1);
LET sResultadoMora       = 0;
LET dFechaApertura       = DATE(1);
LET dFechaPrimerConsumo  = DATE(1);
LET dLineaCredito        = 0;
LET cTipoTransaccion     = '';
LET dMontoTransaccion    = 0;
LET dPorcentajeUso       = 0;
LET dFechaInicio         = DATE(1);
LET dFechaFin            = DATE(1);
LET sFinMes              = 0;
LET cResultadoEntrega    = '';
LET cIdMensaje           = '';
LET sEnviado             = 0;
LET dFPprimerCompra      = DATE(1); 
LET dFPrimerDisp         = DATE(1);
LET dMontoPrimerCompra   = 0;
LET dMontoPrimerDisp     = 0;
LET cTipoCobranza        = '';

CALL bdicobranza:"informix".sp_inserta_bitacora_cob(cEmpresa, cProceso, P_COD_RET, P_MENSAJE, '01')
    RETURNING P_COD_RET;

IF P_COD_RET != '000000' THEN
   LET P_MENSAJE  = 'Error en el llamado al sp_inserta_bitacora_cob.';
   RETURN P_COD_RET,P_MENSAJE;
END IF;

--dFechaInicio  día 1 de cada mes
IF DAY(TODAY) = 1 THEN
    LET dFechaInicio = TODAY - 1;
    LET dFechaInicio = MDY(MONTH(dFechaInicio),1,YEAR(dFechaInicio)) - 1 UNITS DAY;
    LET dFechaFin    = TODAY - 1;
ELSE
    LET dFechaInicio = MDY(MONTH(TODAY),1,YEAR(TODAY));
    LET dFechaFin = TODAY - 1;
END IF;


--TEMPORAL solo para pruebas
--LET dFechaInicio = MDY(MONTH(mdy('04','01','2015')),1,YEAR(mdy('04','01','2015')));
--LET dFechaFin = mdy('04','01','2015') - 1;
/*
IF DAY(mdy('04','06','2015')) = 1 THEN
    LET dFechaInicio = mdy('04','06','2015') - 1 UNITS DAY;
    LET dFechaInicio = MDY(MONTH(dFechaInicio),1,YEAR(dFechaInicio));
    LET dFechaFin    = mdy('04','06','2015') - 1;
ELSE
    LET dFechaInicio = MDY(MONTH(mdy('04','06','2015')),1,YEAR(mdy('04','06','2015')));
    LET dFechaFin = mdy('04','06','2015') - 1;
END IF;
*/
--LET dFechaInicio = MDY(MONTH(mdy('04','01','2015')),1,YEAR(mdy('04','01','2015')));
--LET dFechaFin = mdy('04','01','2015') - 1;

--TEMPORAL solo para pruebas

--TEMPORAL solo para pruebas
--RETURN P_COD_RET,P_MENSAJE;
--TEMPORAL solo para pruebas

SET ISOLATION TO DIRTY READ;
SET LOCK MODE TO WAIT 3;

SELECT num_credito,fecha_mov,monto
  FROM bdicred:sd_movhis
 WHERE empresa= cEmpresa
   AND fecha_mov >= dFechaInicio
   AND fecha_mov <= dFechaFin
   AND codigo_fun in (select cod_fun from bdicred:sd_conceptospagomanual)	
   AND codigo_ref = 1 	
   AND reversado = 'N'
INTO TEMP movimientos WITH NO LOG;

CREATE INDEX inx_mov_tmp ON movimientos(fecha_mov,num_credito);
UPDATE STATISTICS HIGH FOR TABLE movimientos;

SELECT num_credito,fecha_mov,monto
  FROM bdicred:sd_movhiscrd
 WHERE empresa= cEmpresa
   AND fecha_mov >= dFechaInicio
   AND fecha_mov <= dFechaFin
   AND codigo_fun in (select cod_fun from bdicred:sd_conceptospagomanualcrd)	
   AND codigo_ref = 1 	
   AND reversado = 'N'
INTO TEMP movimientos_plazo WITH NO LOG;

CREATE INDEX inx_mov_pzotmp ON movimientos_plazo(fecha_mov,num_credito);
UPDATE STATISTICS HIGH FOR TABLE movimientos_plazo;

--Se obtienen los pagos de todos los días del mes
FOREACH WITH HOLD
    SELECT num_campana,num_credito,numcte,num_producto,fecha_envio,resultado_entrega,pago_dia1,pago_dia2,pago_dia3,pago_dia4,pago_dia5,pago_ndias,
           estatus_resultado,fecha_cambio_estatus,resultado_mora,fecha_apertura,fecha_primer_consumo,linea_credito,tipo_transaccion,monto_transaccion,porcentaje_uso
      INTO sNumCampana,cNumCredito,cNumcte,cNumProducto,dFechaEnvio,cResultadoEntrega,dPagoDia1,dPagoDia2,dPagoDia3,dPagoDia4,dPagoDia5,dPagoDiaN,
           cEstatusResultado,dFechaCambioEstatus,sResultadoMora,dFechaApertura,dFechaPrimerConsumo,dLineaCredito,cTipoTransaccion,dMontoTransaccion,dPorcentajeUso
      FROM bdicobranza:cb_rep_resultado_sms_hist
     WHERE fecha_envio >= dFechaInicio
       AND fecha_envio <= dFechaFin
--     WHERE fecha_envio >= mdy(month(today),1,year(today))
--and num_credito in ('600069252598','600072009639','600079911092')

     SELECT id_mensaje,tipo_cobranza INTO cIdMensaje,cTipoCobranza
       FROM bdicobranza:cb_cat_campania
      WHERE empresa=cEmpresa
        AND num_campania = sNumCampana;
--Envíos SMSs
--     IF sNumCampana IN (5,6,15,16,18) AND (cResultadoEntrega IS NULL OR cResultadoEntrega = '') THEN
     IF sNumCampana IN (5,6,15,16,18,11,14,19,20,21,22) THEN
        IF cResultadoEntrega IS NULL OR cResultadoEntrega = '' THEN LET cResultadoEntrega = ''; END IF;
        BEGIN WORK;
--        IF (cResultadoEntrega IS NULL OR cResultadoEntrega = '') THEN
        IF cResultadoEntrega = '' THEN
            SELECT SUM(estatus) INTO sEnviado 
            FROM bdimnsj:mnsjr_trx_batch
            WHERE cuenta = cNumCredito
            AND id_mensaje = cIdMensaje
            AND date(fecha_hora_registro) >= dFechaEnvio
            AND date(fecha_hora_registro) <= dFechaFin;

            IF sEnviado IS NULL OR sEnviado = '' THEN LET sEnviado = -1; END IF;

--            IF sEnviado IS NULL OR sEnviado = '' THEN
            IF sEnviado = -1 THEN
                SELECT SUM(estatus) INTO sEnviado 
                FROM bdimnsj:mnsjr_trx_batch_his
                WHERE cuenta = cNumCredito
                AND id_mensaje = cIdMensaje
                AND date(fecha_hora_registro) >= dFechaEnvio
                AND date(fecha_hora_registro) <= dFechaFin;

                IF sEnviado IS NULL OR sEnviado = '' THEN LET sEnviado = 0; END IF;
            END IF;

            IF sEnviado > 0 THEN
                UPDATE bdicobranza:cb_rep_resultado_sms_hist
                   SET resultado_entrega = 'COMPLETADO'
                 WHERE empresa = cEmpresa
                   AND num_campana = sNumCampana
                   AND num_credito = cNumCredito
                   AND fecha_envio = dFechaEnvio;
            ELSE
                UPDATE bdicobranza:cb_rep_resultado_sms_hist
                   SET resultado_entrega = 'NO COMPLETADO'
                 WHERE empresa = cEmpresa
                   AND num_campana = sNumCampana
                   AND num_credito = cNumCredito
                   AND fecha_envio = dFechaEnvio;
            END IF;
         END IF;
--Envíos SMSs Primer Consumo
         IF dFechaApertura IS NULL OR dFechaApertura = '' THEN LET dFechaApertura = DATE(1); END IF;
         IF dLineaCredito IS NULL OR dLineaCredito = '' THEN LET dLineaCredito = -1; END IF;

--         IF sNumCampana = 16 AND ((dFechaApertura IS NULL OR dFechaApertura = '') OR (dLineaCredito IS NULL OR dLineaCredito ='')) THEN
         IF sNumCampana = 16 AND (dFechaApertura = DATE(1) OR dLineaCredito = -1) THEN
            IF cTipoCobranza IN ('A','P') THEN
                SELECT mae.fecha_apertura, mas.monto_otorgado, ind.f_primer_compra, ind.f_primer_disp, ind.monto_primer_compra, ind.monto_primer_disp
                  INTO dFechaApertura   , dLineaCredito     , dFPprimerCompra, dFPrimerDisp, dMontoPrimerCompra, dMontoPrimerDisp
                  FROM bdicred:sd_maecred mae
                INNER JOIN bdicred:sd_maesdos mas ON mas.empresa = mae.empresa AND mas.num_credito = mae.num_credito
                INNER JOIN bdicred:sd_indicador_cred ind ON ind.empresa = mae.empresa AND ind.num_credito = mae.num_credito
                 WHERE mae.empresa = '001'
                   AND mae.num_credito = cNumCredito;
            ELSE
                SELECT mae.fecha_apertura, mas.monto_otorgado, ind.f_primer_compra, ind.f_primer_disp, ind.monto_primer_compra, ind.monto_primer_disp
                  INTO dFechaApertura   , dLineaCredito     , dFPprimerCompra, dFPrimerDisp, dMontoPrimerCompra, dMontoPrimerDisp
                  FROM bdicred:sd_maecredcrd mae
                INNER JOIN bdicred:sd_maesdoscrd mas ON mas.empresa = mae.empresa AND mas.num_credito = mae.num_credito
                INNER JOIN bdicred:sd_indicador_cred_crd ind ON ind.empresa = mae.empresa AND ind.num_credito = mae.num_credito
                 WHERE mae.empresa = '001'
                   AND mae.num_credito = cNumCredito;
            END IF;

            IF dFPprimerCompra IS NULL THEN LET dFPprimerCompra = DATE(1); END IF;
            IF dFPrimerDisp IS NULL THEN LET dFPrimerDisp = DATE(1); END IF;

            IF dFPprimerCompra != DATE(1) THEN
               LET dFPprimerCompra = dFPprimerCompra;
               LET dMontoPrimerCompra = dMontoPrimerCompra;
               LET cTipoTransaccion   = 'COMPRA';
            ELIF dFPrimerDisp != DATE(1) THEN
               LET dFPprimerCompra = dFPrimerDisp;
               LET dMontoPrimerCompra = dMontoPrimerDisp;
               LET cTipoTransaccion   = 'DISPOSICION';
            END IF;

            UPDATE bdicobranza:cb_rep_resultado_sms_hist
               SET fecha_apertura = dFechaApertura,
                   linea_credito = dLineaCredito,
                   fecha_primer_consumo = dFPprimerCompra,
                   monto_transaccion = dMontoPrimerCompra,
                   tipo_transaccion = cTipoTransaccion,
                   porcentaje_uso = (dMontoPrimerCompra / (CASE WHEN dLineaCredito = 0 THEN 0.01 ELSE dLineaCredito END)) * 100
             WHERE empresa = cEmpresa
               AND num_campana = sNumCampana
               AND num_credito = cNumCredito
               AND fecha_envio = dFechaEnvio;

               LET cTipoTransaccion     = '';
         END IF;
         COMMIT WORK;
     END IF;

     LET dFechaConsulta = dFechaEnvio;

     IF dPagoDia1 IS NULL OR dPagoDia1 = '' THEN
        LET dFechaConsulta = dFechaEnvio;
        LET sPago = 1;
     ELIF dPagoDia2 IS NULL OR dPagoDia2 = '' THEN
        LET dFechaConsulta = dFechaEnvio + 1 UNITS DAY;
        LET sPago = 2;
     ELIF dPagoDia3 IS NULL OR dPagoDia3 = '' THEN
        LET dFechaConsulta = dFechaEnvio + 2 UNITS DAY;
        LET sPago = 3;
     ELIF dPagoDia4 IS NULL OR dPagoDia4 = '' THEN
        LET dFechaConsulta = dFechaEnvio + 3 UNITS DAY;
        LET sPago = 4;
     ELIF dPagoDia5 IS NULL OR dPagoDia5 = '' THEN
        LET dFechaConsulta = dFechaEnvio + 4 UNITS DAY;
        LET sPago = 5;
/*     ELIF dPagoDiaN IS NULL THEN
        LET dFechaConsulta = dFechaEnvio + 5 UNITS DAY;
        LET sPago = 6;*/
     ELSE
        LET dFechaConsulta = DATE(1);
        CONTINUE FOREACH;
     END IF;

     LET sNumPago = (dFechaFin - dFechaEnvio) + 1;

     BEGIN WORK;
--     WHILE sNumPago < 6
     WHILE sPago <= sNumPago
        IF cTipoCobranza IN ('A','P') THEN
           SELECT SUM(monto) INTO dPago
             FROM movimientos
            WHERE fecha_mov   = dFechaConsulta
              AND num_credito = cNumCredito;
        ELSE
           SELECT SUM(monto) INTO dPago
             FROM movimientos_plazo
            WHERE fecha_mov   = dFechaConsulta
              AND num_credito = cNumCredito;
        END IF;

         IF dPago IS NULL OR dPago = '' THEN LET dPago = 0; END IF;

         IF sPago = 1 THEN
            UPDATE bdicobranza:cb_rep_resultado_sms_hist
               SET pago_dia1 = dPago
             WHERE empresa = cEmpresa
               AND num_campana = sNumCampana
               AND num_credito = cNumCredito
               AND fecha_envio = dFechaEnvio;
         ELIF sPago = 2 THEN
            UPDATE bdicobranza:cb_rep_resultado_sms_hist
               SET pago_dia2 = dPago
             WHERE empresa = cEmpresa
               AND num_campana = sNumCampana
               AND num_credito = cNumCredito
               AND fecha_envio = dFechaEnvio;
         ELIF sPago = 3 THEN
            UPDATE bdicobranza:cb_rep_resultado_sms_hist
               SET pago_dia3 = dPago
             WHERE empresa = cEmpresa
               AND num_campana = sNumCampana
               AND num_credito = cNumCredito
               AND fecha_envio = dFechaEnvio;
         ELIF sPago = 4 THEN
            UPDATE bdicobranza:cb_rep_resultado_sms_hist
               SET pago_dia4 = dPago
             WHERE empresa = cEmpresa
               AND num_campana = sNumCampana
               AND num_credito = cNumCredito
               AND fecha_envio = dFechaEnvio;
         ELIF sPago = 5 THEN
            UPDATE bdicobranza:cb_rep_resultado_sms_hist
               SET pago_dia5 = dPago
             WHERE empresa = cEmpresa
               AND num_campana = sNumCampana
               AND num_credito = cNumCredito
               AND fecha_envio = dFechaEnvio;
/*         ELIF sNumPago = 6 THEN
            UPDATE bdicobranza:cb_rep_resultado_sms_hist
               SET pago_dian = dPago
             WHERE empresa = cEmpresa
               AND num_campana = sNumCampana
               AND num_credito = cNumCredito
               AND fecha_envio = dFechaEnvio;*/
         END IF;
         LET sPago = sPago + 1;
         LET dFechaConsulta = dFechaConsulta + 1 UNITS DAY;
     END WHILE;
     LET sPago = 0;
     COMMIT WORK;
END FOREACH;

DROP TABLE movimientos;
DROP TABLE movimientos_plazo;

--SET DEBUG FILE TO "sp_genera_inf_rep_recuperado_sms.out";
--TRACE ON;

LET dFechaInicio = dFechaInicio;
LET dFechaFin = dFechaFin;

LET sPago = 0;

--Se obtienen los pagos de los últimos días del mes
IF DAY(dFechaFin) = 5 AND MONTH(dFechaFin) in (1,2,4,6,8,9,11) THEN
    LET dFechaInicio = dFechaInicio - 1 UNITS MONTH;
    LET dFechaInicio = MDY(MONTH(dFechaInicio),27,YEAR(dFechaInicio));
    LET sFinMes = 1;
ELIF DAY(dFechaFin) = 5 AND MONTH(dFechaFin) in (5,7,10,12) THEN
    LET dFechaInicio = dFechaInicio - 1 UNITS MONTH;
    LET dFechaInicio = MDY(MONTH(dFechaInicio),26,YEAR(dFechaInicio));
    LET sFinMes = 1;
--Se obtienen los pagos de los últimos días del mes de Febrero únicamente
ELIF DAY(dFechaFin) = 5 AND MONTH(dFechaFin) = 3 AND YEAR(dFechaFin) IN (2016,2020,2024,2028,2032) THEN
    LET dFechaInicio = dFechaInicio - 1 UNITS MONTH;
    LET dFechaInicio = MDY(MONTH(dFechaInicio),25,YEAR(dFechaInicio));
    LET sFinMes = 1;
ELIF DAY(dFechaFin) = 5 AND MONTH(dFechaFin) = 3 AND YEAR(dFechaFin) NOT IN (2016,2020,2024,2028,2032) THEN
    LET dFechaInicio = dFechaInicio - 1 UNITS MONTH;
    LET dFechaInicio = MDY(MONTH(dFechaInicio),24,YEAR(dFechaInicio));
    LET sFinMes = 1;
END IF;

LET dFechaFin = (MDY(MONTH(dFechaInicio),1,YEAR(dFechaInicio)) + 1 UNITS MONTH) - 1  UNITS DAY;

IF sFinMes = 1 THEN
    SELECT num_credito,fecha_mov,monto
      FROM bdicred:sd_movhis 
     WHERE empresa= cEmpresa
       AND fecha_mov >= MDY(MONTH(dFechaInicio),1,YEAR(dFechaInicio))
       AND fecha_mov <= today
       AND codigo_fun in (select cod_fun from bdicred:sd_conceptospagomanual)	
       AND codigo_ref = 1 	
       AND reversado = 'N'
    INTO TEMP movimientos_findemes WITH NO LOG;

    CREATE INDEX inx_mov_findemestmp ON movimientos_findemes(fecha_mov,num_credito);
    UPDATE STATISTICS HIGH FOR TABLE movimientos_findemes;

    SELECT num_credito,fecha_mov,monto
      FROM bdicred:sd_movhiscrd
     WHERE empresa= cEmpresa
       AND fecha_mov >= MDY(MONTH(dFechaInicio),1,YEAR(dFechaInicio))
       AND fecha_mov <= today
       AND codigo_fun in (select cod_fun from bdicred:sd_conceptospagomanualcrd)	
       AND codigo_ref = 1 	
       AND reversado = 'N'
    INTO TEMP movimientos_findemes_plazo WITH NO LOG;

    CREATE INDEX inx_mov_findemespzotmp ON movimientos_findemes_plazo(fecha_mov,num_credito);
    UPDATE STATISTICS HIGH FOR TABLE movimientos_findemes_plazo;

--Sumariza los pagos de los días N para las campañas generadas antes del 25 o 27 de cada mes
    FOREACH WITH HOLD
        SELECT num_campana,num_credito,fecha_envio,pago_ndias
          INTO sNumCampana,cNumCredito,dFechaEnvio,dPagoDiaN
          FROM bdicobranza:cb_rep_resultado_sms_hist
         WHERE fecha_envio >= MDY(MONTH(dFechaInicio),1,YEAR(dFechaInicio))
           AND fecha_envio <= dFechaInicio - 1 UNITS day

         SELECT id_mensaje,tipo_cobranza INTO cIdMensaje,cTipoCobranza
           FROM bdicobranza:cb_cat_campania
          WHERE empresa=cEmpresa
            AND num_campania = sNumCampana;

        IF cTipoCobranza IN ('A','P') THEN
            SELECT SUM(monto) INTO dPagoDiaN
              FROM movimientos_findemes
             WHERE fecha_mov  >= dFechaEnvio + 5 UNITS DAY
               AND fecha_mov  <= dFechaFin
               AND num_credito = cNumCredito;
        ELSE
            SELECT SUM(monto) INTO dPagoDiaN
              FROM movimientos_findemes_plazo
             WHERE fecha_mov  >= dFechaEnvio + 5 UNITS DAY
               AND fecha_mov  <= dFechaFin
               AND num_credito = cNumCredito;
        END IF;

        IF dPagoDiaN IS NULL OR dPagoDiaN = '' THEN LET dPagoDiaN = 0; END IF;

        BEGIN WORK;
        UPDATE bdicobranza:cb_rep_resultado_sms_hist
           SET pago_ndias = dPagoDiaN
         WHERE empresa    = cEmpresa
           AND num_campana = sNumCampana
           AND num_credito = cNumCredito
           AND fecha_envio = dFechaEnvio;
        COMMIT WORK;
    END FOREACH
--Registra los pagos de los días 25 o 27 de cada mes en adelante hasta 5 días después
    FOREACH WITH HOLD
        SELECT num_campana,num_credito,fecha_envio,pago_dia1,pago_dia2,pago_dia3,pago_dia4,pago_dia5,pago_ndias
          INTO sNumCampana,cNumCredito,dFechaEnvio,dPagoDia1,dPagoDia2,dPagoDia3,dPagoDia4,dPagoDia5,dPagoDiaN
          FROM bdicobranza:cb_rep_resultado_sms_hist
         WHERE fecha_envio >= dFechaInicio
           AND fecha_envio <= dFechaFin

         LET dFechaConsulta = dFechaEnvio;
         LET sNumPago = 5;

         IF dPagoDia1 IS NULL OR dPagoDia1 = '' THEN
            LET dFechaConsulta = dFechaEnvio;
            LET sPago = 1;
--            LET sNumPago = 4;
         ELIF dPagoDia2 IS NULL OR dPagoDia2 = '' THEN
            LET dFechaConsulta = dFechaEnvio + 1 UNITS DAY;
            LET sPago = 2;
--            LET sNumPago = 3;
         ELIF dPagoDia3 IS NULL OR dPagoDia3 = '' THEN
            LET dFechaConsulta = dFechaEnvio + 2 UNITS DAY;
            LET sPago = 3;
--            LET sNumPago = 2;
         ELIF dPagoDia4 IS NULL OR dPagoDia4 = '' THEN
            LET dFechaConsulta = dFechaEnvio + 3 UNITS DAY;
            LET sPago = 4;
--            LET sNumPago = 1;
         ELIF dPagoDia5 IS NULL OR dPagoDia5 = '' THEN
            LET dFechaConsulta = dFechaEnvio + 4 UNITS DAY;
            LET sPago = 5;
--            LET sNumPago = 0;
/*         ELIF dPagoDiaN IS NULL OR dPagoDiaN = '' THEN
            LET dFechaConsulta = dFechaEnvio + 5 UNITS DAY;
            LET sPago = 6;*/
         ELSE
            LET dFechaConsulta = DATE(1);
            CONTINUE FOREACH;
         END IF;

         SELECT id_mensaje,tipo_cobranza INTO cIdMensaje,cTipoCobranza
           FROM bdicobranza:cb_cat_campania
          WHERE empresa=cEmpresa
            AND num_campania = sNumCampana;

         BEGIN WORK;
--         WHILE sNumPago < 6
         WHILE sPago <= sNumPago
            IF cTipoCobranza IN ('A','P') THEN
                SELECT SUM(monto) INTO dPago
                  FROM movimientos_findemes
                 WHERE fecha_mov   = dFechaConsulta
                   AND num_credito = cNumCredito;
            ELSE
                SELECT SUM(monto) INTO dPago
                  FROM movimientos_findemes_plazo
                 WHERE fecha_mov   = dFechaConsulta
                   AND num_credito = cNumCredito;
            END IF;

             IF dPago IS NULL OR dPago = '' THEN LET dPago = 0; END IF;

             IF sPago = 1 THEN
                UPDATE bdicobranza:cb_rep_resultado_sms_hist
                   SET pago_dia1 = dPago
                 WHERE empresa = cEmpresa
                   AND num_campana = sNumCampana
                   AND num_credito = cNumCredito
                   AND fecha_envio = dFechaEnvio;
             ELIF sPago = 2 THEN
                UPDATE bdicobranza:cb_rep_resultado_sms_hist
                   SET pago_dia2 = dPago
                 WHERE empresa = cEmpresa
                   AND num_campana = sNumCampana
                   AND num_credito = cNumCredito
                   AND fecha_envio = dFechaEnvio;
             ELIF sPago = 3 THEN
                UPDATE bdicobranza:cb_rep_resultado_sms_hist
                   SET pago_dia3 = dPago
                 WHERE empresa = cEmpresa
                   AND num_campana = sNumCampana
                   AND num_credito = cNumCredito
                   AND fecha_envio = dFechaEnvio;
             ELIF sPago = 4 THEN
                UPDATE bdicobranza:cb_rep_resultado_sms_hist
                   SET pago_dia4 = dPago
                 WHERE empresa = cEmpresa
                   AND num_campana = sNumCampana
                   AND num_credito = cNumCredito
                   AND fecha_envio = dFechaEnvio;
             ELIF sPago = 5 THEN
                UPDATE bdicobranza:cb_rep_resultado_sms_hist
                   SET pago_dia5 = dPago
                 WHERE empresa = cEmpresa
                   AND num_campana = sNumCampana
                   AND num_credito = cNumCredito
                   AND fecha_envio = dFechaEnvio;
             END IF;
             LET sPago = sPago + 1;
             LET dFechaConsulta = dFechaConsulta + 1 UNITS DAY;
         END WHILE;

         IF sPago > 0 THEN
             UPDATE bdicobranza:cb_rep_resultado_sms_hist
               SET pago_ndias = 0
             WHERE empresa    = cEmpresa
               AND num_campana = sNumCampana
               AND num_credito = cNumCredito
               AND fecha_envio = dFechaEnvio;
         END IF;
         LET sPago = 0;
         COMMIT WORK;
    END FOREACH;
    DROP TABLE movimientos_findemes;
    DROP TABLE movimientos_findemes_plazo;
END IF;

/*
IF pMensaje = 'SMS' THEN
    INSERT INTO bdicobranza:cb_rep_resultado_sms_hist(empresa, num_campana, num_credito, numcte, num_producto, fecha_envio, ciudad, estado, num_celular, nombre1, nombre2, apell_paterno, apell_materno, 
            mora, sdo_venc_int_mora, pago_min, pago_min_sin_vdo, pago_ven, pago_req_sms, costo) --, resultado_entrega, pago_dia1, pago_dia2, pago_dia3, pago_dia4, pago_dia5, pago_ndias, estatus_resultado, fecha_cambio_estatus, resultado_mora, fecha_apertura, fecha_primer_consumo, linea_credito, tipo_transaccion, monto_transaccion, porcentaje_uso) 
        VALUES('001', pCampana, pNumCredito, pNumCte, pNumProducto, pFechaCampana, cCiudad, cEstado, pCelularMail, cNombre1, cNombre2, cApellidoP, cApellidoM, 
            dPagosVencidos, dSdoVencIntMora, dPagoMinimoTotal, vMensualidad, dPagoMinimoTotal, pPpagoReqSms, dCosto);
ELSE
    INSERT INTO bdicobranza:cb_rep_resultado_mail(empresa, num_campana, num_credito, numcte, num_producto, fecha_envio, ciudad, estado, correo_elec, nombre1, nombre2, apell_paterno, apell_materno, 
            mora, sdo_venc_int_mora, pago_min, pago_min_sin_vdo, pago_ven, pago_req_email, costo) --, resultado_entrega, pago_dia1, pago_dia2, pago_dia3, pago_dia4, pago_dia5, pago_ndias, estatus_resultado, fecha_cambio_estatus, resultado_mora, fecha_apertura, fecha_primer_consumo, linea_credito, tipo_transaccion, monto_transaccion, porcentaje_uso) 
        VALUES('001', pCampana, pNumCredito, pNumCte, pNumProducto, pFechaCampana, cCiudad, cEstado, pCelularMail, cNombre1, cNombre2, cApellidoP, cApellidoM, 
            dPagosVencidos, dSdoVencIntMora, dPagoMinimoTotal, vMensualidad, dPagoMinimoTotal, pPpagoReqSms, dCosto);
END IF;
*/

    CALL bdicobranza:"informix".sp_inserta_bitacora_cob(cEmpresa, cProceso, P_COD_RET, P_MENSAJE, '03')
    RETURNING P_COD_RET;

    IF P_COD_RET != '000000' THEN
       LET P_MENSAJE  = 'Error en el llamado al sp_inserta_bitacora_cob.';
       RETURN P_COD_RET,P_MENSAJE;
    END IF;

END
RETURN P_COD_RET,P_MENSAJE;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_grabacompromisosacuerdos(pEmpresa char(3), pSucursal char(4), pOrigen smallint,
pEmpleadoCaptura integer, pNumCliente char(20), pNumCuenta char(20),pPlazo char(2), pImporte integer, pTipo char(1),
pEmpleadoSup integer, pNombreSup char(40), pFechaCompac date)

RETURNING CHAR(6);


    DEFINE cVarDataErr      VARCHAR(64);
    DEFINE iSqlErr                INTEGER;
    DEFINE iSamErr             INTEGER;

    DEFINE vCodRet            CHAR(6);
    DEFINE vNumcliente     CHAR(20);
    DEFINE vNumCuenta    CHAR(20);
    DEFINE vActivo                CHAR(1);
    DEFINE vTipoCompac   CHAR(1);
    DEFINE dtefecha             DATE;
    DEFINE chrplazo	    	CHAR(2);
    DEFINE intactivo		  SMALLINT;
    DEFINE intdiasplazo	      SMALLINT;
    DEFINE intdiasfecha	      SMALLINT;    
    define v_codret char(5);
    DEFINE vFechaHoy          DATE;
    
    LET vFechaHoy = date(1);
BEGIN
    ON EXCEPTION
        SET iSqlErr, iSamErr, cVarDataErr
        IF iSqlErr <> 0 THEN
            LET vCodRet=iSqlErr;
            Rollback;
            RETURN vCodRet;
        END IF;
    END EXCEPTION;


    --SET DEBUG FILE TO "/tmp/grabacompromisosacuerdos.out";
    --TRACE ON;

    --INICIALIZACION DE VARIABLES--
    LET vCodRet        	     = "000";
    LET dtefecha       	      = '01-01-1900';
    LET chrplazo	      = '';
    LET intactivo	        = 0;
    LET intdiasplazo	   = 0;
    LET intdiasfecha	   = 0;
    LET v_codret = '000';

BEGIN WORK;

IF pEmpresa IS NOT NULL AND pSucursal IS NOT NULL AND pOrigen <> 0 AND pEmpleadoCaptura <> 0
    AND pNumCliente IS NOT NULL AND pNumCuenta IS NOT NULL AND pPlazo IS NOT NULL AND pImporte <> 0
    AND pTipo IS NOT NULL AND pEmpleadoSup <> 0 AND pNombreSup IS NOT NULL AND pFechaCompac IS NOT NULL THEN

      --MACF 20150416
      SELECT fecha_hoy INTO vFechaHoy
        FROM bdicred:sd_fechas
       WHERE empresa = '001';

      IF pFechaCompac > vFechaHoy THEN 
         LET vCodRet = "003";
         Rollback;
         RETURN vCodRet;
      END IF;
     
      IF NOT EXISTS(SELECT {+INDEX(bdicred:sd_maecred idx_idx_maecredb)} num_credito 
                FROM  bdicred:sd_maecred where num_credito = pNumCuenta) THEN
         LET vCodRet = "003";
         Rollback;
         RETURN vCodRet;
      END IF;
      
      IF pImporte <= 0 THEN
          LET vCodRet = "003";
          Rollback;
          RETURN vCodRet;
      END IF;
      --MACF 20150416
      
      --while (length(pPlazo) < 2)
      --    LET pPlazo= "0" || pPlazo;
      --end while;
      if (substr(pPlazo,1,1) = '0') then
          let pPlazo = substr(pPlazo,2,1);
      end if;

      if pOrigen = '1' then
        let pImporte = pImporte / 100;
      end if;

       IF NOT EXISTS(select {+INDEX(bdicobranza:cb_compac idx_compac2)} numcliente 
            from bdicobranza:cb_compac 
            where empresa = pEmpresa and numcliente = pNumCliente and numcuenta = pNumCuenta) then

            insert into bdicobranza:cb_compac (empresa, sucursal, origen, empleado_captura, numcliente, numcuenta, plazo, importe, tipo_compac,
            activo, flag_pago, efectuo_compac, nombre_efectuo, fecha_compac, fecha_insert, hora_insert)
            values (pEmpresa, pSucursal, pOrigen, pEmpleadoCaptura, pNumCliente, pNumCuenta, pPlazo, pImporte, pTipo, '1', '0', pEmpleadoSup, pNombreSup, pFechaCompac, current, current);

            
            LET vCodRet        = "000";   --Insercion Correcta

       ELSE

            Select {+INDEX(bdicobranza:cb_compac idx_compac2)} numcliente, numcuenta, activo, tipo_compac, fecha_compac, plazo
            into vNumcliente, vNumCuenta, vActivo, vTipoCompac, dtefecha, chrplazo
            From bdicobranza:cb_compac
            where empresa = pEmpresa and numcliente = pNumCliente and numcuenta = pNumCuenta;

            IF vTipoCompac = '1' and pTipo = '2'  THEN

                    Update bdicobranza:cb_compac
                    set empresa = pEmpresa, sucursal = pSucursal, origen = pOrigen, empleado_captura = pEmpleadoCaptura, plazo = pPlazo,
                    importe=pImporte, tipo_compac = '2', activo = '1', flag_pago = '0', efectuo_compac = pEmpleadoSup, nombre_efectuo = pNombreSup,
                    fecha_compac = pFechaCompac
                    where empresa = pEmpresa and numcliente = pNumCliente and numcuenta = pNumCuenta;

                    
                    LET vCodRet        = "001";   --Acuerdo Actualizado por un Compromiso

            ELSE
					LET intactivo = 0;
					LET intdiasplazo = NVL(chrplazo,0) * 7;
                    LET intdiasfecha = CURRENT::DATE - dtefecha;
                    IF intdiasfecha <= intdiasplazo THEN
                        LET intactivo = 1;
                    END IF;

                    IF pTipo = '1' and vTipoCompac = '1' then

                         IF intactivo = 0 then                             
							           Update bdicobranza:cb_compac
                    	    set empresa = pEmpresa, sucursal = pSucursal, origen = pOrigen, empleado_captura = pEmpleadoCaptura, plazo = pPlazo,
                            importe=pImporte, tipo_compac = '1', activo = '1', flag_pago = '0', efectuo_compac = pEmpleadoSup, nombre_efectuo = pNombreSup,
                            fecha_compac = pFechaCompac
                    	    where empresa = pEmpresa and numcliente = pNumCliente and numcuenta = pNumCuenta;

							
                            LET vCodRet        = "001";   --Acuerdo Actualizado por un Compromiso

                         ELSE
                             LET vCodRet        = "002";   --Compromiso o Acuerdo de Pago Activo
                         END IF;

					ELSE
						IF pTipo = '2' and vTipoCompac = '2' AND intactivo = 0 then
						    Update bdicobranza:cb_compac
                    	    set empresa = pEmpresa, sucursal = pSucursal, origen = pOrigen, empleado_captura = pEmpleadoCaptura, plazo = pPlazo,
                            importe=pImporte, tipo_compac = '2', activo = '1', flag_pago = '0', efectuo_compac = pEmpleadoSup, nombre_efectuo = pNombreSup,
                            fecha_compac = pFechaCompac
                    	    where empresa = pEmpresa and numcliente = pNumCliente and numcuenta = pNumCuenta;							
						else
						    LET vCodRet        = "002";   --Compromiso o Acuerdo de Pago Activo
						end if;
                    END IF;

            END IF;

       END IF;
ELSE
    LET vCodRet        = "003";   --Falta algun parametro
END IF;

COMMIT WORK;
  if v_codret = '000' then  
    execute procedure bdicred:sp_graba_indicador(pempresa, pNumCuenta,pImporte,'' , current, 5) into v_codret;
  end if;
    RETURN vCodRet;

END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_repcob_cartera_env_pba()
	RETURNING
		CHAR(6) 		AS COD_RET,
		CHAR(80)		AS MENSAJE_RET;		
			
		---DECLARACIONES
		DEFINE iSqlErr				                               INTEGER;
		DEFINE iIsamErr				                               INTEGER;
		DEFINE iPagoVenc			                               INTEGER;
		DEFINE cTabla		      	                             CHAR(1);
		DEFINE cStatusCred			                             CHAR(2);
		DEFINE cCiudad, v_empresa				                     CHAR(3);
		DEFINE cProceso                                      CHAR(4);
		DEFINE cCodRet,vvcCod_ret                            CHAR(6);
		DEFINE vhora                                         CHAR(8);
		DEFINE cNumcte, cNumCredito, cNumTarjeta				     CHAR(20);
    DEFINE vHora3                                        CHAR(22);
		DEFINE vCurrent                                      CHAR(25);
    DEFINE cNombreRegion		                             CHAR(30);
		DEFINE cDescripcion			                             CHAR(50);
		DEFINE cDescripcionFinllam                           CHAR(50);
		DEFINE vcNombre				                               VARCHAR(60);
		DEFINE cMensajeRet, cNombreArchivo, cRuta			       CHAR(80);						
    DEFINE cTipoLogica			                             CHAR(100);
    DEFINE cSql          		                             CHAR(1024); 
		DEFINE cConsulta		  	                             CHAR(2200);
		   										
		DEFINE dtFechaHoy, dtFechaCorteIniCte  			         DATE;
		DEFINE dtFechaCorteFinCte, dtFechaUltPago	           DATE;
		DEFINE dtFechaMax, dtFechaMaxCart                    DATE;
		define vdia                                          DATE;
		
		DEFINE sNumVencidos, sNumPagos			                 SMALLINT;
		DEFINE sFinLlamada			                             SMALLINT;
		DEFINE sTipo_logica                                  SMALLINT;
		
		DEFINE dMoratorio, dSaldoTotal, dSdoVencidoTot		   DECIMAL(18,2);
		DEFINE dPagoMinimo, dMensActual, dPagoUnaMora 		   DECIMAL(18,2);
		DEFINE dMontoPagos			                             DECIMAL(18,2);
    DEFINE iCuenta                                       INTEGER;
    --DEFINE vHoraFinLLamada DATETIME HOUR to FRACTION(3);
    DEFINE vHoraFinLLamada DATETIME HOUR to second;
                
		---INICIALIZACIONES
		LET iSqlErr      = 0;   LET iIsamErr      = 0;    LET dMoratorio      = 0.00;   LET dSaldoTotal      = 0.00;
		LET iPagoVenc		 = 0;	  LET sNumVencidos	= 0; 		LET dSdoVencidoTot  = 0.00; 	LET dPagoMinimo			 = 0.00;
		LET dMensActual	 = 0.00;LET dPagoUnaMora  = 0.00;	LET sNumPagos			  = 0;   		LET dMontoPagos			= 0.00;
		LET sFinLlamada	 = 0;
    
    LET cCodRet      = "000000";    LET cMensajeRet      = "Proceso exitoso";  		LET v_empresa          = '001'; 		LET cProceso            = '0073';
		LET cTabla		 	 = "N";         LET cNombreArchivo 	 = "";                		LET cConsulta	         = "";  		  LET cSql		 		        = "";
 		LET cRuta		 		 =  "";		      LET dtFechaHoy       = ""; 	                  LET dtFechaCorteIniCte = "";        LET dtFechaCorteFinCte  = "";
		LET cNumcte 		 = "";  		    LET cNumCredito			 = ""; 		                LET cNumTarjeta			   = "";        LET cDescripcion		    = ""; 
		LET cStatusCred	 = ""; 		      LET dtFechaUltPago	 = "";  		              LET cCiudad				     = "";        LET cNombreRegion		    = "";      
		LET vcNombre		 = "";		      LET cTipoLogica			 = "";                    LET vvcCod_ret         = '';        LET vdia                = '';  
		LET vhora        = '';          LET vCurrent         = '';                    LET vHora3             = '';        LET cDescripcionFinllam = '';   
    LET dtFechaMax   = date(1);     LET dtFechaMaxCart   = date(1);               LET iCuenta            = 0;         LET sTipo_logica        = 0;
    LET vHoraFinLLamada = CURRENT;
    	
	BEGIN 
		ON EXCEPTION SET iSqlErr, iIsamErr, cMensajeRet
			IF iSqlErr != 0 THEN
				LET cCodRet = iSqlErr;	
				LET cMensajeRet = TRIM(cMensajeRet) || '--> ' || cNumcte || cNumCredito;			  				
     			
			 RETURN cCodRet, cMensajeRet;
				
		   END IF;
		END EXCEPTION;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;


		--SET DEBUG FILE TO "/informix/macf/sp_repcob_cartera_env.trc";
		--TRACE ON;
		 
		--DETERMINACION DE FECHA CORTE:
		SELECT fecha_hoy   INTO dtFechaHoy
		FROM bdicred:"informix".sd_fechas
		WHERE empresa = v_empresa;
		
		SELECT max(fecha_insert) INTO dtFechaMax 
               FROM bdicobranza:"informix".cb_cat_directorio_cte
               WHERE tipo_cobranza = 'A';
    
    SELECT max(date(fechacartera)) INTO dtFechaMaxCart
		   FROM bdicobranza:"informix".cb_cat_movimientos
		   WHERE tipocobranza = 'A';  
		
   
    TRUNCATE bdicobranza:cb_encabezadosexcelenviada; 
    			 					
		--SE AGREGA ENCABEZADO AL REPORTE PARA EL ARCHIVO EXCEL.
		INSERT INTO bdicobranza:"informix".cb_encabezadosexcelenviada (NumeroCliente,NumeroCredito,NumeroTarjeta,InteresMoratorio,SdoTotalLiquidacion,SdoVencidoTotal,PagoMinimo,MensualidadActual,NumVencidosInicial,NumVencidosFinal,StatusCred,FechaUltPago,PagoUnaMora,Ciudad,Descripcion,Region,LogicaCampana,NumPagos,MontoPagos,ResultGestion,NombreGestion)
		VALUES("No. De cliente","No. De credito","No. Tarjeta","Int. Moratorio","Sdo. Tot. Liquidacion","Sdo. Vencido Tot.","Pago min.","Mens. Actual","No. Vencidos inicial","No. Vencidos final","Status cred.","Fech. Ult Pago","Pago 1 mora","Ciudad","Descripcion","Region","Logica o campana","No. Pagos","Monto pagos","Resultado de gestion","Nombre de gestion");		
	
		SELECT empresa,
           numcte,
           num_credito, 
           SUM(NVL(moratorio,0.00)) AS IntMoratorio,
           SUM(NVL(saldo_total,0.00)) AS SdoTotLiqui,
			     SUM(NVL(NVL(monto_vencido,0.00) + NVL(mto_venc_trasp,0.00) + NVL(moratorio,0.00) + NVL(interes_iva,0.00),0.00)) AS SdoVencidoTot,
				   SUM(NVL(pago_minimo,0.00)) AS PagMinimo,
				   SUM(NVL((NVL(pago_minimo,0.00) + NVL(mto_venc_trasp,0.00) + NVL(moratorio,0.00)),0.00)) AS MensActual,
				   SUM(NVL(pago_venc,0)) AS NumVencIni,
           NVL(fecha_ult_pago,"") AS FechUltPag,
           SUM(NVL(pago_una_mora,0.00)) AS Pago1Mora,
           SUM(NVL(num_pagos,0)) AS NumPagos,
           SUM(NVL(monto_pagos,0)) AS MontosPag,
           NVL(ciudad,"") AS Ciudad,
           NVL(tipo_logica,0) tipo_logica, NVL(codigo_resultado,0) codigo_resultado
      FROM bdicobranza:cb_cat_directorio_cte 
      WHERE tipo_cobranza = "A"    
        AND fecha_insert >= dtFechaMax
        AND status_cliente <> "NT" AND status_cliente <> "TE"
        AND tipo_logica = 2                --- TEST MACF  49,814
      GROUP BY empresa, numcte, num_credito, fecha_ult_pago, ciudad, tipo_logica, codigo_resultado, tipo_cobranza
			 INTO TEMP paso_catdir WITH NO LOG;

      begin;
      CREATE INDEX idx_paso_catdir ON paso_catdir (numcte, num_credito) ONLINE;
      commit;

      begin;
      CREATE INDEX idx_paso_catdir2 ON paso_catdir (tipo_logica) ONLINE;
      commit;

      begin;
      CREATE INDEX idx_paso_catdir3 ON paso_catdir (codigo_resultado) ONLINE;
      commit;

      UPDATE statistics HIGH FOR TABLE "informix".paso_catdir;    

		--SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND INTO vHora3 from sysmaster:sysshmvals;
    --INSERT INTO bdicobranza:cb_bitacora(empresa, num_proceso, fecha_ejecucion, cod_ret, mensaje, user_insert, fecha_insert, hora_insert) 
    --VALUES(v_empresa, cProceso, today, '000000', 'Termina creación de tabla temporal paso_catdir', 'informix', vdia, vHora3);
		
		FOREACH WITH HOLD
		 			SELECT NVL(a.numcte,""),  NVL(a.num_credito,""), a.intmoratorio,
                 a.sdototliqui, a.sdovencidotot, a.pagminimo, a.mensactual, a.numvencini,  
                 a.fechultpag, a.pago1mora, a.ciudad, NVL(e.descripcion,""), a.numpagos,
                 a.montospag, NVL(g.descripcion,""), a.tipo_logica				   
    			INTO cNumcte, cNumCredito, dMoratorio, dSaldoTotal, dSdoVencidoTot, dPagoMinimo, dMensActual,iPagoVenc, dtFechaUltPago, dPagoUnaMora,
               cCiudad, cTipoLogica, sNumPagos, dMontoPagos, cDescripcion, sTipo_logica				 				 
    			FROM "informix".paso_catdir a
		            LEFT OUTER JOIN bdicobranza:cb_param_campania e ON(e.valor_numerico = a.tipo_logica and e.grupo_parametro = 'LOGICA')
		            LEFT OUTER JOIN bdicobranza:cb_cat_tipo_resultado g	ON (g.codigo_resultado = a.codigo_resultado)
		      /*      
    			SELECT NVL(a.numcte,"") AS NumDeCliente, NVL(a.num_credito,"") AS NumDeCredito, NVL(c.num_tarjeta,"") AS NumTarjeta, a.intmoratorio AS IntMoratorio,
                 a.sdototliqui AS SdoTotLiqui, a.sdovencidotot, a.pagminimo AS PagMinimo,
    				     a.mensactual AS MensActual, a.numvencini AS NumVencIni, NVL(d.num_vencidos,0) AS NumVencFin, NVL(b.status_cred,"") AS StatusCred, 
                 a.fechultpag AS FechUltPag, a.pago1mora AS Pago1Mora, a.ciudad AS Ciudad, NVL(e.descripcion,"") AS LogicaCampana, a.numpagos AS NumPagos,
                 a.montospag AS MontosPag, NVL(g.descripcion,"") AS NombreGestion				   
    			INTO cNumcte,cNumCredito,cNumTarjeta,dMoratorio,dSaldoTotal,dSdoVencidoTot,dPagoMinimo,dMensActual,iPagoVenc,sNumVencidos,cStatusCred,dtFechaUltPago,
    			 	   dPagoUnaMora,cCiudad,cTipoLogica,sNumPagos,dMontoPagos,cDescripcion  --sFinLlamada,cDescripcion				 				 
    			FROM "informix".paso_catdir a
    				LEFT OUTER JOIN bdicred:"informix".sd_maecred b ON( b.num_credito = a.num_credito)
    				INNER join bdicred:sd_tarjeta c on a.empresa = c.empresa and a.num_credito = c.num_credito and c.secuencia = (select max(secuencia) from bdicred:sd_tarjeta where a.empresa = empresa AND a.num_credito = num_credito and tipo_tarjeta = 'T' AND status_tar = 'A')
    				LEFT OUTER JOIN bdicred:"informix".sd_indicador_cred d ON(d.num_credito = a.num_credito)			
    				LEFT OUTER JOIN bdicobranza:"informix".cb_param_campania e ON(e.valor_numerico = a.tipo_logica)
    				LEFT OUTER JOIN  bdicobranza:"informix".cb_cat_movimientos f ON( LPAD(TRIM(f.cliente),9,"0") = a.numcte )
    				LEFT OUTER JOIN bdicobranza:"informix".cb_cat_tipo_resultado g	ON (g.codigo_resultado = a.codigo_resultado)
    			WHERE b.num_producto = "6001" 
    				AND b.num_producto = c.prodtarjeta
    				AND e.grupo_parametro = "LOGICA"
    				AND f.tipologica = a.tipo_logica
    				AND f.tipocobranza = "A"
    				AND date(f.fechacartera) >= dtFechaMaxCart
          */
          
          SELECT LIMIT 1 nvl(m.finllamada,0) as finllamada, nvl(c.descripcion,'') as descripcion,
                   (SELECT MAX(horafinllamada) FROM bdicobranza:cb_cat_movimientos WHERE cvemovimiento = m.cvemovimiento AND cliente = m.cliente 
                                                AND tipologica = m.tipologica AND tipocobranza = m.tipocobranza
                                                AND date(fechacartera) = date(m.fechacartera) ) AS HoraFinLLamada  
              INTO sFinLlamada, cDescripcionFinllam, vHoraFinLLamada
              FROM bdicobranza:cb_cat_movimientos m, 
                   bdicobranza:cb_cat_tipo_resultado c
             WHERE m.cvemovimiento = 'L' 
               --AND m.cliente = cNumcte  -- no coincide porque m.cliente no tiene ceros a la izq.
               AND m.tienda = cNumCredito 
               AND m.tipologica = sTipo_logica 
               AND m.tipocobranza = 'A'
               /*AND m.horafinllamada = (SELECT MAX(horafinllamada) 
                                         FROM bdicobranza:cb_cat_movimientos 
                                        WHERE cvemovimiento = m.cvemovimiento 
                                          AND cliente = m.cliente 
                                          AND tipologica = m.tipologica
                                          AND tipocobranza = m.tipocobranza
                                          --AND horafinllamada = horafinllamada
                                          AND date(fechacartera) = date(m.fechacartera) --dtFechaMaxCart
                                             
               )*/ 
               AND date(m.fechacartera) = dtFechaMaxCart
               AND m.finllamada = c.codigo_resultado;
               
               IF nvl(sFinLlamada,'') = '' THEN continue foreach; END IF;  
          
          --SELECT NVL(num_tarjeta,"") INTO cNumTarjeta 
          SELECT LIMIT 1 NVL(num_tarjeta,""), m.status_cred INTO cNumTarjeta, cStatusCred 
    			  FROM bdicred:sd_tarjeta a, bdicred:sd_maecred m 
    			 WHERE a.empresa = v_empresa
             AND a.empresa = m.empresa  
             AND a.num_credito = cNumCredito
             AND a.num_credito = m.num_credito
             AND a.secuencia = (select max(secuencia) from bdicred:sd_tarjeta 
                                 where empresa = a.empresa AND num_credito = a.num_credito and tipo_tarjeta = 'T' AND status_tar = 'A'); 
			
			    SELECT NVL(num_vencidos,0) INTO sNumVencidos 
            FROM bdicred:sd_indicador_cred 
           WHERE empresa = v_empresa
             AND num_credito = cNumCredito;
			
      			--SELECT LIMIT 1 nvl(m.finllamada,0) finllamada, nvl(c.descripcion,'') descripcion INTO sFinLlamada, cDescripcion   -- NEW BY MACF
            --  FROM bdicobranza:cb_cat_movimientos m, 
            --       bdicobranza:cb_cat_tipo_resultado c 
            -- WHERE date(m.fechacartera) = dtFechaMaxCart 
            --   AND m.tienda = cNumCredito 
            --   AND m.cvemovimiento = 'L'
            --   AND m.horafinllamada = (SELECT MAX(horafinllamada) FROM bdicobranza:cb_cat_movimientos 
            --                            WHERE date(fechacartera) = dtFechaMaxCart 
            --                              AND tienda = cNumCredito and cvemovimiento = 'L')
            --   AND c.codigo_resultado = m.finllamada ; 
            
            --- modif 2013/07/05   
            
			
      			SELECT LIMIT 1 NVL(b.nombre,"") AS NombreCiudad,NVL(c.nombre_region,"") AS NombreRegion  
      			INTO vcNombre,cNombreRegion
      			FROM bdinteg:"informix".si_catciudades a
      				               LEFT OUTER JOIN bdinteg:"informix".si_ciudades b ON(b.ciudad_coppel::INT = a.numerociudad) 	
      				               LEFT OUTER JOIN bdinteg:"informix".si_regiones c ON(c.numero_region	= a.regioncobranzas)
      			WHERE a.numerociudad = cCiudad::INT;
			
      			BEGIN WORK;
              --SE INSERTA TODA LA INFORMACION EN LA TABLA FINAL.
        			INSERT INTO bdicobranza:"informix".cb_encabezadosexcelenviada (NumeroCliente, NumeroCredito, NumeroTarjeta, InteresMoratorio, SdoTotalLiquidacion,
                         SdoVencidoTotal, PagoMinimo, MensualidadActual, NumVencidosInicial, NumVencidosFinal, StatusCred, FechaUltPago, PagoUnaMora, Ciudad,
                         Descripcion, Region, LogicaCampana, NumPagos, MontoPagos, ResultGestion, NombreGestion)
        			--VALUES(cNumcte,cNumCredito,cNumTarjeta,dMoratorio,dSaldoTotal,dSdoVencidoTot,dPagoMinimo,dMensActual,iPagoVenc,sNumVencidos,cStatusCred,dtFechaUltPago,dPagoUnaMora,cCiudad,vcNombre,cNombreRegion,cTipoLogica,sNumPagos,dMontoPagos,sFinLlamada,cDescripcion);
        		  VALUES( "'" || lpad(TRIM(cNumcte),9,'000000000'), cNumCredito, cNumTarjeta, dMoratorio, dSaldoTotal, dSdoVencidoTot, dPagoMinimo, dMensActual,
                     iPagoVenc, sNumVencidos, cStatusCred, dtFechaUltPago, dPagoUnaMora, cCiudad, vcNombre, cNombreRegion, cTipoLogica, sNumPagos, dMontoPagos, 
                     sFinLlamada,cDescripcionFinllam);
            COMMIT WORK;
    
            		  
		END FOREACH
						
		--SE OBTIENE EL NOMBRE DEL ARCHIVO.
		SELECT valor 
		INTO cNombreArchivo
		FROM bdicobranza:"informix".cb_param 
		WHERE cod_param = 73;	

		--SE OBTINE LA RUTA DONDE SE GENERARÁ EL ARCHIVO.
		SELECT valor_alfabetico
		INTO cRuta
		FROM bdicobranza:"informix".cb_param_campania
		WHERE tipo_campania = 11
			AND grupo_parametro = "RUTAS" 
			AND num_parametro = 1;

-- COMENTAR QUE SE GENERE EL ARCHIVO PARA QUE SE GUARDE TODO EN LA TABLA cb_encabezadosexcelenviada Y VER QUE CANT. DE REGS. GENERA
			
		LET cNombreArchivo = TRIM(cNombreArchivo)||YEAR(dtFechaHoy)||LPAD(MONTH(dtFechaHoy),2,0)||LPAD(DAY(dtFechaHoy),2,0); 
		-- lpad(trim(NumeroCliente),9,'00000000')
		LET cConsulta = "SELECT NumeroCliente,NumeroCredito,NumeroTarjeta,InteresMoratorio,SdoTotalLiquidacion,SdoVencidoTotal,PagoMinimo,MensualidadActual,NumVencidosInicial,NumVencidosFinal,StatusCred,FechaUltPago,PagoUnaMora,Ciudad,Descripcion,Region,LogicaCampana,NumPagos,MontoPagos,ResultGestion,NombreGestion FROM bdicobranza:'informix'.cb_encabezadosexcelenviada";		
    
    LET cSql = '';
		LET cSql = 'echo "set isolation to dirty read; UNLOAD TO ' ||TRIM(cRuta)||TRIM(cNombreArchivo)||'.xls'|| ' DELIMITER '|| '''	'''||' '||TRIM(cConsulta)||'" > '|| TRIM(cRuta) ||'query1.sql';
		
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = "dbaccess bdicobranza " ||TRIM(cRuta)||'query1.sql';
		SYSTEM cSql;
		LET cSql = '';
		LET cSQL = "rm " ||TRIM(cRuta)||'query1.sql';		
		SYSTEM cSql; 
		
		--IF cTabla="S" THEN
		--		DROP TABLE bdicobranza:"informix".cb_encabezadosexcelenviada;
		--END IF;
		
    LET cMensajeRet = TRIM(cNombreArchivo)||'.xls';					
		
    --CALL bdicobranza:"informix".sp_inserta_bitacora_cob(v_empresa, cProceso, cCodRet, cMensajeRet, '03') RETURNING vvcCod_ret;  --TEST
    		
		RETURN cCodRet, cMensajeRet;
		
	END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para obtener el Resultado de cartera enviada.', 
'AUTOR: Guadalupe Payan',
'FECHA: Noviembre 2012',
'BD    : BDICOBRANZA',
'VERSION: 20121106.0842',
'Fecha: 2013/10/25. Autor:MACF. Desc.:Tabla fija y dividir queries para optimizar.';

CREATE FUNCTION "informix".convert_to_date(dt int8)
RETURNING datetime year to second
WITH (NOT VARIANT)
define d_return date;

ON EXCEPTION
    begin
        let d_return = today + 1 units day;
        return d_return;
    end
end exception

let d_return = to_date(to_char(dt),"%Y%m%d%H%M%S");
return d_return;
END FUNCTION;